window.MEDIA_DATA = {"stats":{"total":897,"watched":358,"watching":22,"planned":515,"dropped":2,"masterpiece":20,"anime":373,"films":456,"marvel":40,"dc":25,"series":21,"cartoons":37,"manga":10,"games":0},"items":[{"title":"Случайное такси","rating":null,"tier":"unrated","review":"","desc":"Таксист Одокава живёт серой однообразной жизнью. У него нет семьи, нет друзей, он чудаковатый, узко мыслящий и мало разговаривающий тип. Единственные его собеседники — это его врач Горики и его одноклассник из средней школы Какихана.        \n                \n        Его клиенты и сами кажутся немного странными. Кабасава — студент колледжа, который хочет, чтобы мир заметил его в Интернете. Сиракава — загадочная медсестра, которая что-то скрывает. «Хомосапиенс» — комедийный дуэт, у которого не всё гладко с профессиональной деятельностью. Местный хулиган по имени Добу. Все они садятся в его такси, едут, ведут обычные разговоры, которые каким-то образом ведут к пропавшей девушке.","poster":"https://shikimori.io/system/animes/original/46102.jpg?1711967048","url":"https://shikimori.one/animes/46102-odd-taxi","status":"watching","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","Триллер"],"episodes":13,"kind":"tv","franchise":null},{"title":"Ранма 1/2 (1989)","rating":null,"tier":"unrated","review":"Остановился на 101 серии","desc":"Классическое аниме (1989–1992). Отец и сын, Ранма и Гэнма Саотомэ, путешествуют по Китаю. Во время тренировок они случайно падают в проклятые источники: от холодной воды Ранма превращается в девушку, а его отец — в панду. Вернувшись в Японию, они поселяются у семьи Тэндо, где вспыльчивую Аканэ прочат в невесты Ранме. (Просмотр приостановлен на 101 серии).","poster":"https://shikimori.io/system/animes/original/210.jpg?1711970051","url":"https://shikimori.one/animes/210-ranma","status":"watching","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевые искусства","Комедия","Романтика","Сёнэн","Фэнтези"],"episodes":161,"kind":"tv","franchise":"ranma"},{"title":"Дандадан 2","rating":null,"tier":"unrated","review":"","desc":"Хотите узнать, что будет, если взять внучку экстрасенса, неверящую в НЛО, и фаната уфологии, который и думать не желает о призраках? А будет самое настоящее испытание на храбрость или, скорее, испытание верой, во время которого каждый из них захочет показать другому ту сторону реальности, о которой второй даже не задумывался. А вот если эти самые призраки и пришельцы начнут активно на них нападать, то из такого сочетания несочетаемого вполне может получиться достойная команда!        \n                \n        Это история о популярной красавице Момо Аясэ и типичном заучке Кэне Такакуре — старшеклассниках, которые вынуждены бороться с чёрт пойми кем во имя их собственного целомудрия и спокойствия на планете Земля!","poster":"https://shikimori.io/system/animes/original/57334.jpg?1716838813","url":"https://shikimori.one/animes/57334-dandadan","status":"watching","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Сверхъестественное","Сёнэн"],"episodes":12,"kind":"tv","franchise":"dandadan"},{"title":"Киноманка Помпо","rating":null,"tier":"unrated","review":"","desc":"«Профессий много, но — прекрасней всех кино!»   \n   А самое прекрасное место для работы — Нялливуд, столица кино и Мекка всех, имеющих отношение к киноиндустрии. Именно здесь живёт и работает «великая» Помпо — талантливый продюсер, обычно снимающая второсортные боевики. Здесь же трудится её ассистент — Джин Фини, который, несмотря на то, что является помощником продюсера, обладает задатками настоящего режиссёра. Здесь не покладая рук вкалывает день и ночь на всевозможных подработках начинающая актриса Натали Вудворд.   \n   И однажды они объединятся, чтобы снять шедевр, достойный побороться за самую почётную кинонаграду.","poster":"https://shikimori.io/system/animes/original/41361.jpg?1711948758","url":"https://shikimori.one/animes/41361-eiga-daisuki-pompo-san","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Комедия","Драма","Искусство"],"episodes":1,"kind":"movie","franchise":null},{"title":"Семья шпиона — Код: Белый","rating":null,"tier":"unrated","review":"","desc":"Первоклассный шпион Лойд Форджер, работающий под псевдонимом Сумрак, узнаёт, что его могут отстранить от выполнения текущей секретной миссии в связи с отсутствием продуктивных результатов. Однако, по удачному стечению обстоятельств, в элитной академии «Эдем», где обучается его приёмная дочь, Аня, для урока кулинарии нужно приготовить десерт, который оценивать будет сам президент академии. Увидев в этом возможность получить звезду, тем самым продемонстрировав наличие успехов операции, Сумрак решает совершить семейную поездку во Фригис, родину неподражаемого десерта мерэ-мерэ. Однако для идеального приготовления любимого блюда судьи потребуется нечто большее, чем просто следование рецепту.","poster":"https://shikimori.io/system/animes/original/53888.jpg?1714956961","url":"https://shikimori.one/animes/53888-spy-x-family-movie-code-white","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Боевик","Комедия","Сёнэн"],"episodes":1,"kind":"movie","franchise":"spy_x_family"},{"title":"Вавилон","rating":null,"tier":"unrated","review":"","desc":"Известный прокурор Дзэн Сэйдзаки ведёт своё расследование о незаконном медицинском исследовании, в котором, по его мнению, фигурируют некая фармацевтическая компания и городской университет.   \n   Однажды на месте расследования он находит папку, некогда принадлежащую анестезиологу по имени Син Инаба, и обнаруживает в ней окровавленные волосы, образцы кожи и странную записку, где написана единственная буква — «F». По мере расследования Дзэн осознаёт, что имеет дело с заговором, связанным с грядущими выборами. Кажется, детектив всё ближе к разгадке. Или же нет?","poster":"https://shikimori.io/system/animes/original/37525.jpg?1711943088","url":"https://shikimori.one/animes/37525-babylon","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Триллер","Психология"],"episodes":12,"kind":"tv","franchise":null},{"title":"Путь домохозяина","rating":null,"tier":"unrated","review":"","desc":"Бессмертный Тацу — живая легенда в сфере криминала. Когда-то его имя вселяло ужас, как полицейским, так и преступникам. Однако по каким-то причинам он бросает бандитскую жизнь, и теперь Тацу — обычный домохозяин, приспособившийся к повседневным домашним делам. Удастся ли бывшему якудза остаться преданным мужем и вести спокойную жизнь, не ввязываясь при этом в различные передряги?","poster":"https://shikimori.io/system/animes/original/43692.jpg?1711951594","url":"https://shikimori.one/animes/43692-gokushufudou","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Приключения","Драма"],"episodes":5,"kind":"ona","franchise":null},{"title":"Судьба: Девочка-волшебница Иллия","rating":null,"tier":"unrated","review":"","desc":"Дополнительный эпизод, вышедший в комплекте с ограниченным выпуском шестого тома манги «Судьба/Девочка-волшебница Иллия 3».","poster":"https://shikimori.io/system/animes/original/26057.jpg?1711949192","url":"https://shikimori.one/animes/z26057-fate-kaleid-liner-prisma-illya-2wei-mahou-shoujo-in-onsen-ryokou","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":1,"kind":"ova","franchise":null},{"title":"Причина полюбить её","rating":null,"tier":"unrated","review":"","desc":"В день, когда Ли Джун Ли поступает в университет Минсон, чтобы наконец встретиться с Ким Марго Ким — своей школьной любовью, — на него набрасывается новая соседка Ли Дуна Ли, ослепительно красивая бывшая айдол. Взрывная и непредсказуемая, Дуна переворачивает жизнь Джуна с ног на голову. Вскоре, к его недоумению, оказывается, что у Марго никак не находится времени на встречу с ним. А в довершение всех бед на одной из вечеринок Джун знакомится с сокурсницей Ира Чхве Ирой, которая после одной довольно смелой игры проникается к нему нежными чувствами. По мере того как Джун всё глубже погружается в тяжёлое прошлое Дуны и узнаёт о непростых семейных обстоятельствах Марго, он пытается разобраться в собственном запутанном клубке чувств.","poster":"https://shikimori.io/system/animes/original/54846.jpg?1710727454","url":"https://shikimori.one/animes/54846-aishang-ta-de-liyou","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Школа"],"episodes":22,"kind":"ona","franchise":null},{"title":"Пикник в потусторонье","rating":null,"tier":"unrated","review":"","desc":"Её первая встреча с Торико Нисиной произошла в Потусторонье, после того, как она увидела «эту штуку» и чуть не погибла. С того самого дня обычная студенческая жизнь самой обычной студентки университета Сорао Камикоси изменилась. В этом Потустороннем мире, наполненном огромным количеством различных тайн, которые существуют рядом с нашими собственными, появляются опасные существа, такие как Кунекуне и Хассяку-сама, о которых говорится в реальных историях о призраках. Ради исследования, получения прибыли и для поиска одного важного человека, Торико и Сорао вступили в Потусторонье.","poster":"https://shikimori.io/system/animes/original/41392.jpg?1711979453","url":"https://shikimori.one/animes/41392-urasekai-picnic","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Детектив","Триллер"],"episodes":12,"kind":"tv","franchise":null},{"title":"Сквозь бальный зал","rating":null,"tier":"unrated","review":"","desc":"Татара Фуджита бесцельно проживает лучшие годы средней школы, не в состоянии найти ни друзей, ни чего-то, что бы его по-настоящему увлекло. И вот, в один прекрасный день на него нападают хулиганы, от которых его спасает загадочный человек. Однако это вовсе не мастер карате, а учитель бальных танцев! Не особенно горя энтузиазмом, Татара приходит к нему на занятие и неожиданно... встречает музу — изумительную талантливую танцовщицу по имени Шизуку Ханаока. Следуя за ней, герой делает первый шаг в будоражащий мир танцевальных соревнований.","poster":"https://shikimori.io/system/animes/original/34636.jpg?1711943429","url":"https://shikimori.one/animes/34636-ballroom-e-youkoso","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Спорт","Сёнэн","Комедия"],"episodes":24,"kind":"tv","franchise":null},{"title":"Бесклассовый герой: Да мне всё равно не нужны эти ваши умения","rating":null,"tier":"unrated","review":"","desc":"В мире, где каждый ребёнок в десять лет получает магический класс и особые умения, будущее человека предопределено с детства. Класс определяет статус, возможности и даже то, как тебя воспринимают окружающие.  — сын двух легенд: знаменитой «Принцессы клинков»  и великого мага, известного как «Король магии» . Все ждали, что он унаследует невероятную силу и станет героем с рождения. Но в день посвящения  не получил ни класса, ни навыков. Его назвали «Бесклассовым», и от него отвернулись — кто-то с жалостью, кто-то с презрением.   \n   Но  не сломался. Он не стал искать оправданий и не позволил чужим словам определить свою судьбу. Вместо магии и даров он выбрал упорство, тренировки и знания. Он изучал то, что другие считали бесполезным, оттачивал технику, развивал тело и разум. Постепенно он начал открывать в себе силу, которая не была дана богиней, — силу, которую он создал сам. И эта сила оказалась куда надёжнее любых классов.","poster":"https://shikimori.io/system/animes/original/56854.jpg?1712433794","url":"https://shikimori.one/animes/56854-mushoku-no-eiyuu-betsu-ni-skill-nanka-iranakatta-n-da-ga","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Иллюзия рая","rating":null,"tier":"unrated","review":"","desc":"Из-за неизвестного катаклизма вся человеческая цивилизация пришла в упадок. Те немногие, кому посчастливилось остаться в живых, обречены на суровое существование в реалиях постапокалипсиса со всеми вытекающими: нехваткой воды, продовольствия, энергии и всех остальных благ, которые в один момент канули в небытие. И как вишенка на торте — монстры, появившиеся после катастрофы, для которых единственная пища — это человек. Но и в таких тяжёлых условиях всё ещё можно жить и радоваться жизни. Молодой парень Мару и его телохранитель Кируко путешествуют по бывшей Японии с великой целью найти Рай.   \n      \n   В это же время группа детей нашли убежище в стенах загадочного закрытого учреждения. Здесь, под заботливой опекой защитников, они растут в относительной безопасности. Они окружены заботой и любовью, могут свободно учиться и играть, однако о том, что находится за стенами, им известно лишь по рассказам взрослых. Конечно, рано или поздно у детей пробуждается неугомонное любопытство, и их душами начинает овладевать томительная жажда познаний.   \n      \n   В этой новой страшной реальности переплетаются судьбы и мечты, а тени прошлого и проблески будущего танцуют в вихре загадок. Каждый здесь не только судорожно пытается выжить, но и найти свой ответ на вопрос зачем ему вообще жить.","poster":"https://shikimori.io/system/animes/original/53393.jpg?1710730322","url":"https://shikimori.one/animes/53393-tengoku-daimakyou","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Детектив","Фантастика","Сэйнэн"],"episodes":13,"kind":"tv","franchise":null},{"title":"Кэрол и Тьюсдей","rating":null,"tier":"unrated","review":"","desc":"Прошло уже пятьдесят лет с тех пор, как человечество начало эмигрировать на Марс. В это время люди превратились в пассивных потребителей, ведь все их нужды теперь обеспечивал ИИ.   \n   Там, на Марсе, в центре города Альба-Сити выживает девушка по имени Кэрол. Она усердно трудится неполный рабочий день в надежде однажды стать музыкантом, но ей чего-то не хватает.   \n   В провинциальном марсианском городке Хершел-Сити живёт другая девушка — Тьюсдей. Она из обеспеченной семьи и тоже мечтает стать музыкантом, однако никто не понимает её, ведь музыку теперь пишет ИИ, а не люди. Тьюсдей чувствует себя самым одиноким человеком в мире.   \n   Случайная встреча сводит девушек вместе. Они обе хотят петь. Обе мечтают создавать музыку. И вместе у них наконец-то появляется шанс.   \n   Двое могут создать лишь крохотную волну, но эта волна в конце концов может перерасти в нечто большее...","poster":"https://shikimori.io/system/animes/original/37435.jpg?1711945431","url":"https://shikimori.one/animes/37435-carole-tuesday","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фантастика","Музыка"],"episodes":24,"kind":"tv","franchise":null},{"title":"Дека-данс","rating":null,"tier":"unrated","review":"","desc":"Прошло много лет с тех пор, как из-за прибытия на Землю неизвестной формы жизни, получившей название «Гадолл», человечество оказалось под угрозой вымирания. Выжившие после внезапной атаки люди построили огромную крепость «Дека-Данс», где и укрылись, разделившись на воинов и тех, кто выполняет функцию поддержки солдат.   \n   Однажды Нацумэ, мечтающая сражаться, встречается с Кабураги, который давно отошёл от битв и теперь занимается ремонтом брони. И эта случайная встреча становится событием, которое способно изменить мир!","poster":"https://shikimori.io/system/animes/original/40056.jpg?1711947383","url":"https://shikimori.one/animes/40056-deca-dence","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фантастика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Золотой парень","rating":null,"tier":"unrated","review":"","desc":"На вид и не скажешь, но Кинтаро Оэ (大江 錦太郎) — гений, закончивший все университетские курсы и ушедший оттуда задолго до выпускного. Он становится путешественником, странствуя с места на место на своём велосипеде в поисках новых знаний о жизни, о мире, о женщинах. Он готов взяться за любую работу, чтобы испытать себя. Его путешествие приводит его в различные места и к различным женщинам, каждая из которых впоследствии влюбляется в трудолюбивого парня.","poster":"https://shikimori.io/system/animes/original/268.jpg?1711951676","url":"https://shikimori.one/animes/268-golden-boy","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Этти","Работа","Сэйнэн"],"episodes":6,"kind":"ova","franchise":null},{"title":"Рейтинг короля","rating":null,"tier":"unrated","review":"","desc":"Если даже статус короля не гарантирует тебе счастливой, безоблачной жизни, то что может дать статус принца? Особенно, если ты маленький глухой беспомощный мальчик, не обладающий никакой властью и не способный держать в руках даже игрушечный меч. Однако Бодзи — наследник трона, поэтому он изо всех сил старается, чтобы стать великим королём. Вот только сколько усилий он ни прикладывает, люди продолжают шептать за его спиной, что он абсолютно никчёмный ребёнок и ни за что не сможет стать достойным правителем.   \n   Растущий в таком безжалостном окружении, Бодзи находит поддержку в единственном друге, которым стала тень на земле. Тень по имени Кагэ, раньше был членом клана ассасинов, который был полностью уничтожен. В живых остался только Кагэ, который растерял свои навыки и теперь перебивается воровством. Двум убогим друзьям, которые, несмотря ни на что продолжают жить и бороться с судьбой, предстоит найти своё место в мире и доказать всем, что выигрывают в итоге те, кто не сдаётся.","poster":"https://shikimori.io/system/animes/original/40834.jpg?1711968194","url":"https://shikimori.one/animes/40834-ousama-ranking","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"],"episodes":23,"kind":"tv","franchise":null},{"title":"Эф — история мелодий","rating":null,"tier":"unrated","review":"","desc":"Ю Химура — прилежный, усердный юноша, намеревающийся и впредь единолично возглавлять рейтинги успеваемости и достижений академии Отова. Однажды он встречает загадочную девушку по имени Юко Амамия , которая, к вящему его удивлению, узнаёт его, будто бы встречалась с ним раньше. Воспоминания отдалённого детства, воспоминания, намеренно оставленные в забытьи... Новая встреча с Юко заставляет Ю столкнуться с разочарованиями и печалью их совместного прошлого и настоящего.   \n      \n   Другой герой, Сюити Кудзэ, поначалу может показаться бабником, но, при более тщательном знакомстве, он оказывается человеком, которому уютно в одиночестве. Мидзуки Хаяма , впрочем, не из тех девушек, которые бы охотно предоставили ему эту возможность, особенно после того, как она услышала прекрасные звуки его скрипки. По мере того, как Мидзуки пытается сблизиться с ним, Сюити, напротив, пытается отвязаться от неё... Неспешная история их многообещающих взаимоотношений омрачена обертонами приближающейся трагедии.","poster":"https://shikimori.io/system/animes/original/4789.jpg?1711948720","url":"https://shikimori.one/animes/z4789-ef-a-tale-of-melodies","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Мартовский лев","rating":null,"tier":"unrated","review":"","desc":"Семнадцатилетний Рэй Кирияма, недавно начавший жить один, не отличается ничем особенным, кроме, разве что, превосходных навыков игры в сёги. Несмотря на обретённую независимость, юноша всё ещё не зрел эмоционально и подростковые проблемы по-прежнему преследуют его в повседневной жизни. Напряжённые отношения с приёмной семьёй и трудности в общении со сверстниками — лишь вершина айсберга. Кажется, шахматная «игра генералов» — единственное, чему он может себя посвятить...   \n   Однако есть в этом мире странная семья, и обстановка в доме этой семьи подобна ядерному взрыву. Шум и гам, смех и веселье, а ещё мяуканье — так громко, что хочется зажмуриться... Маленький старый дом в маленьком городе на большой реке. Дом, в котором однажды случайно оказался Рэй. Дом, где его с улыбками встретили три замечательные девушки, три сестры — старшая Акари, средняя Хината и совсем малышка Момо.   \n   Задержится ли юноша в этом доме? Забудет ли о своих печалях в его стенах? Или, быть может, сам развеет печали здешних приветливых обитателей?","poster":"https://shikimori.io/system/animes/original/31646.jpg?1711937760","url":"https://shikimori.one/animes/31646-3-gatsu-no-lion","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Сэйнэн","Комедия"],"episodes":22,"kind":"tv","franchise":null},{"title":"Праздник кукол","rating":null,"tier":"unrated","review":"","desc":"Однажды ночью на голову ничего не подозревающего члена якудза по имени Йошифуми Нитта сваливается странный предмет, а вместе с ним — и куча проблем. Странным предметом оказывается коробка с не менее странной девочкой внутри. Девочку зовут Хина, и она обладает потрясающими сверхъестественными способностями.   \n   Может, Йошифуми и не надо свалившегося ему на голову «счастья», но как-то так получается, что он оставляет девочку жить у себя. Её суперсилы могут оказаться вполне полезными в его работе, но всегда остаётся нехилый риск того, что Хина применит свои способности не на том, на кого укажет Йошифуми, а на нём самом! Не говоря о небольшом минусе, связанном со сверхспособностями: если Хина их не использует, то с течением времени теряет рассудок, превращаясь в безумного монстра, уничтожающего всё, что попадётся под руку.   \n   Так и начинается необычная жизнь крайне необычной парочки.","poster":"https://shikimori.io/system/animes/original/36296.jpg?1711953782","url":"https://shikimori.one/animes/z36296-hinamatsuri","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Рэй Зеро","rating":null,"tier":"unrated","review":"","desc":"Недалёкое будущее. Токио разрушен, на его руинах образовалась новая столица, и теперь это самый грязный и порочный город на земле. Однако не все подчиняются правилам этого мира, среди них и тайная организация «Рэй». В одной из последних операций им удалось захватить опасного преступника, известного как Хоакин Найто, но всё оказалось лишь спланированной ловушкой, и наши прелестные спецагенты Сёко и Рэй попадают в плен.","poster":"https://shikimori.io/system/animes/original/9006.jpg?1711970428","url":"https://shikimori.one/animes/9006-rei-zero","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Хентай","Комедия","Приключения"],"episodes":2,"kind":"ova","franchise":null},{"title":"How Heavy Are the Dumbbells You Lift?","rating":null,"tier":"unrated","review":"","desc":"Знакомьтесь: Хибики Сакура — ничем не примечательная старшеклассница, которая очень сильно любит поесть. Её лучшая подруга — Аяка Уэхара, которая в один не прекрасный для Хибики день замечает, что та набрала вес. Неприятные новости приводят девушку к мысли о том, что нужно садиться на диету, но... не с аппетитом Сакуры! А потому героиня отправляется в спортивный комплекс в надежде там добиться хоть какого-то результата. На новом месте она встречает президента студенческого совета своей школы Акэми Сорюин, которая тоже решила записаться на занятие, ведь у мнимой тихони, оказывается, настоящий «мышечный фетиш». Теперь парочке придётся пройти через все трудности интенсивных тренировок на пути к своим заветным целям. Ну а делать это с удовольствием поможет тренер-красавчик Нарудзо Матио.","poster":"https://shikimori.io/system/animes/original/39026.jpg?1711948579","url":"https://shikimori.one/animes/39026-dumbbell-nan-kilo-moteru","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Этти","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Потерянные в звёздном свете","rating":null,"tier":"unrated","review":"","desc":"Нанъён Джу — учёная, чья мама-астронавт не смогла вернуться на Землю, когда что-то пошло не так во время исследования Марса. Нанъён всегда мечтала о космосе и лелеет надежду однажды отправиться на Марс, чтобы найти хоть какой-то след своей матери.Её мечта сбывается, когда её отбирают в состав экипажа для марсианской экспедиции. Но перед стартом она знакомится с Джеем — музыкантом, который к тому же занимается починкой старых звуковых приборов. А свело их вместе старенькое проигрывающее устройство, доставшееся Нанъён в наследство от матери.","poster":"https://image.tmdb.org/t/p/w500/nUxBCfw8BGjZZcn6byAgRNcnHbl.jpg","url":"https://shikimori.one/animes/61595-i-byeol-e-pil-yohan","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Фантастика"],"episodes":1,"kind":"ona","franchise":null},{"title":"Звёздное дитя 3","rating":100,"tier":"masterpiece","review":"","desc":"Анонсированный третий сезон популярного аниме «Звёздное дитя». История продолжается после событий второго сезона — расследование тайн шоу-бизнеса, месть Аквы и восхождение новой айдол-группы B-Komachi под руководством Руби.","poster":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx182587-fsU8LOjmd7oj.jpg","url":"https://shikimori.one/animes/60058-oshi-no-ko-3rd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Сверхъестественное","Сэйнэн"],"episodes":11,"kind":"tv","franchise":"oshi_no_ko"},{"title":"Быть героем Икс","rating":100,"tier":"masterpiece","review":"","desc":"Героями не рождаются, героями становятся! Эти слова вдвойне справедливы для альтернативного мира, в котором героем может стать каждый, а, точнее, любой человек, заслуживший достаточное количество людского доверия. Как узнать, что ты способен на подвиги и заработал достаточное количество уважения? Очень просто. Разнообразные данные, касающиеся общественного мнения, рейтинги популярности и прочие важные сведения по конкретному индивидууму автоматически собираются, анализируются и отображаются на специальном девайсе, который можно носить на запястье.        \n        Стоит только набрать нужное количество баллов доверия, и самый обычный человек может обрести суперспособности и перевоплотиться в супергероя, который спасёт мир!","poster":"https://shikimori.io/system/animes/original/53447.jpg?1713562770","url":"https://shikimori.one/animes/53447-tu-bian-yingxiong-x","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Супергероика","Комедия"],"episodes":24,"kind":"ona","franchise":null},{"title":"Благоухающий цветок расцветает с достоинством","rating":100,"tier":"masterpiece","review":"","desc":"В тихом городке, где государственная школа Тидори и закрытая академия Кикё соседствуют, их ученики живут словно в разных мирах. Тидори — это школа «грубой силы»: вечные драки на переменах и хулиганы с устрашающими лицами. , шестнадцатилетний ученик Тидори, вполне привык к репутации «страшного парня» и беззаботно проводит дни в компании верных друзей, помогая по вечерам в семейной кондитерской.        \n        Однажды в лавку Цумуги заходит таинственная покупательница, но, смущённая, уходит прежде, чем он успевает обратиться к ней. Наутро он обнаруживает записку, в которой девушка — , ученица престижной девичьей академии Кикё — признаётся, что вовсе не испугалась его внешности, а напротив, нашла его добрым и искренним. Для Ринтаро это кажется невероятным: как может ученица элитной школы оценить ученика из «гнезда хулиганов»?        \n        Первая встреча переворачивает мир обоих подростков: под масками социального статуса и предрассудков начинают пробиваться тёплые чувства и желание понять друг друга. Несмотря на враждебность, царящую между Тидори и Кикё, и недоверие ровесников, Ринтаро и Каоруко решают преодолеть барьеры: от школьных коридоров до собственных страхов. Их история — это нежная, проникновенная драма о том, как искренность и взаимное уважение способны расцветать, подобно самому благородному цветку, даже в самых неприветливых условиях.","poster":"https://shikimori.io/system/mangas/original/144267.jpg?1712757061","url":"https://shikimori.one/animes/59845-kaoru-hana-wa-rin-to-saku","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Школа","Драма","Повседневность"],"episodes":13,"kind":"tv","franchise":null},{"title":"Рубеж Шангри-Ла 2","rating":100,"tier":"masterpiece","review":"ну меня после каждой серии мурашило нахуй че сказать","desc":"С тех пор как Ракуро Хидзутомэ, он же Санраку, начал играть в мегапопулярную виртуальную игру «Рубеж Шангри-Ла», он по-настоящему в неё влюбился. Обычные игроки только мечтают хотя бы взглянуть на одного из семи уникальных, почти непобедимых монстров — а Санраку уже успел одолеть двоих! Такого не ожидал никто.\n\nТеперь, чтобы продвинуть сюжет, наш герой отправляется в приключение со своей зайцеобразной проводницей Эмуль. Цель — раздобыть магический боевой модуль в древней мастерской. Задача, казалось бы, плёвая, особенно когда с тобой клановые соратники: Това «Артур Пенсилгон» Аманэ и Кэй «ОйКацо» Уоми. Вот только у этих двоих, похоже, имеется свой интерес — и вряд ли они помогают Санраку по доброте душевной.\n\nНо даже так: новые знания, ценные союзники и битвы с мощнейшими боссами. Вникая в тайны игрового мира, Санраку вполне способен перевернуть «Рубеж Шангри-Ла» с ног на голову. И кто знает — может быть, именно он навсегда изменит эту игру? А заодно и сам изменится… хотя вряд ли — он же заядлый игроман.","poster":"https://shikimori.io/system/animes/original/58572.jpg?1711887230","url":"https://shikimori.one/animes/58572-shangri-la-frontier-kusoge-hunter-kamige-ni-idoman-to-su-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Детектив"],"episodes":25,"kind":"tv","franchise":"shangri_la_frontier"},{"title":"Полное исследование","rating":100,"tier":"masterpiece","review":"АХУЕННОЕ, КРАСИВОЕ, СКАЗОЧНОЕ","desc":"С малолетства мечтая работать аниматором, Нацуко Хиросэ устроилась на студию сразу после окончания старшей школы и мгновенно построила карьеру, став режиссёром. Её первая работа о боевых девочках-волшебницах была признана гениальной и стала хитом. На очереди новый шедевр — фильм о первой любви.        \n        Однако проект не движется с места: не испытавшая влюблённости Нацуко, не может ухватить за хвост концепцию романтики. Сроки горят, а прогресса нет никакого. Нервничают все: продюсер Наоми Фукусима, коллеги Нацуко, зрители, и только она сама пребывает в какой-то прострации. А тут ещё известие о смерти режиссёра, снявшего в своё время провалившийся в прокате аниме-фильм «Сказание о погибели».        \n        И вот так погружённая в неясные размышления Нацуко не глядя съедает просроченную пищу, захрипев, падает на пол, теряет сознание и… оказывается в мире «Сказания о погибели».","poster":"https://shikimori.io/system/animes/original/58502.jpg?1711127172","url":"https://shikimori.one/animes/58502-zenshuu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика","Драма","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Перерождение мужчины средних лет в дочь дворянина","rating":100,"tier":"masterpiece","review":"Очень интерессное, и сюжет не гавна. И персонажи классные. И рисовка приятная. Жду 2 сезон","desc":"Умудрённый жизненным опытом и годами службы, 52-летний Кэндзабуро Тондабаяси никак не ожидал, что его, как какого-нибудь сопливого школьника, отправит в другой мир Грузовик-сан. Несмотря на возраст, способности к психологической адаптации у почти-пенсионера на высоте! Он довольно легко смирился с тем фактом, что оказался не где-нибудь, а в теле юной злодейки-аристократки Грейс Оверн, имя которой ему почему-то знакомо. Поскрёбшись в памяти, Кэндзабуро осознал, что Грейс Оверн — персонаж отомэ-игры, в которую недавно играла его дочь. Она-то как раз и посвятила полюбопытствовавшего отца в некоторые детали и общую завязку истории.        \n                \n        Выдрессированный законами корпоративной этики, Кэндзабуро всерьёз отнёсся к своей новой роли и твёрдо намерен следовать требованиям сюжета. Пусть он и в игре, но и играть следует по правилам! Так что теперь он изо всех сил будет стараться вести себя как типичная злодейка из высшего света, вот только… его представления о гордости аристократии, врождённая японская вежливость и накопленная с возрастом мудрость заставляют его действовать несколько иначе, чем предполагалось сценаристами игры. Справится ли новоиспечённая дворянка со своей ролью?","poster":"https://shikimori.io/system/animes/original/57719.jpg?1712218596","url":"https://shikimori.one/animes/57719-akuyaku-reijou-tensei-ojisan","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Школа","Сэйнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Вайолет Эвергарден. Фильм","rating":100,"tier":"masterpiece","review":"","desc":"Вайолет продолжает помогать другим людям писать письма, выражая все чувства клиентов на бумаге. Однако она всё никак не может забыть о майоре Гилберте Бугенвиллее, который однажды дал ей возможность понять, что же значит «Я люблю тебя» и шанс начать жизнь с чистого листа.        \n        Однажды она встречает старшего брата Гилберта — Дитфрида, который всё твердит ей позабыть о прошлом, связанным с майором, и идти навстречу будущему, но она, конечно же, понимает, что это крайне трудно смириться с потерей дорогого человека и подавить огромную боль в душе. Вскоре после этого поступает заказ от очередного клиента, а на складе почтового отделения оказывается письмо без адреса получателя. Достигнет ли Вайолет цели, и что ждёт девушку в дальнейшем?","poster":"https://shikimori.io/system/animes/original/37987.jpg?1711979789","url":"https://shikimori.one/animes/37987-violet-evergarden-movie","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Драма","Фэнтези"],"episodes":1,"kind":"movie","franchise":"violet_evergarden"},{"title":"Дандадан","rating":40,"tier":"exceeded","review":"","desc":"Хотите узнать, что будет, если взять внучку экстрасенса, неверящую в НЛО, и фаната уфологии, который и думать не желает о призраках? А будет самое настоящее испытание на храбрость или, скорее, испытание верой, во время которого каждый из них захочет показать другому ту сторону реальности, о которой второй даже не задумывался. А вот если эти самые призраки и пришельцы начнут активно на них нападать, то из такого сочетания несочетаемого вполне может получиться достойная команда!        \n                \n        Это история о популярной красавице Момо Аясэ и типичном заучке Кэне Такакуре — старшеклассниках, которые вынуждены бороться с чёрт пойми кем во имя их собственного целомудрия и спокойствия на планете Земля!","poster":"https://shikimori.io/system/animes/original/57334.jpg?1716838813","url":"https://shikimori.one/animes/57334-dandadan","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Сверхъестественное","Сёнэн"],"episodes":12,"kind":"tv","franchise":"dandadan"},{"title":"Звёздное дитя","rating":100,"tier":"masterpiece","review":"","desc":"Красная ковровая дорожка, яркие вспышки фотоаппаратов, восторженные вскрики поклонников! Наверняка каждый хоть раз в жизни мечтал прославиться: стать знаменитым музыкантом, востребованным актёром или популярным певцом. Только вот путь становления звездой тернист, и лишь немногим удаётся осуществить мечту. Но что, если двери в шоу-бизнес были бы открыты с самого начала?        \n                \n        Аквамарин и Руби ] — дети популярной певицы Ай Хосино. Им не составило труда начать карьеру и влиться в развлекательную индустрию, ведь они с самого начала являлись её частью. Пускай близнецы с рождения принадлежат миру грёз и им суждено стать идолами, знают ли они, что главное оружие в этой сфере — ложь, а яркий свет софитов скрывает тёмные стороны шоу-бизнеса? Чтобы выжить в этом блистательном мире и раскрыть главную тайну их матери, Аквамарину и Руби тоже придётся надеть маски и смиренно играть свои роли.","poster":"https://shikimori.io/system/animes/original/52034.jpg?1711937183","url":"https://shikimori.one/animes/52034-oshi-no-ko","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Сверхъестественное","Сэйнэн"],"episodes":11,"kind":"tv","franchise":"oshi_no_ko"},{"title":"Звёздное дитя 2","rating":100,"tier":"masterpiece","review":"","desc":"Красная ковровая дорожка, яркие вспышки фотоаппаратов, восторженные вскрики поклонников! Наверняка каждый хоть раз в жизни мечтал прославиться: стать знаменитым музыкантом, востребованным актёром или популярным певцом. Только вот путь становления звездой тернист, и лишь немногим удаётся осуществить мечту. Но что, если двери в шоу-бизнес были бы открыты с самого начала?        \n                \n        Аквамарин и Руби ] — дети популярной певицы Ай Хосино. Им не составило труда начать карьеру и влиться в развлекательную индустрию, ведь они с самого начала являлись её частью. Пускай близнецы с рождения принадлежат миру грёз и им суждено стать идолами, знают ли они, что главное оружие в этой сфере — ложь, а яркий свет софитов скрывает тёмные стороны шоу-бизнеса? Чтобы выжить в этом блистательном мире и раскрыть главную тайну их матери, Аквамарину и Руби тоже придётся надеть маски и смиренно играть свои роли.","poster":"https://shikimori.io/system/animes/original/55791.jpg?1711701998","url":"https://shikimori.one/animes/55791-oshi-no-ko-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Сверхъестественное","Сэйнэн","Искусство"],"episodes":13,"kind":"tv","franchise":"oshi_no_ko"},{"title":"Меч и жезл Вистории","rating":100,"tier":"masterpiece","review":"","desc":"Мир, в котором живёт Уилл Серфорт, некогда был погружен в кромешную тьму. Тяжёлое положение людей облегчили пять магов, известных как Магия Венде, которые, собравшись, создали купол, похожий на небосвод и защищающий территорию от демонов. С тех пор выдающиеся волшебники стараются добиться этого звания, чтобы продолжать поддерживать магию купола и когда-нибудь освободить людей от демонов.        \n                \n        Несмотря на то, что у Уилла нет ни капли магии, он тоже жаждет стать Магия Венде и для этого поступил в магическую академию. Всё потому, что не хочет расставаться со своей возлюбленной Эльфарией, которая уже заняла своё место среди пятёрки лучших магов. Уилл старается изо всех сил, но он всего лишь талантливый воин в мире, где магия ценится превыше всего.","poster":"https://shikimori.io/system/animes/original/58059.jpg?1715110377","url":"https://shikimori.one/animes/58059-tsue-to-tsurugi-no-wistoria","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Сёнэн"],"episodes":12,"kind":"tv","franchise":"wistoria"},{"title":"Перерождение в аристократа со способностью анализа 2","rating":100,"tier":"masterpiece","review":"АПУПЕННО, я даже плакал моментами!! КРУТО КРУТО очень хорошо!","desc":"В мире, где меч и магия определяют силу, Арс Ловент находит свой путь в другом. Переродившись в теле юного дворянина, он не получил ни выдающегося таланта к фехтованию, ни мощного магического дара. Единственное его преимущество — навык «Оценка», позволяющий видеть скрытый потенциал людей и предметов. Благодаря этому дару он уже сумел собрать вокруг себя верных союзников, чьи способности дополняют его стратегический ум.\n\nПротивостояние за пост губернатора герцогства Миссиан между Кураном Саламакией и Васмарком Саламакией вступает в новую фазу. Арс, чьи земли находятся в центре этого конфликта, впервые отправляется на поле боя в составе армии Курана — союзника, чья победа напрямую влияет на выживание его владений. Война становится реальностью, и теперь каждое его решение, каждое назначение и каждый анализ талантов могут склонить чашу весов.","poster":"https://image.tmdb.org/t/p/w500/bRb6OBP1uZB4ofNEChU0plsaYVb.jpg","url":"https://shikimori.one/animes/59131-tensei-kizoku-kantei-skill-de-nariagaru-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай","Военное","Магия"],"episodes":12,"kind":"tv","franchise":"kantei_skill"},{"title":"Провожающая в последний путь Фрирен","rating":100,"tier":"masterpiece","review":"","desc":"Эльфийская волшебница Фрирен, в прошлом одолевшая Короля демонов вместе со своими героическими товарищами Химмелем, Хайтером и Айзеном, продолжает странствовать по миру. Пытаясь лучше понять чувства людей и исполнить последние желания ушедших друзей, Фрирен отправляется в путешествие со своей ученицей Ферн и воином Штарком.","poster":"https://shikimori.io/system/animes/original/52991.jpg?1705662788","url":"https://shikimori.one/animes/52991-sousou-no-frieren","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Фэнтези","Сёнэн"],"episodes":28,"kind":"tv","franchise":"frieren"},{"title":"Провожающая в последний путь Фрирен 2","rating":100,"tier":"masterpiece","review":"","desc":"Продолжение странствий эльфийской волшебницы Фрирен, в прошлом одолевшей Короля демонов вместе с героем Химмелем, священником Гайтером и воином Айзеном. Пытаясь лучше понять человеческие чувства и исполнить последние желания ушедших друзей, Фрирен вместе со своей ученицей Ферн и молодым воином Штарком держит путь дальше на север — к легендарному месту упокоения душ Ауриоле, где, по преданиям, можно вновь поговорить с теми, кого уже нет в живых.","poster":"https://image.tmdb.org/t/p/w500/1TtrtRIwXz5BB0gXEl8zgBypl9c.jpg","url":"https://shikimori.one/animes/59978-sousou-no-frieren-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Драма","Магия","Сёнэн"],"episodes":10,"kind":"tv","franchise":"frieren"},{"title":"Меч и жезл Вистории 2","rating":100,"tier":"masterpiece","review":"","desc":"Второй сезон аниме-адаптации «Меч и жезл Вистории». Уилл Серфорт, лишённый магических способностей, но обладающий непревзойдённым мастерством фехтования, продолжает свой путь к вершине магического мира, чтобы исполнить данное обещание.","poster":"https://image.tmdb.org/t/p/w500/hM00JrQlrfI0wTSweYDMLUMcv8u.jpg","url":"https://shikimori.one/animes/59983-tsue-to-tsurugi-no-wistoria-season-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Сёнэн"],"episodes":12,"kind":"tv","franchise":"wistoria"},{"title":"Кайдзю 8 2","rating":90,"tier":"exceeded","review":"","desc":"Второй сезон аниме «Кайдзю номер восемь». Японию продолжают терроризировать гигантские монстры-кайдзю. 32-летний Кафка Хибино, получивший способность превращаться в сверхмощного человекоподобного кайдзю, продолжает службу в третьем подразделении Сил обороны Японии вместе с Миной Асиро и Рэно Итикавой, защищая людей от смертельной угрозы.","poster":"https://shikimori.io/system/animes/original/52588.jpg?1717955244","url":"https://shikimori.one/animes/59177-kaijuu-8-gou-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Военный","Сёнэн"],"episodes":11,"kind":"tv","franchise":"kaiju_8"},{"title":"Безымянная память","rating":90,"tier":"exceeded","review":"","desc":"Из-за проклятия, наложенного коварной ведьмой безмолвия, наследный принц Оскар не может иметь детей. В поисках решения он отправляется на поиски Тинаши, легендарной ведьмы, которая, как говорят, может помочь. После покорения смертельно опасной башни и встречи с ведьмой, выясняется, что только женщина с выдающимися магическими способностями может дать ему потомство. Оскар предлагает Тинаше стать его женой, что решило бы его проблему, но та отказывается. Тем не менее, принц уговаривает её пожить с ним год, чтобы попытаться разорвать проклятие или заключить брак.","poster":"https://shikimori.io/system/animes/original/53835.jpg?1718812093","url":"https://shikimori.one/animes/53835-unnamed-memory","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Романтика"],"episodes":12,"kind":"tv","franchise":"nameless_memory"},{"title":"Повелитель тайн: Клоун","rating":90,"tier":"exceeded","review":"имба, просто имба","desc":"Мир вступил в новую эру: дымящиеся трубы, ревущие машины, броненосцы и дирижабли прокладывают путь прогрессу. Но за завесой пара и железа прячется нечто иное — потустороннее, древнее, шепчущее в тени о тайнах, которые человечество предпочло бы забыть.        \n                \n        Чжоу Минжуй просыпается не в своём теле и не в своём времени. Его новое имя — Клейн Моретти, и он живёт в мире, напоминающем викторианскую эпоху, где магия и наука идут рука об руку. Здесь пророчества пишутся кровью, судьбы вершатся при помощи ритуалов, а зелья потусторонних даруют силу и открывают двери, которые лучше бы остались закрыты. По мере того как Клейн погружается в этот мир, он оказывается между двумя силами: ортодоксальными церквями и таинственными культами, теперь каждый шаг — это сделка с неизвестным. Клейн сделал выбор — не бежать, не прятаться, а взглянуть в самую суть мира, распутать клубок предзнаменований и теней. Он стал Провидцем — тем, кто ищет истину сквозь иллюзии, кто читает мир, словно книгу, и в каждом знаке видит больше, чем просто совпадение. Тайны множатся, свет меркнет, но его путь лишь начинается.","poster":"https://shikimori.io/system/animes/original/49818.jpg?1716302836","url":"https://shikimori.one/animes/49818-guimi-zhi-zhu-xiaochou-pian","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Детектив","Сверхъестественное","Триллер"],"episodes":13,"kind":"ona","franchise":null},{"title":"Магическая битва 3","rating":90,"tier":"exceeded","review":"","desc":"Действие аниме происходит в мире, где люди оказались вовсе не последним звеном в пищевой цепи, и любой ничего не подозревающий обыватель при должной доле невезения может оказаться съеденным демонами, которые воплощают собой негативные человеческие эмоции. Таких созданий называют проклятиями. Пускай люди в большинстве своём не догадываются о существовании проклятий, те имеют уже давнюю историю, одним из эпизодов которой являются деяния легендарного демона Сукуны Рёмэна, которого с большим трудом удалось одолеть. Его тело было поделено на двадцать частей, которые оказались разбросаны по миру. Если найдётся некто, кто поглотит все фрагменты его плоти, то он обретёт мощь, способную уничтожить современную цивилизацию.        \n        Вот такая сложилась ситуация в мире, где в полном неведении о нависшей над человечеством угрозе проживает старшеклассник Юдзи Итадори. У Юдзи совершенно иные заботы: он каждый день навещает дедушку в больнице и отбрыкивается от спортивных кружков, которые мечтают заполучить его из-за выдающейся физической силы и выносливости. Юдзи предпочёл вступить в клуб оккультных наук, с которого и начались все неприятности, когда в руки членов клуба попал таинственный предмет, на который наложено проклятье. Не долго думая, школьники разбили запечатывающее заклинание и выпустили на свет ужасные силы.","poster":"https://shikimori.io/system/animes/original/40748.jpg?1711956606","url":"https://shikimori.one/animes/57658-jujutsu-kaisen-shimotsuki-hen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Школа","Сёнэн"],"episodes":12,"kind":"tv","franchise":"jujutsu_kaisen"},{"title":"Поднятие уровня в одиночку 2: Восстань из тени","rating":85,"tier":"exceeded","review":"Всё хорошо, всё прикольно, персонажи прикольные","desc":"Благодаря новообретённой профессии — Монарх Теней, дающей власть над теневой армией, Сон Джину становится достаточно сильным, чтобы наконец отправиться в Дьявольский Замок. Его цель — найти три предмета, необходимые для создания Эликсира Жизни, единственного средства, способного излечить болезнь его матери [character=173977 кёнхе-пак]Кёнхе[/character].\nТем временем гигантские муравьи, населяющие печально известный остров Чеджу, начинают отращивать крылья. Это означает, что вскоре они смогут представлять серьёзную угрозу и за пределами острова. «Время пришло. Больше ждать нельзя». Ассоциация Охотников Кореи при поддержке S-ранговых охотников из Японии планирует четвёртый — решающий рейд на остров Чеджу, чтобы покончить с угрозой раз и навсегда.\nДостигнет ли Сон Джину своей цели? И останется ли он в стороне, если даже сильнейшим охотникам остров может оказаться не по зубам?","poster":"https://shikimori.io/system/animes/original/58567.jpg?1711833968","url":"https://shikimori.one/animes/58567-ore-dake-level-up-na-ken-season-2-arise-from-the-shadow","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Приключения","Сверхъестественное"],"episodes":13,"kind":"tv","franchise":"solo_leveling"},{"title":"Голубая шкатулка","rating":81,"tier":"exceeded","review":"Красивое приятное, гг не даун","desc":"«Каждое утро... есть один человек, которого я всегда очень хочу увидеть»        \n        Тайки Иномата учится в школе со спортивным уклоном «Эймэй» и состоит в команде по бадминтону. Каждое утро Тайки стремится первым попасть в спортзал, который всегда открыт для желающих лишний раз потренироваться, но, как бы он ни старался, там всегда есть, кому поприветствовать его. Когда-то Тинацу Кано, раз за разом отрабатывающая баскетбольные броски по утрам, была для Тайки не более чем примером для подражания, но сейчас она главная мотивация для раннего подъёма и дополнительных тренировок. И, хоть Тинацу и кажется недосягаемой звездой, Тайки намерен сделать всё, чтобы однажды дотянуться до неё. Однако... кто мог ожидать, что расстояние между ними сократится в самом прямом смысле?!","poster":"https://shikimori.io/system/animes/original/57181.jpg?1716148111","url":"https://shikimori.one/animes/57181-ao-no-hako","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Спорт","Школа","Сёнэн"],"episodes":25,"kind":"tv","franchise":null},{"title":"Восхождение героя щита 4","rating":80,"tier":"exceeded","review":"","desc":"Наофуми Иватани вместе с тремя другими людьми был призван в параллельный мир, чтобы стать его героем. При переносе каждый из них получил специальную экипировку, которая соответствует типу героя. Наофуми достался легендарный щит, и парень решил отправиться в путешествие по сказочному миру.         \n        Но уже в самом начале пути у него возникли проблемы.        \n        Не обладающий выдающейся харизмой, парень к тому же оказался совсем не готов к геройским деяниям, поэтому сразу получил прозвище слабейшего из призванных.         \n        Брошенного другими героями, Наофуми в результате ограбили и подставили. А затем начали остерегаться все кому не лень: и крестьяне, и даже король. Сильные мира сего обратились во врагов, и неудачливый герой потерял веру в людей. Но кое-что всё-таки изменилось — он преисполнился гневом и желанием отомстить.","poster":"https://shikimori.io/system/animes/original/35790.jpg?1711976737","url":"https://shikimori.one/animes/57732-tate-no-yuusha-no-nariagari-season-4","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":"shield_hero"},{"title":"Эта фарфоровая кукла влюбилась 2","rating":80,"tier":"exceeded","review":"","desc":"Застенчивый старшеклассник по имени Вакана с детства грезит о том, чтобы стать мастером изготовления традиционных японских кукол. И неспроста, ведь дедушка парня добрую половину жизни отдал этому ремеслу. К сожалению, как бы Вакана ни старался, а освоить главное — создание кукольных голов — ему никак не удаётся. Зато в пошиве миниатюрной одежды он, кажется, уже весьма преуспел... и не думал не гадал, что именно это поможет ему сблизиться с одноклассницей — красавицей Марин Китагавой.        \n        Всегда весёлая, общительная и такая недосягаемая, девушка, как оказалось, имеет не менее странное, чем у Ваканы, увлечение — эроге-игры и косплей персонажей из них. Едва узнав, что парень умеет обращаться со швейной машинкой, красотка тут же вгрызается в него мёртвой хваткой и, прилагая всё своё очарование, просит сшить для неё костюм.        \n        А вот в одних ли умениях дело или, быть может, тут замешано что-то ещё, будущему мастеру-кукольнику только предстоит узнать, попутно открыв для себя простую истину: вовсе не важно, чем ты увлечён, главное — что это тебе по душе!","poster":"https://shikimori.io/system/animes/original/48736.jpg?1708765101","url":"https://shikimori.one/animes/53051-sono-bisque-doll-wa-koi-wo-suru-zoku-hen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Школа","Сэйнэн"],"episodes":12,"kind":"tv","franchise":"sono_bisque_doll"},{"title":"Реинкарнация безработного: История о приключениях в другом мире 2. Часть 2","rating":80,"tier":"exceeded","review":"","desc":"Рудеус начинает жить мирной жизнью: покупает дом, женится на Сильфиетте и весело проводит время, переживая приключения вместе с товарищами из Академии магии. Всё идёт хорошо, однако счастье не может длиться вечно.\nТихим вечером приходит письмо от Гиса, в котором говорится, что спасательная группа во главе с Полом Грейратом так и не смогла отыскать Зенит. Поиски зашли в тупик, группе необходима помощь. Если Рудеус согласится отправиться в путь, то на долгое время покинет дом, уже ставший ему родным, и будет разлучён с Сильфиеттой, которая ждёт ребёнка.\nПеред Рудеусом, который ещё вчера был уверен, что наконец осуществил свою мечту, встаёт сложный выбор.","poster":"https://shikimori.io/system/animes/original/55888.jpg?1718617531","url":"https://shikimori.one/animes/55888-mushoku-tensei-ii-isekai-ittara-honki-dasu-part-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Исекай","Фэнтези","Приключения","Драма","Магия"],"episodes":12,"kind":"tv","franchise":"mushoku_tensei"},{"title":"Рубеж Шангри-Ла","rating":78,"tier":"exceeded","review":"","desc":"Как правило, у старшеклассников насыщенная загруженная жизнь: одни добиваются успехов в спорте, вторые усиленно вгрызаются в гранит науки, третьи ищут романтики и любви. Всё это не имеет никакого отношения к Ракуро Хидзутомэ. Его интересует лишь одна на свете вещь — прохождение самых отстойных из наиотстойнейших компьютерных игр. Их иногда непросто разыскать, но стоит Ракуро натолкнуться на такую, и он с наслаждением и азартом проходит её до конца. Навыки игры у него непревзойдённые, и нет настолько дрянной игры, чтобы он отказался в неё играть.        \n                \n        Поэтому когда в руки уверенного в себе Ракуро попадает новая виртуальная игра под названием «Рубеж Шангри-Ла», он недолго думая запускает её и пропускает предисловие, чтобы поскорей ринуться в бой! Ракуро, несомненно, эксперт, но и игра не так проста, как может показаться. Сумеет ли Ракуро, взявший себе псевдоним Санраку, дойти до финала и раскрыть все секреты Шангри-Ла?","poster":"https://shikimori.io/system/animes/original/52347.jpg?1710839889","url":"https://shikimori.one/animes/52347-shangri-la-frontier-kusoge-hunter-kamige-ni-idoman-to-su","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Сёнэн"],"episodes":25,"kind":"tv","franchise":"shangri_la_frontier"},{"title":"Дни Сакамото 2","rating":50,"tier":"exceeded","review":"","desc":"Таро Сакамото — живая легенда в мире профессиональных киллеров. До недавних пор у него были только преданные фанаты да враги... а теперь появилась и любимая девушка, которая строго наказала завязывать с убийствами! Ну, Сакамото долго не думал и ради свадьбы с любовью всей своей жизни отбросил криминальное прошлое, а затем поднабрал вес и посвятил себя семейному магазину и воспитанию любимой дочки.        \n        Однако у мира киллеров на Сакамото свои планы, бывшие коллеги не собираются дать ему просто так уйти. Сможет ли Сакамото, растерявший прежнюю форму, защитить себя и своих близких?!","poster":"https://shikimori.io/system/animes/original/58939.jpg?1716816957","url":"https://shikimori.one/animes/58939-sakamoto-days","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика"],"episodes":11,"kind":"tv","franchise":"sakamoto_days"},{"title":"Лазарь","rating":50,"tier":"exceeded","review":"Очнь хорошо","desc":"2052 год. Мир достиг невиданного процветания благодаря «Хапуне» — универсальному лекарству избавляющему от боли и болезней. Его создатель гениальный доктор  исчез сразу после запуска препарата.        \n        Три года спустя он возвращается с пугающим заявлением: у «Хапуны» есть скрытый побочный эффект — все, кто её принимал скоро умрут. Человечеству грозит массовая гибель и чтобы предотвратить катастрофу создаётся элитный отряд «Лазарь» — пятеро агентов со всего мира. Их миссия: найти доктора и создать спасительную вакцину пока не стало слишком поздно.","poster":"https://shikimori.io/system/animes/original/56038.jpg?1713655004","url":"https://shikimori.one/animes/56038-lazarus","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Комедия","Приключения"],"episodes":13,"kind":"tv","franchise":null},{"title":"Дисквалифицирован по жизни","rating":50,"tier":"exceeded","review":"","desc":"О чём может мечтать взрослый половозрелый мужчина, как не о радушной компании очаровательных юных дев? А если он ещё и в другом мире, попав в который приобрёл суперспособности, как в компьютерной игре? «За такое счастье и помереть не жалко!» — подумал бы любой отаку и уставший от будней клерк. Но только не Сэнсэй! Его депрессивная писательская натура требует совсем иных развлечений, например, немедленной трагической смерти. Да и как он может грезить о таком повороте судьбы, как перерождение, если жил задолго до той эпохи, когда изобрели видеоигры и выдумали сюжеты о реинкарнации в других мирах?        \n                \n        Тем не менее, в 1948 году Сэнсэй случайно очутился в ином мире. Решив отыскать идеальное место для собственной кончины, он пустился в путь, но то и дело оказывался втянут в какие-то совершенно неуместные необыкновенные приключения. Писатель ищет смерти, а не авантюр и удовольствий. Однако как он ни подставляется под удар врага, как ни бросается на амбразуру наперекор опасности, в итоге — выходит сухим из воды. Это история о жалком, несчастном человеке, который жаждет конца, а вместо этого становится героем.","poster":"https://shikimori.io/system/animes/original/52367.jpg?1714589122","url":"https://shikimori.one/animes/52367-isekai-shikkaku","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Я перевоплотился в 7 принца так что буду … 2","rating":40,"tier":"exceeded","review":"","desc":"Простолюдин, мечтавший овладеть магией, после гибели от рук дворян переродился в теле Ллойда де Салума , седьмого принца королевства ]. Теперь, обладая воспоминаниями из прошлой жизни и необходимым магическим талантом, Ллойд погружается в изучение и открытие новых заклинаний, двигаясь навстречу своей мечте. Однако жизнь принца наполнена своими сложностями: Ллойду предстоит столкнуться с политическими интригами, коварными врагами и неожиданными союзниками. Но что бы ни ждало его впереди, юный принц твёрдо намерен совершенствовать свою магию так, как ему заблагорассудится!","poster":"https://shikimori.io/system/animes/original/53516.jpg?1718207142","url":"https://shikimori.one/animes/53516-tensei-shitara-dainana-ouji-datta-node-kimama-ni-majutsu-wo-kiwamemasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"],"episodes":12,"kind":"tv","franchise":"tensei_7_prince"},{"title":"Подземелье вкусностей","rating":30,"tier":"exceeded","review":"","desc":"«Голод не тётка — пирожка не поднесёт» — эту истину не понаслышке знает любой авантюрист, бывающий в подземелье и вынужденный таскать с собой огромный запас провианта. Это довольно серьёзная проблема, ведь количество еды полностью диктует длительность путешествия. Мало того, в подземелье на каждом шагу встречаются опасности и кровожадные монстры, готовые слопать зазевавшегося искателя приключений вместе с потрохами, снаряжением и товарищами. В таких условиях чаще приходится беспокоиться не о еде, а о том, чтобы не стать ею.        \n                \n        Именно эта напасть случилась с сестрой Лая Тордена, Фалин, угодившей в пасть дракона. К счастью, маги-воскресители работают исправно, так что Фалин вполне можно спасти, но действовать необходимо в большой спешке. Понимая, что нужно торопиться, Лай, едва выведя свой отряд наружу, отправился назад, приняв решение не тратить время на закупку продовольствия.        \n                \n        Вполне логично, вот только сестроядный дракон обитает аж на третьем этаже подземелья. Путь туда неблизкий, а оздоровительное голодание в условиях постоянных сражений не вариант. Что же делать? Ответ прост: пора осознать, что необязательно любить монстров, главное — уметь их правильно готовить!","poster":"https://shikimori.io/system/animes/original/52701.jpg?1717859891","url":"https://shikimori.one/animes/52701-dungeon-meshi","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Комедия","Приключения","Кулинария","Сёнэн"],"episodes":24,"kind":"tv","franchise":null},{"title":"Первородный грех Такопи","rating":30,"tier":"exceeded","review":"окей окей","desc":"Инопланетянин по имени  прилетает на Землю с миссией: «делиться счастьем и дарить окружающим радость». Но его чистое стремление сталкивается с суровой реальностью, полной жестокости и одиночества. Каждая попытка  обрадовать Сидзуке Кудзэ перерастает в новые несчастья. Простая игрушка или невинный совет открывают сотни путей прямиком в бездну.  искренне верит, что способен сделать людей счастливыми, но что делать, если чужая боль слишком глубока, а каждое вмешательство лишь портит и без того тяжёлую жизнь?","poster":"https://shikimori.io/system/mangas/original/142600.jpg?1708887531","url":"https://shikimori.one/animes/60489-takopii-no-genzai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Фантастика"],"episodes":6,"kind":"ona","franchise":null},{"title":"Санда","rating":25,"tier":"exceeded","review":"","desc":"Что заставляет одного подростка напасть на другого с ножом посреди школы? С этого вопроса начинается кошмар второгодки Санды, ставшего жертвой внезапного и жестокого нападения со стороны одноклассницы Сиори Фуюмуры. Поначалу он списывает всё на проблемы переходного возраста, решив, что стал разменной монетой в её внутреннем конфликте.        \n        Очень скоро Санда понимает, что причина лежит гораздо глубже. Фуюмура действовала не на эмоциях — её поступок был продиктован сомнениями, которые буквально разъедали её изнутри. Она видела в Санде не просто жертву, а загадку, которую нужно было разгадать любой ценой.        \n        Оказывается, корень зла — в сомнениях Фуюмуры относительно происхождения самого Санды. Её нападение было чудовищным экспериментом, попыткой докопаться до правды. Так банальная, на первый взгляд, школьная драма превращается в запутанный детектив, где ничто не является тем, чем кажется, а у каждого поступка есть своя скрытая и глубокая причина.","poster":"https://shikimori.io/system/mangas/original/138842.jpg?1712843693","url":"https://shikimori.one/animes/59267-sanda","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Драма","Детектив","Ужасы","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Брачный токсин","rating":25,"tier":"exceeded","review":"","desc":"Мастер ядов  — профессиональный убийца, готовящийся к самому сложному заданию в своей жизни: женитьбе. Вся его предыдущая жизнь была посвящена тренировкам и изучению смертоносных искусств, поэтому в романтических отношениях и искусстве свиданий он совершенно не разбирается.        \n        На помощь приходит  — ловкая мошенница, считающая себя непревзойдённым знатоком любовных дел. Вместе эта необычная пара решает сделать всё возможное, чтобы Гэро обрёл семейное счастье. Однако на пути к цели им предстоит столкнуться с целым преступным миром, который явно не намерен уступать без боя.","poster":"https://shikimori.io/system/mangas/original/146211.jpg?1712770256","url":"https://shikimori.one/animes/62601-marriagetoxin","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Романтика","Драма"],"episodes":13,"kind":"tv","franchise":null},{"title":"Моя геройская академия: Вне закона","rating":22,"tier":"exceeded","review":"прикольная история и красивая","desc":"Герои, получившие лицензию на право защищать мирных жителей от суперзлодеев, считаются настоящей элитой. Но, поскольку не каждый может стать героем, есть и те, кто использует свои силы для служения людям вне рамок закона. Таких личностей люди прозвали линчевателями. Коити Хаймавари, по кличке Ползун, не смог официально стать героем, поэтому использует свою скромную причуду, чтобы совершать добрые поступки в свободное от работы время. Судьбоносная схватка с бандитами вынуждает его объединиться с двумя другими нелегальными героями — уличной артисткой Кадзухо (Поп Степ) и громилой Кастетом. Их история — это не путь к славе, а битва за справедливость в серых зонах закона, где каждый поступок бросает вызов системе, забывшей, что истинный героизм рождается из готовности помочь даже ценой свободы.","poster":"https://shikimori.io/system/mangas/original/99949.jpg?1708923789","url":"https://shikimori.one/animes/60593-vigilante-boku-no-hero-academia-illegals","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Школа"],"episodes":13,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"Дни Сакамото","rating":21,"tier":"exceeded","review":"класнючее аниме, жалко обрвали сезон так быстро","desc":"Таро Сакамото — живая легенда в мире профессиональных киллеров. До недавних пор у него были только преданные фанаты да враги... а теперь появилась и любимая девушка, которая строго наказала завязывать с убийствами! Ну, Сакамото долго не думал и ради свадьбы с любовью всей своей жизни отбросил криминальное прошлое, а затем поднабрал вес и посвятил себя семейному магазину и воспитанию любимой дочки.        \n        Однако у мира киллеров на Сакамото свои планы, бывшие коллеги не собираются дать ему просто так уйти. Сможет ли Сакамото, растерявший прежнюю форму, защитить себя и своих близких?!","poster":"https://shikimori.io/system/animes/original/58939.jpg?1716816957","url":"https://shikimori.one/animes/58939-sakamoto-days","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика"],"episodes":11,"kind":"tv","franchise":"sakamoto_days"},{"title":"Этот глупый свин не понимает мечту Санта-Клауса","rating":20,"tier":"exceeded","review":"","desc":"Сакута Адзусагава выполнил обещание, данное Маи Сакурадзиме: теперь они оба студенты университета и учатся вместе. И всё бы ничего, да только Сакута вновь оказывается втянут в странную историю с необъяснимым феноменом, известным как «подростковый синдром» — явлением, при котором эмоции и переживания подростков становятся причиной сверхъестественных событий. На этот раз оно связано с зимой, рождеством и мечтами, в которые взрослые уже давно перестали верить.        \n        Когда знакомая девушка оказывается в ситуации, где грань между реальностью и фантазией начинает стираться, Адзусагава решает помочь ей разобраться в происходящем. Ему предстоит понять, что скрывается за кажущейся сказкой, и как помочь тому, кто оказался в плену собственных чувств.        \n        Тёплая и одновременно грустная история о чудесах, вере и боли взросления, продолжающая раскрывать мир, где эмоциональные травмы становятся реальностью, а настоящая поддержка важнее любых волшебных подарков.","poster":"https://shikimori.io/system/animes/original/57433.jpg?1717530171","url":"https://shikimori.one/animes/57433-seishun-buta-yarou-wa-santa-claus-no-yume-wo-minai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Сверхъестественное","Школа"],"episodes":13,"kind":"tv","franchise":"seishun_buta_yarou"},{"title":"Маг воды","rating":20,"tier":"exceeded","review":"","desc":"После смерти Рё Михара переместился в другой мир. Перед возрождением ему довелось пообщаться с ангелом Михаэлем, который даровал ему магию воды и другие способности. Расспросив, чего хочет сам Рё и услышав, что тот желает лишь спокойствия и размеренности, Михаэль отправил его в дебри огромного леса.        \n        Рё, однако, не смог долго бездельничать. С одной стороны, работать заставляет нужда (всё-таки кушать хочется и надо противостоять опасным жителям леса), с другой — взыграл врождённый трудоголизм. Потихоньку развивая магию, Рё добился значительного прогресса и заскучал. Отправившись на разведку, он натолкнулся на раненного авантюриста по имени Авель, который попросил помочь ему добраться до ближайшего человеческого поселения.        \n        Так Рё покинул родную обитель и, забыв о своих первоначальных планах, отправился на поиски приключений.","poster":"https://shikimori.io/system/mangas/original/164607.jpg?1718587266","url":"https://shikimori.one/animes/60732-mizu-zokusei-no-mahoutsukai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма","Триллер"],"episodes":12,"kind":"tv","franchise":null},{"title":"Аватар короля 3","rating":20,"tier":"exceeded","review":"","desc":"В многопользовательской онлайн-игре «Слава» Е Сю считался легендарным игроком уровня «профи». Однако по многочисленным причинам Сю вышвырнули из команды. После ухода с профессиональной сцены парень устраивается менеджером в интернет-кафе. Когда «Слава» открывает свой десятый сервер, Сю снова погружается в игру. С десятилетним опытом, воспоминаниями о прошлом и самодельным оружием, его возвращение обещает быть запоминающимся. Кто знает, может так и начинается путь Короля.","poster":"https://shikimori.io/system/animes/original/33926.jpg?1711969864","url":"https://shikimori.one/animes/49559-quanzhi-gaoshou-3rd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":"quanzhi_gaoshou"},{"title":"Кайдзю номер восемь","rating":20,"tier":"exceeded","review":"","desc":"Уже несколько десятилетий Японию терроризируют громадные монстры, которые получили название кайдзю. Они появляются из ниоткуда и не только пожирают людей, но и разрушают целые города. Однако за прошедшие годы наука и техника продвинулись далеко вперёд. Для защиты граждан были созданы элитные войска, которые денно и нощно рискуют своими жизнями ради спасения людей. Благодаря этому противостоять угрозе удаётся довольно успешно. Свой вклад в поддержание мирных будней вносят и специальные клининговые отряды, очищающие улицы от туш убитых монстров.        \n                \n        32-летний профессиональный уборщик Кафка Хибино, когда-то мечтавший вступить в ряды защитников, после нескольких провалов на отборе опустил руки и убедил себя, что его всё устраивает. Кто-то ведь должен и чистоту наводить, верно? «Неверно», — возражает Кафке новенький стажёр Рено Итикава и сообщает коллеге, что возраст для вступления в боевой отряд недавно повысили до 33-х лет. Получается, у Кафки есть один-единственный распоследний шанс стать защитником людей. Шанс-то есть, а вот ни силёнок, ни здоровья в наличии уже нет. Но главное — найти в себе решимость!        \n                \n        «Нашёл!» — сообщил Кафке мелкий летающий кайдзю и залез к нему в рот. Нетренированный Кафка превратился в могучего человекоподобного кайдзю. На которого тотчас начал охоту защитный отряд. Кафка оказался перед дилеммой: с одной стороны, хочет спастись, сбежав от отряда, с другой — хочет стать его частью.","poster":"https://shikimori.io/system/animes/original/52588.jpg?1717955244","url":"https://shikimori.one/animes/52588-kaijuu-8-gou","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Военный","Сёнэн"],"episodes":12,"kind":"tv","franchise":"kaiju_8"},{"title":"Добро пожаловать в класс превосходства 3","rating":20,"tier":"exceeded","review":"","desc":"Зимние каникулы пролетели в один миг, и класс 1-D с новыми силами начал третий семестр. Не успели студенты влиться в учебный процесс, как их внезапно собрали и загрузили в автобусы. Учащиеся первого, второго и третьего годов отправились в школьный лагерь, где по прибытии их ожидал очередной специальный экзамен. Всех перемешали в группы, так что враги стали временными союзниками, а союзники — врагами. Каждого, кто не справится и подведёт команду, ждёт отчисление, что в будущем повлечёт за собой множество неблагоприятных последствий для всего класса. Сейчас единственная цель класса D — получить лучший из возможных результатов и не допустить исключения одноклассников из школы. Что предпримет Киётака? Займёт ли предпочитаемую им нейтральную сторону или же вмешается и поможет ребятам в этой игре на выбывание?","poster":"https://shikimori.io/system/animes/original/51180.jpg?1718592122","url":"https://shikimori.one/animes/51180-youkoso-jitsuryoku-shijou-shugi-no-kyoushitsu-e-3rd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Психология","Школа"],"episodes":13,"kind":"tv","franchise":"classroom_of_the_elite"},{"title":"Непринуждённая жизнь в другом мире экс-кандидата в герои","rating":20,"tier":"exceeded","review":"","desc":"Скромный купец Баназа был призван в другой мир в королевство Крайроад в качестве кандидата в герои, чтобы победить армию тьмы. Однако характеристики призванного оказались настолько заурядными, что ни о каком геройстве не могло быть и речи. Поэтому Баназу, который сменил имя на Флио, выдворили из королевства, так как вернуть его в родной мир возможности тоже нет. Его отправили жить к чёрту на кулички, дав немного денег и снаряжения на первое время.        \n        Никто и подумать не мог, что с получением второго уровня Флио откроет буквально безграничные способности, о которых не смеют мечтать даже сильнейшие маги и авантюристы! Как поступит наш герой с новообретёнными силами, и какие приключения и опасности ждут его на пути?","poster":"https://shikimori.io/system/animes/original/56923.jpg?1718686012","url":"https://shikimori.one/animes/56923-lv2-kara-cheat-datta-motoyuusha-kouho-no-mattari-isekai-life","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Романтика"],"episodes":12,"kind":"tv","franchise":null},{"title":"О моём перерождении в слизь 3","rating":20,"tier":"exceeded","review":"","desc":"Римуру Темпест выходит победителем из решающей схватки с королём демонов Клейманом. С помощью Диабло война с королевством Фалмут завершается в пользу Римуру. Благодаря притоку переселенцев и присоединению леса Джура, государство Темпест начинает стремительно развиваться.[br][br]Победа Римуру меняет расклад сил, открывая новую эру мира — но надолго ли она продлится, вопрос отдельный. Юки Кагуразака и Казалим плетут интриги совместно с Альянсом Харлекин, стремясь любыми способами покончить с Римуру. Более того, Западная святая церковь продолжает свой непримиримый поход против Римуру и его нечеловеческих подданных. И союзники, и враги ведут тонкую игру умов, осторожно продвигая собственные цели, лишь бы не нарушить хрупкое равновесие. Но стоит упасть первой костяшке домино — и начнётся гонка за верховную власть.","poster":"https://shikimori.io/system/animes/original/53580.jpg?1718498771","url":"https://shikimori.one/animes/53580-tensei-shitara-slime-datta-ken-3rd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Фэнтези","Сёнэн"],"episodes":24,"kind":"tv","franchise":"tensei_shitara_slime"},{"title":"Этот замечательный мир! 3","rating":20,"tier":"exceeded","review":"","desc":"Казума Сато [佐藤 和真] — бывший отаку-бездельник, а ныне искатель приключений в другом мире — возвращается домой после событий в деревне Багровых Демонов. И хотя команда стала на шаг ближе к победе над Повелителем Демонов и его полчищами, Казума всеми силами старается отложить выполнение этой миссии, а его команда всё глубже погружаeтся в долги и совершает ошибки на заданиях из-за внезапных авантюр и эксцентричных выходок. Неожиданное приглашение от принцессы, желающей лично узнать о «героических» деяниях его команды, и сопротивление Даркнесс [ダスティネス・フォード・ララティーナ / ダクネス], лишь подогревающее их интерес, побуждают их отправиться во дворец — навстречу новому замечательному приключению с непредсказуемыми последствиями!","poster":"https://shikimori.io/system/animes/original/49458.jpg?1717634812","url":"https://shikimori.one/animes/49458-kono-subarashii-sekai-ni-shukufuku-wo-3","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Пародия"],"episodes":11,"kind":"tv","franchise":"konosuba"},{"title":"Юный лорд — мастер побега","rating":20,"tier":"exceeded","review":"","desc":"Пускай восьмилетний Токиюки Ходзё не блещет талантами, это не мешает ему наслаждаться жизнью, ведь он не кто-нибудь, а следующий наследник по линии сёгунов Камакура. Однако его беззаботному существованию резко пришёл конец, когда Такаудзи Асикага совершил государственный переворот и сверг клан Камакура. От смерти юного принца спас самопровозглашённый священник-пророк Ёрисигэ Сува, и Токиюки смог унести ноги. Однако это не значит, что он теперь в безопасности, наоборот, он стал целью для убийц, которых нанял новый правитель. Чтобы выжить, Токиюки должен не только по-максимуму проявить свой единственный талант — умение хорошо прятаться, но и постараться найти надёжных союзников, которые помогут ему вернуть трон и восстановить сёгунат Камакура во всём его блеске!","poster":"https://shikimori.io/system/animes/original/54724.jpg?1712679389","url":"https://shikimori.one/animes/54724-nige-jouzu-no-wakagimi","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","История","Самураи","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Перерождение в аристократа со способностью анализа","rating":18,"tier":"great","review":"","desc":"Умерев, обычный японский офисный сотрудник переродился в другом мире как дворянин Арс Ловент. Хотя у юного Арса нет таланта ни к магии, ни к мастерству меча, всё же кое-чем похвастаться он может: Арс — единственный обладатель навыка Оценка, с помощью которого он способен определять достоинства и недостатки не только вещей, но и человека.        \n                \n        Такой полезный навык пригодился бы во все времена, но особенно необходим он сейчас, когда ситуация в стране, где проживает Арс, не отличается стабильностью. Государственный аппарат погряз в коррупции, то и дело вспыхивают бунты недовольных жителей, а дворяне укрепляют свои поместья, готовясь к предстоящей войне. Вот и Арс решил, что, чтобы выжить, ему нужно собрать вокруг себя талантливых и сильных людей. Например, иностранца-изгоя, который мастерски владеет мечом; рабыню, обладающую непревзойденным магическим искусством; застенчивого мальчика, жаждущего знаний. Эти одарённые люди обязательно помогут Арсу сохранить в безопасности его земли!","poster":"https://shikimori.io/system/animes/original/55265.jpg?1718586614","url":"https://shikimori.one/animes/55265-tensei-kizoku-kantei-skill-de-nariagaru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"],"episodes":12,"kind":"tv","franchise":"kantei_skill"},{"title":"Три сестры Микадоно оказались неожиданно простыми","rating":15,"tier":"great","review":"","desc":"Романтическая комедия о парне по имени Ю Аясэ, сыне знаменитой актрисы, который всегда считал себя обычным и не слишком талантливым. После смерти матери, Ю вынужден переехать в дом её подруги, где живут три гениальные сестры Микадоно: актриса Кадзуки, чемпионка по боевым искусствам Нико и мастер сёги Мива. Сначала Ю думает, что никогда не сможет сблизиться с такими выдающимися девушками, но постепенно открывает, что за их успехами скрываются простые человеческие чувства и уязвимость, а настоящая семья строится на поддержке и тепле.","poster":"https://shikimori.io/system/mangas/original/142649.jpg?1712772257","url":"https://shikimori.one/animes/59207-mikadono-sanshimai-wa-angai-choroi","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия","Драма"],"episodes":12,"kind":"tv","franchise":null},{"title":"Аля иногда кокетничает со мной по","rating":15,"tier":"great","review":"","desc":"Академия Сэйрэй — элитное учебное заведение, собирающее самых выдающихся учеников Японии. , наполовину русская, наполовину японка, занимает пост казначея студенческого совета. Её отличают острый ум, эффектная внешность и строгий нрав. В отличие от неё, одноклассник  не проявляет рвения к учёбе, предпочитая лениться и казаться равнодушным ко всем окружающим, включая Алю.         \n        Сначала раздражённая его безынициативностью, Алиса постепенно начинает проявлять к Масатике интерес, выражая свои чувства на русском языке. Однако она не знает, что он свободно владеет этим языком, изучив его ради подруги детства, с которой мечтает воссоединиться. Совместное времяпрепровождение сближает Алю и Масатику, превращая их отношения в увлекательную игру с ноткой романтики. Каждому из них предстоит разобраться в своих новых чувствах и узнать, куда приведёт их необычная связь.","poster":"https://shikimori.io/system/animes/original/54744.jpg?1718725558","url":"https://shikimori.one/animes/54744-tokidoki-bosotto-russia-go-de-dereru-tonari-no-alya-san","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Восхождение в тени","rating":15,"tier":"great","review":"","desc":"Кем вы хотели стать в детстве? Известным футболистом? Супергероем? Или, быть может, певцом, собирающим огромную толпу на концертах? Всё это не про нашего главного героя Сида, ведь он всегда восхищался людьми из закулисья, теми, кто почти не предпринимает никаких действий в открытую, а появляется лишь в самый ответственный момент и, сделав дело, бесследно исчезает.         \n                \n        В нашем мире такое трудно провернуть, ведь что ни делай, а против атомной бомбы не попрёшь. И вот, раздумывая о способах отражения ядерного оружия голыми руками, наш герой приходит к умозаключению, что без магии никак. Удобно получилось, ведь вскоре после этого парень встретил пресловутый грузовик, который и отправил его на тот свет, а если быть точнее, то в мир, полный мечей, магии и прочих прелестей фэнтези-вселенных. Уж теперь-то у Сида не будет препятствий на пути к становлению величайшим правителем из тени.","poster":"https://shikimori.io/system/animes/original/48316.jpg?1711956877","url":"https://shikimori.one/animes/48316-kage-no-jitsuryokusha-ni-naritakute","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фэнтези"],"episodes":20,"kind":"tv","franchise":"kage_no_jitsuryokusha"},{"title":"Восхождение в тени 2","rating":15,"tier":"great","review":"","desc":"После происшествия на фестивале Бусин, которое взбудоражило всю страну, главному герою Сиду Кагэно казалось, дали время отдохнуть. Но это было лишь затишье перед бурей, ведь совсем скоро вновь объявилась несносная сестра главного героя, Клэр, которая взяла его с собой в «Беззаконный город» ради охоты на Кровавую Королеву — легендарного вампира-прародителя. Изначально Сид был не в восторге от идеи совместного времяпрепровождения, но осознав, насколько круто это всё звучит, не смог отказать себе в удовольствии поучаствовать. Между тем, трое правителей «Беззаконного» тоже собираются вмешаться в ситуацию, а луна вообще обратилась алым цветом. Что со всем этим будет делать Сид — величайший правитель из тени, которого только видел этот мир?","poster":"https://shikimori.io/system/animes/original/54595.jpg?1710728144","url":"https://shikimori.one/animes/54595-kage-no-jitsuryokusha-ni-naritakute-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":"kage_no_jitsuryokusha"},{"title":"Восхождение героя щита 3","rating":15,"tier":"great","review":"","desc":"Адаптация ваншота из фанбука 2025 года «Моя геройская академия: Ультра-эпоха», повествующей о визите старшеклассницы  в старшую школу U.A.","poster":"https://shikimori.io/system/animes/original/40357.jpg?1710812777","url":"https://shikimori.one/animes/40357-tate-no-yuusha-no-nariagari-season-3","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Исекай","Фэнтези","Приключения","Боевик"],"episodes":12,"kind":"tv","franchise":"shield_hero"},{"title":"Для каждой тебя, что я раньше любил","rating":15,"tier":"great","review":"","desc":"Коёми Такасаки, живущий с матерью после развода родителей, поступает в подготовительную школу при местном университете. Школьная жизнь, насыщенная событиями и приятным времяпрепровождением с друзьями, обходит Коёми, сосредоточенного на учёбе, стороной. В старшей школе он предпринимает попытки найти друзей, но у него ничего не выходит. Его жизнь по-настоящему меняется только тогда, когда к нему неожиданно обращается его одноклассница Кадзунэ Такигава, которая рассказывает ему, что прибыла из 85-го мира, где они с Коёми давным-давно возлюбленные.","poster":"https://shikimori.io/system/animes/original/49834.jpg?1711335938","url":"https://shikimori.one/animes/49834-boku-ga-aishita-subete-no-kimi-e","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Романтика","Фантастика","Комедия"],"episodes":1,"kind":"movie","franchise":null},{"title":"Истинная красота","rating":15,"tier":"great","review":"","desc":"Устав от того, что на неё смотрят свысока из-за непривлекательной внешности, школьница средних классов Лим Джугён Лим обращается к преображающей силе макияжа. Сначала она пробует ВВ-крем, тинт для губ и подводку для глаз, а затем переходит на тушь, клей для создания складки на веках и цветные линзы. Не успевает она опомниться, как из девочки, которую травили за уродство, превращается в признанную красавицу высшего класса. Теперь, окружённая толпой поклонников, восхищающихся её божественной внешностью, Джугён может наслаждаться комфортной школьной жизнью — нужно лишь хранить в тайне то, как она выглядит без макияжа.Однако всё меняется, когда в её жизнь входит новый ученик по имени Ли Су Хо. Красавец Су Хо мгновенно становится популярным среди сверстников, а по случайности оказывается единственным одноклассником, увидевшим лицо Джугён без макияжа. Теперь, когда её репутация под угрозой, Джугён должна сделать всё возможное, чтобы скрыть правду о своей внешности от остальных ребят в классе. Но чем больше времени она проводит с Су Хо, тем чаще задаётся вопросом: неужели истинная красота человека заключена лишь в его внешности?","poster":"https://shikimori.io/system/animes/original/57192.jpg?1716209167","url":"https://shikimori.one/animes/57192-yeosin-gangnim","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Романтика"],"episodes":13,"kind":"ona","franchise":null},{"title":"Добро пожаловать в класс превосходства","rating":15,"tier":"great","review":"","desc":"Старшая школа Кодо Икусэй — престижное учебное заведение, окончив которое, выпускники гарантированно поступят в университет или найдут отличную работу. Учащимся позволено ходить с любыми прическами и приносить любые личные вещи. Кодо Икусэй — школа, похожая на рай, но правда состоит в том, что такой подход применим только к ученикам с высокой успеваемостью.        \n        Первогодка Киётака Аянокоджи учится в классе D, куда руководство школы «сливает» студентов, набравших низкие показатели на вступительных экзаменах. Шаг за шагом он вливается в школьную жизнь и заводит новые знакомства, благодаря чему его положение постепенно начинает меняться.","poster":"https://shikimori.io/system/animes/original/35507.jpg?1711982853","url":"https://shikimori.one/animes/35507-youkoso-jitsuryoku-shijou-shugi-no-kyoushitsu-e","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Психология","Школа"],"episodes":12,"kind":"tv","franchise":"classroom_of_the_elite"},{"title":"Клинок, рассекающий демонов","rating":15,"tier":"great","review":"","desc":"Действие происходит в эпоху Тайсё. Ещё с древних времён ходят слухи о том, что в лесу обитают человекоподобные демоны, которые питаются людьми и ходят по ночам, ища новую жертву. Но... это же просто легенда, ведь так?..        \n        Тандзиро Камадо — старший сын в семье, потерявший своего отца и взявший на себя заботу о своих родных. Однажды он уходит в соседний город, чтобы продать древесный уголь. Вернувшись утром, парень обнаруживает перед собой страшную картину: вся родня была зверски убита, а единственной выжившей является Нэдзуко  — обращённая в демона, но пока не потерявшая всю человечность младшая сестра.        \n        С этого момента для Тандзиро и Нэдзуко начинается долгое и опасное путешествие, в котором мальчик намерен разыскать убийцу и узнать способ исцеления для своей сестры. Но в состоянии ли дети преодолеть все трудности и вернуться домой?","poster":"https://shikimori.io/system/animes/original/38000.jpg?1711958556","url":"https://shikimori.one/animes/z38000-kimetsu-no-yaiba","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Триллер"],"episodes":26,"kind":"tv","franchise":"kimetsu_no_yaiba"},{"title":"Клинок, Рассекающий Демонов: Тренировка Хашира","rating":15,"tier":"great","review":"","desc":"Инцидент в Деревне кузнецов завершился, и его последствия могут оказаться судьбоносными для Японии. Собравшись на срочное совещание, столпы, обсудив текущую ситуацию, приходят к заключению, что нынешние охотники на демонов слишком слабы, чтобы оказывать достойное сопротивление Молодым лунам. Такое положение дел чревато большими человеческими потерями и может поставить под угрозу существование самой организации.         \n        Каменный столп Гёмэй Химэдзима предлагает устроить рядовым охотникам тренировку. Разделившись на группы, бойцы побывают у каждого столпа по очереди и усовершенствуют свои боевые навыки. Тренировки обещают быть сверхинтенсивными и экстра беспощадными. Но такова цена выживания в эту непростую эпоху.","poster":"https://shikimori.io/system/animes/original/55701.jpg?1717980797","url":"https://shikimori.one/animes/55701-kimetsu-no-yaiba-hashira-geiko-hen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","История","Сёнэн"],"episodes":8,"kind":"tv","franchise":"kimetsu_no_yaiba"},{"title":"Лукизм","rating":15,"tier":"great","review":"","desc":"Пак Хёнсок — пухлый, прыщавый подросток в очках, является постоянной жертвой травли со стороны одноклассников. Единственным шансом на избавление ему видится  переезд в другой город. Но однажды ночью он просыпается от странных ощущений, и, подойдя к зеркалу, видит, что превратился в стройного красавчика. При этом его старое тело никуда не пропало: оно просто спит в кровати. Заполучив способность перемещаться между двумя телами, днём Хёнсок становится кумиром в новой школе, а ночью оборачивается собой прежним, чтобы выйти на смену и заработать на жизнь. Конечно, Хёнсок радуется открывшимся перспективам, вот только не чувствует себя собой. Новое тело не способно в один момент переменить характер зашуганного парня. Получив новую внешность и возможность начать жизнь с чистого листа, сможет ли Хёнсок измениться и обрести надежду на лучшее будущее?","poster":"https://shikimori.io/system/animes/original/53149.jpg?1709518628","url":"https://shikimori.one/animes/53149-oemojisangjuui","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Драма","Сверхъестественное"],"episodes":8,"kind":"ona","franchise":null},{"title":"Неправильный способ использования исцеляющей магии","rating":15,"tier":"great","review":"","desc":"Застряв в школьном холле и глядя на проливной дождь на улице, старшеклассник Кэн Усато размышлял об унылости собственной жизни, в которой ничегошеньки не происходит. Да ещё и зонт забыл. В общем, полностью погрузился в ощущение тягостности и бессмысленности своего существования. Погрузился, однако, всего на пару минут, так как его прервали президент ученического совета Судзунэ Инуками и вице-президент Рюсэн Кадзуки, которые одолжили ему зонт.        \n                \n        Случайное знакомство грозило перерасти в дружбу и жить бы Кэну насыщенной школьной жизнью, но его новых товарищей спустя несколько минут после встречи призвали в другой мир в качестве героев! Ну и Усато засосало вместе с ними по пути. Его сэмпаи получили чудесные способности, а вот у Усато обнаружился в общем-то бесполезный в настоящем бою талант исцеления. Ничего особенного.        \n                \n        Вот только почему все вокруг переполошились, смотрят на него испуганными глазами, наказывают помалкивать об этом и вообще норовят убрать его с глаз долой? Чем может грозить целому королевству обычный маг-целитель? Кэн узнает это на собственной шкуре, когда его заберёт с собой лидер отряда спасателей, Роза. И ничто уже Кэна не спасёт.","poster":"https://shikimori.io/system/animes/original/49613.jpg?1718847937","url":"https://shikimori.one/animes/49613-chiyu-mahou-no-machigatta-tsukaikata","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Комедия"],"episodes":13,"kind":"tv","franchise":null},{"title":"Непризнанный школой владыка демонов! 2","rating":15,"tier":"great","review":"","desc":"Всесильный Владыка демонов, обладающий силой уничтожать людей, богов и стихии, за годы бесконечных войн устал от битв и возжаждал умиротворения и покоя. Поэтому, недолго думая, он решает махнуть рукой на существующий мир и возродиться сразу в будущем. Проходит каких-то две тысячи лет, и Владыка перерождается в мире, который, к его изумлению, полон спокойствия и давно позабыл о временах сражений. Вроде бы всё складывается так, как Аносу и хотелось, вот только из-за отсутствия практики сами магические силы ослабли, причем ослабли настолько, что даже не в состоянии признать в юноше истинного Владыку демонов! И когда Анос пытается поступить в Академию для кандидатов в Князи Тьмы, его объявляют негодным!","poster":"https://shikimori.io/system/animes/original/40496.jpg?1711962874","url":"https://shikimori.one/animes/48417-maou-gakuin-no-futekigousha-shijou-saikyou-no-maou-no-shiso-tensei-shite-shison-tachi-no-gakkou-e-kayou-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Школа"],"episodes":12,"kind":"tv","franchise":"maou_gakuin"},{"title":"О моём перерождении в слизь. Фильм","rating":15,"tier":"great","review":"","desc":"История разворачивается вокруг королевства Раджа. Тамошняя принцесса по имени Това вынуждена регулярно принимать на себя скверну, отравляющую земли королевства. Ради спасения Товы её преданный слуга, огр Хиро, отправляется в лес Джуры за помощью. Римуру Темпест соглашается вмешаться и направляется в Раджу, собираясь разобраться в происходящем и постараться помочь Тове.","poster":"https://shikimori.io/system/animes/original/49877.jpg?1709524281","url":"https://shikimori.one/animes/49877-tensei-shitara-slime-datta-ken-movie-guren-no-kizuna-hen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Боевик","Приключения","Комедия","Фэнтези","Сёнэн"],"episodes":1,"kind":"movie","franchise":"tensei_shitara_slime"},{"title":"Одинокий рокер!","rating":15,"tier":"great","review":"","desc":"Мечтающая в будущем играть в музыкальной группе, старшеклассница Хитори Гото взялась за уроки игры на гитаре. Ничего не мешает исполнению её мечты, кроме самой Хитори, которая настолько застенчива и зажата, что не смогла завести ни одного друга, чего уж говорить о создании собственного музыкального коллектива. Сама судьба решает помочь Хитори, и та, на своё счастье, встречает Нидзику Идзити, которая играет на ударных в собственной группе и как раз подыскивает гитаристку!","poster":"https://shikimori.io/system/animes/original/47917.jpg?1711944241","url":"https://shikimori.one/animes/47917-bocchi-the-rock","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Музыка","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Папаши дружбаны","rating":15,"tier":"great","review":"","desc":"Работа наёмного убийцы требует немалого профессионализма, но у напарников-киллеров Кадзуки Курусу и Рэя Сувы с этим ладится не очень. Так, на очередном задании они случайно столкнулись с малышкой Мири, отправившейся в незнакомый город на поиски отца, и по стечению обстоятельств вынуждены были оставить её у себя.        \n        С их ненормированным рабочим днём, плавающим графиком, отсутствием стабильности и постоянным риском для жизни даже забота о кошке становится серьёзным вызовом и превращается в неразрешимую проблему, что уж говорить о настоящем живом 4-летнем ребёнке? Смогут ли двое друзей — хозяйственный, но ветреный игроман Кадзуки Курусу и мрачный, но добросердечный затворник Рэй Сува — воспитать девочку, не нанеся при этом вреда обществу, своей работе и собственно этой самой девочке?","poster":"https://shikimori.io/system/animes/original/53411.jpg?1717379040","url":"https://shikimori.one/animes/53411-buddy-daddies","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Перевоплотился в седьмого принца, так что я буду совершенствовать как захочу","rating":15,"tier":"great","review":"","desc":"Простолюдин, мечтавший овладеть магией, после гибели от рук дворян переродился в теле Ллойда де Салума , седьмого принца королевства ]. Теперь, обладая воспоминаниями из прошлой жизни и необходимым магическим талантом, Ллойд погружается в изучение и открытие новых заклинаний, двигаясь навстречу своей мечте. Однако жизнь принца наполнена своими сложностями: Ллойду предстоит столкнуться с политическими интригами, коварными врагами и неожиданными союзниками. Но что бы ни ждало его впереди, юный принц твёрдо намерен совершенствовать свою магию так, как ему заблагорассудится!","poster":"https://shikimori.io/system/animes/original/53516.jpg?1718207142","url":"https://shikimori.one/animes/53516-tensei-shitara-dainana-ouji-datta-node-kimama-ni-majutsu-wo-kiwamemasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"],"episodes":12,"kind":"tv","franchise":"tensei_7_prince"},{"title":"Семья шпиона. Часть 2","rating":15,"tier":"great","review":"","desc":"Как люди ни ценили бы искренность и правду, ложь продолжает оставаться неизбывной частью жизни и, как ни парадоксально звучит, зачастую счастливой жизни, залогом которой она и служит. Это абсолютно верно в случае семьи Форджеров, само существование которой — сплошной обман. Каждый член этой поддельной семьи врёт остальным, скрывая правду о себе.        \n                \n        Лойд Форджер скрывает, что он секретный агент Весталиса. Йор Форджер умалчивает, что является наёмной убийцей, работающей в Остании. Тем не менее правда об их фиктивном браке и настоящих профессиях известна «дочери» Лойда, Ане, которую тот взял из приюта, не подозревая, что та не так проста, как кажется. Девочка, прошедшая через эксперименты, обрела способность читать чужие мысли.        \n                \n        Пример этой фальшивой семьи подтверждает, что существует ложь во спасение. Особенно, когда на кону стоит ни много ни мало — мир во всём мире и жизни невинных людей!","poster":"https://shikimori.io/system/animes/original/50602.jpg?1711940706","url":"https://shikimori.one/animes/50602-spy-x-family-part-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Боевик","Комедия"],"episodes":13,"kind":"tv","franchise":"spy_x_family"},{"title":"Фарс из убийства девушки-нежити","rating":15,"tier":"great","review":"","desc":"С развитием человеческой цивилизации в XIX веке демоны, которые до тех пор жили до некоторой степени привольно, были уничтожены под корень. Лишь немногие из сверхъестественных существ остались в живых, так как стали союзниками людей в борьбе с демонами и поклялись, что никогда не причинят вреда человеку. Несмотря на это, все не-люди так и воспринимаются в обществе, как постоянная угроза, их ненавидят, боятся и презирают. Неудивительно, что в такой напряжённой обстановке дело нередко доходит до конфликтов, которые зачастую заканчиваются преступлением.        \n                \n        Здесь в игру и вступает загадочная тройка детективов: Цугару Синути, Ая Риндо и Сидзуку Хасэи. Раскрыть любую загадку для них проще простого, однако с лёгкостью решить они могут только чужие проблемы, а вот свои продолжают доставлять неприятности. Да и детективная работа для них сродни развлечению, на самом деле каждый из них преследует собственные цели.","poster":"https://shikimori.io/system/animes/original/54790.jpg?1710727467","url":"https://shikimori.one/animes/54790-undead-girl-murder-farce","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Детектив","История","Вампиры"],"episodes":13,"kind":"tv","franchise":null},{"title":"Хоримия: кусочек","rating":15,"tier":"great","review":"","desc":"На первый взгляд может показаться, что Хори — обыкновенная девушка, но внешность бывает обманчивой. Популярная и холодная красавица может вдруг оказаться заботливой и доброй домохозяйкой. Миямура, который по началу кажется нелюдимым хулиганом, на деле оказывается очень вежливым и дружелюбным человеком. Так абсолютно разные герои узнают много нового друг о друге и начинают сближаться.        \n        Когда учёба подходит к концу, Хори вместе с Миямурой, а также со своими друзьями оглядываются назад, чтобы вспомнить драгоценные моменты, которые они пережили за время учёбы в старшей школе Катагири. Это последний шанс для наших героев, чтобы вспомнить и насладиться теми бесценными воспоминаниями, кусочками истории, о которых мы не могли и подумать.","poster":"https://shikimori.io/system/animes/original/54856.jpg?1711329192","url":"https://shikimori.one/animes/54856-horimiya-piece","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Школа","Романтика","Сёнэн"],"episodes":13,"kind":"tv","franchise":"horimiya"},{"title":"Ведьмак: Сирены глубин","rating":15,"tier":"great","review":"анимеция классная и сюжет прикольный","desc":"Хотару Ичиджо  — ученица пятого класса начальной школы — переехала с родителями из Токио в деревенскую глубинку. И была крайне удивлена тем, что местные дети ничего не знают о большом городе. Но еще сильнее она удивилась, когда узнала, что единственную на всю деревню школу посещают всего четыре ученика. И, несмотря на разный возраст, все они учатся в одном классе.        \n        Однако на этом различия со столицей не спешили заканчиваться. Хотару предстоит узнать ещё много нового о жизни в глуши, где никто никогда не запирает двери, где окрестности утопают в пушистой зелени, где журчат ручьи, где вспаханные поля залиты солнечным светом и где вокруг, как ни прислушивайся, везде — умиротворяющая тишина, изредка нарушаемая звуком проезжающих мимо стареньких автомобилей...        \n        Это словно другой мир, странный мир, в котором без проводника никак не обойтись. К счастью, у Хотару их появляется сразу четверо: жизнерадостные сёстры Нацуми  и Комари , их старший молчаливый брат Сугуру  и несносная Рэн-чан . Эти дети готовы помочь новой подруге адаптироваться в привычном для них мире. Впрочем, узнать у неё о большом городе они тоже не против.","poster":"https://shikimori.io/system/animes/original/17549.jpg?1711966488","url":"https://shikimori.one/animes/y17549-non-non-biyori","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Семья шпиона 2","rating":13,"tier":"great","review":"","desc":"Лойд Форджер — самый крутой шпион Весталиса, на плечи которого возложена важнейшая миссия, от успеха которой зависит хрупкий мир с соседней Останией. Провал же означает войну двух государств. Для выполнения задания необходимо понять намерения Донована Десмонда — крупного политика Остании, который практически не появляется на публике. Исключение он делает для элитной академии «Эдем», где учатся его дети. Логичным решением проблемы оказывается создание фальшивой семьи Форджеров с поддельной женой Йор и подложной дочерью Аней, которая отправится учиться в «Эдем».\n\nКажется, со временем Лойд начал проникаться чувствами к своим ненастоящим родным. Сможет ли семья, созданная исключительно для выполнения миссии, стать настоящей для трёх одиноких людей? И как эта привязанность скажется на успехе всей операции? Ведь враг не дремлет, и для победы нужно быть готовым пожертвовать всем.","poster":"https://shikimori.io/system/animes/original/53887.jpg?1710729511","url":"https://shikimori.one/animes/53887-spy-x-family-season-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Сёнэн"],"episodes":12,"kind":"tv","franchise":"spy_x_family"},{"title":"Старик из деревни становится Святым мечом","rating":12,"tier":"great","review":"нравитсчя","desc":"Скромный инструктор фехтования Берил Гарденант живёт в глухой деревне. Когда-то он мечтал о славе и подвигах, но те времена остались в далёком прошлом. Теперь он занят повседневными делами и думать забыл о высоких стремлениях. Всё резко меняется, когда его бывшая ученица Аллусия Цитрус, ставшая командиром Королевских рыцарей, предлагает ему стать специальным инструктором рыцарского ордена.        \n        Несмотря на убеждение, что произошла какая-то ошибка, Берил отправляется в столицу, где встречает и других своих бывших учеников, каждый из которых достиг больших высот в своей сфере деятельности. В большом городе Берилу предстоит столкнуться с новыми вызовами, необычными ситуациями и осознать, что его навыки могут быть куда более значимыми, чем ему казалось.","poster":"https://shikimori.io/system/mangas/original/145480.jpg?1712757504","url":"https://shikimori.one/animes/59452-katainaka-no-ossan-kensei-ni-naru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа","Повседневность"],"episodes":12,"kind":"tv","franchise":"kenja_ojisan"},{"title":"24-й округ Токио","rating":12,"tier":"great","review":"","desc":"У трёх друзей детства Рана Акаги, Сюты Аой и Коки Суйдо мало общего: их семьи имеют разный социальный статус, у них непохожие хобби и совершенно разные характеры. Объединяет трёх парней то, что они родились и выросли в 24-м округе Токио. Это не совсем обычный район, так как это искусственно созданный остров, расположенный  в Токийском заливе. Несмотря на свою непохожесть, друзья много времени проводили вместе, пока не произошёл печальный инцидент.        \n        Спустя год они встречаются, и вдруг их телефоны начинают одновременно звонить. Звонит их общий «погибший» друг, который предлагает им «выбрать будущее». Теперь трём юношам предстоит попытаться доступным им способом защитить любимый дом, жителей острова и их будущее.","poster":"https://shikimori.io/system/animes/original/50204.jpg?1716777134","url":"https://shikimori.one/animes/50204-tokyo-24-ku","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Фантастика","Супергероика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Злодейка девяносто девятого уровня","rating":12,"tier":"great","review":"","desc":"Непредвиденное стечение обстоятельств помогло пятилетней аристократке Юмиэлле Долкнесс осознать, что в прошлой жизни она жила в Японии, а её нынешняя реальность — это мир компьютерной игры для девушек. Изюминка игры в том, что чёрный цвет волос считается проклятым, а Юмиэлла как раз родилась с шевелюрой оттенка воронова крыла. Разумеется, это не случайность, а следствие того, что по сценарию её персонаж — главная злодейка и скрытый босс игры.        \n        Если оригинальная Юмиэлла Долкнесс боролась за место рядом с возлюбленным, то нынешней — глубоко плевать на романтику, зато очень хочется избежать положенного ей по сюжету трагического финала. Поэтому она решает ни в коем случае не привлекать к себе внимание и тихонько тренировать свою уникальную тёмную магию.        \n        Все планы Юмиэллы проваливаются, когда она поступает в магическую академию и выясняется, что она сильна как сто тысяч чертей: ей нет равных ни в магии, ни в физической силе. А если прибавить сюда тот факт, что она брюнетка, то ей не избежать того, чтобы стать для всех бельмом на глазу. И будто мало ей всех этих проблем, центральная героиня игры начинает подозревать, что Юмиэлла не скромная злодейка местного разлива, а самый что ни на есть Король демонов!","poster":"https://shikimori.io/system/animes/original/54837.jpg?1710981919","url":"https://shikimori.one/animes/54837-akuyaku-reijou-level-99-watashi-wa-ura-boss-desu-ga-maou-dewa-arimasen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Школа","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Любовная болезнь хананои","rating":12,"tier":"great","review":"","desc":"В цветущую пору юности, когда жизнь только-только начинает свой разбег, а молодые люди стремятся к знаниям, в их юных сердцах поселяется жажда иного чувства, прекраснейшего и в то же время самого горького чувства на Земле — любви.        \n                \n        Старшеклассница Хотару Хинасэ относится к любви более приземлённо, считая, что её время ещё не пришло, и предпочитает проводить свободное время с семьёй и друзьями, не забивая голову романтической чепухой. Её одноклассник Саки Хананои — полная противоположность Хотару в романтических делах. Он мечтает о любви и в поисках  единственной перебрал уже кучу девушек, но той, кому готов навек отдать сердце, к сожалению, так и не нашёл.        \n        И вот после очередной любовной неудачи Саки, судьба, словно в награду за прошлые поражения, сводит его с Хотару. Этот снежный день навсегда изменит жизнь первого красавца школы и девчонки, несведущей в любви.","poster":"https://shikimori.io/system/animes/original/55597.jpg?1718402297","url":"https://shikimori.one/animes/55597-hananoi-kun-to-koi-no-yamai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёдзё","Романтика","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Магическая битва 2","rating":12,"tier":"great","review":"","desc":"Тридцать первое октября 2018 года, район Сибуя. Множество простых людей заключены под магической завесой и взяты в заложники союзом проклятых духов под началом Махито и Гэто. Всех гражданских обещают выпустить невредимыми только с одним условием: сильнейший маг современности Сатору Годзё должен явиться в Сибую и принять бой.\nУченики и преподаватели Магического техникума разбиваются на группы, чтобы быстрее эвакуировать мирных жителей перед началом масштабной битвы. Вместе с тем, сам Сатору Годзё прибывает на место действия и отправляется прямиком к станции. События развиваются согласно плану Сугуру Гэто.","poster":"https://shikimori.io/system/animes/original/51009.jpg?1711334733","url":"https://shikimori.one/animes/51009-jujutsu-kaisen-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Сёнэн","Сверхъестественное"],"episodes":23,"kind":"tv","franchise":"jujutsu_kaisen"},{"title":"Месть масамунэ R","rating":12,"tier":"great","review":"","desc":"Доставивший проблем школьный культурный фестиваль наконец-то подошёл к концу. Лучший герой и героиня спектакля выбраны. Вместе с этим Масамунэ начинает казаться, что Аки становится мягче в отношении к нему, но он ещё не подозревает, как много преград впереди.        \n        Масамунэ Макабэ продолжает претворять свой план мести в жизнь. Впереди школьная поездка в самый романтичный город в мире!","poster":"https://shikimori.io/system/animes/original/51498.jpg?1710734611","url":"https://shikimori.one/animes/51498-masamune-kun-no-revenge-r","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Гарем","Школа","Сёнэн"],"episodes":12,"kind":"tv","franchise":"masamune_kun"},{"title":"Невероятный новичок средних лет, прошедший","rating":12,"tier":"great","review":"","desc":"Общеизвестно, что начинать путь авантюриста нужно в раннем возрасте, ведь магическая сила и её запас могут развиваться только пока обладатель достаточно юн. Перезреешь — прогресса в магии не видать как собственных ушей, а без магической базы страдают и другие параметры силы, так что, будучи взрослым, полноценным приключенцем, увы, уже не стать.        \n        Однако Рик Гладиатор наперекор всем устоям решил стать авантюристом, когда ему уже перевалило за тридцать два. Конечно, у него не было бы никаких шансов, не попадись он случайно на глаза группе авантюристов S-ранга, которые увидели в нём потенциал и взялись тренировать. Два года адских тренировок, во время которых он не раз умирал, но был воскрешён, и вот Рик готов сдавать экзамен на получение ранга Е.        \n        Далеко ли заведёт решимость и желание стать авантюристом обычного мужчину средних лет?","poster":"https://shikimori.io/system/animes/original/54913.jpg?1712086104","url":"https://shikimori.one/animes/54913-shinmai-ossan-boukensha-saikyou-party-ni-shinu-hodo-kitaerarete-muteki-ni-naru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Обычный мужчина средних лет и его журнал активности в VRMMO","rating":12,"tier":"great","review":"","desc":"Обычный 38-летний офисный трудяга по имени Дайти Танака, серые будни которого наполнены лишь работой, вдруг осознал, что настало время что-то менять в своей жизни, и решил попытать счастье в мире виртуальных игр. Новая реальность стала для Дайти второй жизнью, где он смог расслабиться и отдохнуть от повседневной рутины, забыв обо всём.        \n                \n        К сожалению, мужчина не в состоянии уделять любимому увлечению много времени. Поэтому, регистрируясь в новой игре под названием «Очередная вольная жизнь онлайн», решил сосредоточиться на приятном времяпрепровождении, а не на прокачке персонажа, выбрав своему аватару самые простенькие навыки, которые считались бесполезными. Будь то приготовление разнообразных блюд, стрельба из лука или создание зелий — Дайти будет рад любому занятию!        \n                \n        Это история о рядовом офисном клерке, который не гонится за статами, а просто наслаждается игрой!","poster":"https://shikimori.io/system/animes/original/54431.jpg?1710728395","url":"https://shikimori.one/animes/54431-toaru-ossan-no-vrmmo-katsudouki","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Одаривая этот замечательный мир взрывами!","rating":12,"tier":"great","review":"","desc":"Пускай Мэгумин и Юн-юн — невероятные представительницы Багрового клана, им всё равно многому ещё нужно научиться, ведь совершенству нет предела. Юн-юн принялась изучать продвинутую магию, а Мэгумин пошла по иному пути — по пути магии взрыва! Несмотря на то, что Мэгумин предупреждали о том, что этот вид магии имеет ограниченную пользу при практическом применении, она продолжает верить, что магия взрыва — это путь к тому, чтобы стать великой и самой желанной волшебницей для отряда. И никто не способен убедить её в обратном!","poster":"https://shikimori.io/system/animes/original/51958.jpg?1710733679","url":"https://shikimori.one/animes/51958-kono-subarashii-sekai-ni-bakuen-wo","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Приключения"],"episodes":12,"kind":"tv","franchise":"konosuba"},{"title":"Проиграйте, чтобы разбогатеть с самого начала игры","rating":12,"tier":"great","review":"","desc":"Работая в нескольких местах, Пэй Цянь всё равно не может свести концы с концами. Сверхурочные часы не оплачиваются, начальство тиранит, условий никаких. Всё изменилось для него в тот момент, когда он скачал на телефон странное приложение. Приложение оказалось Системой конвертации валюты, которая не только отправила его в прошлое, назад в его студенческие годы, но и сделала предложение, от которого невозможно отказаться.        \n        Суть его такова: Пэй Цянь получает возможность начать собственное дело на те финансы, которые выделяет ему Система. Однако вывести виртуальные деньги в реальный кошелёк, он сможет только из полученной прибыли (причем по крайне невыгодному курсу) или… забрать себе всё вложенное в дело по курсу один к одному в том случае, если бизнес прогорит.        \n        Вывод: нет смысла убиваться над построением бизнеса, ведь гораздо выгоднее пустить его под откос! И чем больше вложишь бабла, тем больше получишь, проиграв!","poster":"https://shikimori.io/system/animes/original/57663.jpg?1714308414","url":"https://shikimori.one/animes/57663-kui-cheng-shoufu-cong-youxi-kaishi","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Приключения"],"episodes":16,"kind":"ona","franchise":null},{"title":"Слабейшая укротительница в путешествии по сбору питомцев","rating":12,"tier":"great","review":"","desc":"Жизнь маленькой Фемиции изменилась в один день: любящие родные возненавидели её, безобидные доселе соседи стали врагами, а сама она превратилась в изгоя. Всё потому, что на церемонии определения навыка, которую должен пройти каждый ребёнок, выяснилось, что навык-то у Фемиции есть и даже тот, о котором она мечтала — укротительница. Однако само по себе наличие навыка мало что определяет, важнее то, сколько у него звёзд. Чем больше звёзд, тем выше ранг навыка, тем искусней будет его обладатель.        \n        У навыка Фемиции нет ни одной звезды. «Значит, бог их не дал, значит, Фемиция «противна» богу, а значит, принесёт несчастье деревне», — примерно так рассудили жители и решили избавиться от ребёнка. Фемиция сбежала, спряталась в лесу и стала выживать самостоятельно. Тяготы новой жизни помогала Фемиции переносить пожилая прорицательница Луба, но вскоре она умерла. Следуя её совету, Фемиция переоделась мальчиком, взяла себе новое имя Айви и отправилась в путешествие.","poster":"https://shikimori.io/system/animes/original/53590.jpg?1711230007","url":"https://shikimori.one/animes/53590-saijaku-tamer-wa-gomi-hiroi-no-tabi-wo-hajimemashita","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Я, владыка демонов, взял эльфийку-рабыню в жёны","rating":12,"tier":"great","review":"","desc":"Могущественный тёмный колдун Заган коротает деньки, изучая чары и проклятия, а также наказывая бедолаг, осмелившихся ступить на его территорию. Однажды он посещает тайный аукцион товаров почившего архидемона, рассчитывая найти редкие артефакты. Вместо этого пред его взором предстаёт невероятно красивая рабыня-эльф Нефелия. Красота — страшная сила, которая тут же разит Загана в его колдунское сердце.        \n        Влюбившись с первого взгляда и потратив, как настоящий мужчина, всё богатство ради покупки рабыни, тёмный маг осознал один немаловажный момент. Хоть он и невероятно могуч, но в общении полный ноль и понятия не имеет, что делать дальше. Как, собственно, и сама девушка, которая хочет отплатить хозяину, но не знает как. Остаётся лишь надеяться, что неуклюжий колдун и застенчивая эльфийка всё-таки смогут каким-то чудом найти общий язык.","poster":"https://shikimori.io/system/animes/original/53434.jpg?1717215361","url":"https://shikimori.one/animes/53434-maou-no-ore-ga-dorei-elf-wo-yome-ni-shitanda-ga-dou-medereba-ii","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Романтика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Реинкарнация аристократа: Благословенный с рождения","rating":12,"tier":"great","review":"","desc":"Ной Арарат появляется на свет с уже готовыми привилегиями — тринадцатым принцем имперской династии, и получает жизнь, о которой большинство может только мечтать. Ведь помимо доступа к лучшему образованию и ресурсам империи, Ной — реинкарнатор, сохранивший память о прошлой жизни, наделённый бесконечным потолком уровня и уникальной способностью использовать навыки своих подчинённых.Однако в стенах императорского двора один лишь статус не гарантирует безопасности. Пока непревзойдённый потенциал Ноя с первых же тренировок выделяет его среди братьев и сестёр, он же привлекает внимание знати, чьи интересы простираются далеко за пределы государственного управления. Рано или поздно Ною придётся научиться лавировать между требованиями, налагаемыми королевским происхождением, и особенностями своей необычной силы — ведь он начинает понимать, что привилегии так же легко открывают путь к контролю над собой, как и дарят власть.","poster":"https://shikimori.io/system/mangas/original/131342.jpg?1712761220","url":"https://shikimori.one/animes/60692-kizoku-tensei-megumareta-umare-kara-saikyou-no-chikara-wo-eru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай","Боевик","Триллер"],"episodes":12,"kind":"tv","franchise":null},{"title":"Безымянная память 2","rating":11,"tier":"great","review":"хорошое","desc":"Из-за проклятия, наложенного коварной ведьмой безмолвия, наследный принц Оскар не может иметь детей. В поисках решения он отправляется на поиски Тинаши, легендарной ведьмы, которая, как говорят, может помочь. После покорения смертельно опасной башни и встречи с ведьмой, выясняется, что только женщина с выдающимися магическими способностями может дать ему потомство. Оскар предлагает Тинаше стать его женой, что решило бы его проблему, но та отказывается. Тем не менее, принц уговаривает её пожить с ним год, чтобы попытаться разорвать проклятие или заключить брак.","poster":"https://shikimori.io/system/animes/original/53835.jpg?1718812093","url":"https://shikimori.one/animes/53835-unnamed-memory","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Романтика"],"episodes":12,"kind":"tv","franchise":"nameless_memory"},{"title":"Создатель магии: Как создать волшебство в другом мире","rating":11,"tier":"great","review":"Долго развивалось аниме, но закончилось неплохо.","desc":"30-летний мужчина, мечтавший стать волшебником, неожиданно погибает. Переродившись в другом мире в облике маленького мальчика по имени Сион Орнштейн, он растёт рядом со своей заботливой старшей сестрой Мари Орнштейн, которая обожает его. Сион с нетерпением ждёт момента, когда сможет применить магические способности, но вскоре с разочарованием обнаруживает, что в этом новом мире магии, судя по всему, не существует. Он проводит следующие годы угрюмым и подавленным ребёнком — пока таинственное явление на соседнем озере не привлекает внимание брата и сестры, вновь пробуждая в Сионе его мечту о магии.Исследуя странное свечение, исходящее от воды, Сион наконец убеждается: магическая энергия действительно существует. Пусть пока она ни на что толком не годится, но он с головой погружается в изучение этой аномалии, полный решимости раскрыть все тайны мира на пути к тому, чтобы самому стать магом.","poster":"https://shikimori.io/system/mangas/original/157056.jpg?1710124970","url":"https://shikimori.one/animes/59265-magic-maker-isekai-mahou-no-tsukurikata","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай","Детектив"],"episodes":12,"kind":"tv","franchise":null},{"title":"Восхождение героя щита 2","rating":11,"tier":"great","review":"","desc":"Адаптация ваншота из фанбука 2025 года «Моя геройская академия: Ультра-эпоха», повествующей о визите старшеклассницы  в старшую школу U.A.","poster":"https://shikimori.io/system/animes/original/40356.jpg?1711976753","url":"https://shikimori.one/animes/40356-tate-no-yuusha-no-nariagari-season-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Исекай","Фэнтези","Приключения","Боевик"],"episodes":13,"kind":"tv","franchise":"shield_hero"},{"title":"DOTA: Кровь дракона 3","rating":11,"tier":"great","review":"","desc":"На протяжении тысячелетий, в каждой из сменяющихся эпох, длится, оставляя следы в истории, одна и та же бесконечная война. Влияет она и на современный мир. Две больших группы вовлечены в эту войну. Первая состоит из монстров, известных как «рукокрылы», способных менять свой внешний вид, превращаясь в людей. Они — бессмертные создания, питающиеся кровью живых существ. Вторая группа — организация под названием «Красные щиты», образованная с целью выслеживать чудовищ и уничтожать их.        \n        Сая Отонаси — на первый взгляд обычная школьница, живущая мирной жизнью со своей семьёй. Единственная проблема в том, что её память о прошлом не простирается дальше событий годичной давности... Однако её счастливая жизнь вскоре будет порушена событием, которое приведёт её к тому, что предназначила ей судьба.","poster":"https://shikimori.io/system/animes/original/150.jpg?1711945024","url":"https://shikimori.one/animes/150-blood","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Драма","Ужасы","Детектив","Сверхъестественное","Военный","Вампиры"],"episodes":50,"kind":"tv","franchise":"dota_dragons_blood"},{"title":"Лжец, лжец","rating":11,"tier":"great","review":"","desc":"На Острове-Академии успехи учеников зависят от побед в разнообразных интеллектуальных состязаниях, где сильнейшему студенту присуждают семь звёзд. Переведённый ученик Хирото Синохара в первый же день невзначай победил абсолютную чемпионку прошлого года, обладательницу шести звёзд — Сарасу Сайондзи и в мгновение ока поднялся на вершину иерархии острова. Однако из-за того, что парень изначально имеет лишь одну звезду, его победа над пятикратно превосходящим его противником по определению считалась невозможной. Из-за этого факта ему пришлось соврать всем ученикам, будто он обладает не одной, а всеми семью звёздами. Теперь Хирото вынужден поддерживать победоносный образ сильнейшего, ведь раскрытие правды может иметь роковые последствия для всей его последующей школьной жизни.","poster":"https://shikimori.io/system/animes/original/48633.jpg?1711960876","url":"https://shikimori.one/animes/48633-liar-liar","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Психология","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Наш дождливый протокол","rating":11,"tier":"great","review":"","desc":"После несчастного случая, унёсшего жизнь отца и оставившего сестру инвалидом, Сюн Токиноя пережил тяжёлое душевное потрясение, из-за которого забросил онлайн-игры. Теперь он примерный старшеклассник, терзаемый раскаянием за свой прошлый образ жизни, и подрабатывает в интернет-кафе, принадлежащем его подруге детства Нодзоми Инацуки, чтобы поддержать семью. Но однажды случай вновь возвращает Сюна в мир онлайн-игр. После внезапного ухода всех игроков из FOX ONE — киберспортивной команды отца Нодзоми — Сюн узнаёт, что семья Инацуки погрязла в долгах. Чтобы помочь расплатиться с ними, Сюн неохотно соглашается принять участие в турнире по онлайн-игре Xaxerion Championship.Вместе с одноклассником Акито Сэндо они втроём принимаются искать талантливых игроков, чтобы возродить команду. Им везёт найти двух многообещающих новичков для FOX ONE, но радоваться рано: если Сюн не сумеет избавиться от гнетущего чувства вины, у наспех собранной команды не будет ни единого шанса на победу в турнире.","poster":"https://shikimori.io/system/animes/original/55894.jpg?1710724918","url":"https://shikimori.one/animes/55894-bokura-no-ame-iro-protocol","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Низкоуровневый персонаж Томодзаки","rating":11,"tier":"great","review":"","desc":"«Что наша жизнь? Игра!»    \n   Примерно такого же мнения придерживается и главный герой этого аниме — старшеклассник Фумия Томодзаки. И, в общем-то, для этого у него есть некоторые основания, ведь он один из лучших игроков в Японии. Вот только он убеждён, что жизнь — это самая паршивая игра из всех возможных. Нет никаких чётких условий, выполнив которые, сможешь достичь успеха, никакой определённости и баланса, да и попросту говоря — вообще никакого смысла нет! В игре есть цель, есть награда, а в жизни что? Несколько разочарованный в игре под названием «Жизнь», Томодзаки знакомится с Аой Хинами — девушкой, которая является игроком не хуже его самого. И вот Аой предлагает юноше свою помощь в освоении этой сложной игры.","poster":"https://shikimori.io/system/animes/original/40530.jpg?1711955484","url":"https://shikimori.one/animes/40530-jaku-chara-tomozaki-kun","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Школа"],"episodes":12,"kind":"tv","franchise":"tomozaki"},{"title":"Повелитель 2","rating":11,"tier":"great","review":"","desc":"Продолжение аниме-сериала «Повелитель», созданного режиссёром Наоюки Ито.\n\nИстория повествует о Момонге, скелете-волшебнике, который остался в легендарной онлайн-игре под названием «Иггдрасиль» из-за некорректной работы сервера. Не имея друзей, родителей и места под солнцем в реальной жизни, он решает не пытаться найти выход из игры и ставит одну-единственную цель: захватить этот мир и прославить имя «Айнза Ул Гоуна». Для усиления Назарика Момонге нужна сильная армия нежити, а для этого нужны сильные, крепкие тела. Он приказывает уничтожить род людоящеров. На сей раз зрителю покажут попытки противостояния людоящеров против Момонги.","poster":"https://shikimori.io/system/animes/original/35073.jpg?1711968222","url":"https://shikimori.one/animes/35073-overlord-ii","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":13,"kind":"tv","franchise":"overlord"},{"title":"Соблазн 2,5-мерного измерения","rating":11,"tier":"great","review":"","desc":"«Меня совершенно не интересуют настоящие девушки!» — заявляет Масамунэ Окумура, заядлый отаку и по совместительству лидер школьного клуба манги. Зачем они нужны, когда у тебя уже есть любимая вайфу?   \n   Всё меняется, когда на пороге клуба появляется настоящая девушка — Ририса Амано. Сначала парень хотел прогнать её, однако выяснилось, что она знает об аниме и манге ничуть не меньше самого Окумуры, да ещё обладает схожими с ним вкусами! Кроме того, Ририса увлечена косплеем и сразу доказывает это, перевоплотившись в любимую героиню парня — Лилиэль. Неужели граница между 2D и 3D постепенно начинает стираться?!","poster":"https://shikimori.io/system/animes/original/53802.jpg?1714587348","url":"https://shikimori.one/animes/53802-2-5-jigen-no-ririsa","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Комедия","Этти","Гарем","Школа"],"episodes":24,"kind":"tv","franchise":null},{"title":"Ты - горничная","rating":11,"tier":"great","review":"миленько, но одноразово","desc":"Однажды в дверь Хитоёси постучали. У входа он обнаружил незнакомку, которая с порога предложила нанять её в качестве горничной. Опешивший Хитоёси Ёкоя, хоть и сомневался в том, что поступает правильно, согласился взять девушку к себе. Пообвыкшись, девушка поведала, что раньше была киллером. Хитоёси пребывал в замешательстве от этого открытия, не зная как поступить, но отбросил все сомнения, после того как новоиспечённая горничная спасла ему жизнь.   \n   Уверенность в своих работниках — это здорово, вот только оказалось, что хозяйка из девушки никакая. Изучение домоводства и время, проведённое с Ёкоей, наполняют жизнь горничной прежде неизвестными эмоциями, вдохновляя её начать всё сначала и стать обычной девушкой. Чтобы начать с чистого листа, она просит дать ей новое имя, и Ёкоя решает назвать её Юки. Обретя близких людей, Юки наслаждается каждым моментом мирных будней в надежде, что сможет оставить своё жестокое и тёмное прошлое позади.","poster":"https://shikimori.io/system/animes/original/57611.jpg?1711222643","url":"https://shikimori.one/animes/57611-kimi-wa-meido-sama","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Приключения","Драма"],"episodes":12,"kind":"tv","franchise":null},{"title":"Шпионский класс 2","rating":11,"tier":"great","review":"","desc":"Четверо участников шпионской команды «Лэмплайт» из Республики Дин отправляются на задание — захватить вражеского агента. Несмотря на разногласия в характерах, из-за которых слаженная работа даётся им нелегко, Тиа, Моника, Эрна и Аннетт всё же справляются с поставленной целью. Наслаждаясь коротким отдыхом, девушки встречают женщину по имени Матильда, которая называет себя матерью Аннетт. Узнавая Матильду ближе, команда невольно оказывается втянута в стремительно нарастающий конфликт, испытывающий на прочность их сплочённость и верность друг другу.[br][br]Тем временем оставшиеся участники «Лэмплайта» замечают, что отправленный отряд до сих пор не вышел на связь. Обеспокоенные судьбой товарищей, Клаус и Лили отправляются в срочную экспедицию на поиски пропавших членов команды. Раскрывая тревожные сведения о нарастающей напряжённости в районе, где в последний раз видели их друзей, они понимают: нужно действовать быстро, чтобы воссоединить команду прежде, чем миссия достигнет точки невозврата.","poster":"https://shikimori.io/system/animes/original/54947.jpg?1710727126","url":"https://shikimori.one/animes/54947-spy-kyoushitsu-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Детектив"],"episodes":12,"kind":"tv","franchise":"spy_classroom"},{"title":"Убивая слизней 300 лет, неожиданно взяла максимальный уровень 2","rating":10,"tier":"solid","review":"","desc":"До боли знакомый каждому любителю историй о перемещениях в иные миры сюжет расскажет об офисной служащей по имени Адзуса Аидзава. Одним прекрасным днём она умирает от переутомления. Однако ей даруют шанс начать новую жизнь в альтернативном мире. Теперь Адзуса живёт в теле семнадцатилетней девушки, став бессмертной ведьмой, и ведёт спокойную жизнь в небольшом домике в горах. Единственным доходом для неё является уничтожение низкоуровневых слизней, обитающих поблизости. И так проходит 300 лет...","poster":"https://shikimori.io/system/animes/original/40586.jpg?1711974494","url":"https://shikimori.one/animes/50949-slime-taoshite-300-nen-shiranai-uchi-ni-level-max-ni-nattemashita-sono-ni","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Приключения"],"episodes":12,"kind":"tv","franchise":"slime_300"},{"title":"Арифурэта: Сильнейший ремесленник в мире 3","rating":10,"tier":"solid","review":"ну как-то чёт не о чём","desc":"Жизнь семнадцатилетнего Хадзимэ  переворачивается с ног на голову в тот самый момент, когда он со своими одноклассниками попадает в иной мир.   \n   Однако до боли знакомый любому отаку сюжет, где героя наделяют непревзойдёнными способностями, зачастую попирающими все мыслимые и немыслимые законы мироздания, даёт трещину ровно тогда, когда всех призванных юношей и девушек наделяют божественными дарами и классами.   \n   Впрочем, ничем не выделяющемуся школьнику, который до недавних пор прослыл изгоем среди своих сверстников, и в этот раз не светит билет в счастливое будущее, так как ему достались самые невзрачные и в плане наращивания боевого потенциала довольно посредственные силы. Сможет ли теперь он пережить все уготованные ему невзгоды и обрести славу великого героя?","poster":"https://shikimori.io/system/animes/original/36882.jpg?1711942149","url":"https://shikimori.one/animes/36882-arifureta-shokugyou-de-sekai-saikyou","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Гарем"],"episodes":13,"kind":"tv","franchise":"arifureta"},{"title":"Сладкий лимонад","rating":10,"tier":"solid","review":"Хорошо закончилось, продолжения не нужно. Хорошая одноразовая романтика.","desc":"С самого детства крайне застенчивой Уке Исимори трудно сближаться с людьми. Она буквально замирает как вкопанная, когда кто-то пытается с ней заговорить, поэтому в средней школе её «наградили» малоприятным прозвищем Камень. Понимая, что так не может дальше продолжаться, уже старшеклассница Ука решила попытаться взять в себя в руки и стать более открытой для других. Однако её решимость тут же охладили, облив газировкой в первый же день учёбы.   \n   Виновником этого инцидента стал Кай Миура, привлекательный парень с волосами цвета лимонада, который оказался полной противоположностью Уки. Популярный, открытый, умеющий постоять за себя, протянуть руку помощи и готовый приободрить, Кай — человек, которым девушка мечтает когда-нибудь стать.   \n      \n   Так или иначе противоположности всегда притягиваются, и вскоре между робкой Укой и общительным Каем завязались дружеские отношения. Застенчивость девушки не смущает парня, так что он поможет Уке шаг за шагом выйти из своей скорлупы и стать более раскрепощённой, а дружеские чувства между молодыми людьми вскоре перерастут в нечто большее.","poster":"https://shikimori.io/system/animes/original/58271.jpg?1717229829","url":"https://shikimori.one/animes/58271-honey-lemon-soda","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Боевой отряд «Полный провал»","rating":10,"tier":"solid","review":"Прикольная анимка, мног очего происходит, пресонажи интересные, но чего-то мне не хватило. Но персонажей я некоторых полюбил.","desc":"Люди обожают героев в ярких костюмах, которые всегда готовы прийти на помощь страждущим и спасти невинных. Обожают так сильно, что снимают про них кино- и мультфильмы, ставят спектакли и задействуют в телепередачах. Жаль, что искренне и безоговорочно верить в происходящее могут только дети, да и те быстро вырастают из сказок про бравых рейнджеров.   \n      \n   А что, если всё будет взаправду? Всамделишные монстры, настоящие сражения, реальные подвиги! Хотели японцы такого экстрима или не хотели, но с ними это произошло. Тринадцать лет назад в небе завис корабль с армией монстров, которые объявили, что планируют захватить Землю. Противостоять нападению вызвались смелые защитники — Хранители драконов, которые за год уничтожили всех главарей вторжения. В живых остались только слабые пешки-комбатанты, которые, к счастью или на беду, практически бессмертны.   \n      \n   Человечество одержало безоговорочную победу, однако знают об этом только сами неудавшиеся захватчики, герои-рейнджеры и их начальство. Год регулярных сражений в прямом эфире, на трансляции которых можно делать неплохие деньги, и организаторы не захотели отказываться от золотой жилы. И вот показательные выступления, которые весь мир принимает за натуральные бои, продолжаются уже двенадцать лет.   \n   Всех всё устраивает: зрители в восторге, рейнджеры получают славу и почёт, закулисные боссы гребут прибыль, и только бедные комбатанты страдают, оказавшись заложниками развлекательной индустрии.   \n   Лишь один-единственный комбатант Ди устал терпеть это издевательство и вопреки всему, веря в победу Зла, решил хоть что-нибудь предпринять. Замаскировавшись, он вступает в ряды доблестных рейнджеров!","poster":"https://shikimori.io/system/animes/original/53770.jpg?1718588567","url":"https://shikimori.one/animes/53770-sentai-daishikkaku","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Сёнэн"],"episodes":12,"kind":"tv","franchise":"sentai_daishikkaku"},{"title":"Ангел по соседству","rating":10,"tier":"solid","review":"","desc":"Аманэ Фудзимия — обычный старшеклассник, который прослыл одиночкой. Он немного ленив, неряшлив и необщителен, однако способен трезво оценить окружающую обстановку и благодаря этому избежать проблем.    \n   Махиру Сина — соседка Аманэ Фудзимии и его полная противоположность. Яркая, общительная и красивая, она в мгновение ока способна стать самой популярной девушкой в школе.    \n      \n   Между этими двумя нет ничего общего, но, как это обычно бывает, противоположности притягиваются.    \n   Возвращаясь домой после занятий, Аманэ Фудзимия заметил одинокую фигуру Махиру на качелях. Промокшая до нитки, девушка выглядела подавленной, и парень не смог пройти мимо. Отдав ей свой зонт, Аманэ спешно ретировался. Однако добрый поступок не прошёл бесследно, уже на следующий день Аманэ почувствовал недомогание, а Махиру Сина, случайно заметившая состояние своего соседа, решила позаботиться о больном.    \n   Таким образом и началась эта романтическая история, наполненная теплотой, заботой и нелепыми ситуациями.","poster":"https://shikimori.io/system/animes/original/50739.jpg?1713148963","url":"https://shikimori.one/animes/50739-otonari-no-tenshi-sama-ni-itsunomanika-dame-ningen-ni-sareteita-ken","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Школа","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Бармен: Бокал бога","rating":10,"tier":"solid","review":"","desc":"В закоулках района Гинза скрывается Eden Hall — тихое и уютное заведение, которым управляет гениальный бармен Рю Сасакура. Ходят слухи, что, выслушав сетования клиента, он может смешать индивидуальный коктейль, который будет для посетителя наивкуснейшим. А после угощения Сасакура даст совет, как клиенту справиться с его бедой.   \n   Однако найти бар Eden Hall будет непросто, точнее, это он должен найти вас. Все посетители уникальны: у каждого своя история, свои проблемы, которые терзают душу и не дают покоя, и когда кажется, что уже ничего не поможет... добро пожаловать в наш бар!   \n   Рю всегда знает рецепт идеального коктейля, который утешит израненную душу и направит её по пути излечения.","poster":"https://shikimori.io/system/animes/original/53407.jpg?1718304395","url":"https://shikimori.one/animes/53407-bartender-kami-no-glass","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Гурман","Работа","Сэйнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Башня Бога 2","rating":10,"tier":"solid","review":"Сюжет интересный, а вот рисовка гавна","desc":"Башня бога — место, в котором сбываются мечты и разбиваются сердца, только сильный духом сможет добраться до самого верха. Именно этого всю жизнь хотела Рахиль, и Двадцать пятый Баам отправился за ней, потому как эта девушка была для него единственным лучиком света в этом мрачном и недружелюбном мире. При входе в башню больше не будет пути назад — только наверх, к новым испытаниям. Многое здесь ждёт главных героев: радость и волнения, победы и поражения, боль и утрата. Смогут ли они добраться до вершины?","poster":"https://shikimori.io/system/animes/original/40221.jpg?1711957297","url":"https://shikimori.one/animes/52635-kami-no-tou-ouji-no-kikan","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Драма","Фэнтези","Детектив"],"episodes":12,"kind":"tv","franchise":"tower_of_god"},{"title":"Вайолет Эвергарден: Вечность и призрак пера","rating":10,"tier":"solid","review":"","desc":"«] ]: Вечность и призрак пера» изображает жизнь благородной девушки Изабеллы Йорк, наследницы дома Йорков, которая вынуждена посещать школу для привилегированных молодых особ. Несмотря на элитность и престижность школы, для Изабеллы это учебное заведение — настоящая тюрьма, потому что она задыхается в её стенах. Потерявшая всякую надежду Изабелла встречает Вайолет Эвергарден, которая назначена её личным инструктором. Поначалу и Вайолет не слишком радует Изабеллу.","poster":"https://shikimori.io/system/animes/original/39741.jpg?1711979796","url":"https://shikimori.one/animes/39741-violet-evergarden-gaiden-eien-to-jidou-shuki-ningyou","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Драма","Фэнтези","Комедия"],"episodes":1,"kind":"movie","franchise":"violet_evergarden"},{"title":"Вермейл в золотом","rating":10,"tier":"solid","review":"","desc":"Студент первого курса академии «Ортигия», Альто Голдфиллд, потерпел неудачу в магическом призыве и теперь, если не сумеет призвать фамильяра, будет вынужден остаться на второй год. В надежде найти толику полезной информации об этих самых призывах он направился в библиотеку, где случайно нашёл древнюю книгу. Воодушевившись, Альто начертил магический круг, произнёс заклинание и призвал демоницу по имени Вермейл, которая издавна была известна своей ужасающей силой и способностью вызывать катастрофы. Представшая перед ним женщина была дерзка и полностью обнажена, чем смутила молодого парня, но Альто Голдфиллд сумел-таки взять себя в руки и озвучил свое желание: «Стань моим фамильяром!»   \n      \n   Новоиспечённому фамильяру жизненно необходима ежедневная подзарядка магической энергией, которую Вермейл получает от хозяина через поцелуй, и пока ученики академии пребывают в лёгком шоке от парочки, Лилия Кудельфейт, давняя подруга Альто, начинает завидовать их особым отношениям.","poster":"https://shikimori.io/system/animes/original/51213.jpg?1713754440","url":"https://shikimori.one/animes/51213-kinsou-no-vermeil-gakeppuchi-majutsushi-wa-saikyou-no-yakusai-to-mahou-sekai-wo-tsukisusumu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Этти","Школа","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Витубер: Я стала популярной после того, как забыл","rating":10,"tier":"solid","review":"","desc":"— витубер третьего поколения в агентстве LiveOn, известная своим строгим, утончённым и почти ангельским образом. Она говорит вежливо, ведёт себя идеально и старается быть примером для других. Но за красивой аватаркой скрывается совсем другая личность — и одна случайная ошибка раскрывает всё.   \n   Однажды ночью Аваюки забывает выключить стрим. Тысячи зрителей становятся свидетелями её настоящей стороны: грубые выражения, пиво, откровенные комментарии о коллегах и полное отсутствие какой-либо скромности. Интернет взрывается, клипы расходятся по соцсетям, а агентство… неожиданно в восторге! Оказывается, именно такого контента от неё и ждали.   \n   Теперь, когда Аваюки получает зелёный свет на своё настоящие поведение: никаких фильтров, никаких притворств. Её трансляции превращаются в шоу без тормозов, где она наконец-то может быть собой — и это приносит ей настоящую популярность. Но сможет ли девушка удержаться на волне успеха, когда всё строится на хаосе и откровенности?","poster":"https://shikimori.io/system/animes/original/54284.jpg?1714634114","url":"https://shikimori.one/animes/54284-vtuber-nandaga-haishin-kiri-wasuretara-densetsu-ni-natteta","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Приключения","Драма"],"episodes":12,"kind":"tv","franchise":null},{"title":"Волшебник ледяного клинка правит миром","rating":10,"tier":"solid","review":"","desc":"В престижной Магической академии Арнольда обучаются только аристократы, хотя формально никакого запрета на обучение простолюдинов нет. Просто сам социальный уклад выдавливает бедняков от попадания в высшие сферы: даже обнаружив в себе магические способности, обычные граждане не могут их развить, так как книги и учителя стоят денег.   \n   Рей Уайт стал первым простолюдином, поступившим в академию, и ещё до своего появления вызвал волну негодования от высокомерных учеников. Вот только презрение одноклассников мало волнует Рея, он вообще его едва замечает. Ему нет дела до малодушного брюзжания окружающих по той причине, что он один из семи сильнейших магов мира, знаменитый Маг ледяного клинка, герой войны, участвовавший в ней с самого детства. Пережив в малом возрасте столько, сколько и не снилось иным взрослым, Рей замкнут, нацелен на результат и испытывает некоторые проблемы с проявлением и пониманием эмоций.   \n   Почему Рей поступил в школу инкогнито? Сможет ли он, безэмоциональный ветеран, влиться в ряды гормонально нестабильных подростков и найти друзей, которых у него никогда не было? Сумеет ли жить обычной школьной жизнью?","poster":"https://shikimori.io/system/animes/original/51711.jpg?1713147838","url":"https://shikimori.one/animes/51711-hyouken-no-majutsushi-ga-sekai-wo-suberu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Глейпнир","rating":10,"tier":"solid","review":"","desc":"Небольшой скучный городок, вроде бы среднестатистический старшеклассник Сюити Кагая — обычный набор для развития необычной истории. Сюжет завязывается, когда красавица Клэр Аоки оказывается в огненной ловушке на складе и Сюити вынужден использовать свою загадочную способность. Он может превращаться в большую собаку, у которой на спине молния, а на боку — револьвер. Кагая спасает девушку, раскрывая тем самым свой секрет. Однако оказывается, что у Клэр свой скелет в шкафу: её семью убила собственная сестра Клэр. И теперь Аоки жаждет разыскать сестру чего бы это ни стоило, поэтому она решает использовать парня и его силу в своих целях...","poster":"https://shikimori.io/system/animes/original/39463.jpg?1711951456","url":"https://shikimori.one/animes/39463-gleipnir","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Детектив","Сверхъестественное","Сэйнэн"],"episodes":13,"kind":"tv","franchise":null},{"title":"Дочь моей мачехи — моя бывшая девушка","rating":10,"tier":"solid","review":"","desc":"Апатичный гик Мидзуто Иридо и замкнутый ботаник Юмэ Иридо казались парой, заключённой на небесах, ведь их связывала взаимная любовь к литературе. К сожалению, их разногласия постепенно росли, и они расстались сразу после окончания средней школы. Однако, по иронии судьбы, эти двое вскоре воссоединились как сводные брат и сестра.   \n      \n   Между бывшей парой вспыхнуло глупое соперничество за «главенство» в семье: ни тот, ни другой не желают признать старшинство противника. Пытаясь решить этот вопрос, Мидзуто и Юмэ заключают пари, что старшим станет тот, кто сможет удержаться и не переступить границы родственных отношений. Соответственно, тот, кто даст слабину и вспомнит былые чувства — проиграл, и не только должен будет называть победителя старшим братом или сестрой, но и обязан выполнить любое желание выигравшего. Однако теперь, когда они живут под одной крышей, их воспоминания начинают оживать, возрождая нежные чувства, которые, возможно, всё ещё теплятся в их сердцах.","poster":"https://shikimori.io/system/animes/original/49470.jpg?1703475537","url":"https://shikimori.one/animes/49470-mamahaha-no-tsurego-ga-motokano-datta","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Магическая битва 0","rating":10,"tier":"solid","review":"","desc":"Много лет назад Юта Оккоцу [乙骨 憂太] и его подруга детства Рика Оримото [折本 理香] пообещали друг другу, что поженятся, когда вырастут. Однако этому обещанию не суждено было сбыться. Рика трагично погибла в результате дорожно-транспортного происшествия. Всё, что от неё осталось, — старое кольцо и монструозный проклятый дух, преследующий Юту и бесконтрольно уничтожающий его обидчиков. В результате очередной особо жестокой атаки юношу задерживают маги — люди, избавляющие мир от проклятий — и приговаривают к казни из-за необычного уровня силы сопровождающего парня призрака. Но у Сатору Годзё [五条 悟], сильнейшего мага Японии, есть иные планы на этот счёт. Он предлагает Юте перевестись в Токийский столичный технический колледж магии, где сам работает преподавателем, чтобы направить мощь духа в правильное русло и научить парня уничтожать монстров с его помощью. Согласившись, Оккоцу встречает других учеников: Маки Дзэнин [禪院 真希], виртуоза проклятого оружия, Тогэ Инумаки [狗巻 棘], обладателя проклятой речи, и Панду [パンダ], разумного медведя. Обучаясь, Юта впервые в жизни начинает понимать себя, верить в свои силы и налаживать общение с окружающими. Но вот за пределами школы всё не так спокойно, ведь заклятый друг Сатору, маг Сугуру Гэто [夏油 傑], готовится осуществить свой мрачный план...","poster":"https://shikimori.io/system/animes/original/48561.jpg?1708744812","url":"https://shikimori.one/animes/48561-jujutsu-kaisen-0-movie","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Боевик","Фэнтези","Сёнэн"],"episodes":1,"kind":"movie","franchise":"jujutsu_kaisen"},{"title":"Мастера Меча Онлайн: Альтернативная «Призрачная пуля» 2","rating":10,"tier":"solid","review":"","desc":"Карэн  всегда чувствовала себя лишней в реальном мире... Как будто она не принадлежит ему. Из-за своего высокого роста (целых 183 см!) девушке было очень трудно завести подруг среди ровесниц. Но всё изменилось, когда Карэн познакомилась с небезызвестной VRMMORPG — «Gun Gale Online». В мире «GGO» Карэн может сыграть за персонажа своей мечты — невысокую девочку, одетую во всё розовое. Но сможет ли Карэн найти друзей в этой экшен-игре?","poster":"https://shikimori.io/system/animes/original/36475.jpg?1711975864","url":"https://shikimori.one/animes/56468-sword-art-online-alternative-gun-gale-online-ii","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":"sao_alternative"},{"title":"Мой братик теперь не братик!","rating":10,"tier":"solid","review":"","desc":"Одним совершенно не примечательным утром заядлый отаку и безвылазный домосед Махиро Ояма с ужасом обнаружил, что в его теле произошли катастрофические изменения — он стал маленькой девочкой! Виновницей этого кардинального и шокирующего преображения оказалась его младшая сестра Михари, решившая сделать из брата подопытного кролика, ну и заодно вытащить его из зоны комфорта. Теперь Махиро предстоит столкнуться с женскими проблемами, вытерпеть ставшие шумными будни и, конечное дело, найти новых друзей!","poster":"https://shikimori.io/system/animes/original/51678.jpg?1711938641","url":"https://shikimori.one/animes/51678-oniichan-wa-oshimai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Школа","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Ниндзя Камуи","rating":10,"tier":"solid","review":"","desc":"Действие аниме происходит в период Эдо. Ниндзя по имени Камуи принимает решение покинуть свой клан и становится мишенью для бывших товарищей, которые начинают преследовать его, чтобы смертью наказать за предательство. Находясь в бегах, Камуи вынужден постоянно скитаться по стране и скрываться, используя весь свой интеллект и навыки, чтобы выжить. Постепенно, преследуемый коварными убийцами, Камуи перестаёт верить людям и впадает в паранойю, считая, что каждый встреченный им человек жаждет его прикончить.","poster":"https://shikimori.io/system/animes/original/5023.jpg?1711966582","url":"https://shikimori.one/animes/5023-ninpuu-kamui-gaiden","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","История","Боевые искусства","Самураи"],"episodes":26,"kind":"tv","franchise":null},{"title":"Перерождение: Монстр","rating":10,"tier":"solid","review":"","desc":"Умерев насильственной смертью, Томокуи Каната, который при жизни обладал сверхъестественными способностями, переродился в другом мире как гоблин — представитель низшей, самой слабой расы. Однако память о прошлой жизни и человеческий разум всё ещё при нём, так что не всё так печально и бесперспективно. Понемногу развиваясь и адаптируясь к новым условиям, новоиспечённый гоблин, при рождении получивший имя Ро, выяснил, что его ключевая, оригинальная и очень редкая способность из прошлой жизни всё ещё с ним. Пускай придётся начинать всё сначала, но стартовые данные у него заметно лучше, чем у других. Так что в непростом деле выживания он уже впереди как собратьев-гоблинов, так и некоторых других разумных рас.   \n   Далеко ли сможет продвинуться по пути эволюции Ро, ещё недавно бывший человеком? Или его прогресс остановят непредвиденные обстоятельства, которые уже однажды привели его к бесславной и глупой кончине?","poster":"https://shikimori.io/system/animes/original/56690.jpg?1718207279","url":"https://shikimori.one/animes/56690-re-monster","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Повелитель","rating":10,"tier":"solid","review":"","desc":"Легендарная онлайн-игра «Иггдрасиль» неожиданно закрывается. Желая остаться в любимом мире подольше, игрок, управляющий персонажем по имени Момонга , решает оставаться в игре до полного отключения серверов. Момонга — лич, глава одной из топовых гильдий, представляющих в игре «тёмную» сторону. В момент отключения сервера он собрал всех своих прислужников в главном зале гильдии, сел на трон и стал ждать неизбежного.   \n   Но произошло невероятное: сервер не прервал подключение, игра продолжилась, а Момонга превратился в скелета, могущественного волшебника. Неигровые персонажи вдруг начали проявлять человеческие эмоции. Не имея родителей, друзей и места в обществе, Момонга решает не пытаться найти выход из игры, а остаться в новом мире, дабы его завоевать.","poster":"https://shikimori.io/system/animes/original/29803.jpg?1711968252","url":"https://shikimori.one/animes/29803-overlord","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":13,"kind":"tv","franchise":"overlord"},{"title":"Поднятие уровня в одиночку","rating":10,"tier":"solid","review":"","desc":"Десять лет назад по всему миру стали открываться некие «врата», ведущие в подземелья с монстрами, противостоять которым оказалось не под силу даже военным. Однако если успеть вовремя победить босса подземелья, то врата пропадут, не открывшись, и мирные люди не пострадают. Сразиться с боссом способны только избранные — люди, получившие особые силы, чтобы бороться с чудовищами. Таких людей назвали «охотниками». Вот только способности, которые они получают, крайне различны как по функционалу, так и по мощи.   \n      \n   Например, охотник Сон Джину относится всего лишь к рангу Е: хоть и сильнее обычного человека, он в разы слабее любого самого слабого охотника. Он не в состоянии справиться с самым ничтожным монстром, поэтому вынужден ходить в подземелье в составе большой группы. Напарники убивают всю мелочь, так что у Сон Джину нет возможности хорошо заработать на охоте. Нет денег, а значит нет финансов на улучшение снаряжения. В общем, замкнутый круг. Однако он продолжает заниматься «охотой», чтобы оплатить больничные счета матери, которая находится в коме.   \n      \n   Всё изменилось, когда, отправившись в очередное низкоранговое подземелье, они с командой наткнулись на очень странную вещь — ещё одно подземелье, которое оказалось внутри того, что они уже очистили. Решив рискнуть, они вошли внутрь.","poster":"https://shikimori.io/system/animes/original/52299.jpg?1710732907","url":"https://shikimori.one/animes/52299-ore-dake-level-up-na-ken","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Приключения","Сверхъестественное"],"episodes":12,"kind":"tv","franchise":"solo_leveling"},{"title":"Развращённая гильдия","rating":10,"tier":"solid","review":"","desc":"Кикуру Мадана — страж, хранящий покой города, защищая его от монстров. Несмотря на юный возраст, он первоклассный охотник, так как всю  жизнь провёл в тренировках и совершенствовании навыков. Осознав вдруг, что молодость уходит и он может не успеть ею насладиться, Кикуру решает исправить это недоразумение и объявляет, что покидает гильдию. Тогда администратор Эноме просит Кикуру сначала подготовить замену себе и поднатаскать новенькую, неуклюжую зверодевушку Хитаму.","poster":"https://shikimori.io/system/animes/original/51212.jpg?1711939460","url":"https://shikimori.one/animes/51212-futoku-no-guild","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Комедия","Фэнтези","Этти","Гарем"],"episodes":12,"kind":"tv","franchise":null},{"title":"Семь главенствующих мечей","rating":10,"tier":"solid","review":"","desc":"В магической академии «Кимберли» начался новый учебный год. Полные энтузиазма первогодки сгорают от нетерпения приступить к занятиям. Однако «Кимберли» — место опасное, ведь каждый пятый студент не доживает до конца обучения, и поступившие быстро это осознают.  Прямо на вступительной церемонии на ребят напал тролль. Одолеть его удалось бесстрашным новичкам Нанао Хибии и Оливеру Хорну. Это событие сделало их знаменитыми на всю академию, а также заложило основу для настоящей дружбы. Это была первая, но далеко не последняя опасность, что таит в себе академия магии «Кимберли». Нашим героям предстоит преодолеть все препятствия и разгадать тайны этого места.","poster":"https://shikimori.io/system/animes/original/50582.jpg?1711965489","url":"https://shikimori.one/animes/50582-nanatsu-no-maken-ga-shihai-suru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Школа"],"episodes":15,"kind":"tv","franchise":null},{"title":"Стесняшка 2","rating":10,"tier":"solid","review":"","desc":"По неизвестным широкой общественности причинам в мире вдруг появились люди, обладающие сверхспособностями — необычайной силой, умением летать и другими. Однако получили их немногие. И эти немногие, вставшие на защиту мира и человечества, стали известны как Герои. Они не только стали символами своих родных стран, но и гарантом безопасности и стабильности для обычных граждан. Войны прекратились, преступность почти искоренена. Супергерои теперь борются со стихийными бедствиями и несчастными случаями. В каждой крупной стране есть свой «супермен», который заботится о благополучии её жителей, а также представляет интересы своего государства в Совете героев. Японию представляет юная героиня Тэру Момидзияма, работающая под псевдонимом Стесняшка.        \n                \n        Пускай Тэру застенчива и полна сомнений, но она тоже настоящий герой! Так что когда на Землю обрушится новая неведомая угроза, Стесняшка будет отважно сражаться наравне с другими героями!","poster":"https://shikimori.io/system/animes/original/57567.jpg?1718826113","url":"https://shikimori.one/animes/57567-shy-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Супергероика","Драма","Сёнэн"],"episodes":12,"kind":"tv","franchise":"shy"},{"title":"Судьба/Начало 2","rating":10,"tier":"solid","review":"","desc":"","poster":"https://shikimori.io/system/animes/original/40812.jpg?1711949799","url":"https://shikimori.one/animes/11741-fate-zero-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Безумие","Музыка","Комедия"],"episodes":12,"kind":"tv","franchise":"fate_zero"},{"title":"Эльфийская песнь","rating":10,"tier":"solid","review":"","desc":"Диклониусы — побочная, мутировавшая ветвь людей, избранная, кажется, самим Богом, чтобы положить конец человечеству. От обычных людей их отличают небольшие рожки на голове и то, что они владеют как бы «шестым чувством», дающим им способность к телекинезу. Именно из-за этой опасной силы правительство отлавливает их и помещает в специальные лаборатории, где они подвергаются жестоким экспериментам.        \n        Люси  — юная и психически неуравновешенная девушка-диклониус, которой удаётся избавиться от сдерживающих её пут и предпринять попытку к бегству, по пути жестоко убивая охранников лаборатории: только выстрелив ей в голову из крупнокалиберного оружия, пулю которого она не успевает отклонить, охрана смогла нанести ей ущерб. Однако Люси удаётся выжить, упав с утёса в океан и дрейфуя некоторое время, пока двое молодых людей, Кота  и Юка , не находят её на пляже. Выстрел в голову вызвал потерю памяти и речевую дисфункцию: единственное, что она в состоянии сказать — междометие «ню», в честь которого нашедшие и окрестили её. В конце концов Кота отводит Люси к себе домой и позволяет ей жить там... Однако похоже на то, что тёмная сторона Люси никуда не исчезла...","poster":"https://shikimori.io/system/animes/original/226.jpg?1711948893","url":"https://shikimori.one/animes/z226-elfen-lied","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Триллер"],"episodes":13,"kind":"tv","franchise":"elfen_lied"},{"title":"Я парировал всё время, чтобы стать сильнейшим","rating":10,"tier":"solid","review":"","desc":"Творятся какие-то тёмные и опасные для страны дела, — понимает правящая верхушка королевства Клейз. Совершено покушение на принцессу, стали появляться сверхмощные монстры, явно созданные людскими руками, — кто-то подталкивает страну к развязыванию войны.        \n                \n        Простолюдин Ноор не имеет об этом всём ни малейшего понятия. Оставшись в детстве сиротой, он, как завещала ему перед смертью мать, всю жизнь стремился к исполнению своей мечты. А мечтал он о том, чтобы стать авантюристом. К сожалению, он в этом не преуспел. Как оказалось, у него нет ни одного приличного навыка. Пройдя через несколько тренировочных центров и так ничего и не добившись, Ноор не отчаялся, а продолжил заниматься в одиночку, параллельно нанимаясь на всякие подсобные работы.        \n                \n        Десять лет ежедневных тренировок привели к тому, что Ноор теперь может парировать одновременную атаку сразу тысячи мечей. Только ведь этого мало, чтобы стать авантюристом, так? Но ничего страшного, Ноор не против проверенного способа добиться цели — он готов и дальше упорно трудиться над собой!","poster":"https://shikimori.io/system/animes/original/57058.jpg?1714765311","url":"https://shikimori.one/animes/57058-ore-wa-subete-wo-parry-suru-gyaku-kanchigai-no-sekai-saikyou-wa-boukensha-ni-naritai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Киберпанк: Бегущие по краю","rating":10,"tier":"solid","review":"","desc":"Дэвид Мартинес — уличный подросток из неблагополучного района Санто-Доминго в Найт-Сити, городе будущего, одержимом высокими технологиями и модификацией тела. Потеряв всё после трагического инцидента, Дэвид решает выжить в жестоком мире, установив военный киберимплант «Сандевистан» и начав путь наёмника-эджраннера.","poster":"https://shikimori.io/system/animes/original/42310.jpg?1711946940","url":"https://shikimori.one/animes/42310-cyberpunk-edgerunners","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Киберпанк","Драма","Психология"],"episodes":10,"kind":"ona","franchise":null},{"title":"Боевой отряд «Полный провал» 2","rating":10,"tier":"solid","review":"чет пидец какой-то вроде интересно но и хуйни натрусили","desc":"Люди обожают героев в ярких костюмах, которые всегда готовы прийти на помощь страждущим и спасти невинных. Обожают так сильно, что снимают про них кино- и мультфильмы, ставят спектакли и задействуют в телепередачах. Жаль, что искренне и безоговорочно верить в происходящее могут только дети, да и те быстро вырастают из сказок про бравых рейнджеров.        \n                \n        А что, если всё будет взаправду? Всамделишные монстры, настоящие сражения, реальные подвиги! Хотели японцы такого экстрима или не хотели, но с ними это произошло. Тринадцать лет назад в небе завис корабль с армией монстров, которые объявили, что планируют захватить Землю. Противостоять нападению вызвались смелые защитники — Хранители драконов, которые за год уничтожили всех главарей вторжения. В живых остались только слабые пешки-комбатанты, которые, к счастью или на беду, практически бессмертны.        \n                \n        Человечество одержало безоговорочную победу, однако знают об этом только сами неудавшиеся захватчики, герои-рейнджеры и их начальство. Год регулярных сражений в прямом эфире, на трансляции которых можно делать неплохие деньги, и организаторы не захотели отказываться от золотой жилы. И вот показательные выступления, которые весь мир принимает за натуральные бои, продолжаются уже двенадцать лет.        \n        Всех всё устраивает: зрители в восторге, рейнджеры получают славу и почёт, закулисные боссы гребут прибыль, и только бедные комбатанты страдают, оказавшись заложниками развлекательной индустрии.        \n        Лишь один-единственный комбатант Ди устал терпеть это издевательство и вопреки всему, веря в победу Зла, решил хоть что-нибудь предпринять. Замаскировавшись, он вступает в ряды доблестных рейнджеров!","poster":"https://shikimori.io/system/animes/original/53770.jpg?1718588567","url":"https://shikimori.one/animes/53770-sentai-daishikkaku","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Сёнэн"],"episodes":12,"kind":"tv","franchise":"sentai_daishikkaku"},{"title":"Сверхкуб","rating":10,"tier":"solid","review":"начало эпик, концовка подвела","desc":"Ван Сяосю Ван с самого детства испытывает чувства к своей подруге детства Яо Шэнь Яо. Теперь они учатся в одном колледже, и парень с удивлением обнаруживает, что Яо отвечает ему взаимностью. Однако слухи об их отношениях быстро расходятся, и вскоре Сяосю оказывается в центре внимания банды хулиганов во главе с Цзюнь Сунь Цзюнем, который сам положил глаз на Яо. Сражаясь за свою любовь, Сяосю теряет сознание и падает в реку.Очнувшись, он замечает на дне реки странное свечение. Стоит ему прикоснуться к светящемуся предмету, как тот сливается с его телом, увлекая юношу в иное измерение. Незнакомый голос представляется Кубом Хорадрика и объявляет Сяосю своим новым носителем. К счастью для парня, куб преподносит ему приятный сюрприз: теперь он способен телепортироваться, а его боевые навыки заметно улучшаются. Отныне Сяосю предстоит собирать драгоценные камни, чтобы куб мог поглощать их, даруя ему всё больше сил — ведь только так он сможет защитить себя и тех, кто ему дорог, от опасностей, которые поджидают впереди.","poster":"https://shikimori.io/system/mangas/original/117676.jpg?1708870526","url":"https://shikimori.one/animes/60057-chao-neng-lifang-chaofan-pian","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика","Триллер"],"episodes":12,"kind":"ona","franchise":null},{"title":"Искажённая страна чудес: Эпизод Хартслабьюла","rating":10,"tier":"solid","review":"","desc":"— обычный японский старшеклассник, который готовится к важному турниру по кэндо. Однако в ночь перед соревнованиями он попадает под колёса таинственного экипажа. Очнувшись, юноша обнаруживает себя в стенах престижного колледжа Ночного Ворона — учебного заведения для одарённых магов в искажённом мире, напоминающем Страну Чудес. Его главной проблемой становится полное отсутствие магических способностей, необходимых для пребывания в этом мире.        \n        Пока директор ищет способ вернуть его домой, герой вынужден приспосабливаться к жизни в колледже, выполняя различные поручения. Ситуация усложняется после инцидента на церемонии посвящения, когда он попадает в немилость к Риддлу Роузхартсу, строгому старосте общежития Червовые Сердца. Знакомство с двумя другими первокурсниками, Эйсом Трапполом и Дьюсом Спейдом, дарит надежду на дружбу, однако их безрассудные поступки приводят к серьёзным последствиям, грозящим исключением. Чтобы исправить ситуацию, герою приходится сопровождать новых товарищей в опасной миссии по исправлению нанесённого школе ущерба, бросив вызов гневу «Багрового Тирана».","poster":"https://shikimori.io/system/animes/original/50139.jpg?1714590938","url":"https://shikimori.one/animes/50139-disney-twisted-wonderland-the-animation-episode-of-heartslabyul","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сверхъестественное","Комедия","Приключения"],"episodes":8,"kind":"ona","franchise":null},{"title":"Я получил читерские способности в другом мире и стал экстраординарным в реальном мире: История о том, как повышение уровня изменило мою жизнь — Спецвыпуск","rating":10,"tier":"solid","review":"","desc":"Специальный ТВ-выпуск для «Я получил читерские способности в другом мире и стал экстраординарным в реальном мире: История о том, как повышение уровня изменило мою жизнь».","poster":"https://shikimori.io/system/animes/original/56906.jpg?1713124024","url":"https://shikimori.one/animes/56906-isekai-de-cheat-skill-wo-te-ni-shita-ore-wa-genjitsu-sekai-wo-mo-musou-suru-level-up-wa-jinsei-wo-kaeta-tv-special","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Школа"],"episodes":1,"kind":"tv_special","franchise":"cheat_skill_isekai"},{"title":"Похоже, сильнейшая профессия — это не герой или мудрец, а инспектор?","rating":10,"tier":"solid","review":"","desc":"Обычная жизнь шестнадцатилетнего старшеклассника  обрывается в тот момент, когда он по воле случая оказывается втянут в неизвестный ему мир, где магическая энергия и уровень определяют всё. Здесь отважные герои отправляются в смертельные походы, мудрецы управляют могущественными заклинаниями, а судьбы решаются в пылу сражений. Сам же юноша не получает ни великой силы, ни особого дара — вместо этого ему навязывают странную, на первый взгляд, бесполезную роль временного инспектора.        \n        Однако со временем выясняется, что его навыки позволяют видеть то, что скрыто от глаз местных жителей и даже опытных воинов: уязвимые места врагов, скрытые таланты союзников и саму структуру магии. Благодаря аналитическому складу ума и поразительной способности к адаптации, он начинает изучать правила новой реальности. В своих путешествиях Хибики обзаводится верными друзьями и спутниками, которые видят в его «бесполезной» профессии невероятный потенциал. Используя системные лазейки временного инспектора и поддержку товарищей, он шаг за шагом становится сильнее, проходя путь от слабого чужака до отважного лидера отряда, способного изменить этот удивительный мир к лучшему — наполнив его благополучием и надеждой для каждого.","poster":"https://shikimori.io/system/mangas/original/109045.jpg?1712842526","url":"https://shikimori.one/animes/62825-saikyou-no-shokugyou-wa-yuusha-demo-kenja-demo-naku-kanteishi-kari-rashii-desu-yo","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Драма","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Стесняшка","rating":9.5,"tier":"solid","review":"","desc":"По неизвестным широкой общественности причинам в мире вдруг появились люди, обладающие сверхспособностями — необычайной силой, умением летать и другими. Однако получили их немногие. И эти немногие, вставшие на защиту мира и человечества, стали известны как Герои. Они не только стали символами своих родных стран, но и гарантом безопасности и стабильности для обычных граждан. Войны прекратились, преступность почти искоренена. Супергерои теперь борются со стихийными бедствиями и несчастными случаями. В каждой крупной стране есть свой «супермен», который заботится о благополучии её жителей, а также представляет интересы своего государства в Совете героев. Японию представляет юная героиня Тэру Момидзияма, работающая под псевдонимом Стесняшка.        \n                \n        Пускай Тэру застенчива и полна сомнений, но она тоже настоящий герой! Так что когда на Землю обрушится новая неведомая угроза, Стесняшка будет отважно сражаться наравне с другими героями!","poster":"https://shikimori.io/system/animes/original/53237.jpg?1710730495","url":"https://shikimori.one/animes/53237-shy","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Драма","Супергероика","Сёнэн"],"episodes":12,"kind":"tv","franchise":"shy"},{"title":"Человек бензопила","rating":9.5,"tier":"solid","review":"","desc":"У Дэндзи  есть мечта — жить мирной и счастливой жизнью, проводя время с любимой девушкой. Однако суровая реальность в лице некоего якудзы заставляет парня вернуться с небес на землю, ведь он вынужден убивать демонов, чтобы расплатиться с необъятными долгами покойного отца. Вместе со своим дьявольским питомцем Почитой, которого использует в качестве оружия, Дэндзи готов сделать что угодно, даже за небольшую плату.        \n                \n        Вскоре парень изжил свою полезность и был убит демоном, заключившим контракт с якудзой. Но верный Почита спасает своего хозяина, заключив с ним контракт. Почита стал одним целым с умирающим Дэндзи, заменив ему сердце, и подарил ему силы человека-бензопилы. Теперь переродившийся Дэндзи, получив умение превращать части своего тела в бензопилы, использует новообретённые способности, чтобы быстро и жестоко расправляться с врагами. Попав под внимание Бюро общественной безопасности, парень получает работу охотника на демонов. Отныне, не страшась даже самых жестоких противников, Дэндзи не остановится ни перед чем, чтобы воплотить в жизнь свои мечты.","poster":"https://shikimori.io/system/animes/original/44511.jpg?1711945574","url":"https://shikimori.one/animes/44511-chainsaw-man","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Жизнь сорокалетнего мужчины в другом мире","rating":9,"tier":"solid","review":"","desc":"Сорокалетний Кэнъити Хамада не умирал, не был призван и не угодил под горячую руку бога, но всё равно оказался вдруг в ином мире. И хотя он посреди леса, в его распоряжении полезный навык — доступ к крупному онлайн-магазину, в котором продаётся буквально всё: от еды и одежды, до инструментов и домов. Надо только раздобыть денег, на которые можно это приобрести. Однако и то проблема решаемая: достаточно продать что-нибудь ненужное, поместив это в специальное подпространство.        \n        Отличные условия для неспешной, комфортной жизни в своё удовольствие, не так ли? И всё бы замечательно, но таких надёжных и опытных мужчин никто в здравом уме не упустит и не оставит в покое. Особенно, женщины любых возрастов, рас и социальных статусов, уж они-то в состоянии оценить мужчину в самом расцвете сил!","poster":"https://shikimori.io/system/mangas/original/147199.jpg?1712720434","url":"https://shikimori.one/animes/59561-around-40-otoko-no-isekai-tsuuhan","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай"],"episodes":13,"kind":"tv","franchise":null},{"title":"Я секретарь гильдии, но я не люблю сверхурочную работу, поэтому я собираюсь подчинить босса в одиночку","rating":9,"tier":"solid","review":"гг красивая, но аниме шлак полный, мемные сценки вывозят и милый перс","desc":"устраивается секретарём в гильдию искателей приключений с полной уверенностью, что эта спокойная, стабильная и прибыльная государственная должность станет её заветным билетом в размеренную жизнь без рисков и сюрпризов — отчёты, печати, немного логистики, и ни капли героизма. Но вскоре она сталкивается с суровой реальностью: искатели застревают в подземельях, рейды проваливаются, кто-то забывает сдать отчёт — всё это ложится на её плечи, переработки становятся нормой, а усталость и недосып — постоянными спутниками в жизни. В один из таких вечеров, когда очередной приказ «обработать ещё один рейд» звучит как насмешка, Алина решает, что хватит — если она всё равно держит гильдию на плаву, то и порядок в ней будет таким, каким она сочтёт нужным. Из-за желания избавиться от горы бумажной волокиты, она надевает свой плащ, спускается в подземелье, вызывает свой молот и начинает побеждать монстров в одиночку, скрывая свою деятельность от всех. Ведь если кто-то узнает, ей придётся отказаться от стабильной работы и стать искателем приключений, а это уже совсем другая жизнь, полная опасности, хаоса и нестабильности, к которой она вовсе не стремится.","poster":"https://shikimori.io/system/animes/original/55997.jpg?1713233717","url":"https://shikimori.one/animes/55997-guild-no-uketsukejou-desu-ga-zangyou-wa-iya-nanode-boss-wo-solo-toubatsu-shiyou-to-omoimasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Арифурэта: Сильнейший ремесленник в мире 2","rating":9,"tier":"solid","review":"","desc":"Перенесённый в другой мир и брошенный бывшими друзьями, Хадзимэ Нагумо был вынужден начинать своё восхождение в буквальном смысле со дна. Именно в лабиринте он усилил свою слабую магию и обрёл нескольких прекрасных союзниц. Теперь, спася своих одноклассников, он отправляется в Эрисен, чтобы сопроводить Мю и её мать. Ради возвращения домой он готов сразиться и одолеть кого угодно — даже бога!","poster":"https://shikimori.io/system/animes/original/40507.jpg?1711942158","url":"https://shikimori.one/animes/40507-arifureta-shokugyou-de-sekai-saikyou-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Исекай","Фэнтези","Боевик","Приключения","Гарем"],"episodes":12,"kind":"tv","franchise":"arifureta"},{"title":"Ведьма и чудовище","rating":9,"tier":"solid","review":"","desc":"Однажды на вокзал одного города прибыл поезд, из которого вышли два довольно необычных человека. Одним из них был высокий мужчина, который нёс за спиной огромный гроб, а вторым — юная хрупкая девица с отвратительным характером. Эта парочка не просто путешествует вместе, и связывают их не романтические, а совсем даже рабочие отношения. Эти двое — сотрудники Ордена магического резонанса, группы которая создана магами и существует для решения магических проблем с помощью магии. Его члены обладают магией, живут ею и работают ради неё.        \n        Так зачем же они приехали сюда, в благополучный, зажиточный город, который находится под защитой надёжной, могущественной героини? Они здесь не забавы ради, а чтобы выполнить задание и уничтожить ведьму, которая, по слухам, объявилась в этом городе. Вот только незадача: местная героиня и есть та самая ведьма, и она денно и нощно спасает жителей, не жалея сил. Так что, получается, ведьмы вовсе не абсолютное зло, требующее полного искоренения? Это Ашафу и Гидо и предстоит выяснить.","poster":"https://shikimori.io/system/animes/original/52816.jpg?1711163872","url":"https://shikimori.one/animes/52816-majo-to-yajuu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Сэйнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Величайший Повелитель Демонов перерождается как типичное ничтожество","rating":9,"tier":"solid","review":"","desc":"Самое могущественное существо всех времён, повелитель демонов Варватос, неимоверно разочаровался тем, какой предсказуемой и несвободной стала его жизнь, когда он обрёл непревзойдённую мощь. Не желая мириться с этим, Варватос решил переродиться, ограничив свои силы, чтобы больше не привлекать к себе лишнего внимания. Кто же мог предположить, что мир будущего окажется сборищем слабаков, так что даже с наложенными ограничениями Варватос всё равно сильнее всех?         \n        Кто-кто, но только не Варватос, который ныне существует в человеческом теле Арда Метеора. Его обожают девушки, королевская семья умоляет его стать следующим правителем, а бывший соратник настаивает на его убийстве. Однако Ард слишком упрям, чтобы отказаться от мечты об обычной школьной жизни, и не остановится ни перед чем, чтобы добиться намеченной цели!","poster":"https://shikimori.io/system/animes/original/48415.jpg?1708763188","url":"https://shikimori.one/animes/48415-shijou-saikyou-no-daimaou-murabito-a-ni-tensei-suru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Гарем","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Внук мудреца","rating":9,"tier":"solid","review":"","desc":"В скучной жизни Шина , обычного офисного работника, казалось бы, не ждало ничего, кроме рутины. Однако судьба с ним распорядилась немного иначе. В силу некоторых обстоятельств Шин умирает, но, в отличие от обычных людей, по каким-то причинам помнит события прошлой жизни. Кроме того, рождается он в далеко не привычном для себя мире. Здесь правит волшебство и магия.        \n        Шина приютил мудрец Мерлин  и вырастил из него выдающегося волшебника. Однако тот жил в отшельничестве, поэтому Шин ничего не знал о внешнем мире. Чтобы это исправить, Шина отправляют в королевскую школу волшебства. Но такая ли уж это хорошая идея?","poster":"https://shikimori.io/system/animes/original/36407.jpg?1711958031","url":"https://shikimori.one/animes/36407-kenja-no-mago","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фэнтези","Романтика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Время ниндзя","rating":9,"tier":"solid","review":"","desc":"Эта история об обычном парне Иттоки Сакурабе, которому «повезло» оказаться не в то время не в том месте. Оказавшись в самой гуще событий и с трудом пережив нападение вражеского ниндзя клана Кога, старшеклассник Иттоки узнал, что на самом деле является 19-м наследником ниндзя клана Ига. Война между кланами уже началась, и нет ни времени, ни возможности придумывать причины для отказа от участия в ней.        \n        Единственный путь к выживанию — усердные тренировки, изобретательность и недоверчивость, ведь любой может оказаться предателем!","poster":"https://shikimori.io/system/animes/original/51098.jpg?1711939642","url":"https://shikimori.one/animes/51098-shinobi-no-ittoki","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Школа","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Девушка на час 2","rating":9,"tier":"solid","review":"","desc":"Кадзуя Киносита — обычный студент университета, который ведёт скромный образ жизни и уже месяц встречается с девушкой… Но счастье длится недолго, и подруга сообщает парню, что бросает его ради другого. Чувствуя себя ниже плинтуса, Кадзуя, чтобы взбодриться, решает воспользоваться приложением, с помощью которого нанимает Тидзуру Итиносэ в качестве «девушки на час». Встретившись на «свидании», Киносита видит в ней красавицу без изъянов. Однако первое впечатление бывает ошибочным...","poster":"https://shikimori.io/system/animes/original/40839.jpg?1711957520","url":"https://shikimori.one/animes/42963-kanojo-okarishimasu-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Гарем","Сёнэн"],"episodes":12,"kind":"tv","franchise":"kanojo_okarishimasu"},{"title":"ЖИЗНЬ ПЕРЕРОЖДЁННОГО МУДРЕЦА В ДРУГОМ МИРЕ. ПОЛУЧЕНИЕ ВТОРОЙ ПРОФЕССИИ И СТАНОВЛЕНИЕ СИЛЬНЕЙШИМ","rating":9,"tier":"solid","review":"","desc":"И так часто работающий сверхурочно, трудоголик Юдзи Сано заканчивал принесённую домой работу, когда был призван в другой мир. Оказавшись вдруг посреди леса, Юдзи решил, что всё это — любопытный сон, которым он может насладиться, пока его не разбудит будильник. Успокоившись на этой мысли, Юдзи, который любил в свободное время играть в компьютерные игры, спокойно воспринял появление во сне монстра-слизи и окна с указанием его навыков и текущего статуса.        \n        Монстра этого Юдзи случайно приручил, а окошко услужливо подтвердило, что он приобрёл навык укрощения монстров. Потом Юдзи случайно набрёл на бесхозную библиотеку магических книг и прочёл их, что обеспечило ему звание мудреца.        \n                \n        Вроде бы никаких супер способностей и читерских навыков, но вполне себе неплохие данные, главное — ими правильно распорядиться!","poster":"https://shikimori.io/system/animes/original/47163.jpg?1701804133","url":"https://shikimori.one/animes/47163-tensei-kenja-no-isekai-life-dai-2-no-shokugyou-wo-ete-sekai-saikyou-ni-narimashita","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Заботы запертой принцессы вампиров","rating":9,"tier":"solid","review":"","desc":"Вот уже три года Теракомари Гандесблад не выходит из своей комнаты и совершенно счастлива. По крайней мере, она была счастлива, пока не узнала, что её назначили на должность командующего армией Мулнитской Империи. Мало того, выяснилось, что доверенная ей армия состоит из сброда, готового восстать против своего генерала, дай тот малейшую слабину.         \n        Теракомари происходит из престижного вампирского рода настолько же могущественного, сколь и известного, так в чём же может быть проблема? Дело в том, что юная вампирша отказывается пить кровь, поэтому слаба и бесполезна. К счастью, верная горничная Виллхейз, которая помешана на Теракомари, всегда готова прийти госпоже на помощь!","poster":"https://shikimori.io/system/animes/original/54103.jpg?1710729015","url":"https://shikimori.one/animes/54103-hikikomari-kyuuketsuki-no-monmon","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Вампиры"],"episodes":12,"kind":"tv","franchise":null},{"title":"Из мечтателя в реалиста","rating":9,"tier":"solid","review":"","desc":"Влюблённый в свою одноклассницу по имени Айка Нацукава, Ватару Садзё мечтал о ней и воображал, как заведёт с ней страстный роман и построит отношения. Представляя, как вожделенная красавица ответит ему взаимностью, Ватару беззаботно проводил дни, иногда отвлекаясь на друзей и учёбу. Пока однажды его внезапно не осенила трезвая, а потому ужасная в своей жестокости мысль: такой никчёмный середнячок, как он, недостоин общества и любви Айки. Осознав эту простую истину, Ватару примирился с ней и стал держаться от Айки на расстоянии.        \n        Сконфуженная такой неожиданной переменой Айка не знала, что и думать, и начала подозревать, что Ватару по какой-то причине возненавидел её. Это начало романтической комедии о двух людях, которые не могут рассказать о своих чувствах и полагают, что их любовь безответна.","poster":"https://shikimori.io/system/animes/original/53632.jpg?1710729945","url":"https://shikimori.one/animes/53632-yumemiru-danshi-wa-genjitsushugisha","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"История о дедушке и бабушке","rating":9,"tier":"solid","review":"","desc":"Не только старшеклассники, живущие в больших городах, попадают в сверхъестественные ситуации и оказываются участниками необыкновенных историй. Иногда и со старичками в деревне случаются настоящие чудеса. Так произошло с пожилой женатой парой Сёдзо и Инэ Сайто, которые однажды утром проснулись вновь молодыми и здоровыми.        \n        Несмотря на этот грандиозный поворот, в их жизни ничего не поменялось: они по-прежнему занимаются работой в саду и по дому, общаются с теми же людьми и любят друг друга, совсем как раньше.","poster":"https://shikimori.io/system/animes/original/56230.jpg?1717406130","url":"https://shikimori.one/animes/56230-jiisan-baasan-wakagaeru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Сверхъестественное"],"episodes":11,"kind":"tv","franchise":null},{"title":"Каким-то образом я стал сильнейшим, прокачивая фермерские навыки","rating":9,"tier":"solid","review":"","desc":"Быть фермером — дело нелёгкое, но юного крестьянина Ала Уэйна оно ничуть не пугает. Более того, Ал с головой погружён в выращивание овощей и фруктов и планирует посвятить этому всю жизнь, поэтому активно прокачивает свои фермерские навыки до максимального уровня и становится первоклассным фермером!        \n        Однако стоит ему достичь таких высот, как жизнь принимает крутой оборот. Похоже, теперь Ал Уэйн не только первоклассный фермер, но и один из сильнейших людей в мире. Недаром говорят: «Хочешь рассмешить бога, расскажи ему о своих планах». Это история о не совсем обычном фермере и лихом завороте судьбы, за которым его поджидает множество приключений и великих свершений.","poster":"https://shikimori.io/system/animes/original/51128.jpg?1711939621","url":"https://shikimori.one/animes/51128-noumin-kanren-no-skill-bakka-agetetara-nazeka-tsuyoku-natta","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Мастер демонического клинка","rating":9,"tier":"solid","review":"","desc":"Проведя в магической коме целую тысячу лет, Тёмный лорд Леонис Дэт Магнус очнулся ото сна и, к своему немалому изумлению, обнаружил, что очутился в теле десятилетнего мальчишки. Не успел Леонис сообразить, что происходит, как столкнулся с Риселией Рей Кристалией, которая как раз в этот момент отчаянно сражалась с войдами — существами, которые почти стёрли человечество с лица Земли.        \n        Решив непременно разобраться со странными загадками нового тысячелетия, Леонис поступил в академию «Святого меча», где учеников обучают сражаться с войдами. Неужели эти неведомые монстры как-то связаны с прошлым Леониса?","poster":"https://shikimori.io/system/animes/original/50184.jpg?1717987085","url":"https://shikimori.one/animes/50184-seiken-gakuin-no-makentsukai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Гарем","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Мифический Дух: Хроники 2","rating":9,"tier":"solid","review":"","desc":"Попав в аварию, Харуто Амакава очнулся не в больнице, а в другом мире, в теле бедного мальчика из трущоб по имени Рио. Пытаясь разобраться в ситуации, новоиспечённый Рио осознал, что унаследовал от мальчика не только магические способности, но и его желание отомстить убийцам матери.         \n        Сконфуженный произошедшим, Рио волей случая спас принцессу Флору из рук похитителей и в качестве награды получил право обучаться в королевской академии. Так начались приключения обычного японского студента, который счастлив открыть новую главу в своей жизни.","poster":"https://shikimori.io/system/animes/original/44203.jpg?1711972300","url":"https://shikimori.one/animes/50306-seirei-gensouki-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Романтика","Гарем"],"episodes":12,"kind":"tv","franchise":"seirei_gensouki"},{"title":"Моя геройская академия 6","rating":9,"tier":"solid","review":"","desc":"] Идзуку Мидория  рано осознал, что люди не рождаются равными. А пришло это понимание, когда его начали дразнить одноклассники, одарённые особой силой. Несмотря на то, что большинство людей в этом мире рождаются с необычными способностями, Идзуку оказался среди тех немногих, кто напрочь их лишён. Однако это не стало помехой для мальчика в стремлении стать таким же легендарным героем, как Всемогущий . Для осуществления мечты Идзуку не без помощи своего кумира поступает в самую престижную академию героев — Юэй. Но это, очевидно, лишь начало его удивительных приключений.","poster":"https://shikimori.io/system/animes/original/31964.jpg?1711944324","url":"https://shikimori.one/animes/49918-boku-no-hero-academia-6th-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Школа","Супергероика","Сёнэн"],"episodes":12,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"Моя геройская академия 7","rating":9,"tier":"solid","review":"","desc":"После коварной диверсии Паранормального Фронта Освобождения и массового побега заключённых из тюрем, в том числе и Все За Одного [オール・フォー・ワン], Япония погрузилась в хаос. Героев не хватает, а те немногие, кто по-прежнему продолжает отважно бороться с преступностью, не справляются с бесчинствами бандитов, заполонившими улицы. Нападения злодеев продолжаются, а символ мира и справедливости — Всемогущий [オール・マイト] — не может больше прийти на помощь.\nВ эти тяжёлые времена правительство Японии запрашивает поддержку у других стран для наведения порядка в своих городах. Из Америки на помощь приходит сильнейшая женщина в мире и ученица Всемогущего — Кэтлин Бейт [キャスリーン・ベイト]. Но Все За Одного предвидел её появление и вместе с Томурой Сигараки [死柄木 弔] приготовил тайный план. Близится время решающей битвы — смогут ли Идзуку Мидория [ 緑谷 出久] и его друзья из Академии Юэй выстоять под натиском зла и вернуть порядок и спокойствие в родную страну и свою жизнь?","poster":"https://shikimori.io/system/animes/original/54789.jpg?1718498811","url":"https://shikimori.one/animes/54789-boku-no-hero-academia-7th-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Школа","Супергероика","Сёнэн"],"episodes":21,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"На самом деле я самый сильный?","rating":9,"tier":"solid","review":"","desc":"20-летний затворник неожиданно переносится из собственной квартиры прямиком к богине, которая предлагает ему второй шанс на жизнь. Она наделяет его невероятно мощными магическими способностями в новом мире, но когда он рождается заново в облике новорождённого принца Рейнхардта, его дар оценивают всего лишь в 2 уровня. Сочтя своего ребёнка полным неудачником, царственные родители бросают его в лесу. Там принц, назвавший себя Харуто Зенфис, встречает Флей — Огненного Фенрира, которая решает посвятить свою жизнь служению ему. В том же лесу их находит родственник Харуто, Голд Зенфис, и решает усыновить мальчика.Проходит девять лет, и всё это время Харуто растёт в семье Зенфис. Его владение сверхмощной барьерной магией день ото дня становится всё совершеннее, хотя сам Харуто вовсе не горит желанием использовать её ради помощи другим. Он тайком практикует свои способности, предпочитая, чтобы родные считали его слабым. Однако его младшая сестра Шарлотта Зенфис раскрывает его настоящую силу, и вместе с Флей Харуто защищает её и остальных членов семьи Зенфис от опасности. Пока в королевстве назревает коварный заговор, Харуто мечтает лишь о том, чтобы сидеть дома и смотреть аниме, но, похоже, ему всё же придётся пустить в ход свою магию, чтобы уберечь приютившую его семью.","poster":"https://shikimori.io/system/animes/original/52969.jpg?1711935863","url":"https://shikimori.one/animes/52969-jitsu-wa-ore-saikyou-deshita","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Не люблю боль, поэтому собираюсь вложить всё в защиту 2","rating":9,"tier":"solid","review":"","desc":"Получив приглашение от своей подруги Рисы Сироминэ, Каэдэ Хондзё погружается в VRMMO-игру New World Online в роли персонажа Мейпл. Не имея ни малейшего представления о том, как играть в эту игру, она расходует все свои очки навыков на защиту. В результате её движения становятся медленными, Каэдэ не может использовать магию и даже подвергается нападению кроликов. Однако, благодаря такому распределению своих очков она получает навык под названием «Абсолютная защита», а также контр-навык, который убивает одним ударом. Так Каэдэ, играя в стиле «мобильной крепости», отправляется навстречу приключениям.","poster":"https://shikimori.io/system/animes/original/38790.jpg?1711955366","url":"https://shikimori.one/animes/41514-itai-no-wa-iya-nanode-bougyoryoku-ni-kyokufuri-shitai-to-omoimasu-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":"bofuri"},{"title":"Непризнанный школой владыка демонов 2! Часть 2","rating":9,"tier":"solid","review":"","desc":"Вторая часть «Непризнанный школой владыка демонов! Сильнейший владыка демонов в истории поступает в академию, переродившись своим потомком» II.","poster":"https://shikimori.io/system/animes/original/48418.jpg?1717859795","url":"https://shikimori.one/animes/48418-maou-gakuin-no-futekigousha-ii-shijou-saikyou-no-maou-no-shiso-tensei-shite-shison-tachi-no-gakkou-e-kayou-part-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Школа"],"episodes":12,"kind":"tv","franchise":"maou_gakuin"},{"title":"Новые врата","rating":9,"tier":"solid","review":"","desc":"Оказавшись, как и множество других людей, в ловушке онлайн-игры «Новые врата», Синъя Киритани, в игре известный под ником Син , сражался изо всех сил и дошёл до самого конца. Многие его товарищи погибли на пути к общей цели, но в итоге Син смог одолеть финального босса. Он с облегчением выдохнул, когда увидел, что его друзья один за другим разлогиниваются и покидают игру.        \n        Уже никуда не торопясь и наслаждаясь чувством выполненного долга, Син получил награды за победу, удивился тому, какими заоблачными стали его показатели силы и прочего, и уже собирался выйти, когда за его спиной вдруг появились двери. Решив на всякий случай проверить, Син прошёл через врата. Как выяснилось позже, эти двери вели обратно в мир игры, только с момента его победы и освобождения игроков в игре минуло пятьсот лет.        \n                \n        Кнопка выхода перед Сином так и не появилась. Однако причин отчаиваться нет. Тем более пора заняться делом и заново освоить игру!","poster":"https://shikimori.io/system/animes/original/57100.jpg?1717940727","url":"https://shikimori.one/animes/57100-the-new-gate","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Перевоплотившийся король-герой","rating":9,"tier":"solid","review":"","desc":"В одной славной стране король Инглис прожил достойную жизнь, правя во благо своего народа. Когда пришёл его смертный час, к нему явилась богиня-покровительница Алистия, которая решила даровать ему второй шанс. Вот только не всегда с этим вторым шансом всё проходит совершенно гладко. Так получилось и в этот раз. Инглис удачно переродился в семье главы рыцарского ордена, однако, переродился он девочкой, к тому же без особых способностей во владении оружием.        \n        Но для юной леди Инглис Эвкус это становится не проблемой, а вызовом и не мешает ей продолжить путь к своей мечте жить для себя, пусть и в роли обычного оруженосца.","poster":"https://shikimori.io/system/animes/original/50481.jpg?1713149157","url":"https://shikimori.one/animes/50481-eiyuuou-bu-wo-kiwameru-tame-tenseisu-soshite-sekai-saikyou-no-minarai-kishi","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Драма"],"episodes":12,"kind":"tv","franchise":null},{"title":"Приключения в другом мире: Воспитывать детей будучи авантю","rating":9,"tier":"solid","review":"","desc":"Если уж день не задался с утра, то будет не везти до самого вечера. Мало того, что Каяно Такуми умер и, как выяснилось, по ошибке, так ещё и вернуться обратно в своё родное тело и свою привычную жизнь уже невозможно. По крайней мере, именно так объяснил некий бог, искренне извиняющийся перед Такуми за доставленные неудобства. Обратно на Землю нельзя, а вот в другой мир — пожалуйста, — объявляет бог и отправляет растерянного Такуми навстречу приключениям. Только в спешке засовывает его не на безопасную полянку близ человеческого жилья, а в самую чащу опасного леса. Неизвестно, выжил бы Такуми в этих дебрях, а вот два очаровательных малыша, которых он там обнаружил, явно погибли бы. Теперь, когда их трое, придётся что-то сообразить, ведь взять ответственность за воспитание крох, кроме него, некому. Как справится Такуми, решивший стать авантюристом, с ролью отца?","poster":"https://shikimori.io/system/animes/original/57380.jpg?1717271026","url":"https://shikimori.one/animes/57380-isekai-yururi-kikou-kosodate-shinagara-boukensha-shimasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Повседневность","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Прощай, жизнь дракона. Здравствуй, жизнь человека","rating":9,"tier":"solid","review":"","desc":"Некогда жил могучий дракон, родившийся вместе с богами и сравнявшийся с ними по силе. Он прожил бесчисленное количество лет, но в итоге был побеждён людьми. Понимая, что всему на свете приходит конец и что ему просто не осталось места в мире, одинокий дракон смиренно принял свою судьбу. Моля о спокойном забвении, где его больше не потревожат мирские тревоги, он вдруг осознал, что оказался вовсе не в небытии, а в теле новорождённого мальчика.        \n                \n        Подрастая в захолустной деревне, бывший дракон, а ныне паренёк по имени Долан, легко вписался в человеческое общество, принял его законы и обычаи и полюбил своих заботливых родных. Жизнь у него настала простая, полная насущных забот и обязанностей. Обычно он занимался земледелием и охотой, но как-то раз отправился исследовать болото, где познакомился с девушкой-змеёй по имени Селина.        \n                \n        Долан и ламия Селина, отправившаяся на поиски потенциального мужа, быстро сдружились. И это история об их приключениях!","poster":"https://shikimori.io/system/animes/original/58445.jpg?1718480022","url":"https://shikimori.one/animes/58445-sayounara-ryuusei-konnichiwa-jinsei","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Реинкарнация безработного: История о приключениях в другом мире 2","rating":9,"tier":"solid","review":"","desc":"После долгих приключений и множества испытаний друзья вернулись домой, однако конец пути оказался только его началом. После того как Эрис покинула Рудеуса и отправилась в собственное странствие, он, разбитый одиночеством, двинулся на Север с одной целью — найти свою мать.\nРудеус потерял всякий интерес к жизни, однако новые друзья помогают ему вернуть радость бытия. Кроме того, он получил приглашения в Магическую академию, куда он когда-то собирался поступать! Похоже, Рудеусу рано уходить от дел, ведь впереди множество великих событий и свершений!","poster":"https://shikimori.io/system/animes/original/51179.jpg?1711939588","url":"https://shikimori.one/animes/51179-mushoku-tensei-ii-isekai-ittara-honki-dasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Исекай","Фэнтези","Приключения","Школа","Драма"],"episodes":12,"kind":"tv","franchise":"mushoku_tensei"},{"title":"Сладкая жизнь","rating":9,"tier":"solid","review":"","desc":"Сможете ли вы ответить на вопрос: «Что такое настоящая любовь?» У каждого найдётся свой ответ. Таким вопросом задавалась и Сато Мацудзака до встречи с Сио Кобэ. Теперь она знает, что любовь — высшее чувство, сладкое на вкус. Найдя своё счастье, Сато стремится сделать всё, чтобы сохранить счастливую жизнь: утром идёт в школу, днём ходит на подработку, а вечером остаётся наедине со своей возлюбленной.        \n        Но не все согласны с её определением любви и стараются помешать Сато в её счастье. Ради того, чтобы эти дни продолжались, героиня пойдёт на всё... даже на убийство.        \n        История сладкой жизни Сато и Сио только начинается!","poster":"https://shikimori.io/system/animes/original/37517.jpg?1704549713","url":"https://shikimori.one/animes/37517-happy-sugar-life","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Драма","Сёдзё-ай","Ужасы","Психология"],"episodes":12,"kind":"tv","franchise":null},{"title":"Становясь волшебницей","rating":9,"tier":"solid","review":"","desc":"Если перед тобой вдруг появится невиданное существо типа Веналиты и возвестит, что ты можешь стать волшебницей, ни одна девушка не упустит этот, единственный в своём роде шанс. А уж тем более если она ярая фанатка этих самых волшебниц и давно мечтает влиться в их ряды. Вот и Утэна Хираги, узнав, что внутри неё томятся магические силы, задрожала от восторга и немедленно на всё согласилась. Трансформация прошла вполне успешно, вот только почему-то на голове у неё не волшебная диадема, а рога, а в руках не жезл справедливости, а подозрительная чёрная палка.        \n        К своему ужасу, Утэна поняла, что стала злодейкой, которая должна сражаться с волшебницами. Причем сражаться немедленно, ведь они уже стоят перед ней. Так что, хотя первой её мыслью был выход из армии злодеев, она просто не успела этого сделать. Скрепя сердце шокированная происходящим Утэна вступила в бой.        \n        Разгоревшаяся битва оказалась настолько жаркой и возбуждающей, а унижать волшебниц и причинять им боль оказалось настолько захватывающе, что Утэна не смогла отказать себе в удовольствии. Выяснив, что в душе она настоящая садистка, Утэна с радостью погрузилась в пучину волшебного разврата!","poster":"https://shikimori.io/system/animes/original/54722.jpg?1718587270","url":"https://shikimori.one/animes/54722-mahou-shoujo-ni-akogarete","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фэнтези","Сёдзё-ай","Этти"],"episodes":13,"kind":"tv","franchise":null},{"title":"Фармацевт из параллельного мира","rating":9,"tier":"solid","review":"","desc":"Иногда даже горькие события приводят к появлению чего-то очень хорошего. Так, смерть младшей сестры от неизлечимой болезни подвигла Кандзи Якутани на то, чтобы посвятить жизнь изобретению лекарств, которые спасли бы людей. Однако в возрасте 31 года Кандзи умер от переутомления, после чего очнулся в другом мире в теле десятилетнего мальчика по имени Фальма де Медисис. Оказалось, что это не просто обычный мальчик, а аристократ, сын известного фармацевта, который к тому же обладает магией. После перемещения новоиспечённый Фальма обнаружил, что может не только управлять водой, как первоначальный владелец тела, но и способен создавать и уничтожать различные субстанции, а также диагностировать болезни.        \n        Выяснив, что его новый мир больше всего напоминает европейское средневековье, что медицина основывается не на научном подходе, а на суевериях, астрологии и божественном провидении, Фальма решает создать собственную аптеку и реформировать систему здравоохранения в империи, сделав так, чтобы эффективные лекарства стали доступными для всех!","poster":"https://shikimori.io/system/animes/original/49438.jpg?1703475683","url":"https://shikimori.one/animes/49438-isekai-yakkyoku","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Шпионский класс","rating":9,"tier":"solid","review":"","desc":"После разрушительной войны человечество осознало, что современное оружие стало чрезмерно мощным и разрушительным. Это привело к переходу от открытых военных действий к скрытым операциям, где основными инструментами стали информация и обман — началась эпоха шпионов.        \n                \n        Клаус, единственный выживший из элитной шпионской команды «Инферно», получает задание сформировать новую группу, способную выполнять так называемые «невыполнимые миссии» — задания с вероятностью провала в 90%. Для этого он набирает семь девушек, каждая из которых ранее считалась неудачницей в шпионской академии. У Клауса есть всего месяц, чтобы обучить их всем необходимым навыкам. Девушкам предстоит преодолеть свои страхи и неуверенность, чтобы стать настоящими шпионками и выжить в мире, где обман стал главным оружием.","poster":"https://shikimori.io/system/animes/original/51252.jpg?1713148493","url":"https://shikimori.one/animes/51252-spy-kyoushitsu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Детектив"],"episodes":12,"kind":"tv","franchise":"spy_classroom"},{"title":"Эльфийская песнь спэшл","rating":9,"tier":"solid","review":"","desc":"Диклониусы — побочная, мутировавшая ветвь людей, избранная, кажется, самим Богом, чтобы положить конец человечеству. От обычных людей их отличают небольшие рожки на голове и то, что они владеют как бы «шестым чувством», дающим им способность к телекинезу. Именно из-за этой опасной силы правительство отлавливает их и помещает в специальные лаборатории, где они подвергаются жестоким экспериментам.        \n        Люси  — юная и психически неуравновешенная девушка-диклониус, которой удаётся избавиться от сдерживающих её пут и предпринять попытку к бегству, по пути жестоко убивая охранников лаборатории: только выстрелив ей в голову из крупнокалиберного оружия, пулю которого она не успевает отклонить, охрана смогла нанести ей ущерб. Однако Люси удаётся выжить, упав с утёса в океан и дрейфуя некоторое время, пока двое молодых людей, Кота  и Юка , не находят её на пляже. Выстрел в голову вызвал потерю памяти и речевую дисфункцию: единственное, что она в состоянии сказать — междометие «ню», в честь которого нашедшие и окрестили её. В конце концов Кота отводит Люси к себе домой и позволяет ей жить там... Однако похоже на то, что тёмная сторона Люси никуда не исчезла...","poster":"https://shikimori.io/system/animes/original/226.jpg?1711948893","url":"https://shikimori.one/animes/z226-elfen-lied","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Триллер"],"episodes":13,"kind":"tv","franchise":"elfen_lied"},{"title":"Я получил читерские способности в другом мире и стал экстраординарным в реальном мире: История о том, как повышение уровня изменило мою жизнь","rating":9,"tier":"solid","review":"","desc":"Жизнь Юи Тэндзё далеко не сахар: с самого детства его травили сверстники, а семья считала помехой. Вскоре и школа стала для паренька настоящим адом, а оскорбления, издёвки и тумаки — верными спутниками школьных будней. Лишь дедушка Юи, который говорил ему никогда не сдаваться и улыбаться несмотря ни на что, любил мальчика.         \n        Немного погодя дедуля покинул этот мир, и парень остался один на один с суровой реальностью. После его смерти, Юи Тэндзё решил пожить в доме дедушки и случайно наткнулся на странную дверь в кладовой, которая, как оказалась, вела в другой мир! И этот мир, наполненный магией, монстрами и бесчисленным количеством артефактов, полностью изменит жизнь Юи.","poster":"https://shikimori.io/system/animes/original/52830.jpg?1714957821","url":"https://shikimori.one/animes/52830-isekai-de-cheat-skill-wo-te-ni-shita-ore-wa-genjitsu-sekai-wo-mo-musou-suru-level-up-wa-jinsei-wo-kaeta","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Школа","Боевик"],"episodes":13,"kind":"tv","franchise":"cheat_skill_isekai"},{"title":"Волшебник Кунон всё видит","rating":9,"tier":"solid","review":"","desc":"Кунон Гурион с рождения лишён зрения, однако не намерен мириться со своей судьбой. Освоив магию воды, он ставит перед собой почти невозможную цель — создать с её помощью новые глаза и впервые увидеть окружающий мир.        \n                \n        Благодаря постоянным экспериментам, необычному мышлению и упорству Кунон развивается с невероятной скоростью, вскоре превосходя даже собственного наставника. Он учится воспринимать пространство без обычного зрения, придавать воде различные формы и создавать из неё полезные предметы.        \n                \n        Талант и изобретательность юного мага быстро привлекают внимание окружающих. Но чем ближе Кунон подбирается к своей мечте, тем сложнее и опаснее становятся испытания, проверяющие пределы его способностей и возможностей собственного тела.","poster":"https://shikimori.io/system/mangas/original/148289.jpg?1712769218","url":"https://shikimori.one/animes/60810-majutsushi-kunon-wa-mieteiru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Триллер"],"episodes":13,"kind":"tv","franchise":null},{"title":"Адский режим: Хардкорный геймер в другом мире","rating":9,"tier":"solid","review":"","desc":"Аллен был скромным офисным служащим, однако жизнь без хорошего образования, девушки и карьерных перспектив в современной Японии его тяготила. Единственное, в чём он нашёл утешение, — это компьютерные игры. Но он не простой любитель. Его страсть — это прохождение сложных и малоизвестных игр на максимальной скорости.   \n      \n   Однажды, устав от очередных скучных игр, которые он с лёгкостью проходил, он наткнулся на сайт, который предлагал доступ к «экстремальному режиму». Ему предоставили выбор, с какими способностями он окажется в новом игровом мире. И он по-геймерски выбрал самый хардкорный режим — класс крестьянин с новым типом способностей — Призыватель и со сложнейшей системой прокачки.   \n      \n   Теперь его главная цель — выжить в этом опасном мире, достичь невиданных высот и спасти своих близких от тяжёлой доли.","poster":"https://shikimori.io/system/mangas/original/134870.jpg?1712746271","url":"https://shikimori.one/animes/60460-hell-mode-yarikomizuki-no-gamer-wa-hai-settei-no-isekai-de-musou-suru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай","Триллер","Школа"],"episodes":12,"kind":"tv","franchise":"hell_mode"},{"title":"Однажды я стану величайшим алхимиком?","rating":8.5,"tier":"good","review":"прикольное, но тоже проходняк","desc":"Осознав, что с ним произошло что-то нехорошее, Такуми Ирума даже не успел запаниковать. Перед ним предстала богиня Норн и разъяснила, что его прошлой жизни пришёл конец и вернуться на Землю он не сможет. Дело в том, что его случайно зацепило заклинанием призыва героев в другой мир. Просто не повезло, но возможна компенсация за причинённые неудобства. Желая отпочковаться от всяких геройских дел, Ирума попросил богиню наделить его безобидной профессией алхимика. Норн согласилась, накинула сверху разных навыков от себя и благословение.   \n   Благодаря этому щедрому дару у Ирумы никак не выйдет откреститься от спасения мира, но это всё потом. Пока можно спокойно адаптироваться к новому миру, ведь богиня отправила Ируму в прошлое — за год до призыва героев. Можно не спеша качать уровни и заодно прикупить красавиц-рабынь — в хозяйстве пригодятся!","poster":"https://shikimori.io/system/animes/original/58822.jpg?1715271339","url":"https://shikimori.one/animes/58822-izure-saikyou-no-renkinjutsushi","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Металлическая Руж","rating":8.5,"tier":"good","review":"","desc":"Одержав победу над инопланетным видом, известным как Узурпаторы, с помощью боевых андроидов Неанов, человечество колонизировало Марс и наслаждалось долгожданным послевоенным миром. Выполнив свою задачу солдат, Неаны превратились в покорных рабочих и граждан второго сорта, обслуживающих людей. Чтобы поддерживать свою жизнедеятельность, андроидам требуется ежедневная доза Нектара, из-за чего они полностью зависят от хозяев, поставляющих им этот наркотик.Однако в этой общественной иерархии существуют и Прото-Неаны — независимые специализированные андроиды, способные призывать металлические экзоскелеты со сверхчеловеческими возможностями. Руж Редстар — одна из таких Прото-Неанов, работающая под прикрытием на Алетейю, правительственную организацию, контролирующую регулирование Неанов, вместе со своей напарницей-человеком Наоми Ортманн.Миссия Руж и Наоми — уничтожить Бессмертную Девятку — Прото-Неанов, угрожающих человечеству по неясным причинам. Тем временем на Марс прибывает следователь, расследующий серию убийств, в которых Руж считается главной подозреваемой. Углубляясь в поиски Бессмертной Девятки, напарницы раскрывают шокирующую информацию о взбунтовавшихся андроидах и организации, на которую те работают.","poster":"https://shikimori.io/system/animes/original/54794.jpg?1711079158","url":"https://shikimori.one/animes/54794-metallic-rouge","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Комедия"],"episodes":13,"kind":"tv","franchise":null},{"title":"Гениальный целитель, который исцелял в одно мгновение, но был изгнан как бесполезный, теперь наслаждается жизнью в качестве тёмного целителя","rating":8.5,"tier":"good","review":"сомнительно но окей","desc":"Выросший в трущобах Зенос прекрасно понимал, что вырваться из нищеты и стать уважаемым членом общества будет очень сложно. Поэтому, когда у него появилась возможность учиться у мага-целителя, он ухватился за неё всеми руками и ногами и, как губка, впитал в себя его премудрости. В следующий раз Зеносу, как он считал, повезло, когда его позвала к себе группа авантюристов. Верой и правдой он служил им долгое время, терпя к себе дурное отношение, пока неблагодарные «товарищи» не изгнали его, объявив, что он им больше не нужен.   \n   Не сказать, что Зенос сильно расстроился, ведь он-то знал, что успех отряда — это прежде всего его заслуга, а то, что бывшие уже соратники не смогли этого понять — это их проблемы. Пораскинув мозгами, Зенос решил открыть собственную клинику. Загвоздка только в том, что он самоучка, который никогда не получал официального образования. Так что у него нет ни диплома, ни денег, чтобы организовать всё по-честному. Нельзя действовать легально? Не проблема. Нужно только отыскать в заброшенной части города пустующий дом покрепче да подобрать случайную рабыню-эльфийку для компании. А остальное приложится!","poster":"https://shikimori.io/system/animes/original/58359.jpg?1717961471","url":"https://shikimori.one/animes/58359-isshun-de-chiryou-shiteita-noni-yakutatazu-to-tsuihou-sareta-tensai-chiyushi-yami-healer-toshite-tanoshiku-ikiru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Девушка на час 4","rating":8,"tier":"good","review":"","desc":"Кадзуя Киносита — обычный студент университета, который ведёт скромный образ жизни и уже месяц встречается с девушкой… Но счастье длится недолго, и подруга сообщает парню, что бросает его ради другого. Чувствуя себя ниже плинтуса, Кадзуя, чтобы взбодриться, решает воспользоваться приложением, с помощью которого нанимает Тидзуру Итиносэ в качестве «девушки на час». Встретившись на «свидании», Киносита видит в ней красавицу без изъянов. Однако первое впечатление бывает ошибочным...","poster":"https://shikimori.io/system/animes/original/40839.jpg?1711957520","url":"https://shikimori.one/animes/59277-kanojo-okarishimasu-4th-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Гарем","Сёнэн"],"episodes":12,"kind":"tv","franchise":"kanojo_okarishimasu"},{"title":"Astro Note","rating":8,"tier":"good","review":"","desc":"Приехав в пансион «Астро Лодж» на собеседование по вакансии шеф-повара, Такуми Миясака вместо шикарного ресторана обнаруживает обшарпанный дом. Разочарованный, Такуми всё же демонстрирует своё мастерство, чем приводит в восторг эксцентричных постояльцев. Больше всех радуется очаровательная хозяйка дома Мира Готокудзи — она влюбляется в его стряпню. А вот Такуми влюбляется в саму Миру. В итоге он соглашается стать поваром, готовящим завтраки в «Астро Лодж», и заселяется в пятый номер.Вскоре Такуми замечает за Мирой странности: она катастрофически не разбирается ни в современной технике, ни в японской еде. К тому же из её комнаты порой доносится незнакомый голос. Такуми и не подозревает, что Мира — инопланетянка, недавно прибывшая с другой планеты с важной секретной миссией.","poster":"https://shikimori.io/system/animes/original/57391.jpg?1718455605","url":"https://shikimori.one/animes/57391-astro-note","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Фантастика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Богиня жаждет игр","rating":8,"tier":"good","review":"","desc":"Когда богиню-дракона Леолешею случайно пробуждают от сна во льдах ледника, она требует привести к ней лучшего игрока этой эпохи. Спустя год ожидания она встречает Фэя Тео Филуса — апостола, человека, наделённого сверхъестественной способностью под названием «Восход» и потому получившего право бросать вызов богам в играх. Фэй Тео Филус и Леолешея понимают, что их объединяет страсть к играм, будь то карты или интеллектуальное состязание с божеством. Заявив, что ей понравился этот человек, Леолешея разрешает Фэю называть её «Лешея» и объединиться с ней, чтобы вместе играть в игры богов.С тех пор как боги позволили людям бросать им вызов, они пообещали исполнить любое желание после десяти побед. Лешея мечтает вновь стать настоящей богиней — ведь когда-то она спустилась в мир людей и лишилась статуса божества. У Фэя же есть лишь одна цель: найти женщину, которая давным-давно научила его играть в игры.Хотя Лешея и Фэй быстро доказывают, что они отличная команда, боги не намерены так просто дарить им десять побед: у каждой игры свои уникальные условия и скрытые правила. Дуэту предстоит действовать слаженно, как единое целое, чтобы наконец добиться своих целей.","poster":"https://shikimori.io/system/animes/original/50869.jpg?1718144143","url":"https://shikimori.one/animes/50869-kami-wa-game-ni-ueteiru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Этти","Игры"],"episodes":13,"kind":"tv","franchise":null},{"title":"Выходные Господина Злодея","rating":8,"tier":"good","review":"","desc":"Испокон веков величайшие злодеи заставляли героев и простой люд трепетать от страха. И если герои ещё могли противостоять злодеям, то обычные люди были бессильны в борьбе с леденящим ужасом, охватывающим их тела и разум при виде чистого зла. Только вот бояться в сущности легко: стой себе с трясущимися поджилкам или беги. А вот создать себе имидж закоренелого душегуба и мерзавца, а потом поддерживать его вовсе не так просто. Так что Зло, как и все остальные, тоже нуждается в отдыхе. Планирование захвата мира, противостояние героям и сохранение статуса негодяя требуют немалых сил.   \n      \n   Господин Злодей — генерал злодейской организации, которая жаждет уничтожить человечество. Изо дня в день ему приходится вступать в схватку с «Рейнджерами», группой так называемых героев, обороняющих Землю. Но сегодня у великого злодея выходной! В этот день он хочет насладиться покоем, вкусной едой, походом по магазинам и созерцанием милых панд в зоопарке. И пусть только кто-нибудь попробует ему помешать!","poster":"https://shikimori.io/system/animes/original/54617.jpg?1710791158","url":"https://shikimori.one/animes/54617-kyuujitsu-no-warumono-san","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Повседневность","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Невообразимые приключения перерождённого дворянина","rating":8,"tier":"good","review":"","desc":"Во время ночной прогулки молодой человек по имени Кадзуя Сиина становится свидетелем нападения на двух девушек. В попытке защитить незнакомок он, не раздумывая, бросается на злоумышленника и погибает от ножевого ранения, после чего перерождается в другом мире третьим сыном знатного аристократа Гарма фон Сильфорд Грасия — Каином фон Сильфордом. В возрасте трёх лет к Каину возвращаются воспоминания о прошлой жизни, а в пять лет совет семи богов наделяет его невообразимыми способностями и навыками, которые мгновенно делают мальчика сильнейшим существом в мире. Получив благословения всех богов, Каин обретает жизнь, похожую на сказку. Однако он отдаёт себе отчёт, что для защиты новой семьи и друзей ему придётся приложить немало усилий, ведь избранника богов неизбежно будут подстерегать столь же могущественные враги.","poster":"https://shikimori.io/system/animes/original/52608.jpg?1710731740","url":"https://shikimori.one/animes/52608-tensei-kizoku-no-isekai-boukenroku-jichou-wo-shiranai-kamigami-no-shito","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Романтика","Гарем"],"episodes":12,"kind":"tv","franchise":null},{"title":"Сбережение 80 000 золотых монет в другом мире к моей старости","rating":8,"tier":"good","review":"","desc":"В жизни Мицухи Ямано наступила чёрная полоса: сначала в автокатастрофе погибла вся её семья, потом хулиганы столкнули скорбящую бедняжку с обрыва. Она должна была погибнуть, но вместо этого оказалась в средневековом мире, где подверглась нападению волков и познакомилась с местными жителями. Немного освоившись, девушка поняла, что сила, переместившая её в другой мир, работает в обе стороны. Теперь она может свободно перемещаться в любое известное ей место из обоих миров. В голове Мицухи зреет план о том, как обеспечить себе лёгкую жизнь и спокойную безбедную старость: торговать в средневековье диковинками современности и скопить скромную сумму в восемьдесят тысяч золотых монет.","poster":"https://shikimori.io/system/animes/original/52461.jpg?1713147005","url":"https://shikimori.one/animes/52461-rougo-ni-sonaete-isekai-de-8-manmai-no-kinka-wo-tamemasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Я стал самым сильным с провальным навыком","rating":8,"tier":"good","review":"","desc":"Когда класс Мимори Токи переместился в другой мир, перенёсшая ребят богиня Вишис объявила, что им всем предстоит стать героями! А затем уточнила, что не совсем всем. Проведённая ею оценка способностей показала, что у всех учеников разные ранги, от самого высокого S до самого низкого D. А вот у Мимори ранг Е, то есть его уровень ниже самого низкого, и он совершенно бесполезен как герой и будет только обузой для остальных. Поэтому Вишис сообщила Мимори, что от него решено немедленно избавиться. И несмотря на протесты Мимори и вмешательство старосты Аяки Сого, богиня при единодушной поддержке остальных одноклассников отправила парня на верную смерть.   \n   Так Тока Мимори оказался в подземелье, из которого никто не выходил живым. И хотя Мимори в полном отчаянии, он не хочет сдаваться просто так. Он жаждет не просто выжить, а выжить и отомстить гнусной мерзавке, которая так с ним обошлась.","poster":"https://shikimori.io/system/animes/original/57892.jpg?1713728316","url":"https://shikimori.one/animes/57892-hazurewaku-no-joutai-ijou-skill-de-saikyou-ni-natta-ore-ga-subete-wo-juurin-suru-made","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Моя новая горничная очень подозрительна","rating":8,"tier":"good","review":"","desc":"Аниме-сериал повествует о юном Юри, хозяине небольшого поместья, и его новой горничной Лилит. Горничная кажется Юри очень подозрительной. Пришла без приглашения, денег не просит, ещё и работает великолепно, а глаза её словно два сияющих аметиста. С ней явно что-то не так, возможно, она ведьма или демон? Не может обычная горничная быть такой замечательной, точно замышляет что-то недоброе.   \n   Сможет ли юный господин раскрыть замыслы подозрительной горничной? Или Юри стоит быть менее мнительным?","poster":"https://shikimori.io/system/animes/original/51837.jpg?1713754078","url":"https://shikimori.one/animes/51837-saikin-yatotta-maid-ga-ayashii","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Сёнэн","Приключения"],"episodes":11,"kind":"tv","franchise":null},{"title":"Другой мир не может противостоять силе мгновенной смерти","rating":7,"tier":"good","review":"","desc":"Ничего не подозревающий старшеклассник Ёгири Такато уютно задремал в автобусе во время школьной поездки, а проснулся уже в пылу кровавой резни и полном хаосе. Выяснилось, что автобус вместе со всем его классом переместился в другой мир, что Ёгири благополучно проспал. Мало того, проспал он также и раздачу навыков, которую проводила призвавшая их Сион. Однако это не самое страшное. Ужасно то, что навыки у ребят оказались неравноценными: у кого-то они полезные для боя и выживания, а у кого-то средненькие или вовсе никчёмные. Оказались даже такие ребята, которые, как Ёгири, вообще не получили навыка.   \n   Эта несправедливость немедля вызвала между одноклассниками раздор, а кончилось всё тем, что сильные бросили слабых на растерзание быстро приближающемуся дракону и ушли. В отличие от брошенной вместе с Ёгири его одноклассницы Данноуры Томотики, угроза близкой смерти нисколько того не встревожила. В конце концов, что может сделать какой-то там стоуровневый дракон человеку, которому подвластна сама смерть? А вот тот факт, что негде подзарядить игровую консоль, приводит в настоящую панику!","poster":"https://shikimori.io/system/animes/original/53730.jpg?1718588603","url":"https://shikimori.one/animes/53730-sokushi-cheat-ga-saikyou-sugite-isekai-no-yatsura-ga-marude-aite-ni-naranai-n-desu-ga","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Маг-обманщик из другого мира","rating":7,"tier":"good","review":"","desc":"Казалось бы, что такого может случиться в жизни обычных старшеклассников Таити  и Рин , которые просто учатся, веселятся и мечтают? Яркий луч света, перенёсший героев в иную реальность!   \n   Когда парочка наконец-таки пришла в себя, то пред ней предстал мир меча и магии, который тут же решил проверить ребят на прочность путём столкновения с несколькими монстрами. С трудом одолев нежданных гостей, Таити и Рин решают поскорее найти способ отправиться назад, домой. Но по пути они натыкаются на группу авантюристов, которые предлагают им вступить в гильдию. Поняв всю безвыходность своего положения и согласившись с предложением, уже на месте герои обнаруживают, что обладают невероятно могущественной магией.","poster":"https://shikimori.io/system/animes/original/37744.jpg?1711955230","url":"https://shikimori.one/animes/z37744-isekai-cheat-magician","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Моя сэмпай - парень?","rating":7,"tier":"good","review":"","desc":"Однажды в размеренную жизнь школьника-кроссдрессера Макото Ханаоки, словно вихрь, ворвалась Саки Аои, ученица на год младше него. Девушка не знала об увлечении Макото и, краснея от смущения и осознания запретности собственных чувств, призналась ему в любви.   \n      \n   Парень давно практикует переодевание и уже привык к осуждению и косым взглядам окружающих. Поэтому, чтобы тотчас устранить недопонимание, он признался Саки в том, что он парень, а также уверил девушку, что не способен кого-то полюбить и не может ответить на её пылкие чувства. Ожидая в ответ на своё признание увидеть удивление на лице девушки, которое вскоре сменит гримаса брезгливости, Макото приготовился отчалить восвояси, но  Саки удивила его! Она заявила, что его увлечение достойно восхищения и что она добьётся от него взаимности любой ценой!","poster":"https://shikimori.io/system/animes/original/54855.jpg?1711421136","url":"https://shikimori.one/animes/54855-senpai-wa-otokonoko","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Школа","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Сильнейший танк рейдит лабиринты","rating":7,"tier":"good","review":"","desc":"Сложность работы руководителя заключается не только в большой ответственности, но и в том, что нужно увидеть сильные и слабые стороны подчинённых, найти к ним подход и наладить эффективный рабочий процесс. Что же, герой Киграс, лидер отряда, в котором состоял Руд, с этим не справился. Не сумев по достоинству оценить защитные способности Руда, которые являются самыми мощными за всю историю, он с позором выгнал его из отряда, обвинив в провале последней вылазки. А ведь Руду очень нужно было это место, ведь в составе отряда героя он мог попадать в подземелье и надеяться одолеть его Хранителя, который, по слухам, может выполнить любое желание. А желание у Руда простое, но крайне важное, он мечтает исцелить страдающую от неизвестной болезни сестру.   \n   Не зная куда податься после увольнения, Руд решил вернуться в родные края, к сестре. По дороге домой он спас от монстра загадочную девушку Луну, которая, как выяснилось, обладает очень редким навыком оценки. Благодаря ей Руд узнал, какими на самом деле навыками, кроме мощной защиты, он владеет. Пускай Руд больше не герой, но его приключения только начинаются!","poster":"https://shikimori.io/system/animes/original/56845.jpg?1718481404","url":"https://shikimori.one/animes/56845-saikyou-tank-no-meikyuu-kouryaku-tairyoku-9999-no-rare-skill-mochi-tank-yuusha-party-wo-tsuihou-sareru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Сказание об обручальных кольцах","rating":7,"tier":"good","review":"","desc":"Десять лет назад принцесса Кристал Новати Ноканатика Новати «Химе» Ноканатика перенеслась из другого мира, спасаясь от покушений злых сил. Оказавшись в современной Японии, она встретила Харуто Сато. Между ними возник негласный уговор: он должен забыть всё увиденное, а взамен они станут друзьями. Спустя годы, отправляясь обратно в королевство Ноканатика, чтобы исполнить свой королевский долг, Химе прощается с Харуто. Однако юноша внезапно вспоминает их первую встречу и мчится туда, где она когда-то появилась, чтобы пересечь портал между мирами и вновь оказаться рядом с ней.Его появление срывает свадебную церемонию Химе и принца Мармаругиаса Гисараса. Праздник жестоко прерывает нападение чудовища из бездны, угрожающего жизни принцессы. Поддавшись порыву, Химе решает обменяться кольцами с Харуто, и это дарует её новоиспечённому супругу силу света, позволяющую сразить монстра. Отныне известный как Король бездны Колец, Харуто должен взять в жёны ещё четырёх принцесс, чтобы обрести новые магические силы и получить шанс одолеть главного врага всего мира — Короля бездны.","poster":"https://shikimori.io/system/animes/original/54265.jpg?1710668926","url":"https://shikimori.one/animes/54265-kekkon-yubiwa-monogatari","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Романтика","Этти","Гарем","Сэйнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Начало после конца","rating":7,"tier":"good","review":"рисовка гавна, сюжет прикольный","desc":"Король Грей стал самым могущественным правителем своего мира. Однако, поднявшись на вершину, осознал, что не получил того, за чем гнался все эти годы. Его бесцельное существование прервала внезапная кончина, после которой он переродился в другом мире как Артур Лейвин. Сохранивший воспоминания о прошлой жизни Артур оказался на континенте Дикатен, месте, где люди обладают магией и обитают магические звери. Со временем, благодаря родительской любви, он проникся человеческой добротой, которой был лишён в прошлом. Теперь ему предстоит осмыслить свои ошибки, найти утраченный смысл жизни и понять, как выбрать правильный путь в этом новом, наполненном волшебством, мире.","poster":"https://shikimori.io/system/mangas/original/154106.jpg?1712844224","url":"https://shikimori.one/animes/60146-saikyou-no-ousama-nidome-no-jinsei-wa-nani-wo-suru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай"],"episodes":12,"kind":"tv","franchise":"tbate"},{"title":"Белого мага, изгнанного из команды героя, подобрал авантюрист ранга S","rating":6,"tier":"mediocre","review":"","desc":"Ллойд, будучи белым магом, постоянно терпит презрение от заносчивого лидера партии героя, Аллена, который в один прекрасный момент выгоняет его без всякой причины. Несмотря на то что Ллойд — бывший ученик легендарного мага, он днями напролёт беспомощно скитается по городу, не в силах найти новую партию, которой требовался бы маг поддержки.Однако судьба Ллойда неожиданно меняется, когда Юи, лидер отряда авантюристов S-ранга, умоляет его присоединиться к её партии для выполнения задания, которое ей очень дорого. Хотя Ллойд продолжает недооценивать свои способности, он всё же принимает настойчивое предложение Юи. Тепло принятый новыми товарищами, Ллойд, возможно, наконец нашёл то самое место, где его магический талант оценят по достоинству.","poster":"https://shikimori.io/system/mangas/original/138928.jpg?1712893305","url":"https://shikimori.one/animes/59424-yuusha-party-wo-tsuihou-sareta-shiromadoushi-s-rank-boukensha-ni-hirowareru-kono-shiromadoushi-ga-kikakugai-sugiru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Парадоксальный навык «Мастер фруктов»","rating":6,"tier":"mediocre","review":"ну короче - тянки красивые, герой дибил, аниме проходняковое, никому не рекомендую! Но из-за тянок лайк! Гг тупой","desc":"В мире, где живёт Лайт Андервуд, существуют демоны, монстры и магия. Разумеется, в таком мире есть и навыки. Только люди с ними не рождаются, а приобретают, съев особый фрукт. С детства Лайт мечтал, как, вкусив плод, получит крутой боевой навык и станет авантюристом, но не случилось.   \n   Ему достался дурацкий навык «Мастера фруктов», который годится только для садоводства. Переиграть ситуацию нельзя, ведь повторное съедание фрукта приведёт к смерти. Приняв свою горькую судьбу, Лайт стал выращивать всякие яблоки и груши, и фрукты навыка тоже. Близкое соседство не прошло даром, Лайт случайно съел ещё один. И не только не помер, а получил новый навык! Да ещё и боевой! Вот теперь можно регистрироваться в гильдии авантюристов!","poster":"https://shikimori.io/system/animes/original/59002.jpg?1717698580","url":"https://shikimori.one/animes/59002-hazure-skill-kinomi-master-skill-no-mi-tabetara-shinu-wo-mugen-ni-taberareru-you-ni-natta-ken-ni-tsuite","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма"],"episodes":12,"kind":"tv","franchise":null},{"title":"Переродившись аристократом-неудачником, я потратил всё своё свободное время чтобы стать великим магом","rating":6,"tier":"mediocre","review":"проходняк. Из + чел поставил цель и идёт к ней, не смотря на привелегии которые ему попадются, ну и всё","desc":"Что делать парню, если его жизнь вдруг меняется прямо во время невинных посиделок за холодным пивком после работы? И я имею в виду — меняется по-настоящему. Этот немолодой обыватель внезапно оказывается в теле Лиама Хамильтона — юного отпрыска дворянского рода, балансирующего на грани полного краха. Среди отчаянно суетящегося отца и совершенно безучастных братьев единственным светлым пятном для Лиама становится возможность наконец заняться магией — о чём он всегда мечтал. Но он даже не подозревает, что это невинное увлечение способно вновь перевернуть его жизнь с ног на голову! Сможет ли Лиам Хамильтон постичь искусство магии? И хватит ли этого, чтобы спасти его от тени, нависшей над всей семьёй?","poster":"https://shikimori.io/system/animes/original/58437.jpg?1718393478","url":"https://shikimori.one/animes/58437-botsuraku-yotei-no-kizoku-dakedo-hima-datta-kara-mahou-wo-kiwametemita","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Спираль","rating":6,"tier":"mediocre","review":"","desc":"Над маленьким затерянным между горами и океаном городке лежит проклятье. Вот только ни жители, ни главная героиня Кириэ Госима не отдают себе в этом отчёт. Первым подозревать, что что-то неладно, начинает молодой человек Кириэ — Сюити Сайто, который приходит к выводу, что над городом довлеет не призрак и не монстр, а символ — удзумаки, то есть спираль, загадочная гипнотическая форма мира. Поначалу она проявляется в мелочах: ракушки, завитки растений, водовороты в озере, вихри в небе. Потом её власть растёт, и символ спирали начинает проявляться на телах людей, завладевает мыслями жителей. Безумие распространяется по городу, и жителей постепенно затягивает в бесконечный круговорот спирали, из которого нет возврата...","poster":"https://shikimori.io/system/animes/original/40333.jpg?1714576514","url":"https://shikimori.one/animes/40333-uzumaki","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Безумие","Драма","Ужасы","Романтика","Сверхъестественное","Триллер","Психология","Сэйнэн"],"episodes":4,"kind":"tv","franchise":null},{"title":"Целитель, которого исключили из группы, оказался сильнейшим!","rating":6,"tier":"mediocre","review":"","desc":"Члены команды, в которой состоял Лауст, долго мирились с тем, что он хреновый целитель, и прощали его недостатки. Не то чтобы по доброте душевной, а, скорее, потому что Лауста было удобно обманывать при распределении заработанного. Однако вскоре терпение товарищей лопнуло (или правильней сказать, они совсем зарвались), и парня выгнали из отряда. И вроде бы ничего страшного, но бывшие коллеги успели ославить Лауста как полнейшего бездаря, поэтому никто не хочет брать его в команду. И помирать бы лекарю-неумёхе с голоду, если бы на его объявление о наборе группы не откликнулась одна милая девушка. Получится ли у Нарсены и Лауста сработаться?","poster":"https://shikimori.io/system/animes/original/57944.jpg?1714160071","url":"https://shikimori.one/animes/57944-party-kara-tsuihou-sareta-sono-chiyushi-jitsu-wa-saikyou-ni-tsuki","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Бывший герой, которого прозвали неудачником и выгнали из дома решил жить самостоятельно","rating":5,"tier":"mediocre","review":"","desc":"Пришёл день, когда старшего сына герцога Вестфельдта изгнали из дома и вычеркнули из истории семьи. Причина в том, что поначалу малыш Аллен подавал большие надежды: в пять лет он уже достиг предела первого уровня силы. Конечно, родные посчитали его гением и ожидали его дальнейшего роста, но этого так и не произошло. Первым достиг второго уровня младший брат Аллена, а тот так навсегда и застрял на первом.   \n   По крайней мере, так полагали окружающие и, расценив Аллена как неудачника, стали презирать и сторониться. А уж когда Аллен провалил и церемонию благословления богини, то его удел был решён. Родные были рады избавиться от позорного пятна на чести рода, а Аллен ещё более был рад покинуть враждебную среду и обрести наконец свободу.   \n   Дело в том, что Аллен — выходец из другого мира, где был героем, победившим могущественное зло. Когда всё плохое оказалось позади, люди перестали его жаловать, так как боялись его силы. Тогда Аллен упросил богиню о реинкарнации с сохранением навыков и сил. Ему нужен был второй шанс, чтобы на этот раз прожить жизнь в тишине и покое.   \n   Удастся ли Аллену отказаться от геройства? Тем более когда вокруг столько прекрасных девушек, которые нуждаются в спасении?","poster":"https://shikimori.io/system/animes/original/55717.jpg?1717186592","url":"https://shikimori.one/animes/55717-dekisokonai-to-yobareta-motoeiyuu-wa-jikka-kara-tsuihou-sareta-node-sukikatte-ni-ikiru-koto-ni-shita","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"12 королевств","rating":null,"tier":"unrated","review":"","desc":"Ёко Накадзима — самая обычная, несколько стеснительная школьница. В один прекрасный день загадочный человек по имени Кэйки появляется перед ней и клянётся в верности. Не успела она толком осознать, что происходит, как на неё нападают демоны, и её утягивает в другой мир. Вдали от дома Ёко и её друзьям предстоит пройти через суровые испытания, чтобы выжить и узнать её истинное предназначение в мире Двенадцати королевств.","poster":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx153-pLhZPQCYk7hl.png","url":"https://shikimori.one/animes/153-juuni-kokuki","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай","Драма","Магия"],"episodes":45,"kind":"tv","franchise":null},{"title":"91 день","rating":null,"tier":"unrated","review":"","desc":"Времена сухого закона. Но власть в городе под названием Беззаконный принадлежит вовсе не полиции. Городом правит мафия. Криминальные боссы и мелкие сошки — каждый наживается за счёт запрещённого варева, которое меж тем только укрепляет свои позиции на чёрном рынке.   \n   Авилио, чья семья погибла в результате мафиозных распрей, возвращается в город спустя семь долгих лет. Но возвращается неспроста. Он жаждет мести. И письмо, полученное от таинственного отправителя, побуждает его действовать.   \n   Но месть, как известно, подают холодной. Здесь нужна расчётливость и терпение. Первым делом Авилио внедряется в семью Ванетти, ту самую, что ответственна за его несчастья, и заводит дружбу с Неро, сыном главаря мафии...   \n   Однако за убийствами следуют ещё больше убийств. Месть порождает новую месть.","poster":"https://shikimori.io/system/animes/original/32998.jpg?1711937952","url":"https://shikimori.one/animes/32998-91-days","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Драма","История"],"episodes":12,"kind":"tv","franchise":null},{"title":"Girls Band Cry","rating":null,"tier":"unrated","review":"","desc":"Бросившая школу и покинувшая родной дом Нина Исэри поступила в предуниверсарий в Токио, однако город принял гостью не очень дружелюбно. У немного неуклюжей Нины всё пошло не по плану, и, оставшись ночью на улице, она узнала, что совсем неподалёку выступает бывшая участница её любимой группы Diamond Dust. Встреча с кумиром, бунтарской, но рассудительной Момокой Кавараги, не только заставляет её серьёзнее задуматься о будущем, но и открывает ещё не зажившие душевные раны юной девочки. В её жизни встаёт важнейший вопрос: продолжать учёбу или стать полноценным членом музыкальной группы? Но в этой неоднозначной ситуации только одно остаётся ясным — в сердце немного инфантильной, наивной и запутавшейся в себе Нины звучит настоящий рок.","poster":"https://shikimori.io/system/animes/original/55102.jpg?1718531254","url":"https://shikimori.one/animes/55102-girls-band-cry","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Музыка","Комедия","Приключения"],"episodes":13,"kind":"tv","franchise":null},{"title":"Авантюристы, которые не верят в человечество, спасут мир","rating":null,"tier":"unrated","review":"","desc":"Жизнь чудовищно несправедлива. Особенно к авантюристу Нику. Подвоха ждать было неоткуда: он опытный боец, члены команды ему как семья, а воспитавший его лидер группы, Аргус, заменил ему отца. Однако стоило Нику обнаружить недостачу в финансах группы и обличить виновника, которым оказался его товарищ по команде, как его самого обвинили в растрате и краже и с позором выгнали на улицу.   \n      \n   Выбитый из колеи произошедшим, Ник опустошён и расстроен, все его представления о мире терпят крах. Будучи в отчаянии, он бесцельно бродил от бара к бару, топя своё горе в алкоголе, пока в одной таверне не встретил товарищей по несчастью. Четверо разочарованных в жизни авантюристов пили ночь напролёт, заливая свои печали, а наутро решили, что им стоит объединиться и организовать собственный отряд. Теперь группа озлобленных авантюристов, которые больше никому не верят и убеждены, что человечество — сборище прогнивших отбросов, постарается заработать себе на хлеб с маслом почти что честным трудом.","poster":"https://shikimori.io/system/animes/original/49612.jpg?1702868538","url":"https://shikimori.one/animes/49612-ningen-fushin-no-boukensha-tachi-ga-sekai-wo-sukuu-you-desu","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Адский рай","rating":null,"tier":"unrated","review":"","desc":"Достигнув всего, чего можно желать: власти, богатства, славы, неблагодарный человек начинает жаждать невозможного — он хочет, чтобы его существование длилось вечно. Всеми силами стремится он продлить свою молодость и сохранить здоровье. Не всем дано преуспеть на этом пути, но всё намного проще, если ты сёгун и в твоих владениях есть легендарная земля, в которой просто обязан находиться источник вечной молодости!   \n      \n   После нескольких провальных попыток исследовать чудесную территорию и найти эликсир бессмертия одиннадцатый сёгун Нариёси Токугава принимает решение не отправлять больше ценных подданных на верную погибель, а выслать туда убийц, которым уже вынесен смертный приговор, с обещанием полного помилования в случае успеха. А чтобы те и не думали сбежать, приставить к каждому искусного палача в сопровождающие.   \n   Какие тайны скрывает рай, из которого никто не вернулся живым, и чем обернётся это путешествие для согласившихся в нём участвовать? Желанной свободой по возвращении или бесконечной пыткой, в которой даже ад покажется раем?","poster":"https://shikimori.io/system/animes/original/46569.jpg?1711955691","url":"https://shikimori.one/animes/46569-jigokuraku","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","История","Самураи","Сёнэн"],"episodes":13,"kind":"tv","franchise":null},{"title":"Акудама Драйв","rating":null,"tier":"unrated","review":"","desc":"Некогда в Японии разразилась гражданская война, в которой насмерть столкнулись два «столичных» региона: Канто, в котором находится Токио, и Кансай, где расположен Киото. В той давней войне Кансай проиграл и, сдав позиции, стал подчиняться Канто. Вот только мятежную душу так просто не усмирить, и с течением времени Кансай стал постепенно выходить из-под контроля государства и полиции Канто. А главные виновники этого опасного неподчинения — преступники, известные как «акудама».","poster":"https://shikimori.io/system/animes/original/41433.jpg?1711939563","url":"https://shikimori.one/animes/41433-akudama-drive","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Астра, затерянная в космосе","rating":null,"tier":"unrated","review":"","desc":"2063 год. Благодаря развитию науки и техники путешествия в космосе теперь не просто возможны, а стали почти таким же обыкновением, как поездка на автобусе. Поэтому ничего удивительного, что ученики старшей школы проводят каникулы не в обычном лагере, а в космическом. Однако космос — территория всё ещё не до конца изученная, поэтому не исключены всяческие происшествия. Так случилось и с группой 5Б, только что прибывшей в лагерь. Неизвестная разумная светящаяся сфера похищает девятерых учеников и уносит их на расстояние 5012 световых лет от родной планеты. Подросткам везёт, они обнаруживают старый пустующий космический корабль, однако на этом везение заканчивается. Теперь им придётся самим выживать в суровых условиях космоса, с ограниченными запасами воздуха и еды, и даже больше — выйти в одиночку в опасное и долгое путешествие на борту «Астры», если они всё-таки хотят вернуться домой.","poster":"https://shikimori.io/system/animes/original/39198.jpg?1701803736","url":"https://shikimori.one/animes/39198-kanata-no-astra","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Приключения","Детектив","Фантастика","Космос"],"episodes":12,"kind":"tv","franchise":null},{"title":"Бакуман","rating":null,"tier":"unrated","review":"","desc":"Моритака Масиро и Акито Такаги — амбициозные ученики девятого класса. Один — художник, второй — начинающий писатель. Вместе они решают стать величайшими мангаками Японии и образуют дуэт под общим псевдонимом «Муто Асироги». В качестве мастерской они берут квартиру умершего дяди Масиро — мангаки, так и не добившегося успеха.   \n   Однажды Масиро спонтанно предлагает выйти за него замуж Михо Адзуки — девушке, в которую он тайно влюблён. И Адзуки, мечтающая стать сэйю и явно не равнодушная к Масиро, к его изумлению, соглашается. Но при одном условии... Сперва они должны осуществить свои мечты: Масиро — стать мангакой и выпустить аниме, а Адзуки — стать сэйю и озвучить одну из героинь его сериала.","poster":"https://shikimori.io/system/animes/original/7674.jpg?1711943384","url":"https://shikimori.one/animes/7674-bakuman","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Комедия","Драма","Романтика"],"episodes":25,"kind":"tv","franchise":null},{"title":"Баракамон","rating":null,"tier":"unrated","review":"","desc":"В наказание за удар, нанесенный известному каллиграфу, молодой и привлекательный каллиграф Сэйшу Ханда  был отправлен в «ссылку» на небольшой островок. Сэйшу, как истинный городской житель, никогда не живший за пределами мегаполиса, должен приспособиться к очень многим непривычным вещам, например: к новым чокнутым соседям, разъезжающим на тракторе; к нежелательным гостям, которые никогда не пользуются парадной дверью; к раздражающим детям, использующим его дом в качестве игровой площадки; и ко многому другому...   \n   Сможет ли городской парень справиться со сводящими с ума трудностями? Смотрите и узнаете это в сумасшедшей комедии, разворачивающейся на маленьком острове.","poster":"https://shikimori.io/system/animes/original/22789.jpg?1711943584","url":"https://shikimori.one/animes/22789-barakamon","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Повседневность","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Блестящий пост","rating":null,"tier":"unrated","review":"","desc":"Идол-группа TiNgS находится на грани расформирования. Их единственный шанс на спасение — полный зал на предстоящем концерте. Если посетители займут все места, то карьеры идолов продолжатся. Эта задача кажется невыполнимой, ведь на предыдущих выступлениях группы собиралось не больше сорока человек. К счастью, у них появился новый талантливый менеджер — Наоки Хинасэ.   \n      \n   Поначалу Наоки не хотел этим заниматься, так как всё ещё переживал из-за прошлого горького опыта. Однако увидев искреннюю страсть Хару Набатамэ, он решил оставить свои сожаления и принял руководство группой TiNgS. Несмотря на трудности, с которыми они сталкиваются в этом амбициозном  начинании, Хару хочет, чтобы все в мире полюбили идолов и даже готова стать сияющим путеводителем для других, чтобы осуществить свою мечту.","poster":"https://shikimori.io/system/animes/original/50221.jpg?1713755444","url":"https://shikimori.one/animes/50221-shine-post","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Музыка","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Богатый детектив. Баланс: Неограничен","rating":null,"tier":"unrated","review":"","desc":"«Деньги могут всё!» — примерно такого девиза придерживается детектив Дайсукэ Камбэ, у которого денег куры не клюют. Однако к чести детектива, надо отметить, что финансы он тратит в том числе и на ведение расследований. Вот только не всех в столичном Управлении полиции устраивает такой подход, и Дайсукэ благополучно сплавляют в Главное управление по борьбе с современными преступлениями, где рано или поздно оказываются все неугодные и проблемные полицейские. В пару Дайсукэ назначают Хару Като, который не одобряет методы Дайсукэ и убеждён, что некоторые вещи не купишь. Двум детективам предстоит как-то притереться друг к другу, параллельно расследуя запутанные криминальные загадки.","poster":"https://shikimori.io/system/animes/original/41120.jpg?1711949711","url":"https://shikimori.one/animes/41120-fugou-keiji-balance-unlimited","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Комедия","Приключения"],"episodes":11,"kind":"tv","franchise":null},{"title":"В конечном счёте я стану твоей","rating":null,"tier":"unrated","review":"","desc":"Сюжет крутится вокруг школьницы Ю Които, которая страстно увлечена мангой для девочек. Воодушевлённая сюжетами любимых книг, Ю и сама надеется когда-нибудь встретить того самого «принца на белом коне», который полюбит её с первого взгляда. Однажды на выпускной церемонии по случаю окончания средней школы один из парней наконец-то признаётся Ю в своих чувствах, но, внезапно, девушка ничего не чувствует...   \n   Героиня уже давно перешла в старшую школу, но до сих пор не ответила на любовное признание молодого человека. Одним погожим днём, идя по школьному двору в поисках комнаты студсовета, она становится свидетелем того, как Токо Нанами, член студсовета, с уверенностью отказывает в признании ухажёра. Ю решает, что Токо имеет достаточно опыта в амурных делах, и просит у неё помощи. Но знала бы девушка, во что это в итоге для неё превратится...","poster":"https://shikimori.io/system/animes/original/37786.jpg?1711982031","url":"https://shikimori.one/animes/z37786-yagate-kimi-ni-naru","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Великий притворщик","rating":null,"tier":"unrated","review":"","desc":"Не  будет преувеличением сказать, что Макото Эдамура , вероятно, величайший в Японии мошенник. На пару с подельником Кудо он решает провернуть аферу в Асакусе и обмануть некоего Француза, однако в итоге оказывается обманут сам. Ведь Француз, не давший себя обдурить, — сам Лоран Тьерри , человек настолько влиятельный, что ему подчиняется даже мафия. Теперь Макото и Кудо придётся заниматься грязными делишками, которые поручает им Лоран, и ещё неизвестно, к чему это их приведёт!","poster":"https://shikimori.io/system/animes/original/40052.jpg?1711951846","url":"https://shikimori.one/animes/40052-great-pretender","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Детектив"],"episodes":23,"kind":"tv","franchise":null},{"title":"Великолепный парк амаги","rating":null,"tier":"unrated","review":"","desc":"Девушки с огнестрельным оружием бывают очень убедительны. Сэйя Каниэ , форменный эгоист с исключительной самовлюблённостью, понял это на раз-два, стоило только зарядить шрапнелью рядом с его красивой физиономией. Но, постойте, откуда у новенькой Исузу Сэнто , на днях переведённой в эту школу, взялся настоящий мушкет? И кто вообще таким способом приглашает на свидание, угрожая застрелить в случае отказа? Как бы то ни было, а деваться некуда, жизнь дороже. И уже на следующий день, неожиданно для себя самого, Сэйя отправляется на «свидание» с очаровательной, но гораздо более странной девушкой.   \n   Впрочем, место для встречи Исузу выбирает не менее странное — парк развлечений «Амаги», давно потерявший свою грандиозную популярность. Перед парнем открывается печальное зрелище: запустелая территория с аттракционами, дышащими на ладан; апатичные маскоты и нерасторопные парковые служащие; кучка зевающих и равнодушных посетителей... А вместо счастливого детского смеха, звучащего то там, то тут, — тишина. Очевидно, проблем у «Амаги» выше крыши. Но зачем его, Сэйю, притащили на этот «праздник жизни»? После экскурсии по парку и ежу понятно, что не ради продолжения романтических отношений. Все становится на свои места, когда парень оказывается в обители Управляющего, где ему доступно и даже несколько пикантно объясняют, что именно от него зависит будущее «Великолепного парка Амаги».","poster":"https://shikimori.io/system/animes/original/22147.jpg?1711940099","url":"https://shikimori.one/animes/z22147-amagi-brilliant-park","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Романтика","Фантастика","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Бтууум!","rating":null,"tier":"unrated","review":"","desc":"Мечты сбываются. И парень Рёта Сакамото [坂本 竜太] полностью оценил иронию данного выражения. Ведь что у него было в реальной жизни? Да почти ничего. Ни работы, ни друзей, ни девушки. Он сидит на шее у матери и постоянно играет в онлайн-игры. И там, в этих играх, всё по-другому — Рёта входит в топ-рейтинг игроков Японии онлайн-игры «Btoom!» И однажды молодой человек, которому надоели все проблемы реального мира, просто захотел убежать туда, в виртуальность, и уснул...\nА проснулся уже на тропическом острове с осознанием того, что он как-то попал в игру. Плохие новости — первый же встречный попытался его убить, причём, видимо, он не один здесь такой псих. Хорошие новости — мечты действительно сбываются! И теперь Рёте придётся со всем этим разбираться.","poster":"https://shikimori.io/system/animes/original/14345.jpg?1711944664","url":"https://shikimori.one/animes/14345-btooom","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Королевская битва","Психология","Фантастика","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Война горничных Акибы","rating":null,"tier":"unrated","review":"","desc":"Если мечтаешь приносить людям радость и озарять тёплым светом их тусклые будни, то у тебя два пути: стать идолом или пойти работать в кафе, где официантки одеваются как горничные. Не обладая никакими талантами, наивная и неуклюжая Нагоми Вахира, которая всегда восхищалась затейливыми нарядами горничных, выбрала второй вариант. Для этого она и приехала в Акихабару.   \n   Устроившись на работу в кафе «Тонтокотон», Нагоми огляделась вокруг и осознала, что мир горничных совсем не такой милый и сказочный, как она представляла. Никто не бегает по цветочным полям, держась за руки и распевая весёлые песенки, а между работницами разных заведений существует жёсткая конкуренция. Девушки отчаянно борются за клиентов, а точнее за их кошельки.   \n   Сможет ли Нагоми оправиться от краха своих радужных иллюзий и найти себе место в этом новом и совершенно незнакомом мире?","poster":"https://shikimori.io/system/animes/original/52193.jpg?1711333244","url":"https://shikimori.one/animes/52193-akiba-meido-sensou","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Вольный стиль! 2","rating":null,"tier":"unrated","review":"","desc":"Харука , посещающий колледж в Токио, вновь встречает Асахи , что наталкивает его на воспоминания о годах средней школы и об Икуе . В это же время Макото  работает над исполнением новой мечты, находясь в Токио вместе с Харукой. А с Рином  приключается неожиданная встреча в Сиднее. Ждёт ли героев впереди новая битва? Или же они столкнутся с прошлым, которое оставили позади?","poster":"https://shikimori.io/system/animes/original/36704.jpg?1711949636","url":"https://shikimori.one/animes/36704-free-dive-to-the-future","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Спорт","Школа","Комедия"],"episodes":12,"kind":"tv","franchise":"free"},{"title":"Граница пустоты: Сад грешников","rating":null,"tier":"unrated","review":"","desc":"«В тот день я шёл по широкой главной улице города. Сам не знаю, почему отправился необычным маршрутом. Это была неожиданная прихоть, а я редко поддаюсь внезапным порывам. Итак, я неторопливо шагал, скользя взглядом по примелькавшимся офисным зданиям, когда сверху рухнуло человеческое тело. Этот душераздирающий влажный звук — он пронизывал насквозь. Сорвавшийся с крыши высотного здания человек умер мгновенно, в этом не могло быть сомнений. По тротуару плеснуло алым. В глаза бросились чёрные длинные волосы, тонкие, хрупкие, белые руки и ноги... и совершенно разбитое лицо. А вокруг стояло лето, уже подходящее к концу, и на память почему-то пришёл засушенный и тонко сплющенный цветок, выпавший из старой книги. Возможно, потому, что тело со сломанной тонкой шеей было так похоже на надломленную лилию...» — вот что подумал Микия Кокуто  в тот день.   \n   Но, как оказалось, эта история началась задолго до того ужасного момента. И, как ни странно, именно с неё и начинается наше знакомство с Сики Рёги  — странной девушкой из древнего и влиятельного рода, которая не так проста, как может показаться на первый взгляд. История приоткроет занавес более глубокой связи этих двух людей. Она расскажет о виновнике того падения с небоскрёба, что имеет столько общего с Рёги... Какой же выбор сделает наша героиня, когда дело коснётся Микии ?","poster":"https://shikimori.io/system/animes/original/2593.jpg?1711957622","url":"https://shikimori.one/animes/2593-kara-no-kyoukai-movie-1-fukan-fuukei","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Боевик","Детектив","Сверхъестественное","Триллер"],"episodes":1,"kind":"movie","franchise":null},{"title":"Детективы Футо","rating":null,"tier":"unrated","review":"","desc":"Технический прогресс шагнул далеко вперёд, и преступники стали использовать специальные устройства, с помощью которых можно превратиться в могучего монстра. Устройство назвали — «Воспоминания гайи», а монстров, сеющих хаос и разрушения в общем-то мирном городе,  — допанты. К счастью, появились люди, которые стали использовать «Воспоминания гайи», чтобы сражаться с допантами. Таким героям, искренне защищающим людей и справедливость, даже удалось навести порядок. Они уничтожили главную злодейскую организацию «Музей», ответственную за нелегальное производство и распространение «Воспоминаний гайи».   \n   Вроде бы все должны были зажить счастливо, но неконфискованные экземпляры «Воспоминаний гайи» продолжают всплывать на чёрном рынке. Поэтому двум героям из детективного агентства «Наруми» отдых не светит. К ним продолжают приходить клиенты, которые сообщают о том, что стали свидетелями сверхъестественных событий, в которых могут быть замешены «Воспоминания гайи».   \n   Что бы это ни было, настоящие преступники или излишняя бдительность и богатое воображение граждан, детективы Футо не дадут в обиду свой город. И накажут всех, кто замыслил что-то недоброе против благополучия города Футо и его жителей!","poster":"https://shikimori.io/system/animes/original/48649.jpg?1711949990","url":"https://shikimori.one/animes/48649-fuuto-tantei","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Детектив","Сверхъестественное","Полиция","Сэйнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Дракон Раджа","rating":null,"tier":"unrated","review":"","desc":"Лу Минфэй Лу — самый обычный старшеклассник, готовящийся к выпуску. Так было, пока он не получил письмо о зачислении в колледж Касселла — учебное заведение, куда он даже не подавал документы. Оказавшись там, Лу узнаёт, что миссия школы предельно проста: защищать человечество от драконов. Втянутый в этот многовековой конфликт, юноша вскоре раскрывает мрачную правду, скрытую за войной людей против драконьего племени.","poster":"https://shikimori.io/system/animes/original/44408.jpg?1711961161","url":"https://shikimori.one/animes/44408-long-zu","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"],"episodes":16,"kind":"ona","franchise":null},{"title":"Дюрарара!!","rating":null,"tier":"unrated","review":"","desc":"Поддельный Сидзуо Хэйвадзима создаёт беспорядки на улицах Икэбукуро.","poster":"https://shikimori.io/system/animes/original/32915.jpg?1711948647","url":"https://shikimori.one/animes/32915-durarara-x2-ketsu-dufufufu","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Детектив","Сверхъестественное"],"episodes":1,"kind":"special","franchise":null},{"title":"Единственному мне, кто тебя любил","rating":null,"tier":"unrated","review":"","desc":"Будучи ребёнком, Коёми Хидака, живущий с отцом после развода родителей, встретил девочку по имени Сиори Сато в исследовательском институте, где работает его отец. Вместе взрослея и с каждым годом становясь всё ближе друг к другу, молодые люди влюбились, но мать Сиори и отец Коёми, не замечая чувств своих детей, объявили им о своей свадьбе. Коёми и Сиори, убеждённые, что им не суждено быть вместе в этой реальности, желают найти мир, в котором они не будут друг для друга сводными братом и сестрой.","poster":"https://shikimori.io/system/animes/original/49835.jpg?1711942382","url":"https://shikimori.one/animes/49835-kimi-wo-aishita-hitori-no-boku-e","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Романтика","Фантастика","Комедия"],"episodes":1,"kind":"movie","franchise":null},{"title":"За гранью","rating":null,"tier":"unrated","review":"","desc":"Серия короткометражных работ Studio 4 ° C, собранных в виде фильма для DVD-издания.   \n      \n   1. Блюз профессора Дэна Петори (англ. Professor Dan Petory\u0027s Blues)   \n   Музыкальный номер с участием ручной куклы по имени Джуниор, которой управляет профессор Дэн Петори. Изрядно выпив, он с удовольствием ответит, почему Земля круглая и почему НЛО летают зигзагообразно.   \n   2. Конец света (англ. End of the World)   \n    обожает рок-концерты. На одном из таких она знакомится со своей сверстницей , с виду обычной девушкой, но самом деле пришелицей из другого измерения, которое она покинула. Девушки быстро сближаются, поэтому после концерта  зовёт свою новую подругу к себе домой, чтобы продолжить веселиться. Однако там их ждёт то, что изменит судьбу каждой из них.   \n   3. Комедия (англ. Comedy)   \n   В Средние века свободолюбивым ирландцам постоянно приходилось сталкиваться с войсками Англии, пытавшимися всячески подчинить соседний народ. В то время над одной из ирландских деревень нависла угроза атаки английских карателей, поэтому юная девушка, ведомая желанием спасти свою семью и сельчан, отправляется на поиски Чёрного мечника — легендарного воина, способного отразить неотвратимую напасть.   \n   4. Хиган (англ. Higan)   \n   Что может быть ужасней, чем война? Особенно, когда против тебя воюют бесчеловечные машины, не имеющие даже капли сострадания. Есть ли смысл в этой войне? Такие мысли тяготят душу любого солдата, срок жизни которого с каждой секундой неумолимо истекает...   \n   5. Хлам-таун: Город мусора (англ. Junk Town)   \n   Хлам-таун буквально кишит роботами — они торгуют, убирают улицы, в общем всячески помогают людям, которые уже давно свыклись с механической жизнью на улицах и в подворотнях города. Но однажды обычный мальчик подружился с таинственным роботом, пожирающим своих собратьев, тем самым увеличиваясь в размерах. Что же задумал машинный мозг? Только его человеческий друг в силах найти ответ на этот вопрос.","poster":"https://shikimori.io/system/animes/original/1072.jpg?1711975816","url":"https://shikimori.one/animes/1072-sweat-punch","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","История","Меха"],"episodes":5,"kind":"ova","franchise":null},{"title":"Золотая пора","rating":null,"tier":"unrated","review":"","desc":"Заблудившись на территории Токийского университета во время вступительной церемонии, первокурсник Тада Банри вместе с другим новичком Янагисавой Мицуо натыкается на девушку с букетом цветов. Ударив Мицуо букетом, та уходит.    \n   Выясняется, что это подруга детства Мицуо — , с которой они договорились пожениться. Однако Мицуо сбежал от «невесты» и поступил в университет. , тем не менее, настроена решительно и, поступив в тот же университет, продолжает борьбу за «жениха».   \n   Банри и Кага ещё не знают, что эта встреча станет для них судьбоносной.","poster":"https://shikimori.io/system/animes/original/17895.jpg?1711951640","url":"https://shikimori.one/animes/z17895-golden-time","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика"],"episodes":24,"kind":"tv","franchise":null},{"title":"Избранный богами","rating":null,"tier":"unrated","review":"","desc":"Прожив несчастную жизнь, полную горестей и неудач, 39-летний Рёма Такэбаяси    умирает во сне. Сжалившись над бедолагой, три божества предлагают ему переродиться в магическом мире, где у него будет одна-единственная задача — оставаясь самим собой, наслаждаться жизнью. Рёма хватается за предоставленный шанс, и божества наделяют его не только мощными физическими данными, но и способностью управлять стихиями, и, пообещав приглядывать за ним, отправляют Рёму, ставшего вновь ребёнком, в лес иного мира.   \n   Проходит три года. За это время Рёма, усиленно изучавший слизь, выводит уникальные виды слизи и, натренировав их, создаёт армию. Кроме того, он активно занимается развитием своих магических способностей. Всё бы ничего, и Рёма вполне доволен своим отшельническим существованием в уютной пещере, ставшей ему домом, но он всё-таки начинает скучать по обществу людей. Вот тут, на удачу Рёмы, ему подворачивается раненый герцогский слуга, который убеждает его покинуть лес. Исцелив слугу, Рёма соглашается пойти с ним и прихватывает с собой свою армию. В очередной раз судьба Рёмы совершает крутой поворот, отправив того в мир, где его ждут поклонение и восхищение его уникальными способностями!","poster":"https://shikimori.io/system/animes/original/41312.jpg?1711957323","url":"https://shikimori.one/animes/41312-kami-tachi-ni-hirowareta-otoko","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Повседневность","Комедия"],"episodes":12,"kind":"tv","franchise":"kamitachi"},{"title":"Избранный богами 2","rating":null,"tier":"unrated","review":"","desc":"Прожив несчастную жизнь, полную горестей и неудач, 39-летний Рёма Такэбаяси    умирает во сне. Сжалившись над бедолагой, три божества предлагают ему переродиться в магическом мире, где у него будет одна-единственная задача — оставаясь самим собой, наслаждаться жизнью. Рёма хватается за предоставленный шанс, и божества наделяют его не только мощными физическими данными, но и способностью управлять стихиями, и, пообещав приглядывать за ним, отправляют Рёму, ставшего вновь ребёнком, в лес иного мира.   \n   Проходит три года. За это время Рёма, усиленно изучавший слизь, выводит уникальные виды слизи и, натренировав их, создаёт армию. Кроме того, он активно занимается развитием своих магических способностей. Всё бы ничего, и Рёма вполне доволен своим отшельническим существованием в уютной пещере, ставшей ему домом, но он всё-таки начинает скучать по обществу людей. Вот тут, на удачу Рёмы, ему подворачивается раненый герцогский слуга, который убеждает его покинуть лес. Исцелив слугу, Рёма соглашается пойти с ним и прихватывает с собой свою армию. В очередной раз судьба Рёмы совершает крутой поворот, отправив того в мир, где его ждут поклонение и восхищение его уникальными способностями!","poster":"https://shikimori.io/system/animes/original/41312.jpg?1711957323","url":"https://shikimori.one/animes/41312-kami-tachi-ni-hirowareta-otoko","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Повседневность","Комедия"],"episodes":12,"kind":"tv","franchise":"kamitachi"},{"title":"Измерение W","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://shikimori.io/system/animes/original/58374.jpg?1718047857","url":"https://shikimori.one/animes/58374-waai-waiwai-waiwaiwai","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":1,"kind":"music","franchise":null},{"title":"Инуясики","rating":null,"tier":"unrated","review":"","desc":"Итиро Инуясики — мужчина 58 лет. Жена и дети полностью игнорируют его, несмотря на то, что он для них сделал. Вдобавок ко всему, лечащий врач ставит герою неутешительный диагноз — рак, констатируя, что жить ему осталось совсем немного. Казалось бы, дела не могут пойти ещё хуже, но однажды Инуясики видит, как ослепляющий свет озаряет звёздное небо. С этого момента его жизнь сильно меняется, и теперь ему нужно привыкать ко всему новому.","poster":"https://shikimori.io/system/animes/original/34542.jpg?1711955190","url":"https://shikimori.one/animes/34542-inuyashiki","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Драма","Психология","Сэйнэн"],"episodes":11,"kind":"tv","franchise":null},{"title":"История любви Тамако","rating":null,"tier":"unrated","review":"","desc":"После того как принц Мэтя , Дэра  и Тёй  вернулись на южные острова, жизнь у Тамако  и её друзей должна была возвратиться на круги своя. Однако время летит, весёлые школьные деньки подходят к концу и скоро настанет время прощаться, ведь у всех свои планы на будущее. А тут ещё и Мочизо  решает уехать учиться в Токио. Как же ему поступить? Рассказать ли Тамако о своих чувствах и о том, что скоро покинет её?","poster":"https://shikimori.io/system/animes/original/21647.jpg?1711976521","url":"https://shikimori.one/animes/z21647-tamako-love-story","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Фантастика","Школа"],"episodes":1,"kind":"movie","franchise":null},{"title":"Как и ожидалось, моя школьная романтическая жизнь не удалась","rating":null,"tier":"unrated","review":"","desc":"Эта история об одном необщительном юноше, Хачимане Хикигае . У него свой искажённый взгляд на жизнь, поэтому не завёл себе парень ни друзей, ни подружки. Всё это, цинично считает он, лживая клоунада, а потому его не касается, ему не нужно.    \n   Хикигая учится в старшей школе и когда видит одноклассников, возбуждённо обсуждающих свою бурную подростковую жизнь, по обыкновению бормочет: «Кучка лжецов!». Когда Хикигаю спрашивают о его мечтах, он по привычке отвечает: «Ничего подобного не имею». И дальше как по заезженной колее. Романтические отношения? Увольте! Девушки? Враги народа! «Весна юности»? Ну что за глупости! Словом, парень сам себе на уме.   \n   И вот когда, казалось бы, переубедить его уже не получится, упорная учительница, преподающая японский язык, решает, что с таким «тяжёлым случаем» помогут справиться только крайние меры. В наказание за саркастическое сочинение на тему «Какой я вижу школьную жизнь» она заставляет Хачимана вступить в странный школьный клуб, президент и единственный член которого — первая красавица школы Юкино Юкиношита. Парень понимает — теперь не отвертеться — и неохотно соглашается, всё ещё не имея представления о том, что это за клуб такой и какова его задача. А задача его в том, объясняет девушка, чтобы помогать всем, кто нуждается в помощи.    \n   И едва она раскрыла рот, как обескураженный Хачиман понял, с какой целью его сюда затащили. Юкино с первых же слов вызвалась решить проблемы личности парня, коих он в себе признавать наотрез отказался. Вот только может ли решить чужие проблемы тот, кто и сам неосознанно, но отчаянно нуждается в помощи?","poster":"https://shikimori.io/system/animes/original/14813.jpg?1711982128","url":"https://shikimori.one/animes/14813-yahari-ore-no-seishun-love-comedy-wa-machigatteiru","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Киноманка Помпо","rating":null,"tier":"unrated","review":"","desc":"«Профессий много, но — прекрасней всех кино!»   \n   А самое прекрасное место для работы — Нялливуд, столица кино и Мекка всех, имеющих отношение к киноиндустрии. Именно здесь живёт и работает «великая» Помпо — талантливый продюсер, обычно снимающая второсортные боевики. Здесь же трудится её ассистент — Джин Фини, который, несмотря на то, что является помощником продюсера, обладает задатками настоящего режиссёра. Здесь не покладая рук вкалывает день и ночь на всевозможных подработках начинающая актриса Натали Вудворд.   \n   И однажды они объединятся, чтобы снять шедевр, достойный побороться за самую почётную кинонаграду.","poster":"https://shikimori.io/system/animes/original/41361.jpg?1711948758","url":"https://shikimori.one/animes/41361-eiga-daisuki-pompo-san","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Комедия","Драма","Искусство"],"episodes":1,"kind":"movie","franchise":null},{"title":"КОМБАТАНТЫ БУДУТ ВЫСЛАНЫ!","rating":null,"tier":"unrated","review":"","desc":"Всегда приходи с пистолетом на поножовщину!   \n      \n   Практически подчинив себе весь мир, лидеры корпорации «]» (некогда подпольной криминальной группировки, а ныне всемогущей злодейской организации) решили попробовать себя в завоевании иных планет. Один бросок кубика, и агенты для внедрения выбраны: Комбатант №6 — главный оперативник с усиленным кибертелом, и Алиса Кисараги — его напарница-андроид. Вместе они вторгаются во вражеский мир... и первое, что там видят — грудастую женщину верхом на единороге.   \n      \n   Но как бы то ни было, а завоевывать мир — рутинная работа для оперативников «]», так что если Шестой хочет славы и продвижения по службе, ему придется хорошенько поработать! Для начала, например, что-то сделать с местной группкой злодеев, которых зовут «Армия Короля демонов»... или как-то так. В конце концов, двум злодейским организациям будет тесно в одном мире!","poster":"https://shikimori.io/system/animes/original/41456.jpg?1711972583","url":"https://shikimori.one/animes/41456-sentouin-haken-shimasu","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фэнтези","Фантастика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Комендант общежития богинь","rating":null,"tier":"unrated","review":"","desc":"Жизнь двенадцатилетнего Коси Нагумо неожиданно идёт под откос, когда отец бросает его после того, как их дом сгорел дотла. Брошенный на произвол судьбы, Коси скитался по улицам, но однажды эксцентричная женщина по имени Минэру Вати сжалилась над ним и привела в женское «общежитие богинь».   \n   Узнав о ситуации Коси, Минэру, которая, как оказывается, является временной хозяйкой общежития, приглашает его стать комендантом. Так Коси знакомится со странными постоялицами: нежной страдающей андрофобией Атэной Саотомэ, вспыльчивой любительницей боевых искусств Кирией Сэнсё и самой Минэру, чьё безрассудство не знает границ, когда дело доходит до науки. Несмотря на это, Коси сделает всё возможное, чтобы выполнить свои обязанности в этой сумасшедшей новой жизни!","poster":"https://shikimori.io/system/animes/original/41812.jpg?1711963241","url":"https://shikimori.one/animes/41812-megami-ryou-no-ryoubo-kun","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Комедия","Романтика","Этти","Гарем"],"episodes":10,"kind":"tv","franchise":null},{"title":"Король магических стрел и Ванадис","rating":null,"tier":"unrated","review":"","desc":"Однажды Бог подарил человеку волшебный лук. Все выпущенные из него стрелы всегда попадали в цель. Благодаря тому человеку и этому луку на континенте воцарили мир и порядок. Но любой жизни приходит конец. Человек умер, а волшебный лук исчез. На континенте вновь воцарилась война. Семеро дев войны Ванадис, которым драконы даровали волшебное оружие, правят семью провинциями континента.   \n   Наша же история начинается со встречи на поле боя одной из семерых Ванадис и талантливого лучника Тигревурмуда Ворна .","poster":"https://shikimori.io/system/animes/original/24455.jpg?1711962147","url":"https://shikimori.one/animes/24455-madan-no-ou-to-vanadis","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Этти","Гарем","Военный"],"episodes":13,"kind":"tv","franchise":null},{"title":"Кулинарные скитания в параллельном мире","rating":null,"tier":"unrated","review":"","desc":"Очередное королевство оказалось не в состоянии самостоятельно справиться с постигшими его проблемами и решило положиться на силу призванных иномирцев. Одного показалось маловато, поэтому с помощью ритуала перенесли сразу четырёх героев. Среди них затесался и 27-летний Цуёси Мукода. Вот только вскоре выяснилось, что его переместили в этот мир по ошибке. Никаких чудесных способностей у него, как не было, так и нет. Вернее, есть один навык, но совсем не героический и совершенно бесполезный в бою. Называется он «Сетевой супермаркет» и даёт Цуёси доступ к товарам, которые продаются в обычном японском магазине.   \n      \n   Когда Цуёси с его макаронами и колбасой турнули из королевства, он отправился в одиночку исследовать новый мир. Кто мог предположить,что кулинарные таланты Цуёси и продукты из гастронома окажутся так хороши, что привлекут внимание даже легендарного волка Фера. Покорённый вкусной едой, Фер заключил с Цуёси контракт и стал его фамильяром. Отныне дуэту из неудавшегося героя, вооружённого сковородкой, и могущественного волка-гурмана открыты все просторы мира.","poster":"https://shikimori.io/system/animes/original/53446.jpg?1709518221","url":"https://shikimori.one/animes/53446-tondemo-skill-de-isekai-hourou-meshi","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Гурман"],"episodes":12,"kind":"tv","franchise":null},{"title":"Кэнди-Бой","rating":null,"tier":"unrated","review":"","desc":"] Юкино  и Канадэ Сакураи  живут в одной комнате в общежитии при школе, наслаждаясь насыщенной порой жизни, юностью, вместе с друзьями. Однажды Юкино встречает Сакую Камияму , ученицу на год младше, а Канадэ в это время узнаёт от друзей, что новая знакомая её сестры уже давно восхищается последней. Это, казалось бы, невинное откровение приводит к цепи событий, которые помогают сёстрам понять свои чувства друг к другу.","poster":"https://shikimori.io/system/animes/original/4535.jpg?1711944915","url":"https://shikimori.one/animes/4535-candy-boy-nonchalant-talk-of-the-certain-twin-sisters-in-daily-life","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёдзё-ай","Школа","Комедия"],"episodes":7,"kind":"ona","franchise":null},{"title":"Лиз и синяя птица","rating":null,"tier":"unrated","review":"","desc":"Мизорэ Йоройзука и Нозоми Касаки — две лучшие подруги, учатся на последнем году старшей школы и обе состоят в клубе школьного духового оркестра. Тихая и застенчивая Мизорэ играет на гобое, а жизнерадостная Нозоми — на флейте. Они счастливо проводят свои дни в старшей школе, пока однажды клуб не начинает репетировать музыку, вдохновлённую сказкой «] и синяя птица». Флейта и гобой изображают Лиз и Девушку , которые в конце обязательно расстаются. Погрузившись в эту удивительную историю, Мизорэ и Нозоми начинают осознавать, что сами не смогут быть вместе всегда. Ведь близится конец учебного года, это последний концерт школьного оркестра, и страх Мизорэ потерять подругу после выпуска серьёзно сказывается на качестве её игры.","poster":"https://shikimori.io/system/animes/original/35677.jpg?1711961090","url":"https://shikimori.one/animes/35677-liz-to-aoi-tori","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Драма","Музыка","Школа"],"episodes":1,"kind":"movie","franchise":null},{"title":"Линия Дьявола","rating":null,"tier":"unrated","review":"","desc":"Вампиры живут среди людей. Но правительству, конечно, не ведомо их существование, ведь внешне они ничем не отличаются от обычных людей. Эти существа научились подавлять жажду человеческой крови. Однако, порой, когда они во власти невыносимого голода или когда их сознание обуревает ярость, монстры, увы, становятся монстрами...   \n   Юки Анзай — наполовину вампир, Цукаса Тайра — обычная студентка. Эта история об их взаимоотношениях.","poster":"https://shikimori.io/system/animes/original/35928.jpg?1711947555","url":"https://shikimori.one/animes/z35928-devils-line","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Ложные выводы","rating":null,"tier":"unrated","review":"","desc":"В детстве Котоко Иванага была унесена ёкаями — сверхъестественными мифическими существами. Они предложили ей роль богини мудрости, что позволило бы стать посредником между людским и потусторонним мирами. Взамен за это у неё заберут правый глаз и левую ногу. После недолгих раздумий Котоко согласилась на сделку, и теперь всякий раз, когда у ёкаев возникают проблемы, они бегут к ней за помощью.   \n   Прошло шесть лет. Куро Сакурагава, которого встретила Котоко, — молодой двадцатидвухлетний студент колледжа, только что расставшийся со своей девушкой. Котоко посчитала это шансом поближе познакомиться с парнем. Однако вскоре осознала, что Куро не совсем прост и имеет некую сверхспособность. Девушка предлагает ему стать напарником в расследовании сверхъестественных дел. Так и начинается их увлекательное и захватывающее приключение.","poster":"https://shikimori.io/system/animes/original/39017.jpg?1711960394","url":"https://shikimori.one/animes/39017-kyokou-suiri","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Романтика","Сверхъестественное","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Ложные выводы","rating":null,"tier":"unrated","review":"","desc":"В детстве Котоко Иванага была унесена ёкаями — сверхъестественными мифическими существами. Они предложили ей роль богини мудрости, что позволило бы стать посредником между людским и потусторонним мирами. Взамен за это у неё заберут правый глаз и левую ногу. После недолгих раздумий Котоко согласилась на сделку, и теперь всякий раз, когда у ёкаев возникают проблемы, они бегут к ней за помощью.   \n   Прошло шесть лет. Куро Сакурагава, которого встретила Котоко, — молодой двадцатидвухлетний студент колледжа, только что расставшийся со своей девушкой. Котоко посчитала это шансом поближе познакомиться с парнем. Однако вскоре осознала, что Куро не совсем прост и имеет некую сверхспособность. Девушка предлагает ему стать напарником в расследовании сверхъестественных дел. Так и начинается их увлекательное и захватывающее приключение.","poster":"https://shikimori.io/system/animes/original/39017.jpg?1711960394","url":"https://shikimori.one/animes/39017-kyokou-suiri","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Романтика","Сверхъестественное","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Любит не любит","rating":null,"tier":"unrated","review":"","desc":"Каждый рассуждает о любви по-своему. Для Юны  романтика превыше всего, в то время как Акари  чересчур приземлённа и практична в своих взглядах. Но девушки есть девушки. А что насчет парней? Те, оказывается, недалеко ушли от своих подруг. У Кадзуоми  ветер в голове, и парень будто ничего не смыслит в вопросах любви. А вот Рио  времени зря не теряет и не упускает ни одной девчонки, которая признаётся ему, пока та кажется милой. Каждый из них рассуждает о любви по-своему. Но настанет день, когда некоторым из них придётся сделать выбор. Кто останется верным себе, а кто — изменит своё представление под властью любви? Ведь та, как известно, меняет людей.","poster":"https://shikimori.io/system/animes/original/39753.jpg?1711967403","url":"https://shikimori.one/animes/39753-omoi-omoware-furi-furare","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Сёдзё","Драма","Романтика","Школа"],"episodes":1,"kind":"movie","franchise":null},{"title":"Любовные неудачи","rating":null,"tier":"unrated","review":"","desc":"Ничто не предвещало перемен в обыденной жизни обычного старшеклассника Асахи Касиваги, кроме разве что предсказания, сделанного тем утром в телевизионной программе. Всё, что было объявлено телевизором, начало сбываться с невообразимой точностью. Происходящее приводит к тому, что Асахи всего за один день знакомится с пятью необычными девушками, одна красивей другой. Мало того, каждая из них делает ему признание в любви! Что делать Асахи с таким неожиданно обрушившимся на него счастьем? Остаётся надеяться, что если он доверится своему сердцу, оно подскажет ему ту единственную, кто подарит ему настоящую чистую любовь. Но вдруг он ошибётся и его постигнет любовная неудача?","poster":"https://shikimori.io/system/animes/original/51403.jpg?1711939087","url":"https://shikimori.one/animes/51403-renai-flops","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Фантастика","Этти","Гарем","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Любовные неудачи","rating":null,"tier":"unrated","review":"","desc":"Ничто не предвещало перемен в обыденной жизни обычного старшеклассника Асахи Касиваги, кроме разве что предсказания, сделанного тем утром в телевизионной программе. Всё, что было объявлено телевизором, начало сбываться с невообразимой точностью. Происходящее приводит к тому, что Асахи всего за один день знакомится с пятью необычными девушками, одна красивей другой. Мало того, каждая из них делает ему признание в любви! Что делать Асахи с таким неожиданно обрушившимся на него счастьем? Остаётся надеяться, что если он доверится своему сердцу, оно подскажет ему ту единственную, кто подарит ему настоящую чистую любовь. Но вдруг он ошибётся и его постигнет любовная неудача?","poster":"https://shikimori.io/system/animes/original/51403.jpg?1711939087","url":"https://shikimori.one/animes/51403-renai-flops","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Фантастика","Этти","Гарем","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Магическая революция перерождённой принцессы","rating":null,"tier":"unrated","review":"","desc":"В юном возрасте принцесса Анисфия вспомнила свою прошлую жизнь, а также невероятную любовь к магии. Чтобы воплотить достижения науки из прошлой жизни в этом фэнтезийном мире, она разработала новую науку «магологию», воссоздав по памяти предметы, которые теперь работают не на электричестве, а при помощи магии. Однажды принцесса стала случайной свидетельницей неприятной сцены, когда её брат Альгард разорвал помолвку со своей невестой Эуфиллией. Юные леди не могли себе даже представить, что эта странная встреча изменит не только их собственное будущее, но и будущее всего королевства.","poster":"https://shikimori.io/system/animes/original/52736.jpg?1713146601","url":"https://shikimori.one/animes/52736-tensei-oujo-to-tensai-reijou-no-mahou-kakumei","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Сёдзё-ай","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Мария Холик","rating":null,"tier":"unrated","review":"","desc":"Как же сложно найти себе идеальную девушку, особенно если ты девушка сама, а парней ненавидишь: они грязные, мерзкие, и от них тут же сыпь по всему телу проступает...   \n   Канако Миямаэ переводится в женскую академию «Небесные королевы» в надежде встретить там любовь своей мечты. В первый же день, заблудившись по дороге в академию, она встречает Марию Сидо , обворожительную младшеклассницу с изящными манерами и прелестным голосом. Познакомившись и пообщавшись немного, они расходятся, а на прощание Мария целует Канако. О-о, очень неплохо, именно такие девушки Канако и нравятся!   \n   В общежитии Канако поселяют в одной комнате с местной звездой Рюкэн Исимой , высокой, стройной, всегда ко всем доброй и успешной во всём, чем занимается; в академии есть даже её фан-клуб. Ещё лучше!   \n   Однако мечты Канако рушатся, когда, зайдя в раздевалку стрелкового клуба, она застаёт там Марию, оказавшуюся... не совсем девушкой. Для проверки Канако делает кое-что очень неприличное и с ужасом понимает, что она не ошиблась — это парень! И не из робкого десятка — шантажом получив от неё клятву молчать, Мария отпускает Канако.   \n   Та в шоке бредёт в свою комнату в общежитие, надеясь хоть там-то выплакаться и рассказать всё своей соседке Рюкэн. Однако Мария времени даром не теряет, и, вернувшись в свою комнату, Канако обнаруживает, что Рюкэн переселили, а у неё новая соседка — кошмар всей её жизни, Мария.","poster":"https://shikimori.io/system/animes/original/5030.jpg?1711962966","url":"https://shikimori.one/animes/z5030-maria-holic","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика","Ужасы","Школа","Повседневность"],"episodes":12,"kind":"tv","franchise":null},{"title":"Меланхолия Харухи Судзумии","rating":null,"tier":"unrated","review":"","desc":"История пойдёт о Такамару Икусабэ. Он учится в Академии десяти сокровищ и, как любой уважающий себя японский школьник, мечтает охмурить какую-нибудь девушку. Однако его любовным похождениям вечно препятствует Нарика Сиходо. Так уж получилось, что он снимает квартиру у её отца.   \n      \n   Однажды мольбы парня были услышаны, и в академию перевели настоящую красавицу, Харуку Такамори, в которую Такамару тут же влюбился. Тем же вечером его с Нарикой преследует группа загадочных ниндзя. Когда кажется, что надежды на спасение уже нет, откуда ни возьмись появляется Харука, одетая словно куноичи (женщина-ниндзя). Назвав Такамару «молодым господином», Харука просит заняться с ней сексом. Оказывается, что секс необходим ей для подпитки суперспособностей, без которых одолеть этих ниндзя она не сможет.","poster":"https://shikimori.io/system/animes/original/6558.jpg?1711946264","url":"https://shikimori.one/animes/6558-choukou-sennin-haruka","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Хентай","Комедия","Приключения"],"episodes":3,"kind":"ova","franchise":null},{"title":"Мемуары Ванитаса","rating":null,"tier":"unrated","review":"","desc":"Быть белой вороной может не только обычный человек, но и вампир. Так, рождённого в ночь Голубой Луны Ванитаса его сородичи-вампиры, обычно появляющиеся при красной луне, презирали, ненавидели и боялись. Общество вампиров отталкивало «не такого», и Ванитас затаил злобу. Ведомый страхом и обидой, в надежде однажды отомстить, он создал великую книгу под названием «Мемуары ]». Этот тайный гримуар был наделён огромной силой, а её обладатель мог уничтожить вампирский род по мановению руки.   \n      \n   По прошествии многих лет книга стала легендой, и многие возжелали её заполучить. Поиски знаменитых «Мемуаров» привели вампира Ноя в Париж, где он случайным образом познакомился с доктором Ванитасом, специализирующимся на вампирах. Как оказалось, тот был человеком, унаследовавшим имя печально известного вампира, а также его книгу. Загадочный доктор использовал полученный гримуар для лечения пациентов-вампиров. Только для чего ему это: во имя блага вампиров или он преследует какие-то тёмные цели?","poster":"https://shikimori.io/system/animes/original/48580.jpg?1708772068","url":"https://shikimori.one/animes/48580-vanitas-no-karte","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Детектив","История","Вампиры","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Мир отомэ-игр - это тяжёлый мир для мобов","rating":null,"tier":"unrated","review":"","desc":"Если не везёт в жизни, то вряд ли повезёт в смерти, а того меньше — в перерождении. Этот удручающий принцип с абсолютной точностью сработал в случае с офисным работником-неудачником, которым помыкали и младшая сестра, и начальство и который в итоге погиб по нелепой случайности. Конечно, невезение продолжилось, и переродился он не где-нибудь, а в мире особо жёсткой отомэ-игры, где мужчин вообще не держат за людей.   \n   Став в новом мире сыном барона Леоном Фо Бартфортом, герой обладает единственным преимуществом: в прошлой жизни он прошёл эту игру до конца и отлично помнит повороты сюжета. Всё, чего он хочет, это никак не участвовать в основном сюжете игры и наслаждаться полной спокойствия и умиротворённости деревенской жизнью. Вот только, похоже, что для исполнения мечты ему придётся устроить революцию и низвергнуть слишком надолго затянувшийся матриархат!","poster":"https://shikimori.io/system/animes/original/50461.jpg?1716776859","url":"https://shikimori.one/animes/50461-otome-game-sekai-wa-mob-ni-kibishii-sekai-desu","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Романтика","Гарем","Меха","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Мириады цветов фантомного мира","rating":null,"tier":"unrated","review":"","desc":"Недалёкое будущее. Мир человеческого воображения. Разноплановые призраки и монстры уже не кажутся нелепой выдумкой, ведь они заполонили мир и стали жить в нём, как в родном. Таких неземных товарищей окрестили «фантомами». Но чудеса сим не закончились. С появлением фантомов люди также подверглись изменениям. Взрыв на станции, производящей генетически модифицированные продукты, привёл к развитию у некоторой части населения сверхъестественных способностей, которые позволяют определять фантомов и бороться с ними.   \n   Главный герой Харухико Итидзё — обычный старшеклассник из академии Осия. Но обычным он может показаться только в школе. За её пределами Харухико — обладатель способности, с помощью которой он может запечатывать фантомов. Так уж случилось, что он не единственный в школе, кто борется с нечистью. Компанию ему составляют: красавица Май Каваками, обладающая силой «пяти элементов»; способная в буквальном смысле пожирать фантомов Рэйна Идзуми и боец-одиночка Който Минасэ.","poster":"https://shikimori.io/system/animes/original/31442.jpg?1711965082","url":"https://shikimori.one/animes/31442-musaigen-no-phantom-world","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фэнтези","Этти","Гарем","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Могучая Бёрди","rating":null,"tier":"unrated","review":"","desc":"Всё, чем последнее время занят Цутому Сэнкава , ученик старшей школы, — это подготовка к экзаменам. А ещё у него есть хобби — исследование старых заброшенных зданий. Иногда, когда выдаётся свободная минутка, он бродит среди руин в покинутых кварталах города.   \n   Во время одной из таких прогулок он становится свидетелем попытки агента ] Бёрди Цефон Альтира  поймать галактического преступника. И попадает в самый разгар боя, где Бёрди, приняв его за противника, смертельно ранит Цутому.   \n   Проснувшись у себя в кровати, сначала он воспринимает всё произошедшее как страшный сон, но вскоре узнаёт, что тело его погибло, а сознание оказалось заключено в теле Бёрди — это был единственный способ спасти Цутому.","poster":"https://shikimori.io/system/animes/original/3974.jpg?1711977197","url":"https://shikimori.one/animes/y3974-tetsuwan-birdy-decode","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Монолог фармацевта","rating":null,"tier":"unrated","review":"","desc":"Уже полгода прошло с того момента, как 17-летнюю Маомао похитили и заставили трудиться в императорском дворце обычной служанкой. Работа тяжёлая, но девушка решила не сдаваться, не унывать и честно вкалывать, пока её не отпустят на покой. Планы изменились, когда до Маомао дошли вести о том, что детей императора одолел серьёзный недуг. Девушка решила тайком попробовать разобраться и помочь, рассчитывая на свой опыт в фармацевтике, которой она занималась раньше, когда проживала в Квартале красных фонарей.   \n   Несмотря на то, что Маомао не хотела привлекать к себе внимания, её вмешательство и талант не остались незамеченными. Вскоре Маомао оказалась вхожа во внутренние покои и вступила в круг приближённых императора. Благодаря своим знаниям и эксцентричному характеру Маомао произведёт фурор во дворце!","poster":"https://shikimori.io/system/animes/original/54492.jpg?1718587512","url":"https://shikimori.one/animes/54492-kusuriya-no-hitorigoto","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","История"],"episodes":24,"kind":"tv","franchise":null},{"title":"Моя подруга-олениха, Нокотан","rating":null,"tier":"unrated","review":"","desc":"Торако Коси — милая, добрая, заботливая и ответственная ученица старшеклассница. Отличница, президент ученического совета и просто замечательный человек: всем поможет, никого не бросит в беде. Все ученики её любят и уважают. Однако никто не знает, что за ширмой безобидной скромной девушки скрывается настоящая хулиганка и беспредельщица, которая держала в страхе всю среднюю школу.   \n   Естественно, Торако скрывает ото всех своё тёмное прошлое. Но в один прекрасный день на пути в школу Торако встречает загадочное существо — девушку-оленя Ноко Сиканоко, которая разглядела настоящую Торако сквозь маску притворства. Теперь репутация Торако висит на волоске, и она должна сделать всё возможное, чтобы Сиканоко никому не проболталась. Но сделать это очень не просто, ведь совершенно непонятно, кто такая Сиканоко, чего она хочет и что у неё на уме!","poster":"https://shikimori.io/system/animes/original/58426.jpg?1718266672","url":"https://shikimori.one/animes/58426-shikanoko-nokonoko-koshitantan","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Как приручить мумию","rating":null,"tier":"unrated","review":"","desc":"Когда под пылающим летним зноем Рихито Тацуно повстречал рядом с домом еле живого мужчину, который из последних сил брёл по дороге, держась за забор, он не подозревал, что ему попался самый настоящий 450-летний вампир. Невинный, добросердечный Рихито предложил страждущему незнакомцу воды, чем и решил свою участь. Бескорыстная щедрость пятилетнего Рихито поразила утомлённого годами одиночества вампира в самое сердце или, точнее, в самый желудок.   \n   С тех пор прошло десять лет. Всё это время вампир Раммару Мори честью и правдой трудился на благо семьи Тацуно, которая держит общественную баню. Возникает закономерный вопрос «почему?». Почему Мори так и не съел парнишку, который полностью в его вкусе? Почему до сих пор прозябает в тухлом захолустье, когда мог бы жить где угодно? Ответ кроется в том факте, что все вампиры немножечко гурманы. У каждого есть свои предпочтения в «еде». Вот, например, Раммару строго предпочитает 18-летних девственников, найти которых становится всё сложнее. Чего удивляться, что в условиях дефицита Раммару попросту решил проследить, чтобы блюдо было готово вовремя и не испортилось!","poster":"https://shikimori.io/system/animes/original/58265.jpg?1717011227","url":"https://shikimori.one/animes/58265-babanbabanban-vampire","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Не издевайся, Нагаторо 2","rating":null,"tier":"unrated","review":"","desc":"Жил-поживал один неприметный старшеклассник — горя не знал, рисовал рисульки разнообразные, в основном про рыцарей, которые прекрасных дам из беды выручают и героизмом, значит, поражают в самое сердце. Естественно, сам таковым ни разу не являлся, а лишь фантазии свои на бумагу переносил. Замкнутый, ранимый, мечтательный Сэмпай...   \n   Но манга мангой, а в реальной жизни всё иначе. Нагаторо , недавно переведённая в ту же школу, архетипичный образ девы в беде не разделяет. Воплощение зла, огнедышащее чудовище, скрывающееся под личиной миленькой девчушки, — вот кто она! И стоило только Сэмпаю с ней познакомиться, как жизнь его превратилась в ад. Ну что, скажите на милость, эта чертовка в нём нашла?   \n   И хотя Нагаторо изо дня в день продолжает терроризировать свою жертву, жертва-то, кажется, начинает привыкать. Но, главное, она понимает, что даже у «чудовища» есть свои слабости. И кто знает, возможно, эта история расскажет о том, как неловкий рыцарь подружился со своим смертельным врагом...","poster":"https://shikimori.io/system/animes/original/42361.jpg?1711954792","url":"https://shikimori.one/animes/50876-ijiranaide-nagatoro-san-2nd-attack","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Школа","Приключения"],"episodes":12,"kind":"tv","franchise":"nagatoro"},{"title":"Невеста чародея","rating":null,"tier":"unrated","review":"","desc":"За свою недолгую жизнь юная Тисэ Хатори успела испытать множество невзгод. Окружённая пренебрежением и жестокостью, лишённая всего, что хотя бы отдалённо напоминало любовь или заботу, не знавшая тепла семейного очага, она смирилась со своей участью, полной бед и злоключений.   \n   И вот однажды, когда всякая надежда уже была утрачена, посреди рабовладельческого аукциона девушку ожидала судьбоносная встреча. Теперь, когда таинственный незнакомец, похожий скорее на чудовище, чем на человека, покупает её за баснословную сумму, жизнь Тисэ больше никогда не вернётся в прежнее русло.   \n   Этот незнакомец по имени Элиас Эйнсворт — чародей, загадочный кудесник, творящий невиданные чудеса. Он решает освободить Тисэ из оков рабства и взять её в ученицы, ведь девушка обладает редчайшим магическим даром. И наконец, чародей делает ошеломляющее заявление: Тисэ станет не только его ученицей, но и невестой!","poster":"https://shikimori.io/system/animes/original/35062.jpg?1711962379","url":"https://shikimori.one/animes/35062-mahoutsukai-no-yome","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фэнтези","Романтика","Сёнэн"],"episodes":24,"kind":"tv","franchise":null},{"title":"Необычное такси","rating":null,"tier":"unrated","review":"","desc":"Таксист Одокава живёт серой однообразной жизнью. У него нет семьи, нет друзей, он чудаковатый, узко мыслящий и мало разговаривающий тип. Единственные его собеседники — это его врач Горики и его одноклассник из средней школы Какихана.   \n      \n   Его клиенты и сами кажутся немного странными. Кабасава — студент колледжа, который хочет, чтобы мир заметил его в Интернете. Сиракава — загадочная медсестра, которая что-то скрывает. «Хомосапиенс» — комедийный дуэт, у которого не всё гладко с профессиональной деятельностью. Местный хулиган по имени Добу. Все они садятся в его такси, едут, ведут обычные разговоры, которые каким-то образом ведут к пропавшей девушке.","poster":"https://shikimori.io/system/animes/original/46102.jpg?1711967048","url":"https://shikimori.one/animes/46102-odd-taxi","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","Триллер"],"episodes":13,"kind":"tv","franchise":null},{"title":"Непутёвый ученик в школе магии","rating":null,"tier":"unrated","review":"","desc":"Что для нас магия? Это нечто невообразимое, существующее только в мечтах. Проходят года и... она становится не просто достоянием общества, а наукой. Каждый день учёные делают всё новые открытия в этом искусстве, построенные в основном на знаниях физики будущего. Естественно, не обойтись и без молодых, для которых была открыта старшая школа при университете. Вот только дискриминация в мире как была, так и остаётся: попасть в неё могут только люди со способностями. Но это ещё не всё: внутри стен школы вас поделят — на «сорняки» и «цветки». Так и оказалась наша главная героиня-сестра Миюки в первом потоке, став лучшей по проходному баллу благодаря своим практическим способностям, а теоретика-брата Тацую отправили во второй поток гнить к «сорнякам». Да не тут-то было: система отбора у школы заметно страдает; уже очень скоро друзья будут распахивать рты от новенького «недомага», девушки будут вешаться на шею, а враги пожалеют, что вообще связались с ним.","poster":"https://shikimori.io/system/animes/original/20785.jpg?1711962361","url":"https://shikimori.one/animes/z20785-mahouka-koukou-no-rettousei","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Фантастика","Школа"],"episodes":26,"kind":"tv","franchise":null},{"title":"Неспешная жизнь уволенного тёмного солдата","rating":null,"tier":"unrated","review":"","desc":"Преданно служивший королю демонов, Дариэль никак не ожидал, что, когда его начальник, один из четырёх генералов Армии демонов, уйдёт на покой, его сын и наследник Башубаза, ставший новым генералом, тут же с позором уволит его со службы и вышвырнет не только из армии, но и из страны. А всё потому, что в Дариэле нет ни капли магии, хотя ею владеет любой самый захудалый демон. Новый генерал не посмотрел даже на то, что Дариэль по сути его сводный брат, ведь прежний главнокомандующий подобрал Дариэля ещё ребёнком, воспитал как сына и поставил на высокую должность. Однако всё это уже позади. Делать нечего, и Дариэль, который представления не имеет, куда ему теперь податься, отправляется куда глаза глядят. Так он случайно оказывается в деревне, где ему предлагают остаться жить. Что нужно бывалому вояке? Сон, прогулки, мирное вскапывание грядок? Нет! Ему надо вступить в гильдию авантюристов и начать громить монстров направо и налево!","poster":"https://shikimori.io/system/animes/original/52446.jpg?1713147062","url":"https://shikimori.one/animes/52446-kaiko-sareta-ankoku-heishi-30-dai-no-slow-na-second-life","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Комедия","Приключения"],"episodes":12,"kind":"tv","franchise":null},{"title":"Ниер: Автомата — Версия 1.1а. Часть 2","rating":null,"tier":"unrated","review":"","desc":"Краткий пересказ событий первых шести эпизодов аниме-сериала «».","poster":"https://shikimori.io/system/animes/original/56930.jpg?1718286345","url":"https://shikimori.one/animes/56063-nier-automata-ver1-1a-part-2","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Драма","Постапокалипсис"],"episodes":12,"kind":"tv","franchise":"nier_automata"},{"title":"Ниер: Автомата — Версия 1.1а","rating":null,"tier":"unrated","review":"","desc":"В далёком будущем Земля превратилась в руины после вторжения пришельцев и созданных ими механических существ. Оставшееся человечество было вынуждено бежать на Луну, оставив планету на милость бездушных машин. Чтобы вернуть свой дом, люди отправляют на поверхность элитных андроидов из отряда \"ЙорХа\".\n\nСреди них — 2B, хладнокровный боевой андроид, и 9S, аналитик с любопытным и живым умом. Их миссия — уничтожить захватчиков, но чем дальше они заходят, тем больше сталкиваются с вопросами, на которые не существует простых ответов. Почему машины проявляют странное поведение? Что значит быть живым? И кому действительно принадлежит этот умирающий мир?\n\nЭто мрачная история о войне, предназначении и поиске смысла среди хаоса разрушенного мира.","poster":"https://shikimori.io/system/animes/original/51105.jpg?1718592170","url":"https://shikimori.one/animes/51105-nier-automata-ver1-1a","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Драма","Постапокалипсис"],"episodes":12,"kind":"tv","franchise":"nier_automata"},{"title":"Низкоуровневый персонаж Томодзаки 2","rating":null,"tier":"unrated","review":"","desc":"Фумия Томодзаки наконец-то освоился в игре под названием «жизнь» — и всё благодаря наставничеству Аой Хинами, его популярной одноклассницы и соперницы по онлайн-игре Attack Families, известной среди игроков как «Таккфам». Летние каникулы подходят к концу, начинается новый учебный семестр, и Томодзаки снова встречается с Аой, которая напоминает ему о главной цели: стать своим среди сверстников и наконец найти себе девушку.[br][br]Однако Томодзаки приходится отложить собственные амбиции в сторону, когда его наивную подругу Ханаби Нацубаяси начинают травить в школе. Хуже того, Аой, как обычно, не замечает происходящего и остаётся в стороне от проблемы. Но на этот раз Томодзаки не один — рядом с ним верные друзья, готовые сделать всё, чтобы помочь Ханаби и вместе прожить свою юность по-настоящему ярко.","poster":"https://shikimori.io/system/animes/original/50803.jpg?1718592412","url":"https://shikimori.one/animes/50803-jaku-chara-tomozaki-kun-2nd-stage","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Школа"],"episodes":13,"kind":"tv","franchise":"tomozaki"},{"title":"О МОЁМ ПЕРЕРОЖДЕНИИ В МЕЧ","rating":null,"tier":"unrated","review":"","desc":"Попаданцам вечно не везёт. Как в прошлой жизни, в которой они, как правило, погибли жестокой глупой смертью, так и в нынешней, где они часто оказываются не в самом выгодном положении. Главному герою этой истории не повезло вдвойне: мало того, что коньки отбросил, вместе с коньками он лишился ног, рук, головы и вообще тела, так как переродился в меч! Да ещё с корабля на бал очутился посреди леса, кишащего монстрами.   \n      \n   Вот в этом хаосе он и повстречал девушку-кошку, которая сбежала от своих хозяев и их жестокого с ней обращения.   \n   Девушка представляется как Фран, а вот меч никак не может назвать имя и не потому что рта нет, а потому что — забыл. Фран любезно дарует мечу имя Мастер, а меч великодушно обещает девушке дружбу и защиту. Отныне они команда, которая будет мочить злодеев, биться за добро и справедливость, ну и параллельно прокачиваться потихоньку.","poster":"https://shikimori.io/system/animes/original/49891.jpg?1711942422","url":"https://shikimori.one/animes/49891-tensei-shitara-ken-deshita","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Обитель Анубиса","rating":null,"tier":"unrated","review":"","desc":"После смерти бабушки Минато  остался совершенно один в этом мире. Кадзари Сайондзи , в семье которой бабушка Минато работала горничной, предлагает ему руку помощи. Так как Минато больше некуда идти, он соглашается принять помощь от неё. Для этого он должен выдать себя за девушку и поселиться в общежитии женской академии, председателем которой является Кадзари. Но вот только девушки, с которыми ему придётся жить, немного озабоченные...","poster":"https://shikimori.io/system/animes/original/35827.jpg?1711968114","url":"https://shikimori.one/animes/35827-otome-domain-the-animation","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Хентай","Комедия","Приключения"],"episodes":1,"kind":"ova","franchise":null},{"title":"Обладатель серебряного сахара и темный фейри: сказка о сахарном яблоке","rating":null,"tier":"unrated","review":"","desc":"Энн Хэлфорд — начинающая мастерица по приготовлению сладостей. Несмотря на свой юный возраст, она решительно настроена стать мастером серебряного сахара, коим была и её мать. По пути в столицу, на ярмарку, где будет определено, кто заслуживает звания Мастера, Энн купила Шелла. Мрачный красавец-фейри — опытный и опасный воин, необходимый Энн в качестве телохранителя. Девушка жаждет подружиться со своим спутником, но в этом мире, где к фейри относятся как к собственности, Шелл не хочет иметь ничего общего с людьми.","poster":"https://shikimori.io/system/animes/original/49980.jpg?1709524064","url":"https://shikimori.one/animes/49980-sugar-apple-fairy-tale","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Фэнтези","Романтика","Сёдзё"],"episodes":12,"kind":"tv","franchise":null},{"title":"Один из отвергнутых: Изгой","rating":null,"tier":"unrated","review":"","desc":"Главный герой Чжан Чулан по традиции вёл жизнь обычного студента, пока в один ужасный день не угодил в переплёт на краю какой-то деревушки. Непринуждённо прогуливаясь по ночному кладбищу, парнишка неожиданно был атакован зомби. И вот, когда казалось, что Чжан вот-вот распрощается с жизнью, откуда ни возьмись появилась таинственная красотка и мигом пустила трупоеда на кебаб. Само собой, сея встреча мигом изменила жизнь унылого героя, открыв врата в мир сверхъестественного.","poster":"https://shikimori.io/system/animes/original/33421.jpg?1711982462","url":"https://shikimori.one/animes/33421-yi-ren-zhi-xia","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Сверхъестественное","Супергероика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Отряд самоубийц из другого мира","rating":null,"tier":"unrated","review":"","desc":"Джокер и его любимая девушка, Харли Квинн, разносят улицы Готэма в пух и прах, унося мешки с деньгами прямо из-под носа полиции, что уже дышит им в затылок. К несчастью для парочки, хотя клоуну и удаётся сбежать, ночь заканчивается тем, что Харли попадает в плен к таинственной женщине, вооружённой катаной.Тем временем Аманда Уоллер, глава правительственной организации A.R.G.U.S., собирает отряд суперзлодеев для беспощадной миссии в другом мире. После того как связь с первым отрядом самоубийц, отправленным через портал, была потеряна, Аманда посылает им на замену Дэдшота, Миротворца, Глиноликого, Короля Король Акул и Харли. Однако вскоре после того, как они проходят портал, их вертолёт терпит крушение прямо посреди битвы между конными воинами и свирепыми орками.Все сопровождающие их бойцы A.R.G.U.S. гибнут при падении, и злодеи, освободившись от оков, врываются в гущу орочьего войска, сами того не желая, помогая людским солдатам — и в награду получают лишь новое заточение. Теперь, скованные магическими кандалами, Харли и её товарищи должны как можно скорее вернуться к порталу, через который попали в этот мир, иначе бомбы, вживлённые A.R.G.U.S. им в шею, взорвутся.","poster":"https://shikimori.io/system/animes/original/55848.jpg?1712184575","url":"https://shikimori.one/animes/55848-isekai-suicide-squad","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения"],"episodes":10,"kind":"tv","franchise":null},{"title":"Парад смерти","rating":null,"tier":"unrated","review":"","desc":"Добро пожаловать в бар «Квиндеким». Бар, за типичной обстановкой и приглушённым светом которого скрывается нечто большее. Кажется, что единственным работником этого загадочного заведения является бармен. Он встречает посетителей и объясняет правила: с этой минуты гости вынуждены вступить в смертельную схватку друг с другом, и игра, выбранная в случайном порядке, — их последний шанс спасти свою жизнь. Бар «Квиндеким» — это место, где человек показывает истинную сущность. Где грехи и пороки уже невозможно скрыть. Где ставка — ваша душа.","poster":"https://shikimori.io/system/animes/original/28223.jpg?1711947433","url":"https://shikimori.one/animes/28223-death-parade","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Сверхъестественное","Триллер","Психология"],"episodes":12,"kind":"tv","franchise":null},{"title":"Перерождение Дяди","rating":null,"tier":"unrated","review":"","desc":"Кто же не мечтает хоть разок побывать в ином мире, наполненном магией и дивными существами?! Хотя обычный семнадцатилетний паренёк Ёсукэ Сибадзаки всерьёз об этом не задумывался, именно ему судьба решила предоставить такой шанс. Условия перемещения, правда, оказались не совсем приятными, но с многотонным грузовиком не поспоришь. На долгие годы тело Сибадзаки погрузилось в кому, а его сознание забросило в другой мир, где его приняли за орка и неустанно преследовали.   \n   Прошло столько лет, что родные уже и не чаяли, что Сибадзаки очнётся, но тот вдруг пришёл в себя и заговорил на странном языке, утверждая, что владеет магией. Разумеется, его приняли за сумасшедшего, и только племянник не отвернулся от дяди. Навестив того в больнице, Такафуми собственными глазами узрел, как дядя управляет огнём и перемещает предметы по воздуху. В таких обстоятельствах было сложно не поверить в историю о другом мире.   \n   Теперь Сибадзаки предстоит восполнить годы, проведённые в коме, и с помощью племянника познакомиться с чудесами современного мира, такими, как интернет, смартфон и игровые консоли, и, конечно, посмотреть кучу вышедшего за это время аниме!","poster":"https://shikimori.io/system/animes/original/49220.jpg?1703475899","url":"https://shikimori.one/animes/49220-isekai-ojisan","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Пародия"],"episodes":13,"kind":"tv","franchise":null},{"title":"Повелитель 3","rating":null,"tier":"unrated","review":"","desc":"2138 год. Виртуальная реальность развивается семимильными шагами, и в это же время популярная онлайн-игра «Иггдрасиль» неожиданно закрывается. Момонга, главный герой истории, решает не выходить из игры до полного отключения серверов. Но произошло невероятное: сервер не прервал подключение, игра продолжилась, а Момонга превратился в могущественного скелета-волшебника. Мир начал расширяться, а NPC-персонажи — испытывать эмоции. Не имея родителей, друзей и места в обществе, Момонга решает не пытаться найти выход из игры, а остаться в ней, управляя Великой Гробницей Назарик.\nВеликий и могущественный Айнз Ул Гоун узнаёт от Демиурга, что его подчинённые во главе с последним хотят для него захватить весь мир. Тем временем группа работников была послана на миссию по исследованию Великой Гробницы.","poster":"https://shikimori.io/system/animes/original/37675.jpg?1711968188","url":"https://shikimori.one/animes/37675-overlord-iii","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":13,"kind":"tv","franchise":"overlord"},{"title":"Повелитель 4","rating":null,"tier":"unrated","review":"","desc":"Прочно обосновавшийся в новом мире, Момонга официально объявил о создании собственного королевства, а себя нарёк великим королём-магом. Если раньше происходящее напоминало ему компьютерную игру: битвы, стратегии, завоевания, то сейчас он всё больше сталкивается с совершенно незнакомыми ему сферами — государственным управлением, мировой экономикой и внешней политикой. Пускай он усиленно строит из себя непобедимого мудреца, но в душе прекрасно осознаёт, что он всего лишь обычный офисный служащий. Поэтому в таких важных вещах Момонга вынужден полагаться на своих верных соратников NPC.\n\nПродолжая укреплять свою власть, Момонга держит в уме и свою основную цель — найти других игроков, которые, возможно, так же, как и он, оказались заперты в игре «Иггдрасиль». Однако пока это лишь предположение, и его единственной поддержкой остаются верные NPC, ставшие ему семьёй. Ради них он готов рискнуть жизнью, и те отвечают ему не меньшей преданностью и обожанием. Разве не в этом доверии и взаимной заботе залог счастливого государства? Момонга убеждён, что да. Сможет ли он донести свои благородные взгляды до здешних жителей, боящихся нежити как огня?","poster":"https://shikimori.io/system/animes/original/48895.jpg?1703476324","url":"https://shikimori.one/animes/48895-overlord-iv","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":13,"kind":"tv","franchise":"overlord"},{"title":"Повседневная жизнь бессмертного короля 3","rating":null,"tier":"unrated","review":"","desc":"С самого рождения Ван Лин  обладает сверхчеловеческими способностями, рядом с которыми меркнет даже могущество сильнейших магов всего мира. Ван Лин не может контролировать свою невероятную силу, поэтому родители накладывают на него печать, которая подавляет его мощь.    \n   В возрасте шестнадцати лет Ван Лин собирается поступать в школу магов, где хочет выглядеть, как обычный школьник, но почему-то всё идёт не по плану.","poster":"https://shikimori.io/system/animes/original/41094.jpg?1711980809","url":"https://shikimori.one/animes/50404-xian-wang-de-richang-shenghuo-3","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма","Школа","Повседневность"],"episodes":12,"kind":"tv","franchise":"xian_wang"},{"title":"Полёт ведьмы","rating":null,"tier":"unrated","review":"","desc":"Аомори, Япония. Провинциальный городок, удивляющий своей красивой природой. Среди гор и прозрачных рек, окружённых зеленью, жизнь течёт особенно размеренно и спокойно. По крайней мере, так было до того, как туда приехала молодая ведьма Макото , которую отправили к родственникам, чтобы она научилась жить вдали от дома и стала лучше в ведьмовском деле.   \n   Она поселяется у троюродного брата Кэя  и сестры Тинацу , которые сразу замечают, что она ведёт себя немного странно. Когда Макото, выбирая метлу на рынке, поднимается на ней в воздух, Тинацу окончательно понимает, что дальше их ждёт весёлая и необычная совместная жизнь.","poster":"https://shikimori.io/system/animes/original/31376.jpg?1711949574","url":"https://shikimori.one/animes/z31376-flying-witch","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Предсмертный список зомби","rating":null,"tier":"unrated","review":"","desc":"Три года назад Акира Тэндо смотрел в будущее с высоко поднятой головой. Он нашёл отличную работу и был полон надежд и амбиций. Но работа мечты оказалась сущим адом: бесконечные переработки и давление со стороны начальства и старших коллег доводили беднягу до предела. Работа высасывала из парня всю жизненную энергию, и по прошествии нескольких лет он оказался истощён как морально, так и физически. Лишь симпатичная коллега Акиры, Саори Отори, в которую молодой человек влюбился с первого взгляда, поддерживала в нём интерес к работе. Однако на любовном фронте Акиру ждала неудача: девушка уже состоит в отношениях с директором компании, так что парень всё чаще стал задумываться об увольнении.   \n      \n   В одно прекрасное утро всё перевернулось с ног на голову. Проснувшись, Акира обнаружил, что весь город заполонили зомби. Ещё ни разу в жизни молодой человек не чувствовал себя более живым и свободным, а мир, поблекший от бесконечных переработок, вдруг засиял яркими красками. Теперь, когда в работе больше нет нужды, Акира решает исполнить всё, о чём так долго мечтал. И никакие зомби ему не помеха!","poster":"https://shikimori.io/system/animes/original/54112.jpg?1711330087","url":"https://shikimori.one/animes/54112-zom-100-zombie-ni-naru-made-ni-shitai-100-no-koto","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика","Фантастика","Драма","Ужасы"],"episodes":12,"kind":"tv","franchise":null},{"title":"Призванный в другой мир во второй раз","rating":null,"tier":"unrated","review":"","desc":"Поначалу история юноши, ставшего главным героем, развивалась по типичному сценарию исекая: его призвали в другой мир в качестве избранного, который спасёт мир от демонов. Что он, собственно, и сделал. На раз-два расправился со всеми злодеями, прославился и стал легендой. Казалось бы, тут должны были появиться слова «и жили они долго и счастливо», однако вместо этого в сюжете образовался неожиданный излом. Выполнив долг, великий Герой несколько расслабился и угодил в западню, устроенную теми, кого не устраивала его всенародная любовь и популярность.   \n      \n   Наш Герой не погиб, а был перемещён обратно на родную Землю в тело ребёнка. Долгое время он пытался вернуться в мир, где он Герой, искал путь назад и взрослел. И вот, уже будучи угрюмым старшеклассником, которого недолюбливают и не понимают одноклассники, он наконец дожил до очередного поворота судьбы: его вновь призвали в тот же мир, только перенёсся он туда вместе со своими одноклассниками. Какие шаги предпримет разочарованный в исекаях юноша, ставший Героем во второй раз?","poster":"https://shikimori.io/system/animes/original/50220.jpg?1711941640","url":"https://shikimori.one/animes/50220-isekai-shoukan-wa-nidome-desu","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Романтика","Гарем"],"episodes":12,"kind":"tv","franchise":null},{"title":"Притворная любовь","rating":null,"tier":"unrated","review":"","desc":"В детстве маленький Раку Ичиджо, как это обычно бывает, пообещал жениться на тогдашней возлюбленной. В знак памяти об этом обещании Раку достался кулон с замком, а его избраннице — ключик от него. Они договорились встретиться в будущем, чтобы открыть его и исполнить обещание.   \n   По прошествии нескольких лет Раку уже старшеклассник, а его возлюбленной из детства и след простыл. Но тут откуда ни возьмись появляется странная напыщенная особа японо-американского происхождения Читогэ Кирисаки, с которой они с первого взгляда не сошлись характерами.   \n   Придя домой, отец Раку (глава клана якудза) сообщает сыну новость о том, что тому, старающемуся жить нормальной жизнью старшеклассника, придётся встречаться с дочерью главы местной бандитской группы (который ещё и старый друг отца Раку). И ею оказывается... Читогэ! Если он откажется, то из-за бандитских разборок от города ничего не останется! Именно поэтому ребятам придётся до поры до времени прикидываться искренне любящей друг друга парочкой.","poster":"https://shikimori.io/system/animes/original/18897.jpg?1711966339","url":"https://shikimori.one/animes/z18897-nisekoi","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика","Фантастика","Школа"],"episodes":20,"kind":"tv","franchise":null},{"title":"ПРИЧИНА ПОЛЮБИТЬ ЕЁ","rating":null,"tier":"unrated","review":"","desc":"В день, когда Ли Джун Ли поступает в университет Минсон, чтобы наконец встретиться с Ким Марго Ким — своей школьной любовью, — на него набрасывается новая соседка Ли Дуна Ли, ослепительно красивая бывшая айдол. Взрывная и непредсказуемая, Дуна переворачивает жизнь Джуна с ног на голову. Вскоре, к его недоумению, оказывается, что у Марго никак не находится времени на встречу с ним. А в довершение всех бед на одной из вечеринок Джун знакомится с сокурсницей Ира Чхве Ирой, которая после одной довольно смелой игры проникается к нему нежными чувствами. По мере того как Джун всё глубже погружается в тяжёлое прошлое Дуны и узнаёт о непростых семейных обстоятельствах Марго, он пытается разобраться в собственном запутанном клубке чувств.","poster":"https://shikimori.io/system/animes/original/54846.jpg?1710727454","url":"https://shikimori.one/animes/54846-aishang-ta-de-liyou","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Школа"],"episodes":22,"kind":"ona","franchise":null},{"title":"Развращённая гильдия","rating":null,"tier":"unrated","review":"","desc":"Кикуру Мадана — страж, хранящий покой города, защищая его от монстров. Несмотря на юный возраст, он первоклассный охотник, так как всю  жизнь провёл в тренировках и совершенствовании навыков. Осознав вдруг, что молодость уходит и он может не успеть ею насладиться, Кикуру решает исправить это недоразумение и объявляет, что покидает гильдию. Тогда администратор Эноме просит Кикуру сначала подготовить замену себе и поднатаскать новенькую, неуклюжую зверодевушку Хитаму.","poster":"https://shikimori.io/system/animes/original/51212.jpg?1711939460","url":"https://shikimori.one/animes/51212-futoku-no-guild","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Комедия","Фэнтези","Этти","Гарем"],"episodes":12,"kind":"tv","franchise":null},{"title":"Романтический киллер","rating":null,"tier":"unrated","review":"","desc":"Что нужно девушке для счастья? Модные шмотки? Куча поклонников? Любовь до гроба? Вовсе нет. Андзу Хосино обойдётся малым и предпочтёт провести время, играя в видео-игры, уплетая шоколад и тиская любимого кота. Это её формула полного незыблемого счастья. Обычно всё это доступно ей в часы, свободные от школы, но не сейчас.   \n      \n   Стоило Андзу включить игру, как из неё выскочила какая-то зараза, назвалась Рири и объявила, что в связи с демографическим кризисом девушке необходимо срочно выйти замуж и начать строгать детишек. И ещё Рири ставит Андзу перед фактом, что тотчас конфискует у неё все соблазны, чтобы ничто не отвлекало ту от выбора жениха и построения с ним отношений. Такой беспредел средь бела дня вызывает у Андзу бурю ярости и негодования. Она клянётся, что костьми ляжет, но не даст втянуть себя в сюжет шаблонного гаремника, в который грозит превратиться её жизнь!","poster":"https://shikimori.io/system/animes/original/52865.jpg?1711936038","url":"https://shikimori.one/animes/52865-romantic-killer","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Сверхъестественное","Пародия","Сёнэн"],"episodes":12,"kind":"ona","franchise":null},{"title":"РУКОВОДСТВО ПО СЕМЕНАМ ФЕЙ","rating":null,"tier":"unrated","review":"","desc":"Дин Юань  — китайский подросток-отаку, который, как и многие любители аниме и видеоигр, хотел посетить знаменитую выставку, посвященную этой сфере. Однако вместо выставки он попадает в необычный мир, где особую важность имеет садоводческое искусство и каждый садовник пользуется магией в повседневной жизни. Постепенно осваиваясь в новом мире, Дин Юань узнаёт о существовании фей и о том, что их выращивают из семян, а затем выясняется, что он — единственный, кто способен это делать. Так начинается история Дин Юаня — спасителя фей.","poster":"https://shikimori.io/system/animes/original/41093.jpg?1711982280","url":"https://shikimori.one/animes/41093-yao-jing-zhong-zhi-shou-ce","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Этти"],"episodes":14,"kind":"ona","franchise":null},{"title":"Рыцарь-скелет вступает в параллельный мир","rating":null,"tier":"unrated","review":"","desc":"Современный мир пестрит разнообразием технологий, новомодных гаджетов и, конечно, изобилием компьютерных игр на любой возраст и вкус. Главного героя покорила игра в жанре фэнтези, в которой он управляет рыцарем-скелетом в сияющих доспехах. Случайно заснув во время игры, он очнулся в другом мире, да не просто в другом, а в мире любимой онлайн-игры, ещё и в качестве своего персонажа Арка.   \n   В происходящее верилось с трудом, но детальность экипировки и окружающего мира не оставляли сомнений в реальности происходящего. Долго не думая и стараясь не поддаваться панике, Арк решил проверить на что способен. Кроме оружия, предметов и навыков, которыми персонаж владел в игре, теперь ему стали доступны и новые опции.   \n   Немного поразмыслив, Арк посчитал, что следует подыскать себе работу, ведь нужно на что-то жить. Отправившись в путь в поисках ближайшего города, он неожиданно набрёл на шайку разбойников, которые измывались над девушками и, как истинный рыцарь, не смог оставить дам в беде. Здесь и начинается долгий, полный опасностей и приключений путь рыцаря-скелета в новом мире.","poster":"https://shikimori.io/system/animes/original/48760.jpg?1708738404","url":"https://shikimori.one/animes/48760-gaikotsu-kishi-sama-tadaima-isekai-e-odekakechuu","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"],"episodes":12,"kind":"tv","franchise":null},{"title":"Сад изящных слов","rating":null,"tier":"unrated","review":"","desc":"«Мы встретились, чтобы двигаться вперёд».   \n      \n   Такао  мечтает создавать обувь и прогуливает школу, трудясь над эскизами в одном из традиционных японских садов. Однажды, застигнутый там ливнем, он знакомится с таинственной девушкой — Юкари , которая определённо старше Такао.   \n   После той встречи, не договариваясь заранее, они продолжают случайно сталкиваться друг с другом, но происходит это только тогда, когда на улице проливной дождь. С каждой встречей отношения Такао и Юкари крепнут, они открываются друг другу, но сезон дождей подходит к концу...","poster":"https://shikimori.io/system/animes/original/16782.jpg?1712343791","url":"https://shikimori.one/animes/x16782-kotonoha-no-niwa","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":1,"kind":"movie","franchise":null},{"title":"Сведённые кукушкой","rating":null,"tier":"unrated","review":"","desc":"Истории о том, как малышей перепутали в роддоме, кажутся просто нереальными. И, точно, никому в голову не придёт, что он окажется одним из таких детей. Шестнадцать лет Наги Умино прожил в неведении, даже не подозревая, что люди, воспитывавшие его все эти годы, ему вовсе не родные.   \n   Узнав правду, парень вознамерился направиться на встречу с настоящими родителями, твёрдо решив заявить о нежелании что-то менять в своей жизни. По пути Наги наткнулся на странную девушку, сидящую на парапете моста и, приняв ту за самоубийцу, попытался спасти от роковой ошибки. Этой девушкой оказалась Эрика Амано, которая просто снимала видео и вовсе не думала сводить счёты с жизнью. После столь необычного знакомства выяснилось, что не только у Наги имеются проблемы в семье.   \n   Эрика из богатой семьи, так что ей уже подыскали жениха, но Эрика не намерена с этим мириться. Внезапно её осеняет гениальная мысль — представить Наги как свою вторую половинку и избежать нежеланной помолвки. Парень противится безумной идее, но Эрика шантажом заставляет его согласиться. Обсудив детали обмана, молодые люди отправляются на встречу с родными девушки. Каково же было удивление парочки юных «аферистов», когда выяснилось, что именно Эрику и Наги перепутали в роддоме. Более того, женихом Эрики является никто иной как сам Наги!","poster":"https://shikimori.io/system/animes/original/48675.jpg?1708745521","url":"https://shikimori.one/animes/48675-kakkou-no-iinazuke","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Комедия","Романтика","Гарем"],"episodes":24,"kind":"tv","franchise":null},{"title":"Сжечь ведьму","rating":null,"tier":"unrated","review":"","desc":"Очень давно в Лондоне большая часть смертей была связана с существованием фантастических зверей — драконов. Они причиняли много вреда, и чтобы как-то это предотвратить, был установлен контроль над этими существами.    \n   Жители «Реального Лондона» не в состоянии видеть драконов, в отличии от жителей «Иного Лондона», скрытого от мира людей. В этом «ином» городе существует специальная организация по разведению и защите драконов, которая заботится о них. Однако там есть только одно непреложное правило — никогда, ни при каких обстоятельствах обычные люди не должны касаться драконов. В контакт с ними могут вступать лишь определённые люди — чародеи и ведьмы, а правонарушителей ждёт заключение под стражу на сто лет либо смертная казнь.    \n   Главные героини Ноэль Нихаси  и Нини Спангл как раз являются ведьмами, в обязанности которых входит уход за драконами, не более. Но однажды случается непредвиденная ситуация: человек вступает в контакт с драконом. И разобраться в ней посылают именно Ноэль и Нини.","poster":"https://shikimori.io/system/animes/original/41468.jpg?1711944771","url":"https://shikimori.one/animes/41468-burn-the-witch","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Боевик","Фэнтези"],"episodes":3,"kind":"ona","franchise":null},{"title":"Совершенно новый зверь","rating":null,"tier":"unrated","review":"","desc":"В этой истории рядом с человечеством живут зверолюди. Современный мир, где природа уступает цивилизации, а людей с генами зверей изгоняют из родных мест. Мировое сообщество пытается стабилизировать ситуацию и создать возможность сосуществования двух видов. Именно для этого в Японии открывают Анима-сити — место, где зверолюди смогут быть собой.   \n      \n   Десять лет спустя семнадцатилетняя Митиру Кагэмори  сбегает в Анима-сити. Прежде она была обычным человеком, но однажды внезапно превратилась в тануки. В городе зверолюдей девушка понимает, что наконец-то может жить свободно. Там же она знакомится с упрямым Сиро Огами , который ненавидит людей, и многими другими жителями Анима-сити, узнавая всё больше об их жизни. Но почему Митиру стала зверочеловеком? Когда герои пытаются это выяснить, происходят неожиданные события.","poster":"https://shikimori.io/system/animes/original/40060.jpg?1711944257","url":"https://shikimori.one/animes/40060-bna","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Супергероика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Сонни Бой","rating":null,"tier":"unrated","review":"","desc":"16 августа, середина долгих летних каникул. Пустые школьные классы, в которых никого нет, тоскливые дни... внезапно прерванные неожиданным происшествием — здание школы, Нагара и 36 его одноклассников вдруг перемещаются в другое измерение!\nТам подростки, брошенные на произвол судьбы, сталкиваются со многими загадочными ситуациями и явлениями. Но главное — приобретают различные способности, находящиеся за пределами человеческого понимания. Некоторые радуются открытым в себе силам и устраивают беспорядки, другие пытаются занять место лидера группы, остальные же — отчаянно ищут способ вернуться в мир, из которого они прибыли.\nНедоверие, неконтролируемая ревность и стремление к лидерству приводят к конфликтам. В водовороте вопросов, которые возникают один за другим, начинается жизнь на грани выживания.\nСмогут ли Нагара и его друзья покорить этот мир и благополучно вернуться домой?","poster":"https://shikimori.io/system/animes/original/48849.jpg?1708765112","url":"https://shikimori.one/animes/48849-sonny-boy","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Детектив","Психология","Драма","Сверхъестественное"],"episodes":12,"kind":"tv","franchise":null},{"title":"Союз серокрылых","rating":null,"tier":"unrated","review":"","desc":"Сон о падении с неба... а после — рождение. Главная героиня без имени появляется на свет из большого кокона в каком-то старом доме и сразу же встречает группу женщин с маленькими крыльями за спиной и сияющими нимбами над головой. Чуть позже ей дают имя — Ракка (яп. 落下 — досл. «падающая») из-за сна, который та видела перед «рождением». Вскоре у неё прорезаются собственные крылья, и она получает свой нимб. Некоторое время спустя девушке рассказывают, что та должна работать в соседнем городе под названием Гури. Вскоре Ракка понимает, что Гури ограждён от остального мира высокой непроходимой стеной, и никто, кроме таинственных «Плащей», не имеет права его покинуть. Так героиня начинает свою жизнь в этом мире, став одной из «Союза Серокрылых».","poster":"https://shikimori.io/system/animes/original/387.jpg?1711952303","url":"https://shikimori.one/animes/z387-haibane-renmei","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":13,"kind":"tv","franchise":null},{"title":"Спокойной ночи, Мир","rating":null,"tier":"unrated","review":"","desc":"Таитиро Арима — хикикомори, ненавидящий свою семью, которую считает самой дерьмовой на планете, а каждого её члена — неудачником, неспособным принести пользу обществу и позаботиться о родных, поэтому бóльшую часть времени он проводит в онлайн-игре «Планета». В виртуальной реальности Таитиро состоит в гильдии под названием «Семья Акабанэ», в которой отношения между согильдийцами являются идеальным примером счастливой семьи и даруют парню душевное спокойствие. Ко всему прочему «Семья Акабанэ» носит статус одной из сильнейших гильдий, что позволяет ей с лёгкостью проходить миссии, бороться с огромными монстрами или сильными командами и побеждать в любой битве. В игре всё так складно, что Таитиро не испытывает никакого желания возвращаться в реальность.   \n      \n   В любых ситуациях члены гильдии стоят друг за друга горой и делятся всем, но несмотря на такую сплоченность у них есть одно нерушимое правило: ни в коем случае нельзя лезть в личную жизнь друг друга. И эту договрённость члены гильдии беспрекословно соблюдают. Только вот изменится ли отношение Таитиро к участникам «Семьи Акабанэ», если он узнает, что виртуальная семья — это его ненавистные родственники?","poster":"https://shikimori.io/system/animes/original/56146.jpg?1713141718","url":"https://shikimori.one/animes/56146-good-night-world","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фэнтези","Комедия"],"episodes":12,"kind":"ona","franchise":null},{"title":"Стальная тревога","rating":null,"tier":"unrated","review":"","desc":"Сикидодзи, иллюстратор серии лайт-новеллов Сёдзи Гато Full Metal Panic!, сообщил, что было дано зелёный свет на производство «режиссёрской версии» первого телесериала Full Metal Panic!!, вышедшего в 2002 году. Режиссёрская версия будет состоять из трёх фильмов. В анонсе не уточняется, появятся ли в этой трилогии новые сцены.","poster":"https://shikimori.io/system/animes/original/36344.jpg?1711949705","url":"https://shikimori.one/animes/36344-full-metal-panic-movie-3-into-the-blue","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фантастика","Меха","Военный"],"episodes":1,"kind":"movie","franchise":null},{"title":"Старшая карта","rating":null,"tier":"unrated","review":"","desc":"Решив поддержать родной приют, оказавшийся на грани закрытия из-за финансовых проблем, Финн Олдман отправился в казино, намереваясь быстро сколотить себе состояние. Однако вместо золотых гор Финна поджидали погоня и перестрелка, в которую он неожиданно оказался втянут. Умудрившийся выжить Финн узнал, что опасный инцидент связан с существованием особенных игральных карт, каждая из которых позволяет владельцу заполучить суперспособность. Карты настолько могущественны, что могут повлиять на расстановку сил в государстве.   \n   Чтобы избежать проблем и минимизировать негативные последствия от использования карт, король Форландии, на территории которой и рассеяны карты, создал специальный отряд под названием «Старшая карта». Членом этого отряда предложили стать и Финну.   \n   Теперь ему вместе с четырьмя коллегами необходимо собрать карты и успеть сделать это раньше многочисленных конкурентов!","poster":"https://shikimori.io/system/animes/original/49154.jpg?1707109149","url":"https://shikimori.one/animes/49154-high-card","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Супергероика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Сыграйте круто, ребята","rating":null,"tier":"unrated","review":"","desc":"Мужественность — неотъемлемая часть представителей сильного пола. Однако не только мужественность определяет парней, не стоит забывать и о целеустремлённости, смелости, трудолюбии и способности не ударить в грязь лицом. Следует также отметить, что мужчины обладают и иными чертами, которые обычно приписывают прекрасному полу. Парни тоже бывают милыми, чувствительными и неуклюжими.   \n      \n   Идеальный тому пример — пятёрка очаровательных парней, которые то и дело попадают в нелепые ситуации. Задуматься и пойти не в ту сторону — не в первый раз! Перепутать заказ в кафе, где работаешь — и это проходили! Забыть кошелёк и обнаружить его отсутствие только на кассе — не в новинку! Какая бы ситуация ни произошла, эти красивые, но временами недотёпистые парни всё равно будут выглядеть невероятно круто!","poster":"https://shikimori.io/system/animes/original/51680.jpg?1715567235","url":"https://shikimori.one/animes/51680-cool-doji-danshi","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Повседневность","Комедия","Приключения"],"episodes":24,"kind":"tv","franchise":null},{"title":"Томо - девушка","rating":null,"tier":"unrated","review":"","desc":"Томо Аидзава и Дзюнъитиро Кубота — самые настоящие братаны и никак иначе. Они шутят друг над другом, спорят и дерутся, но всегда прикроют спины друг друга. Ничего не в состоянии разрушить эту крепкую мужскую дружбу! Кроме, разве что, того ничтожного факта, что Томо — девушка и что она по уши влюблена в Дзюна.   \n      \n   Пускай Томо — сорванец и с детства вела себя как полноправный член мальчишеской банды, пускай она не даёт своих в обиду и смело лезет в бой, это ещё не причина напрочь игнорировать её признания! А глупый Дзюн мало того, что не замечает её пылких чувств, он вообще считает её парнем! Как остаться самой собой, но при этом завоевать сердце любимого? Задачка как раз для боевой девчонки, которой все препятствия по плечу!","poster":"https://shikimori.io/system/animes/original/52305.jpg?1713753045","url":"https://shikimori.one/animes/52305-tomo-chan-wa-onnanoko","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Туманная гора 5 элементов","rating":null,"tier":"unrated","review":"","desc":"Два эпизода-компиляции с повторением ключевых моментов оригинальной OVA «Медсёстры ночной смены», известные также как эпизоды 5.5 и 10.5.","poster":"https://shikimori.io/system/animes/original/24743.jpg?1711982097","url":"https://shikimori.one/animes/24743-yakin-byoutou-specials","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Хентай","Комедия","Приключения"],"episodes":2,"kind":"ova","franchise":null},{"title":"Фантастический мир с обращённым в красавицу мужчиной и…","rating":null,"tier":"unrated","review":"","desc":"Давно известно, что нужно быть аккуратнее с желаниями, ведь они имеют свойство сбываться!   \n      \n   К сожалению, ничем не примечательный офисный работник Хината Татибана, возраст которого давно перевалил за тридцать, забыл эту прописную истину. Напившись в компании давнего друга Дзингудзи Цукасы, он, изведшийся от полного отсутствия женского внимания, пожелал сам стать ослепительной красавицей, сражающей мужские сердца. Тут откуда ни возьмись появилась богиня и перенесла обоих в другой мир. Вот так желание Татибаны и исполнилось! Он превратился в сногсшибательную лоли, перед чарами которой никто не может устоять. Богиня объявила друзьям, что теперь они герои и им полагается спасти мир от Короля Демонов. Если, конечно, они хотят вернуть Татибане мужской облик.   \n      \n   А они хотят! Ещё как хотят! Или нет?","poster":"https://shikimori.io/system/animes/original/48997.jpg?1706500083","url":"https://shikimori.one/animes/48997-fantasy-bishoujo-juniku-ojisan-to","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Пародия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Цветок вечности","rating":null,"tier":"unrated","review":"","desc":"Мадока Куоно  очень энергичная девушка, страстью и гордостью которой является клуб \"Джерси\", цель которого - помощь всем нуждающимся людям!   \n   Жизнь Мадоки переворачивается с ног на голову, когда странная незнакомка просит её помочь - пилотировать робота. Желая защитить людей и свой родной город Камогаву, Мадока соглашается попробовать справиться с воскресшим внезапно роботом, и бороться с инопланетянами, вторгающимися и атакующими Землю..","poster":"https://shikimori.io/system/animes/original/11227.jpg?1711970960","url":"https://shikimori.one/animes/11227-rinne-no-lagrange","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фантастика","Меха"],"episodes":12,"kind":"tv","franchise":null},{"title":"Чёрный призыватель","rating":null,"tier":"unrated","review":"","desc":"Проснувшись в незнакомом новом месте, герой Кельвин узнал, что получил силу и способности. Взамен, однако, ему пришлось отдать воспоминания о прошлой жизни. Став призывателем, герой отправился в новый мир, чтобы творить добро. Его спутницей стала златовласая дева по имени Эфил. Получив новую жизнь и возможности, Кельвин пустился в странствия, намереваясь найти дорогу домой. На своём пути он встретит как друзей, так и врагов. Сможет ли Кельвин с их помощью вернуть воспоминания?","poster":"https://shikimori.io/system/animes/original/51064.jpg?1713754611","url":"https://shikimori.one/animes/51064-kuro-no-shoukanshi","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Шарлотта","rating":null,"tier":"unrated","review":"","desc":"Ю Отосака не всегда был эгоистом и обманщиком. Изменения в характере начались в тот момент, когда он неожиданно открыл в себе паранормальную способность, предоставляющую возможность ровно на пять секунд вселяться в чужое тело. Обзаведясь такой полезной силой, юноша удивляться не стал, а, немного пораскинув мозгами, в конце концов нашёл ей нужное применение. В чём бы вы думали? В учёбе.\nУхитряясь незаметно «похищать» тела усердных пятерочников, Ю раз за разом списывал на экзаменах. В итоге с отличием закончил среднюю школу и поступил в престижную старшую. Ну а дальше дело оставалось за малым: таким же макаром просочиться в лучший университет и тем самым устроить себе и младшей сестрёнке благополучное будущее.\nСо временем все вокруг стали казаться идиотами, что только укрепляло амбицию парня, твёрдо уверенного в своей уникальности. Уникальности, насчёт которой кое-кому однажды захотелось поспорить... И вот хитрая Нао Томори, в прямом смысле появившаяся словно из ниоткуда, не без злорадства сбила спесь с самодовольного трюкача, стоило ей только сказать, что такие, как он, на этом свете вовсе не редкость.","poster":"https://shikimori.io/system/animes/original/28999.jpg?1711945851","url":"https://shikimori.one/animes/28999-charlotte","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Школа","Драма","Сверхъестественное","Суперсила"],"episodes":13,"kind":"tv","franchise":null},{"title":"Сказания арада: война","rating":null,"tier":"unrated","review":"","desc":"Барон Абель  - обычный парень живущий на континенте Арад. В 981 году \"проклятый свет Казана\" упал на землю, став причиной появления множества ужасных монстров. Во время катаклизма проклятие затронуло левую руку Барона , и та стала одержима темными силами, но найденный меч с духом-хранителем по имени Рокси  позволяет сдерживать развитие проклятия. С того самого времени наш герой путешествует по континенту в поисках еды, ночлега и разгадки тайны проклятия.","poster":"https://shikimori.io/system/animes/original/4657.jpg?1711941991","url":"https://shikimori.one/animes/4657-arad-senki-slap-up-party","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Фэнтези"],"episodes":26,"kind":"tv","franchise":null},{"title":"Волчий дождь","rating":null,"tier":"unrated","review":"","desc":"Согласно древней легенде, незадолго до Конца Света появится Рай, и только волки будут знать, как его найти. Несмотря на то, что последнего живого волка видели около 200 лет назад, они по-прежнему существуют, научившись принимать человеческий облик.   \n   Киба (牙), раненый белый волк-одиночка, отправляется в город Фриз, почуяв запах лунного цветка, являющегося ключом от Рая. Там он сталкивается с Цумэ (爪), Хигэ (須) и Тобоэ (遠吠え) — другими волками, которые, как и он, пришли в город по запаху цветка. Но в городе волки встречают Квента Яйдена (クエント・ヤイデン), бывшего шэрифа Кириоса, и его собаку Блю (ブル), одержимых охотой на волков. Находящуюся без сознания Чезу (チェザ), Деву Цветка, которой суждено привести волков в рай, изучает в лаборатории Шер Дегрэ (シェール・ドゥグレ). Почувствовав волчью кровь, Чеза просыпается, но когда волки проникают в лабораторию, девушку похищает Лорд Дарсия Третий (ダルシア), чьи люди и создали Чезу...","poster":"https://shikimori.io/system/animes/original/202.jpg?1711980527","url":"https://shikimori.one/animes/202-wolf-s-rain","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Драма","Фэнтези","Детектив","Фантастика"],"episodes":26,"kind":"tv","franchise":null},{"title":"Красноволосая принцесса Белоснежка","rating":null,"tier":"unrated","review":"","desc":"История повествует о молодой девушке по имени Шираюки — обладательнице редчайших волос, таких же красных, как спелые наливные яблоки. Несмотря на щедрый подарок природы, писаную и необычную красоту, девушка ведёт образ жизни простолюдинки, которой нет дела до роскошного королевского замка, возвышающегося посреди её родного города. А до его высокородных обитателей ей нет дела вдвойне.   \n   Но однажды равнодушие улетучивается. Причиной тому становится богатый, но прослывший своей глупостью принц, влюбившийся в девушку с первого взгляда. Невзирая на её собственные желания и чувства, принц решает во что бы то ни стало добиться расположения красноволосой девицы. Поглощённая мыслями о том, как избавиться от свалившейся на неё напасти, Шираюки обрезает прекрасные волосы и решает спастись от напористого мужа королевских кровей, иммигрировав в соседнюю страну.   \n   Удирая через лес, беглянка знакомится с молодым человеком по имени Зен, который помогает ей избавиться от погони. Что теперь произойдёт с Шираюки, потерявшей возможность вернуться на родину? И кто на самом деле её загадочный новый друг?","poster":"https://shikimori.io/system/animes/original/30123.jpg?1711939833","url":"https://shikimori.one/animes/30123-akagami-no-shirayuki-hime","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёдзё","Драма","Фэнтези","Романтика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Ящик предложений Мэдаки","rating":null,"tier":"unrated","review":"","desc":"Мэдаку Куроками (黒神めだか) — первый класс старшей школы — выбирают президентом школьного совета. Первая же вещь, которую она делает на новой должности — учреждает ящик для отзывов и предложений, позже прозванный учениками «Ящиком ]». Она призывает учеников без колебаний опускать в ящик письма с любыми их проблемами и обещает браться за любое дело от кого угодно.   \n   Так как Мэдака выиграла выборы в школьный совет с ошеломляющими 98% голосов, получилось, что она — единственный член совета. Она просит своего друга детства Зэнкичи Хитоёши (人吉 善吉) о помощи, и тот неохотно, но соглашается вступить в совет. Вскоре Мэдака вербует ещё двоих учеников: бывшего члена клуба дзюдо Коки Акунэ  (阿久根 高貴) в качестве секретаря и участницу плавательного клуба Могану Кикайджиму (喜界島もがな) за ежедневную плату в 300 йен в качестве казначея.   \n   Теперь школьный совет проводит время, решая проблемы, переданные им через «Ящик Мэдаки», будь то хулиганы, торчащие в клубах, в которых они не состоят, девушки, которым требуется помощь в написании любовного письма, или люди, потерявшие своих домашних животных.","poster":"https://shikimori.io/system/animes/original/11761.jpg?1711963199","url":"https://shikimori.one/animes/z11761-medaka-box","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Романтика","Школа","Повседневность"],"episodes":12,"kind":"tv","franchise":null},{"title":"Связанные небом (Yosuga no Sora)","rating":null,"tier":"unrated","review":"","desc":"В мире, населённом девятью расами, люди занимают самое низкое положение и постоянно сталкиваются с презрением со стороны остальных. Лайт покидает родной дом, мечтая стать великим искателем приключений, однако его навык «Бесконечная гача», способный материализовывать случайные предметы, кажется окружающим совершенно бесполезным.   \n      \n   Вскоре Лайт становится представителем человечества в Союзе племён — отряде, объединившем представителей разных рас. Во время исследования Бездны, опаснейшего подземелья в мире, товарищи внезапно предают его и оставляют умирать среди чудовищ.   \n      \n   Оказавшись на грани гибели, Лайт вновь использует свой дар и неожиданно призывает Мэй — могущественную горничную 9999-го уровня, поклявшуюся ему в абсолютной верности. Открыв истинные возможности «Бесконечной гачи» и собрав вокруг себя невероятно сильных союзников, Лайт начинает готовить возмездие тем, кто обрёк его на смерть.","poster":"https://shikimori.io/system/animes/original/8861.jpg?1711982702","url":"https://shikimori.one/animes/8861-yosuga-no-sora","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Драма","Этти"],"episodes":12,"kind":"tv","franchise":null},{"title":"Хранитель вечности","rating":null,"tier":"unrated","review":"","desc":"С развитием науки человечеству открылись знания о существовании магии, что повлекло огромные изменения во всём мире. Однако мальчик по имени Тота , живущий в небольшом  городке, далёк от этих изменений. И всё же его обычная жизнь не лишена собственной магии. Поддержку в изучении этого навыка он получает от своей учительницы и друзей. Но тихие деньки заканчиваются, и юношу ждёт удивительное приключение.","poster":"https://shikimori.io/system/animes/original/33478.jpg?1711979444","url":"https://shikimori.one/animes/z33478-uq-holder-mahou-sensei-negima-2","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Летнее время","rating":null,"tier":"unrated","review":"","desc":"Симпэй и не думал возвращаться в родной город из Токио, пока не узнал о смерти сводной сестры. И вот он стоит на причале небольшого острова — места, где провёл детство, — и с грустью вспоминает дни минувшие. Усио больше нет. Она утонула, пытаясь спасти ребёнка.   \n   Винить некого, разве что злую судьбу. Причина смерти ясна, обстоятельства указывают на несчастный случай. Однако те немногие, кто видел на теле девушки следы удушения, верят в убийство.    \n   Вдобавок среди островитян ходят дурные слухи о неких тенях — двойниках людей, которые несут смерть увидевшим их. Местные сказки, не более. Так и думал бы Симпэй, если бы его вторая сводная сестра Мио не клялась, что за три дня до смерти Усио видела точную её копию...","poster":"https://shikimori.io/system/animes/original/47194.jpg?1711975472","url":"https://shikimori.one/animes/47194-summertime-render","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Сверхъестественное","Триллер","Сёнэн"],"episodes":25,"kind":"tv","franchise":null},{"title":"Страна самоцветов","rating":null,"tier":"unrated","review":"","desc":"Далёкое будущее. Самоцветы — новая форма жизни, населяющая Землю. У них нет гендерных различий, но они наделены бессмертием. Однако жизнь их, как и у людей, непростая: лунные обитатели постоянно терроризируют новых землян, дабы похитить и превратить в обычные украшения. Поэтому 28 самоцветов должны противостоять захватчикам.   \n   Каждому камню предназначена своя роль, например, воин или врач. Будучи всего 300-летним, Фосфофиллит (младший из всей расы), ещё не имеющий своего предназначения, хочет помочь в борьбе против лунных оккупантов, хотя он слишком слаб и хрупок для боя. Но вот, однажды, мастер Самоцветов — Адамант — поручает ему создать энциклопедию истории самородков.","poster":"https://shikimori.io/system/animes/original/35557.jpg?1711954240","url":"https://shikimori.one/animes/35557-houseki-no-kuni","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сэйнэн","Боевик","Драма","Фэнтези","Детектив"],"episodes":12,"kind":"tv","franchise":null},{"title":"Последняя фантазия XV","rating":null,"tier":"unrated","review":"","desc":"Несколько эпизодов, вышедших в качестве бонусов к игре «Final Fantasy XV». В них показаны события, не вошедшие в игру и о которых зритель знает только со слов персонажей. В основном истории сосредоточены на воспоминаниях о детстве главных героев игры — наследного принца королевства Люцис Ноктиса и троих его друзей и телохранителей из королевской гвардии.","poster":"https://shikimori.io/system/animes/original/33080.jpg?1711944634","url":"https://shikimori.one/animes/z33080-brotherhood-final-fantasy-xv","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":5,"kind":"ona","franchise":null},{"title":"Седьмая жизнь злодейки: узы вражды","rating":null,"tier":"unrated","review":"","desc":"Пятнадцать лет жизни герцогская дочь Рише Ирмгард Верцнер готовилась стать будущей королевой, но потерпела полный крах, когда наследный принц разорвал с ней помолвку ради другой. Изгнанная с родины, Рише стала купцом и довольно успешно строила бизнес, пока не погибла. А после этого она вернулась на пять лет назад в сцену разрыва помолвки. Ошеломлённая происходящим Рише тем не менее не растерялась и заново устроила свою жизнь, но на этот раз как травница. Однако она опять умерла во цвете лет и предсказуемо оказалась перед очами бросающего её жениха.   \n   Осознав, что любая мелочь имеет влияние на судьбу, Рише прожила уже шесть разных жизней: была купцом, травницей, горничной и даже рыцарем. Вот только каждый раз она успевала дожить только до двадцати лет, а затем так или иначе умирала из-за развязанной соседним королём крупномасштабной войны.   \n   Начав седьмой круг, Рише решила, что с неё хватит интенсивных приключений и полной занятости. Да, было весело, но пора и честь знать. Она жаждет пожить наконец в своё удовольствие и не думать о завтрашнем дне. Да и желательно бы ещё протянуть до старости, а не попасть в очередную временнýю петлю. Тут ей под руку подворачивается тот самый кровожадный король-тиран Арнольд Хайн, который чуть погодя устроит войну, и предлагает выйти за него замуж, пообещав, что будет исполнять любое её желание.","poster":"https://shikimori.io/system/animes/original/56352.jpg?1710723926","url":"https://shikimori.one/animes/56352-loop-7-kaime-no-akuyaku-reijou-wa-moto-tekikoku-de-jiyuu-kimama-na-hanayome-seikatsu-wo-mankitsu-suru","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Романтика","Комедия"],"episodes":12,"kind":"tv","franchise":null},{"title":"Белая коробка","rating":null,"tier":"unrated","review":"","desc":"Аой Миямори  никогда не забудет школьный клуб анимации, но главное — то сияющее чувство радости, переполняющее её в дни последнего культурного фестиваля накануне выпуска из старшей школы. Чувство трепета перед демонстрацией своей работы зевающей публике, и чувство выполненного долга — после. Гордость за себя и своих одноклубников. Мечты о том, чтобы стремительным рывком ворваться в аниме-индустрию большого города и вместе, впятером, после счастливой встречи создать что-то стоящее усилий.   \n   Но мечты мечтами, а реальность берёт своё. Два года спустя Аой работает ассистентом продюсера в небольшой анимационной студии, выполняя рутинную и лишённую удовольствия работу. С момента выпуска энтузиазм девушки несколько поубавился, однако, несмотря на жёсткий график и трудовую суету, она всё ещё надеется выполнить обещание, которое они с одноклубниками Эмой , Мидори , Мисой  и Шизукой  дали когда-то друг другу.   \n   Создать грандиозное аниме сложно, но если заручиться поддержкой настоящих друзей — даже такая нелёгкая задача станет пустяковой затеей!","poster":"https://shikimori.io/system/animes/original/25835.jpg?1711973756","url":"https://shikimori.one/animes/z25835-shirobako","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа","Повседневность"],"episodes":24,"kind":"tv","franchise":null},{"title":"Мелочи жизни","rating":null,"tier":"unrated","review":"","desc":"Наша жизнь состоит из милых сердцу мелочей. Казалось бы, попасть с подругами под дождь, заставлять себя сделать домашнюю работу и так и не сделать её, что-то приготовить на ужин — это так обычно, повседневно. Но этот сериал заставит вас по-новому взглянуть на эти вещи! Ведь если присмотреться, в каждом действии заключена скрытая магия, в каждом человеке скрыта тайна.   \n   Вот, например, Май Минаками  — казалось бы, такая умная и серьёзная, а на самом деле в душе она та ещё шутница, и это часто прорывается наружу. Юко Айой  непоседливая, шумная — от таких ожидаешь только неприятностей. Но она на самом деле очень добрый человек, который всегда рад помочь окружающим, пусть иногда и несколько странными способами. Мио Наганохара  увлекается рисованием фривольной манги, но в повседневной жизни это весёлый и открытый человек, сильно стесняющийся своего хобби. Нано Синономэ  — заботливый и добрый робот... Стоп! Какой робот в повседневности? Такой вот, самый обычный робот, придуманный самым обычным восьмилетним Профессором ! А ещё, местную школу посещают аристократ-фермер, ездящий на занятия на любимом козле, фанатка оружия, любители футбольного го и другие, самые обычные личности.   \n   В общем, перед нами обычно-необычные истории из жизни дружной компании девочек. И каждый найдёт в этих коротких сценках что-то своё.","poster":"https://shikimori.io/system/animes/original/10165.jpg?1711966129","url":"https://shikimori.one/animes/10165-nichijou","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Школа","Сёнэн"],"episodes":26,"kind":"tv","franchise":null},{"title":"Озорная Такаги","rating":null,"tier":"unrated","review":"","desc":"В классе Нисикаты  учится девочка по имени Такаги. Весёлая, симпатичная — глаз не оторвать. И — чудо! — сидит за соседней партой. Любой мальчишка на месте Нисикаты надул бы в штаны от счастья, однако для последнего Такаги — сущее наказание. Ведь именно его, бедного, бедного Нисикату она выбрала в качестве объекта для своих глупых розыгрышей.   \n   Изо дня в день мальчик пытается дать однокласснице бой, отплатить ловкачке той же монетой. Однако любой его замысел трещит под каблучком хитрой Такаги, раз за разом утирающей горе-мстителю нос.   \n   «Ну, погоди, ]! Вот увидишь: когда-нибудь я тебя разыграю», — думает Нисиката, от обиды и злости сжав кулаки. Он даже пытается её игнорировать. Но то ли слабовольность мешает ему, то ли какие другие чувства, пока смутные и непонятные... И уже через каких-то пару минут Нисиката вновь поддаётся на провокацию.   \n   Почему же Такаги такая упрямая? Разве ей больше не над кем пошутить? А может, Нисиката просто не в состоянии кое-что смекнуть? И как знать, возможно, поддразнивание Такаги уже не будет казаться таким обидным...","poster":"https://shikimori.io/system/animes/original/35860.jpg?1711957667","url":"https://shikimori.one/animes/35860-karakai-jouzu-no-takagi-san","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Школа","Сёнэн"],"episodes":12,"kind":"tv","franchise":null},{"title":"Добро пожаловать в класс превосходства 4","rating":80,"tier":"exceeded","review":"","desc":"Второй год обучения в элитной старшей школе «Кодо Икусэй» преподносит Киётаке Аянокоджи новые суровые испытания. Едва перейдя на второй курс, ученики сталкиваются с ужесточёнными правилами выживания. Администрация школы внедряет систему OAA (Over All Ability) — мобильное приложение, которое отныне переводит все академические и физические навыки студентов в публичные числовые рейтинги, не оставляя шанса на скрытность.   \n   Также объявляется о проведении специального экзамена с беспрецедентными условиями. Второкурсники обязаны объединиться в пары с первокурсниками. На кону стоит многое: если образованная пара набирает низкий балл, отчисление грозит исключительно ученику второго курса. Пока студенты пытаются справиться с академическим давлением и наладить контакт с порой весьма своеобразными новичками, над Аянокоджи нависает скрытая угроза. Становится известно, что среди поступивших первокурсников затесался тайный агент из «Белой комнаты», чья единственная цель — любой ценой добиться его исключения.","poster":"https://shikimori.io/system/mangas/original/125053.jpg?1708932048","url":"https://shikimori.one/animes/59708-youkoso-jitsuryoku-shijou-shugi-no-kyoushitsu-e-4th-season-2-nensei-hen-1-gakki","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Триллер","Детектив","Школа"],"episodes":16,"kind":"tv","franchise":"classroom_of_the_elite"},{"title":"Начало после конца 2","rating":8,"tier":"good","review":"","desc":"Получив второй шанс на жизнь, ныне уже подросший Артур Лейвин — в своём прошлом воплощении беспощадный и не имевший равных король — наконец-то стал искателем приключений, чему поспособствовала его наставница Жасмин Флеймсворт. Хотя до заветной цели — стать сильнее, чем в прошлой жизни, — ему ещё далеко, Артур проявляет в своих приключениях выдающиеся способности, превосходя все ожидания.Тем временем подруга Артура, эльфийка и принцесса королевства Эленуар Тессия Эралит, тоже начинает путь искателя приключений. Из-за давней вражды между людьми и эльфами на неё возложена обязанность нести добрую волю и налаживать дружеские отношения с человеческими королевствами. Однако когда некая таинственная группировка начинает угрожать и без того хрупким связям между расами, Артур и Тессия вскоре обнаруживают, что им предстоит сыграть ключевую роль в переменах к лучшему.","poster":"https://shikimori.io/system/mangas/original/21090.jpg?1712715022","url":"https://shikimori.one/animes/61831-saikyou-no-ousama-nidome-no-jinsei-wa-nani-wo-suru-season-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":"tbate"},{"title":"Похоже, сильнейшая профессия — это не герой или мудрец, а инспектор?","rating":8,"tier":"good","review":"","desc":"Обычная жизнь шестнадцатилетнего старшеклассника  обрывается в тот момент, когда он по воле случая оказывается втянут в неизвестный ему мир, где магическая энергия и уровень определяют всё. Здесь отважные герои отправляются в смертельные походы, мудрецы управляют могущественными заклинаниями, а судьбы решаются в пылу сражений. Сам же юноша не получает ни великой силы, ни особого дара — вместо этого ему навязывают странную, на первый взгляд, бесполезную роль временного инспектора.   \n   Однако со временем выясняется, что его навыки позволяют видеть то, что скрыто от глаз местных жителей и даже опытных воинов: уязвимые места врагов, скрытые таланты союзников и саму структуру магии. Благодаря аналитическому складу ума и поразительной способности к адаптации, он начинает изучать правила новой реальности. В своих путешествиях Хибики обзаводится верными друзьями и спутниками, которые видят в его «бесполезной» профессии невероятный потенциал. Используя системные лазейки временного инспектора и поддержку товарищей, он шаг за шагом становится сильнее, проходя путь от слабого чужака до отважного лидера отряда, способного изменить этот удивительный мир к лучшему — наполнив его благополучием и надеждой для каждого.","poster":"https://shikimori.io/system/mangas/original/109045.jpg?1712842526","url":"https://shikimori.one/animes/62825-saikyou-no-shokugyou-wa-yuusha-demo-kenja-demo-naku-kanteishi-kari-rashii-desu-yo","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Драма","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Ранма 1/2 (2024)","rating":20,"tier":"exceeded","review":"","desc":"Ранма Саотоме — одарённый юный мастер боевых искусств. Во время тренировок в Китае он случайно угодил в проклятый источник: теперь от холодной воды парень превращается в рыжеволосую девушку, а от горячей снова становится собой. Ситуация усложняется, когда отец решает сосватать его за вспыльчивую Аканэ Тэндо.","poster":"https://image.tmdb.org/t/p/w500/1C4HtKv13BQnhofwnPZiyfti5aC.jpg","url":"https://www.themoviedb.org/tv/259140","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевые искусства","Комедия","Романтика","Сёнэн","Фэнтези"],"episodes":12,"kind":"tv","franchise":"ranma"},{"title":"Ранма 1/2 (2024) 2 сезон","rating":20,"tier":"exceeded","review":"","desc":"Второй сезон ремейка приключений Ранмы и Аканэ от студии MAPPA. Новые противники, ещё больше хаоса, битв боевых искусств и курьёзных романтических ситуаций с участием Шампу, Рёги и других колоритных персонажей.","poster":"https://image.tmdb.org/t/p/w500/sDtNyuelzLQCQTlTd3kppvWg5P6.jpg","url":"https://shikimori.one/animes/60564-ranma-2024-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик"],"episodes":12,"kind":"tv","franchise":"ranma"},{"title":"Старик из деревни становится Святым мечом 2","rating":20,"tier":"exceeded","review":"","desc":"Второй сезон Katainaka no Ossan, Kensei ni Naru.","poster":"https://shikimori.io/system/mangas/original/145480.jpg?1712757504","url":"https://shikimori.one/animes/61897-katainaka-no-ossan-kensei-ni-naru-ii","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"],"episodes":12,"kind":"tv","franchise":"kenja_ojisan"},{"title":"Реинкарнация безработного: История о приключениях в другом мире 3","rating":50,"tier":"exceeded","review":"","desc":"После трагических событий в Лабиринте Телепортации Рудеус возвращается домой в Шарию, где обретает покой семейной жизни рядом с Сильфиеттой и Рокси. Рокси устраивается преподавателем в магическую академию Раноа, а Рудеус занимается обустройством быта и уходом за своей матерью Зенит и сёстрами Норн и Айшей. Параллельно с этим Эрис, намереваясь стать сильнее, проходит изнурительные тренировки под началом Бога Меча Галла Фариона.\n\nОднако мирный период в Шарии оказывается лишь недолгим затишьем, когда перед Рудеусом открываются двери парящей крепости Бронированного Короля Драконов Пергиуса Долы. Визит к легендарному владыке небес оборачивается цепочкой непредсказуемых событий, и чтобы защитить свой дом, герою вновь предстоит пройти через суровые испытания.","poster":"https://image.tmdb.org/t/p/w500/tn2mxPYSSUPHgfcAe5SCga1DO0i.jpg","url":"https://shikimori.one/animes/59193-mushoku-tensei-iii-isekai-ittara-honki-dasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Исекай","Фэнтези","Приключения","Драма","Магия"],"episodes":14,"kind":"tv","franchise":"mushoku_tensei"},{"title":"Страна чудес смертников","rating":null,"tier":"unrated","review":"","desc":"Ещё до начала этой истории огромное землетрясение опустошило большую часть японских земель и практически уничтожило Токио, погрузив три четверти города под воду.   \n   История переносит нас на 10 лет вперёд к Игараши Ганте (五十嵐 丸太), казалось бы обычному скромному мальчику, учащемуся в средней школе префектуры Нагано. Выживший в том ужасном землетрясении, он ничего не помнит о трагедии и живёт нормальной спокойной жизнью.   \n   Но всё меняется в тот день, когда какой-то человек, весь в крови, влетает в класс Ганты через окно. С безумной ухмылкой Красный Человек вырезает весь класс, но вместо того, чтобы убить и Ганту, тот внедряет ему в грудь красный осколок кристалла.   \n   Спустя несколько дней после резни, Ганта оказывается единственным подозреваемым. И после подозрительно быстрого суда его приговаривают к пожизненному заключению в \"Стране чудес смертников\" (\"Deadman Wonderland\"), частной тюрьме, похожей на парк развлечений.","poster":"https://shikimori.io/system/animes/original/6880.jpg?1711947382","url":"https://shikimori.one/animes/6880-deadman-wonderland","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Боевик","Ужасы","Фантастика","Сверхъестественное"],"episodes":12,"kind":"tv","franchise":null},{"title":"Магическая академия Атараксия: Гибрид x Сердце","rating":null,"tier":"unrated","review":"","desc":"Кизуна Хида вступает в стратегическую академию обороны Атараксия по просьбе своей сестры. Ученики этой академии обладают некой магической силой. Там Кизуна сталкивается с Айнэ Чидоригафучи — девушкой, пилотирующей магическую броню «Зерос». Эта броня работает за счёт магических способностей её пилота и приводится в действие при помощи «сердца гибридного привода». Вдруг, ни с того ни с сего, Айнэ начинает раздеваться прямо на глазах у Кизуны... Позже он узнаёт от своей сестры, что обладает силой, способной усиливать способности девушек посредством непристойных действий. И только от его силы зависит исход битвы против другого мира.","poster":"https://shikimori.io/system/animes/original/31845.jpg?1711963060","url":"https://shikimori.one/animes/31845-masou-gakuen-hxh","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Фэнтези","Романтика","Фантастика","Этти","Гарем","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Какой сейчас Тамон?!","rating":null,"tier":"unrated","review":"","desc":"Старшеклассница Утагэ Киносита живёт мыслями о любимом айдоле. Кажется, только вчера Тамон Фукухара проходил прослушивания, и вот два года спустя он звезда популярной айдол-группы F/ACЕ, оккупировавшей все экраны страны.    \n   Однажды Утагэ, которая подрабатывает уборкой квартир, пришлось выйти на замену заболевшего коллеги. По иронии судьбы, её новым клиентом оказался тот самый Тамон.... или его вторая версия. Депрессивная, унылая, тревожная и совсем не похожая на того игривого и заводного певца, которому Утагэ поклоняется уже не первый год. Преданную фанатку такой образ не смутил — теперь на ней миссия не дать Тамону оплошать перед другими поклонницами.","poster":"https://shikimori.io/system/animes/original/59047.jpg?1718129732","url":"https://shikimori.one/animes/59047-tamon-kun-ima-docchi","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Да, я Сакамото, а что?","rating":null,"tier":"unrated","review":"","desc":"Школьник-первогодка Сакамото круче, чем все варёные яйца мира! В первый же учебный день он привлекает массу внимания. Девушки его обожают, парни негодуют. Даже парень-модель оказывается в его тени. Какие фокусы ни старалась бы провернуть мужская часть школьников, главный герой всегда изящен и блистателен. Сакамото может казаться гордым одиночкой, но он не отказывает в помощи, в том числе одному пареньку, которого вечно задирают. С какими препятствиями ни сталкивался бы красавец, он преодолевает их с уверенностью и достоинством.","poster":"https://shikimori.io/system/animes/original/32542.jpg?1711971689","url":"https://shikimori.one/animes/z32542-sakamoto-desu-ga","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Ярость Бахамута: Друзья из Манарии","rating":null,"tier":"unrated","review":"","desc":"Когда-то люди, боги и демоны объединились, чтобы противостоять древнему пробудившемуся злу — чудовищу Бахамуту. С той поры прошло немало времени. О тех невероятных событиях начали слагать легенды.   \n   Сегодня представители раньше враждующих рас вместе обучаются в Академии Мистерия. Здесь каждого ученика обучат магии без какой-либо дискриминации. В этом учебном заведении волею судьбы встретились Энн, прилежная и талантливая ученица, и Грея, дочь человека и дракона. Какие же приключения выпадут на долю этих девушек?","poster":"https://shikimori.io/system/animes/original/31537.jpg?1711962739","url":"https://shikimori.one/animes/z31537-manaria-friends","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Школа"],"episodes":10,"kind":"tv","franchise":null},{"title":"Клубничный зефир","rating":null,"tier":"unrated","review":"","desc":"Милые девочки делают милые вещи милыми способами. Нет, это не то, о чём многие подумали — перед нами комедия о повседневности, о вещах, которые составляют ткань нашей жизни. Будь то походы в школу с друзьями, подработка, весёлые праздники или простая готовка обеда. И всё это с милой примесью абсурда!   \n   Кто же наши герои? ] Миу , любящая шутить, что называется, «на грани»; жертва большинства её атак наивная Мацури ; серьёзная и добросовестная Тика  и странная иностранка Ана , которая почти уже не иностранка. Приглядывает за этой компанией старшая сестра Тики, двадцатилетняя Нобуэ . Впрочем, приглядывает — это громко сказано, иногда наоборот, девочки приглядывают за Нобуэ.    \n   Дружная компания веселится как может, всякий раз отыскивая в повседневной рутине повод для радости!","poster":"https://shikimori.io/system/animes/original/488.jpg?1711954722","url":"https://shikimori.one/animes/z488-ichigo-mashimaro","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия","Школа","Повседневность"],"episodes":12,"kind":"tv","franchise":null},{"title":"Истинная грусть","rating":null,"tier":"unrated","review":"","desc":"Мима Киригоэ, участница поп-группы «CHAM!», решает бросить карьеру певицы, чтобы попробовать себя в качестве актрисы. Некоторые её фанаты недовольны этим решением — в особенности невменяемый и начавший преследовать девушку парень, который называет себя Мэмания. По мере продвижения Мимы в новой карьере близкие ей люди погибают от рук жестокого убийцы, и вскоре Мима постепенно теряет способность отличать реальность от вымысла...","poster":"https://shikimori.io/system/animes/original/437.jpg?1711968641","url":"https://shikimori.one/animes/437-perfect-blue","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Полнометражка","Безумие","Драма","Ужасы","Психология"],"episodes":1,"kind":"movie","franchise":null},{"title":"Прощай, Лара","rating":null,"tier":"unrated","review":"","desc":"С детства Лару манил мир за пределами моря. Пока её сёстры наслаждались безмятежной жизнью в океанских глубинах, она мечтала однажды ступить на берег и познакомиться с людьми, о которых знала лишь по рассказам. Эта мечта привела дочь морского владыки к ведьме Грейс, предложившей исполнить её желание. Лара влюбилась в человеческого принца и отправилась на поверхность, готовая пожертвовать всем. Но её надежды не сбываются, и заветное желание растворяется в морской пучине.   \n   Двести лет спустя судьба дарит девушке ещё один шанс. Очнувшись в современной Японии, она знакомится с бойкой, но замкнутой девушкой Мари Оцу, ставшей первым человеком, протянувшим ей руку помощи. Для принцессы-русалки этот мир предстаёт совершенно незнакомым. Ей предстоит привыкнуть к чуждой реальности, узнать людей, о которых она когда-то лишь мечтала, и понять, что значит жить среди них. На этом пути бывшую гостью из океанских глубин ждёт множество удивительных открытий.   \n   Однако последствия давней сделки никуда не исчезли. Теперь лишь настоящая любовь способна разрушить древнее проклятие и дать Ларе шанс изменить свою судьбу, которая когда-то казалась неизбежной.","poster":"https://shikimori.io/system/animes/original/58878.jpg?1716092174","url":"https://shikimori.one/animes/58878-sayonara-lara","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Романтика"],"episodes":12,"kind":"tv","franchise":null},{"title":"Управление воспоминаниями","rating":null,"tier":"unrated","review":"","desc":"Чтобы вернуться в прошлое, Гуань Чао Гуань изо всех сил пытается найти «горящий камень», способный активировать временную пушку, но случайно попадает в Бюро управления памятью. Только победив БАГ-существ на уровнях памяти, он сможет вернуться в реальность. Сумеет ли Гуань Чао с помощью таких администраторов, как Фантан и Байчжун, успешно справиться с этой задачей? Какие испытания ждут его на каждом уровне памяти...","poster":"https://shikimori.io/system/animes/original/50462.jpg?1716776825","url":"https://shikimori.one/animes/50462-jiyi-guanli-ju","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Детектив","Психология","Супергероика"],"episodes":1,"kind":"ona","franchise":null},{"title":"Один на один: Леди не играют в файтинги","rating":null,"tier":"unrated","review":"","desc":"Думаете, в престижных женских академиях бьются только за оценки? Как бы не так! Добро пожаловать в подпольный мир школьного киберспорта, где благородные девицы выясняют отношения в «Уличном бойце»!   \n   Ая Мицуки — девушка из простой семьи, которая обожает дешёвый рамэн и ничем не отличается от сверстниц. Мечтая стать утончённой аристократкой, она поступает в престижную и невероятно строгую женскую академию «Куроми». В стенах учебного заведения Ая быстро находит свой идеал — Мио Ёруэ, безупречную и элегантную «королеву» школы, которой все поклоняются. Однако иллюзия благородства рушится, когда девушка случайно заглядывает в пустующий кабинет и застаёт Мио за яростной игрой в хардкорный файтинг! В академии видеоигры под строжайшим запретом, но застигнутая врасплох Мио не пугается. Заметив, что новенькая отлично разбирается в игровом сленге, она немедленно вызывает её на виртуальную дуэль. Оказывается, Ая и сама с раннего детства была настоящей грозой виртуальных арен. Теперь благородным девицам придётся тайно делить один экран, прятаться от учителей и на геймпадах выяснять, чьё комбо лучше, ведь в пылу виртуального поединка светским манерам больше нет места!","poster":"https://shikimori.io/system/animes/original/46488.jpg?1714576535","url":"https://shikimori.one/animes/46488-tai-ari-deshita-ojousama-wa-kakutou-game-nante-shinai","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сэйнэн","Комедия","Сёдзё-ай","Игры","Школа"],"episodes":12,"kind":"tv","franchise":null},{"title":"Адский режим: Хардкорный геймер в другом мире 2","rating":10,"tier":"solid","review":"","desc":"Аллен был скромным офисным служащим, однако жизнь без хорошего образования, девушки и карьерных перспектив в современной Японии его тяготила. Единственное, в чём он нашёл утешение, — это компьютерные игры. Но он не простой любитель. Его страсть — это прохождение сложных и малоизвестных игр на максимальной скорости.        \n                \n        Однажды, устав от очередных скучных игр, которые он с лёгкостью проходил, он наткнулся на сайт, который предлагал доступ к «экстремальному режиму». Ему предоставили выбор, с какими способностями он окажется в новом игровом мире. И он по-геймерски выбрал самый хардкорный режим — класс крестьянин с новым типом способностей — Призыватель и со сложнейшей системой прокачки.        \n                \n        Теперь его главная цель — выжить в этом опасном мире, достичь невиданных высот и спасти своих близких от тяжёлой доли.","poster":"https://shikimori.io/system/mangas/original/134870.jpg?1712746271","url":"https://shikimori.one/animes/60460-hell-mode-yarikomizuki-no-gamer-wa-hai-settei-no-isekai-de-musou-suru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Исекай","Триллер","Школа"],"episodes":12,"kind":"tv","franchise":"hell_mode"},{"title":"Пока ты не умрёшь, я буду любить тебя","rating":null,"tier":"unrated","review":"","desc":"Объявление о гибели соседки по комнате Шины Тоцуки равнодушно констатируется в начале урока, и день продолжается как ни в чём не бывало. В сиротском приюте, где детей воспитывают как солдат, смерть — это не что-то новое. Страна охвачена войной, которая тянется уже многие годы и не знает конца. Положение столь плачевное, что даже дети-сироты вынуждены умирать на поле боя каждый день. В отличие от остальных, Шина не может смириться с творящимся вокруг ужасом и мечтает о скорейшем окончании боевых действий.   \n      \n   В ночь смерти своей соседки Шина встречает девушку, с ног до головы покрытую кровью, которая, несмотря на тяжёлое состояние, казалось, находится в приподнятом настроении. На следующий день эта девушка переводится в класс Шины в качестве новой ученицы и представляется как Мими Кагари. Личность Мими окутана тайной. По слухам, она является секретным оружием сиротского дома — девушкой не способной умереть. Назначенная новой сожительницей Шины, Мими надеется найти с ней общий язык и освоиться в непривычной школьной жизни.   \n      \n   Так начинается необычная дружба двух противоположностей, расцветающая на фоне охваченного огнём мира.","poster":"https://shikimori.io/system/mangas/original/115122.jpg?1712759203","url":"https://shikimori.one/animes/61126-kimi-ga-shinu-made-koi-wo-shitai","status":"planned","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Драма","Детектив","Ужасы","Школа"],"episodes":13,"kind":"tv","franchise":null},{"title":"Вуайеристы","rating":null,"tier":"unrated","review":"","desc":"Переехав в квартиру своей мечты, Пиппа и Томас замечают, что их окна выходят прямо на квартиру напротив, невольно приглашая их стать свидетелями изменчивых отношений привлекательной пары соседей. Но опрометчивая попытка анонимного вмешательства в чужую жизнь запускает цепь событий, неизбежно ведущих к катастрофе.","poster":"https://image.tmdb.org/t/p/w500/AfpVHF5JYeyKXSBzHgz6PwB5RgU.jpg","url":"https://www.themoviedb.org/movie/645710","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Драма","Комедия"]},{"title":"Жизнь за год","rating":null,"tier":"unrated","review":"","desc":"История 17-летнего Дэрина, который узнаёт, что его подруга смертельно больна. Он решает подарить девушке целую жизнь, уместив её в год, который ей остался.","poster":"https://image.tmdb.org/t/p/w500/q6ZdZVrYerWjOa1DASzCmcN9Lyg.jpg","url":"https://www.themoviedb.org/movie/447362","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Триллер"]},{"title":"Запрещённый приём","rating":null,"tier":"unrated","review":"","desc":"Действие развернется в 1950 году. Молодую девушку по настоянию ее злодейского отчима определяют в больницу для душевнобольных, где спустя пять дней главную героиню лоботомируют. Чтобы оградиться от боли, она выдумывает сказочный мир, где и начинает планировать свой побег — для этого ей нужно раздобыть пять предметов.","poster":"https://image.tmdb.org/t/p/w500/2euubYDsiT0qRs4vGPWq0jC27gC.jpg","url":"https://www.themoviedb.org/movie/23629","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Триллер"]},{"title":"Игра в имитацию","rating":null,"tier":"unrated","review":"","desc":"1941 год. Британская разведка безуспешно бьется над расшифровкой кода шифровальной машины «Энигма», разработанной немцами. Для достижения результатов наняты лучшие специалисты в области дешифровки, среди которых математик Алан Тьюринг — ученый блестящий, но не от мира сего. Добиться расположения коллег ему поможет Джоан Кларк (Кира Найтли) — единственная девушка, оказавшаяся в мужской команде, работающей над «Энигмой». Они с Аланом даже успеют обручиться, поскольку беспредельно уважают друг друга, но до свадьбы дело не дойдет. Тьюринг не хочет мучить девушку, поскольку не в силах пойти против своей природы: он гей, а геев в Великобритании преследовали по закону.","poster":"https://image.tmdb.org/t/p/w500/uJpPm9i2z9tckfxiKFGwGER3l3x.jpg","url":"https://www.themoviedb.org/movie/205596","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["История","Драма","Триллер","Военный"]},{"title":"Игры с огнём","rating":null,"tier":"unrated","review":"","desc":"Когда суровый начальник пожарной части Джейк Карсон и его элитная команда опытных пожарных спасают троих детей, оказавшихся на пути наступающего лесного пожара, они быстро понимают, что никакие тренировки не могли подготовить их к самой сложной работе — стать няньками. Не имея возможности найти родителей детей, они сталкиваются с тем, что их жизни, работа и родное пожарное депо стремительно переворачиваются с ног на голову, ведь дети — как и пожары — дикие и непредсказуемые.","poster":"https://image.tmdb.org/t/p/w500/aXUwwT1hgVnLxlk0odOwlhNfvVj.jpg","url":"https://www.themoviedb.org/movie/554241","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Комедия","Драма"]},{"title":"Малефисента","rating":null,"tier":"unrated","review":"","desc":"Юная волшебница Малефисента вела уединенную жизнь в зачарованном лесу, окруженная сказочными существами, но однажды все изменилось... В её мир вторглись люди, которые принесли с собой разрушение и хаос, и Малефисенте пришлось встать на защиту своих подданных, призвав на помощь могущественные тёмные силы. В пылу борьбы Малефисента наложила страшное заклятие на новорожденную дочь короля, прекрасную Аврору. Но, наблюдая за тем, как растет маленькая принцесса, Малефисента начинает сомневаться в правильности своего поступка - ведь, возможно, именно Аврора может вдохнуть новую жизнь в волшебное лесное царство.","poster":"https://image.tmdb.org/t/p/w500/jbfXlNA5uTL6eVuHCEOtFiPTauf.jpg","url":"https://www.themoviedb.org/movie/102651","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Боевик","Семейный","Романтика"]},{"title":"Малефисента: Владычица тьмы","rating":null,"tier":"unrated","review":"","desc":"Действие происходит через несколько лет после того, как Малефисента наложила злые чары на принцессу Аврору. Фильм рассказывает про сложную взаимосвязь между тёмной феей и будущей королевой, о новых союзниках и противниках в деле защиты волшебного леса и магических существах, которые в нем обитают.","poster":"https://image.tmdb.org/t/p/w500/2X47NabGhQePjFcd1em2uyUp090.jpg","url":"https://www.themoviedb.org/movie/420809","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Фэнтези","Приключения"]},{"title":"Мальчик в девочке","rating":null,"tier":"unrated","review":"","desc":"Романтическая комедия, повествующая о двух соседях, девушке и парне, которые являются абсолютными противоположностями по жизни. Кроме того, они являются заклятыми врагами. Однако все меняется, когда однажды утром они обмениваются телами. Их реакция достаточно неожиданна, поначалу они пытаются нанести вред репутации своему новому образу, но наступает момент, когда заключив сделку между собой, они достигают небывалого успеха.","poster":"https://image.tmdb.org/t/p/w500/w7F8O8kA5QYmLbrEOVVGrsgvJvY.jpg","url":"https://www.themoviedb.org/movie/37725","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Романтика"]},{"title":"Миллион для чайников","rating":null,"tier":"unrated","review":"","desc":"В центре рассказа будет разведенная пара, которая крадет латунный чайник, который не владеет всеми свойствами лампы джинна, но если кто-то неподалеку ощущает невыносимую боль, он сразу выдает наличку.","poster":"https://image.tmdb.org/t/p/w500/6txTmb8OIimrQezgD8ERMmrrbnT.jpg","url":"https://www.themoviedb.org/movie/127867","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Триллер"]},{"title":"Не смотрите наверх","rating":null,"tier":"unrated","review":"","desc":"Два астронома отравляются в пресс-тур, чтобы предупредить человечество о приближающейся комете, которая скоро уничтожит Землю. А человечество в ответ: «Ну и что?»","poster":"https://image.tmdb.org/t/p/w500/nLWRxZYkUVM3gQNyF70jFMvImG3.jpg","url":"https://www.themoviedb.org/movie/646380","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фантастика","Драма"]},{"title":"Паранойя","rating":null,"tier":"unrated","review":"","desc":"Адам Кэссиди - типичный «белый воротничок», пытающийся преуспеть на должности молодого специалиста в крупной телекоммуникационной корпорации. После одной весьма дорогостоящей ошибки он сталкивается лицом к лицу с безжалостным президентом компании, который соглашается не увольнять провинившегося при одном условии: Адам должен шпионить за старым наставником своего босса...","poster":"https://image.tmdb.org/t/p/w500/736ybhy95v8brVnVQT608F8glmp.jpg","url":"https://www.themoviedb.org/movie/115348","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Пророк","rating":null,"tier":"unrated","review":"","desc":"Маркус с ранних лет отличается от других людей. И это очень беспокоит его родителей. У него есть особенный дар - он предвидит разные события, однако не может ничего сделать, чтобы их предотвратить. Он уже знает, что его младший брат трагически погибнет. Он очень его любит и всячески старается защитить. Поэтому Маркуса всегда мучает совесть. Тогда он вместе с родителями решает, что ему необходимо уехать жить к сестре. Приехав в большой город Маркус сразу знакомится с Сонией, красивой и порядочной девушкой, которая работает на фабрике стекла. Маркус сразу понимает, что Сония - женщина всей его жизни. Однако эта девушка является невестой его двоюродного брата Камилу...","poster":"https://image.tmdb.org/t/p/w500/93auY1VSO6nmOwRD2kAtFYZHp47.jpg","url":"https://www.themoviedb.org/tv/46125","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мыльная опера","Драма","Триллер"]},{"title":"Экстремальная робота","rating":null,"tier":"unrated","review":"","desc":"У детективов из отдела по борьбе с наркотиками никак не получается ловить подозреваемых, зато прекрасно выходит устраивать автоаварии и получать нагоняи от начальства. Коллега из другой группы хоть и младше их капитана, а уже получил повышение. Однажды тот даёт этим неудачникам наводку, и вот уже наши герои целую неделю ведут наблюдение за бандой наркоторговцев, сидя в пустом кафе напротив. Когда выясняется, что преступники часто заказывают здесь доставку еды, копы выкупают помещение и начинают там работать под прикрытием. Внезапно их жареная курица становится невероятно популярной, заведение раскручивается, назревает конфликт между долгом и неожиданно найденным призванием.","poster":"https://image.tmdb.org/t/p/w500/20tJSVKLhhoTcCI4iLFTcax8KT6.jpg","url":"https://www.themoviedb.org/movie/567646","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Криминал"]},{"title":"Всегда говори да","rating":100,"tier":"masterpiece","review":"","desc":"Депрессивный главный герой всегда и всем говорил «нет» - например, друзьям, если они зовут куда-то. Но в один прекрасный день он заключает соглашение, по которому всегда должен отвечать «Да» на любое предложение...","poster":"https://image.tmdb.org/t/p/w500/oIkuOFFs6MIdPcIbLLefwFtq9yD.jpg","url":"https://www.themoviedb.org/movie/10201","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Ты водишь!","rating":100,"tier":"masterpiece","review":"","desc":"Каждый год в течение месяца пять друзей участвуют в беспощадно-навороченной версии игры в «кошки-мышки». Они играют в нее с первого класса, чтобы, рискуя собственной шеей, работой и отношениями, одолеть противника с победоносным криком: «Ты водишь!» В этом году «кошки-мышки» приходятся на свадьбу единственного непобежденного игрока, что вроде как должно сделать из него легкую мишень. Но он знает, что они придут… и он готов.","poster":"https://image.tmdb.org/t/p/w500/4GTpZgK5ijNGzJSB6tXjz8Xz7t2.jpg","url":"https://www.themoviedb.org/movie/455980","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Боевик","Драма"]},{"title":"Шоу трумана","rating":100,"tier":"masterpiece","review":"","desc":"Представьте себе, что вы вдруг начинаете понимать, что всё вокруг вас - декорации, а люди - актёры, притворяющиеся теми, кем они вам кажутся. Весь ваш мир оказывается большим телесериалом, где вы исполняете главную роль, даже не подозревая об этом. Вся ваша жизнь - результат работы автора телешоу, которое вот уже тридцать лет смотрит вся планета, начиная с момента вашего рождения. В такой ситуации оказался Труман, главный герой картины. Будет ли он продолжать жить в безопасном мире, где, как он теперь знает, у него практически нет свободы выбора, или все-таки выйдет из «игры» и станет сам хозяином своей судьбы, в которой его ждет не запланированная сценарием девушка?","poster":"https://image.tmdb.org/t/p/w500/lYMMRbMZCyn12t6HLVYfmWfHrrq.jpg","url":"https://www.themoviedb.org/movie/37165","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"2+1","rating":15,"tier":"great","review":"","desc":"Жизнь Самуэля была легка и беззаботна на юге Франции, пока однажды одна из его бывших подружек не подкинула ему грудного ребёнка — его дочь Глорию, и не сбежала. Не сумев найти мать, Самуэль решает посвятить себя воспитанию девочки в Лондоне...","poster":"https://image.tmdb.org/t/p/w500/mTs8eI0lmJ6THUBWe9pizUb6iVV.jpg","url":"https://www.themoviedb.org/movie/382591","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Быстрее пули","rating":15,"tier":"great","review":"","desc":"Наёмник под кодовым именем Божья Коровка отправляется на новую миссию: вместо заболевшего коллеги он должен сесть в скоростной поезд Токио — Киото, выкрасть чемоданчик и сойти на промежуточной станции. Но выполнение простого задания сильно осложняется, когда выясняется, что состав просто кишит всевозможными киллерами.","poster":"https://image.tmdb.org/t/p/w500/oK3e4nDFB8lsT8H1D7bMHXoXsRH.jpg","url":"https://www.themoviedb.org/movie/718930","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Триллер"]},{"title":"Гран Туризмо","rating":15,"tier":"great","review":"","desc":"История об исполнении желаний подростка, игравшего в Gran Turismo, чьи игровые навыки позволили выиграть серию соревнований Nissan, чтобы стать настоящим профессиональным гонщиком. Основано на реальной истории.","poster":"https://image.tmdb.org/t/p/w500/zS3cofAvqaKAvdXCPrZjToI3N6H.jpg","url":"https://www.themoviedb.org/movie/980489","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Боевик"]},{"title":"Затерянный город","rating":15,"tier":"great","review":"","desc":"После смерти мужа-археолога Лоретта Сейдж спряталась от общества и стала писать довольно популярные любовно-приключенческие романы. События в них разворачиваются в экзотических местах, а спутником главной героини неизменно выступает красавец Дэш, которого на обложках книг воплощает модель Алан — мечта всего фандома. После презентации очередного бестселлера Лоретту внезапно похищает эксцентричный миллиардер, уверенный, что она сможет расшифровать древние надписи и привести его к сокровищам затерянного города из её последней книги. Алан случайно становится свидетелем похищения и, решив доказать, что может быть героем и в реальной жизни, вместе с ассистентками писательницы разрабатывает спасательную операцию и сам отправляется Лоретте на выручку.","poster":"https://image.tmdb.org/t/p/w500/evYb6mGNNU9rmtmSCworfxuGm8i.jpg","url":"https://www.themoviedb.org/movie/752623","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия"]},{"title":"Зелёная книга","rating":15,"tier":"great","review":"","desc":"В 1962 году Тони Лип, вышибала, был нанят в качестве водителя для пианиста Дона Ширли, чтобы сопровождать его в турне по южным штатам — в те времена, когда афроамериканцы полагались на путеводитель под названием «Зелёная книга негритянского автомобилиста».","poster":"https://image.tmdb.org/t/p/w500/fYch3e75YFnsJS9wAOOMlzErMqR.jpg","url":"https://www.themoviedb.org/movie/490132","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","История"]},{"title":"Зов предков","rating":15,"tier":"great","review":"","desc":"Серхат — успешный хирург, который много лет назад покинул отчий дом. Втайне от семьи он женился на любимой девушке Мелек и каждый день наслаждается своей счастливой семейной жизнью.    \n        \n    Однажды Серхату поступает звонок из Урфы и мужчина вынужден оставить работу и жену, и вернуться на родину. Приехав домой, он узнает, что многолетняя кровная вражда истощила его семью и остановить кровопролитие сможет лишь религиозный брак, который Серхат должен заключить с Йылдыз. Оказавшись в безвыходной ситуации, мужчина соглашается. Мелек, приехавшая к мужу узнает, что у него появилась вторая супруга, а тем временем сам Серхат погружается в мрачные тайны своей семьи и особняка, в котором он живет.","poster":"https://image.tmdb.org/t/p/w500/kpGNC7yOcHRUN7wQ40ePre9ZybH.jpg","url":"https://www.themoviedb.org/tv/298629","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Мулан","rating":15,"tier":"great","review":"","desc":"История о бесстрашной молодой девушке, которая выдаёт себя за мужчину, чтобы вступить в ряды армии, противостоящей Северным захватчикам, надвигающимся на Китай. Старшая дочь храброго воина Хуа, Мулан — энергичная и решительная девушка. Когда Император издаёт указ о том, что один мужчина из каждой семьи должен вступить в ряды Имперской армии, Мулан занимает место своего больного отца, еще не зная, что ей предстоит прославиться как одному из величайших воинов в истории Китая.","poster":"https://image.tmdb.org/t/p/w500/uxPauLtzjl9oWZtS1Bwp9mCDRFh.jpg","url":"https://www.themoviedb.org/movie/337401","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Драма","История"]},{"title":"Основатель","rating":15,"tier":"great","review":"","desc":"Рэй Крок - амбициозный коммивояжёр, который долго пытается найти идею, способную изменить его жизнь. Всё меняется, когда он знакомится с братьями Диком и Маком Макдональд, владельцами небольшой, но необычайно успешной закусочной в Калифорнии. Впечатлённый скоростью обслуживания и продуманной системой работы, Рэй видит в их бизнесе огромный потенциал. Он убеждает братьев расширять сеть ресторанов по всей стране и постепенно превращает небольшую семейную закусочную в крупнейшую сеть быстрого питания. Однако путь к успеху оказывается связан с жёсткой конкуренцией, конфликтами и непростыми решениями, которые навсегда меняют судьбу Макдональдса.","poster":"https://image.tmdb.org/t/p/w500/od99mPXwo4Qgptozx2KWj5Wn0ju.jpg","url":"https://www.themoviedb.org/movie/310307","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Триллер"]},{"title":"Подземелья и драконы: Честь среди воров","rating":15,"tier":"great","review":"","desc":"Эдгин Дарвис вместе с верной воительницей Хольгой объединяются с рассеянным магом Саймоном, ловкой друидкой Дорик и чопорным паладином Зенком, чтобы вернуть утерянную реликвию, наделенную огромной силой. Однако всё быстро идет наперекосяк, когда на их пути встает злодей Фордж.","poster":"https://image.tmdb.org/t/p/w500/nAbRIxxRJfCP2U9tpVJU1zWb6Ni.jpg","url":"https://www.themoviedb.org/movie/493529","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Комедия"]},{"title":"Родители в законе","rating":15,"tier":"great","review":"","desc":"Оуэн — простоватый банковский менеджер, который собирается жениться на любви всей своей жизни. Однажды его банк грабят неуловимые бандиты. Оуэн уверен, что эти самые грабители — родители его будущей жены, с которыми он только что познакомился.","poster":"https://image.tmdb.org/t/p/w500/dgHd4w25T0riMXqyVROSkzG3KhQ.jpg","url":"https://www.themoviedb.org/movie/921636","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Боевик","Комедия"]},{"title":"Снежная пятёрка","rating":15,"tier":"great","review":"","desc":"Приготовьтесь к бесконечному рискованному приключению пяти восхитительных говорящих щенков в ледяной стуже, которые принимают участие в захватывающей гонке по Аляске. Присоединяйтесь к друзьям — большому парню Бутузу, забияке Би-Догу, смелой Розабелле, сладкому Будде, грязнуле Замараше и их новому другу на Аляске, Шасте, и получите удовольствие в замечательном и смешном семейном фильме о силе команды и исполнении желаний.","poster":"https://image.tmdb.org/t/p/w500/uiyPb6jNQcLtu5Y8RoNuDtB8YiD.jpg","url":"https://www.themoviedb.org/movie/14059","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Приключения","Драма"]},{"title":"Странный: История Эла Янковича","rating":15,"tier":"great","review":"","desc":"С самого детства Альфред Янкович увлекался музыкой и обожал переделывать слова в песнях. Но строгий отец считал, что сын должен пойти работать на завод, а не заниматься всякой ерундой, и даже разбил втихаря подаренный Элу матерью аккордеон. Поступив в колледж, парень безуспешно пытается устроиться в какую-нибудь музыкальную группу, когда по совету друзей записывает пародию на «My Sharona» и отправляет кассету на радио. Его песня становится хитом.","poster":"https://image.tmdb.org/t/p/w500/5ZvYnEpORJlgmtb8b5NIjTYgSK9.jpg","url":"https://www.themoviedb.org/movie/928344","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Музыка","Комедия","Драма"]},{"title":"Турист","rating":15,"tier":"great","review":"","desc":"Американский турист Фрэнк приезжает в Италию, чтобы залечить душевную рану. В Венеции он знакомится с необычной женщиной по имени Элиза. Израненное сердце, похоже, готово сдаться новой возлюбленной. Однако планы Фрэнка и Элизы грубейшим образом нарушает водоворот интриг и опасностей.","poster":"https://image.tmdb.org/t/p/w500/r5HJSdkiwV5n5Ht9cm8EL8u21SQ.jpg","url":"https://www.themoviedb.org/movie/37710","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Романтика"]},{"title":"Джуманджи: Зов джунглей","rating":11,"tier":"great","review":"","desc":"На этот раз в полном опасностей и приключений мире Джуманджи оказываются четверо подростков. Их ждет схватка с носорогами, чёрными мамбами, а на каждом шагу будет подстерегать бесконечная череда ловушек и головоломок. Чтобы пройти игру и остаться в живых, им придётся перевоплотиться в персонажей игры: робкий и застенчивый Спенсер превращается в отважного и сильного исследователя, здоровяк Фридж – в заучку-коротышку, модница и красавица Беттани – в профессора, а неуклюжая и нескладная Марта становится бесстрашной и ловкой амазонкой. Друзьям придётся привыкнуть к совершенно новым и таким непривычным для себя ролям и найти дорогу домой.","poster":"https://image.tmdb.org/t/p/w500/8x54Dct05F1mIGKmmswasHFVumt.jpg","url":"https://www.themoviedb.org/movie/353486","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези"]},{"title":"Джуманджи: Новый уровень","rating":11,"tier":"great","review":"","desc":"Пытаясь спасти Спенсера, снова попавшего в игру, туда же отправляются и остальные. К их удивлению, правила Джуманджи изменились, и более того - на этот раз в игру затянуло дедулю Спенсера и его престарелого друга Майло. Чтобы выполнить задания и вернуться домой, друзьям предстоит отправиться в путешествие по ранее неизведанным и таинственным уголкам Джуманджи – от засушливой пустыни до заснеженных гор.","poster":"https://image.tmdb.org/t/p/w500/eEjh9ljWHGLg8jrvgzNJxRrqQVK.jpg","url":"https://www.themoviedb.org/movie/512200","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези"]},{"title":"Жизнь пи","rating":11,"tier":"great","review":"","desc":"Это история сына владельца одного индийского зоопарка, мальчика по имени Пи. Он познаёт мир, учится отстаивать свои принципы, ищет собственную дорогу к Богу, живя по канонам трёх конфессий, влюбляется… Но волей судьбы его семья вынуждена эмигрировать. На полпути между Индией и Канадой корабль терпит крушение, и Пи остаётся в шлюпке вместе с бенгальским тигром, гиеной, зеброй и орангутаном. Вокруг безбрежная водная гладь, а впереди — неизвестность…","poster":"https://image.tmdb.org/t/p/w500/sKfOdwKRDoVROHg9B7suyKM82I9.jpg","url":"https://www.themoviedb.org/movie/87827","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Триллер"]},{"title":"Незабываемое рождество","rating":10,"tier":"solid","review":"","desc":"Потеряв память в результате несчастного случая на горнолыжном курорте, избалованная наследница в Рождество оказывается в уютном доме неудачливого вдовца и его дочери.","poster":"https://image.tmdb.org/t/p/w500/z7NyO0G82hVq0UoW2ODGM5s3MOW.jpg","url":"https://www.themoviedb.org/movie/833097","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Комедия","Семейный"]},{"title":"100 вещей и ничего лишнего","rating":10,"tier":"solid","review":"","desc":"Лучшие друзья Пауль и Тони, находясь буквально в шаге от богатства, на спор отказываются от всего своего имущества, чтобы доказать — вещи не имеют на парней никакого влияния. Ставки высоки, а их пари оказывается под угрозой, когда на горизонте появляется симпатичная девушка, ведь сложно произвести впечатление, когда ты миллионер без штанов…","poster":"https://image.tmdb.org/t/p/w500/jr1n6v4dFFhxhHVGRJTHY2bvdKr.jpg","url":"https://www.themoviedb.org/movie/546630","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Аферистка","rating":10,"tier":"solid","review":"","desc":"Марла руководствуется принципом «побеждает сильнейший». Она искусно пользуется людьми, прикрываясь заботой о них, и наловчилась безнаказанно обдирать своих богатых клиентов за счет редкого обаяния и немалой доли цинизма. Но её новая подопечная не так проста, как кажется, и сладкая жизнь аферистки скоро превратится в игру на выживание.","poster":"https://image.tmdb.org/t/p/w500/aMHRjjaFmafke2eDyTDKifHeXJR.jpg","url":"https://www.themoviedb.org/movie/601666","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Триллер","Драма","Комедия"]},{"title":"В активном поиске","rating":10,"tier":"solid","review":"","desc":"В успешной жизни соучредителя крупного рекламного агентства Андрея есть всё: и квартира в центре города, и модные друзья, и большое будущее в рекламной сфере. Но однажды на пороге его дома появляется девятилетний ребёнок, утверждающий, что он его сын. Теперь Андрею предстоит нелёгкий путь: стать отцом, не отказываясь от карьеры, и, главное, найти мать ребёнка из десятков своих бывших возлюбленных.","poster":"https://image.tmdb.org/t/p/w500/7GhCTdlgYc37mjxpm2QR64EkASl.jpg","url":"https://www.themoviedb.org/tv/135027","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Гнев человеческий","rating":10,"tier":"solid","review":"","desc":"Грузовики лос-анджелесской инкассаторской компании Fortico Security часто подвергаются нападениям, и во время очередного ограбления погибают оба охранника. Через некоторое время в компанию устраивается крепкий немногословный британец Патрик Хилл. Он получает от босса прозвище Эйч и, впритык к необходимому минимуму пройдя тесты по фитнесу, стрельбе и вождению, отправляется на первое задание. Вскоре и его грузовик пытаются ограбить вооруженные налётчики, но Эйч в одиночку расправляется с целой бандой и становится героем. Кажется, слава и уважение коллег его совершенно не интересуют, ведь он преследует свои цели.","poster":"https://image.tmdb.org/t/p/w500/nRE9zOfzdp4uQMeDOgCvMf6izNh.jpg","url":"https://www.themoviedb.org/movie/637649","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Криминал","Драма"]},{"title":"Грань будущего","rating":10,"tier":"solid","review":"","desc":"В недалёком будущем раса инопланетян вторгается на Землю. Никакая армия в мире не может противостоять им. Майор Уильям Кейдж умирает в бою, но случается невозможное - он оказывается во времённой петле. Раз за разом он попадает в один и тот же бой, сражается и умирает... снова и снова. И каждое повторяющееся сражение приближает его к разгадке того, как победить врага.","poster":"https://image.tmdb.org/t/p/w500/98Ll6igWXdjHiKuZtCacTzRGyNX.jpg","url":"https://www.themoviedb.org/movie/137113","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Драма"]},{"title":"День *да*","rating":10,"tier":"solid","review":"","desc":"Молодые герои фильма сумели почувствовать и грозные отголоски войны, начавшейся в такой же день 29 лет назад, и свою ответственность за безмятежность мирных будней, и радость встречи с первым глубоким чувством, и необходимость всегда быть вместе, что бы ни случилось...","poster":"https://image.tmdb.org/t/p/w500/pEvAk4f7fZxdNe27vImbtw8SwTF.jpg","url":"https://www.themoviedb.org/movie/848412","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фильм","Триллер"]},{"title":"Достать ножи","rating":10,"tier":"solid","review":"","desc":"Сразу после празднования 85-летия, знаменитого автора детективов Харлана Тромби находят мёртвым в собственном особняке. Расследовать загадочную смерть берётся обаятельный и проницательный детектив Бенуа Блан. Ему предстоит распутать хитросплетения обмана, жадности и семейных тайн, окутавших этот дом, где каждый может оказаться подозреваемым, а правда — куда опаснее, чем кажется.","poster":"https://image.tmdb.org/t/p/w500/mGfb75tcFWxuT8esS1isHrNFE90.jpg","url":"https://www.themoviedb.org/movie/546554","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Детектив"]},{"title":"Миньоны: Грювитация","rating":10,"tier":"solid","review":"","desc":"Миллион лет миньоны искали самого великого и ужасного предводителя, пока не встретили Грю. Пусть он ещё очень молод, но у него в планах по-настоящему гадкие дела, которые заставят планету содрогнуться.","poster":"https://image.tmdb.org/t/p/w500/19GXuePqcZSPD5JgT9MeVdeu9Tc.jpg","url":"https://www.themoviedb.org/movie/438148","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Комедия","Криминал","Фантастика","Семейный"]},{"title":"Красное уведомление","rating":10,"tier":"solid","review":"","desc":"Действие фильма начинает своё развитие в тот момент, когда подходит к своему завершению выпущенное Интерполом «Красное уведомление». Оно предполагает высший ордер, требующий активизировать охоту и поимку самых разыскиваемых в мире людей.  В центре истории оказывается опытный сотрудник ФБР по имени Джон Хартли. За свою карьеру он провёл немало задержаний. И в этот раз ему кажется, что всё пройдёт гладко. Но Хартли ошибается.","poster":"https://image.tmdb.org/t/p/w500/u6m4JTp9ZEAF25mSo0xfStmXSHh.jpg","url":"https://www.themoviedb.org/movie/512195","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Криминал"]},{"title":"Мой шпион","rating":10,"tier":"solid","review":"","desc":"Самый суровый агент ЦРУ, выполняя сверхсекретное задание, случайно попадает на камеру 9-летней девчонки. Софи готова сохранить все в строжайшей тайне, если Джей-Джей научит её быть настоящей шпионкой.","poster":"https://image.tmdb.org/t/p/w500/g6g0bbJKQj2wUM6bOFJVoHW7o1V.jpg","url":"https://www.themoviedb.org/movie/592834","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Боевик","Комедия"]},{"title":"Области тьмы","rating":10,"tier":"solid","review":"","desc":"История о человеке, которому удается максимально раскрыть возможности своего мозга.","poster":"https://image.tmdb.org/t/p/w500/knbmiQHJd8eaadsuAKhXH5g0QPS.jpg","url":"https://www.themoviedb.org/tv/62687","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Боевик","Приключения"]},{"title":"Операция фортуна","rating":10,"tier":"solid","review":"","desc":"Суперагент британской разведки Орсон Форчун наслаждался заслуженным отпуском, когда родине срочно понадобились его услуги. Из секретной лаборатории похищено предположительно смертельное оружие, поэтому собрав команду из лучших оперативников, Орсон выходит на посредника в готовящейся сделке продажи — миллиардера и большого поклонника знаменитостей Грэга Симмондса. А чтобы подобраться к нему, в качестве прикрытия решает использовать известного голливудского актёра Дэнни Франческо.","poster":"https://image.tmdb.org/t/p/w500/59BOaiC3CAM6sXyKLlMpY1MU1ks.jpg","url":"https://www.themoviedb.org/movie/739405","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Триллер","Приключения"]},{"title":"Пока не сыграл в ящик","rating":10,"tier":"solid","review":"","desc":"Именно так решили два больных раком соседа по больничной палате, когда услышали свой приговор. Один из них вспыльчивый миллиардер, а второй эрудированный автомеханик. Они составляют список дел, которые необходимо сделать прежде, чем они сыграют в ящик, и отправляются в кругосветное путешествие, путешествие всей своей жизни. Прыжки с парашютом? Посмотрим. Гонки на раритетных автомобилях? Сделано. Посмотреть на пирамиды? Отлично. Открыть радость жизни прежде, чем станет слишком поздно? Точно!","poster":"https://image.tmdb.org/t/p/w500/wOgd3KgFq2ceo8hIgrxjiB8cVYz.jpg","url":"https://www.themoviedb.org/movie/7350","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Проект \"Адам\"","rating":10,"tier":"solid","review":"","desc":"12-летний Адам Рид все еще скорбит по своему отцу, который умер год назад. Однажды он заходит в свой гараж и обнаруживает там раненого пилота, который оказывается самим Адамом из будущего. Взрослый Адам рассказывает маленькому себе о том, что в будущем только-только появилась возможность путешествовать во времени и теперь он пытается вернуться в прошлое, чтобы спасти отца. Герои должны объединить усилия, чтобы выполнить непростую миссию и спасти свой мир.","poster":"https://image.tmdb.org/t/p/w500/2we1SegemOvGnJ27bhspny4kX04.jpg","url":"https://www.themoviedb.org/movie/696806","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фантастика","Комедия"]},{"title":"Робот по имени Чаппи","rating":10,"tier":"solid","review":"","desc":"В футуристическом обществе, где полиция из несокрушимых роботов держит преступность в узде, одинокий дроид переходит на новую ступень эволюции.","poster":"https://image.tmdb.org/t/p/w500/gEYz6t7RqsseZrJgjD0wR77p3T7.jpg","url":"https://www.themoviedb.org/movie/198184","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Боевик","Фантастика"]},{"title":"Соник","rating":10,"tier":"solid","review":"","desc":"Отвязный ярко-синий ежик Соник вместе со своим новообретенным лучшим другом-человеком Томом Вачовски знакомится со сложностями жизни на Земле и противостоит злодейскому доктору Роботнику (Джим Керри), который хочет пленить Соника и использовать его безграничную суперсилу для завоевания мира.","poster":"https://image.tmdb.org/t/p/w500/5VkEgD5YIJye87E1xX6NQ5BVaTc.jpg","url":"https://www.themoviedb.org/movie/454626","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Семейный","Фантастика"]},{"title":"Тим Талер, или Проданный смех","rating":10,"tier":"solid","review":"","desc":"Мальчик заключает сделку с чертом, продав ему свой смех. Но вскоре он понимает, что не все в мире продается...","poster":"https://image.tmdb.org/t/p/w500/ihpH1gxfnwC0NXDIO9rprazTFry.jpg","url":"https://www.themoviedb.org/movie/892832","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Фильм","Фэнтези"]},{"title":"Уйти красиво","rating":10,"tier":"solid","review":"","desc":"Старые друзья Вилли, Джо и Эла, несмотря на свой пенсионный возраст, впервые в жизни решают свернуть с праведного пути, чтобы сохранить свои пенсионные накопления.  Угнетенная оплатой счетов и потерей своих близких, пожилая троица решает рискнуть всем и намерена совершить ограбление банка, присвоившего их деньги.","poster":"https://image.tmdb.org/t/p/w500/qFqW8wX9r6UTnWZ2spIWroijRNM.jpg","url":"https://www.themoviedb.org/movie/353070","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Комедия","Драма"]},{"title":"Дедушка нелёгкого поведения","rating":9,"tier":"solid","review":"","desc":"История о своенравном мальчике Питере, вступающем в борьбу за своё личное пространство с овдовевшим дедушкой, который переселяется в его любимую комнату. Желая вытеснить деда, Питер разворачивает целую кампанию шалостей, но малоподвижный старик оказывается куда изобретательнее, чем можно было предположить.","poster":"https://image.tmdb.org/t/p/w500/3YZn8WIVUWvYXGjpW58Y77OSI9b.jpg","url":"https://www.themoviedb.org/movie/425001","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Семейный","Драма"]},{"title":"Кладбище домашних животных","rating":9,"tier":"solid","review":"","desc":"Доктор Луис Крид переезжает в маленький городок, где его семью ждет большой дом, а самого Луиса - скромная должность врача. Несчастье приходит в дом Кридов: кот Черч, домашний любимец, по нелепой случайности попадает под колеса грузовика. Гибель Черча повергает семью доктора в шок, и Луис решается на отчаянный шаг. Он хоронит кота на древнем индейском кладбище, обладающем по легенде таинственной воскрешающей силой. И однажды ночью погибший кот возвращается к хозяевам.","poster":"https://image.tmdb.org/t/p/w500/6Xa3dKMx5CmKcJjx0IHijEkKCxW.jpg","url":"https://www.themoviedb.org/movie/8913","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"Коп на драйве","rating":9,"tier":"solid","review":"","desc":"Молодой неуверенный в себе полицейский Райан в один прекрасный день узнаёт, что ему осталось жить ровно месяц. И Райан понимает, что это последний шанс изменить себя и сделать всё, о чём он мечтал. Но он ещё не знает, что диагноз был поставлен ошибочно…","poster":"https://image.tmdb.org/t/p/w500/ocgJV1vHluVSOLZFO3SAAFMpGZ3.jpg","url":"https://www.themoviedb.org/movie/613377","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Боевик","Драма"]},{"title":"Очень страшное кино","rating":9,"tier":"solid","review":"","desc":"На Тьюздей, младшую дочь Синди Кэмпбелл, нападает Призрачное Лицо. Старшая дочь Сара разыскивает ставшую отшельницей мать, и они пытаются остановить очередную волну убийств в Вудсвилле вместе с разросшимся семейством Бренды Микс.","poster":"https://image.tmdb.org/t/p/w500/w5rqOMj4J85Dee1tA3qNwhPuxKt.jpg","url":"https://www.themoviedb.org/movie/1273221","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Очень страшное кино 2","rating":9,"tier":"solid","review":"","desc":"Студентка Синди Кэмпбелл пытается оправиться от пережитых событий и поступает в колледж, надеясь начать спокойную жизнь. Однако вокруг неё снова начинают происходить странные и пугающие вещи: появляются зловещие видеозаписи, после просмотра которых люди умирают, а в доме её друзей будто обитает нечто потустороннее. Вместе с друзьями Синди пытается разобраться в происходящем.","poster":"https://image.tmdb.org/t/p/w500/rra2vGpmqa7MpJAiQwxI084noxz.jpg","url":"https://www.themoviedb.org/movie/4248","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Очень страшное кино 3","rating":9,"tier":"solid","review":"","desc":"Журналистка Синди Кэмпбелл охвачена желанием сделать скандальный репортаж о каком-нибудь мировом заговоре и открыть самые секретные материалы. Вскоре она становится свидетельницей необъяснимых явлений. На Землю вот-вот высадится десант зловещих инопланетян, на полях появились странные концентрические круги, некий Избранный пророчит нехорошее всему человечеству, дети со странными глазами пугают взрослых, под угрозой жизнь самого Президента.","poster":"https://image.tmdb.org/t/p/w500/viF6jgzIJyKRucdPOkdloK95ntj.jpg","url":"https://www.themoviedb.org/movie/4256","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Смурфики","rating":9,"tier":"solid","review":"","desc":"Спасаясь от злого волшебника Гаргамеля, крошечные смурфики оказываются за пределами родной деревни и через магический портал попадают прямиком в шумный Нью-Йорк, в самый центр Центрального парка.","poster":"https://image.tmdb.org/t/p/w500/2Fqo8sDLfNYv8ofqAXCo8AZYoSo.jpg","url":"https://www.themoviedb.org/movie/41513","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Комедия","Фэнтези","Приключения"]},{"title":"Тебе стоило уйти","rating":9,"tier":"solid","review":"","desc":"Тео Конрой - обеспеченный бывший банкир на пенсии, чей брак с намного более молодой женой-актрисой, Сюзанной, трещит по швам из-за его ревности и мрачных теней в его прошлом. Стремясь наладить отношения, Тео и Сюзанна отправляются вместе с шестилетней дочкой Эллой отдохнуть в съемном загородном доме в Уэльсе. Однако вскоре после приезда Тео начинает подозревать, что некая зловещая сила в доме знает их с Сюзанной секреты даже лучше, чем они сами знают друг друга.","poster":"https://image.tmdb.org/t/p/w500/4J9PACetIEY8KxJ9DXgLOhcAJvK.jpg","url":"https://www.themoviedb.org/movie/514593","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Драма"]},{"title":"Апгрейд","rating":8,"tier":"good","review":"","desc":"2046 год. Разнообразные технологии участвуют во всех аспектах человеческой жизни. Но в этом технологичном мире Грей — один из немногих людей, кто любит работать руками. Он восстанавливает и чинит старые автомобили. Однажды, возвращаясь от клиента, Грей с женой попадают в аварию, а после — в руки банды отморозков, в результате чего женщина погибает, а Грей оказывается парализованным ниже шеи. Тот самый богатый клиент предлагает несчастному поставить экспериментальный имплант Stem, который может полностью восстановить подвижность.","poster":"https://image.tmdb.org/t/p/w500/9A14EDBFTP1xlG7poolUcSWhXtW.jpg","url":"https://www.themoviedb.org/movie/500664","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Фантастика"]},{"title":"Измеряя мир","rating":8,"tier":"good","review":"","desc":"Аристократу Александру фон Гумбольдту было с рождения предначертано наслаждаться жизнью в родовом замке, выезжать на светские рауты и охоту, а по выходным посещать церковь. Но он с детства мечтал о путешествиях.Сыну бедняков Карлу Гауссу было с рождения предначертано повторить нелёгкую судьбу родителей. Но школьный учитель распознал его гений и выхлопотал стипендию для учебы в гимназии. Александр Фон Гумбольдт путешествовал всю свою жизнь, постигая мир через собственный опыт и наблюдения — и мир приобрел учёного-энциклопедиста и основателя множества областей науки. Карл Гаусс всю жизнь прожил в Брауншвайге и Гёттингене, что не помешало ему изобрести теорию чисел и стать одним из величайших математиков всех времен. В 1828 году два исследователя и покорителя мира встретятся на Первом Всемирном конгрессе в Берлине…","poster":"https://image.tmdb.org/t/p/w500/cfpyj2VIszSfogh3SGTJ8nnxxPx.jpg","url":"https://www.themoviedb.org/movie/115023","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Логово зверя","rating":8,"tier":"good","review":"","desc":"Замкнутый подросток воодушевляется знакомством со своим новым соседом, и уже вместе парочка начинает исследовать дом с привидениями, который его семья накануне купила по неведению.","poster":"https://image.tmdb.org/t/p/w500/pVJRBVhWlUt9ZYkPojPXO009GAS.jpg","url":"https://www.themoviedb.org/movie/146243","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"М3ГАН","rating":8,"tier":"good","review":"Хоррор-триллер про куклу-андроида с искусственным интеллектом.","desc":"Джемма — блестящий робототехник в компании по производству игрушек, разрабатывает M3GAN: уникальную реалистичную куклу с искусственным интеллектом, запрограммированную стать идеальным компаньоном для ребёнка. Когда Джемма внезапно становится опекуном своей осиротевшей 8-летней племянницы Кэди, она решает протестировать прототип M3GAN на девочке. Однако защитные алгоритмы куклы стремительно эволюционируют в пугающую и смертоносную сторону, уничтожая любую потенциальную угрозу для своей юной хозяйки.","poster":"https://image.tmdb.org/t/p/w500/d9nBoowhjiiYc4FBNtQkPY7c11H.jpg","url":"https://www.themoviedb.org/movie/536554-m3gan","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Фантастика","Триллер"]},{"title":"Мой домашний крокодил","rating":8,"tier":"good","review":"","desc":"Семья Примм переезжает в Нью-Йорк, где выясняется, что в их доме на чердаке живёт поющий крокодил Лайл. Лайл помогает адаптироваться после переезда маленькому Джошу Примму. Но злобный сосед мистер Грампс хочет, чтобы зверя изолировали от людей.","poster":"https://image.tmdb.org/t/p/w500/7StJsS3WKzMRIvAmGg1iPski9mQ.jpg","url":"https://www.themoviedb.org/movie/830784","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Семейный","Музыка"]},{"title":"Неувольняемый","rating":8,"tier":"good","review":"","desc":"Венсан обожает свою непыльную работу. Однако грядет массовое сокращение госслужащих. Начальница Изабель всеми силами пытается найти причину для его увольнения, а он категорически отказывается уходить по собственному желанию. В ее власти командировать его в самые сложные и удаленные места службы: от африканской глуши и амазонских джунглей до Северного полюса. Кто победит в этой схватке не на жизнь, а на повышенную пенсию?","poster":"https://image.tmdb.org/t/p/w500/nSQRdqZ4fyy3Ll5OIPMsWZhTZba.jpg","url":"https://www.themoviedb.org/movie/745608","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Проклятие. Дом с прислугой","rating":8,"tier":"good","review":"","desc":"Джой устраивается горничной в семью Умы и Нираха. Её предупреждают, что нельзя вмешиваться в жизнь хозяев, но девушка начинает замечать странные вещи, и вскоре узнаёт, что до неё здесь работала другая горничная, которая умерла. Вот только её призрак всё ещё обитает в доме...","poster":"https://image.tmdb.org/t/p/w500/1Z2SwNd0NIcSUENOl2WKpFwPKkD.jpg","url":"https://www.themoviedb.org/movie/709717","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Детектив"]},{"title":"Тихое место","rating":8,"tier":"good","review":"","desc":"В мире, который захватили ужасные монстры, реагирующие на любой звук, семья с двумя детьми живёт на отдалённой ферме. Семейство разучило целый комплекс специальных жестов, которые помогают им общаться, не издавая ни единого звука. Кроме того, каждый из членов семьи должен очень тихо передвигаться, чтобы чудовища их не услышали. Однако дом, где живут дети, не может быть самым тихим местом на земле.","poster":"https://image.tmdb.org/t/p/w500/b6MMVZWO7LPITq9XS5a4R22CZjG.jpg","url":"https://www.themoviedb.org/movie/447332","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Фантастика"]},{"title":"Чародейка","rating":8,"tier":"good","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/vcpv514xHFlqaQF9hSfA12L1Gw7.jpg","url":"https://www.themoviedb.org/movie/613668","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Бесконечность","rating":7,"tier":"good","review":"","desc":"С самого детства Эван страдает от странных видений и реалистичных снов, знает вещи, которые никогда не запоминал, и имеет непонятно откуда взявшиеся навыки. С диагнозом «шизофрения» он влачит жалкое существование и зависит от таблеток. Пытаясь раздобыть очередную партию, Эван вздорит с дилером, устраивает заварушку и попадает в полицию. А там на него выходит загадочный мужчина, который утверждает, что знает его очень давно — ещё со Второй Пунической войны.","poster":"https://image.tmdb.org/t/p/w500/1h0XbvscYPOx2S1KksPI0JfP2Zu.jpg","url":"https://www.themoviedb.org/movie/581726","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Боевик","Приключения"]},{"title":"Правда или действие","rating":7,"tier":"good","review":"","desc":"Обычная игра «Правда или действие» превращается в жестокую гонку со смертью, когда к процессу подключается нечто сверхъестественное. Стоит кому-то из участников соврать или не выполнить положенное действие, его ждет жестокая расправа. Кто в итоге сможет выйти победителем в жестокой игре?","poster":"https://image.tmdb.org/t/p/w500/po4JZAYWs6VIejlSOxOehnUNRaI.jpg","url":"https://www.themoviedb.org/movie/460019","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Ужасы","Драма"]},{"title":"Страшная воля богов","rating":7,"tier":"good","review":"","desc":"Сун Такахата тяготится своей заурядной жизнью, пока однажды в его классе не начинают происходить странные вещи. Школьникам являются загадочные игрушки во главе с куклой Дарума — божеством, приносящим счастье. Загадочные посетители призывают ребят принять участие в играх, цена которым — жизнь. Они подбадривают сомневающихся, рисуя радужные перспективы. Однако в случае отказа от участия им грозит немедленная смерть…","poster":"https://image.tmdb.org/t/p/w500/7p7KF58yOKYKewCqAghbnmZ2pGT.jpg","url":"https://www.themoviedb.org/movie/241863","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Ужасы","Комедия"]},{"title":"Топор 2006","rating":6,"tier":"mediocre","review":"","desc":"Сибирский отшельник, чья жизнь была разрушена жерновами Великой Октябрьской революции, проводит 17 лет в добровольном изгнании. Узнав о нападении фашистской Германии на СССР, бывший казачий офицер, не задумываясь, устремляется на фронт, чтобы защитить родную землю.","poster":"https://image.tmdb.org/t/p/w500/g7mPlb1isRDz6figswyrs9pskWZ.jpg","url":"https://www.themoviedb.org/tv/79709","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Бегущий по лезвию 2049","rating":5,"tier":"mediocre","review":"","desc":"Содержимое тайной могилы вызывает интерес промышленного магната, а также офицера Кей из полиции Лос-Анджелеса, который отправляется на поиски пропавшей легенды.","poster":"https://image.tmdb.org/t/p/w500/fnIJeT9GZvscKm5PbmAvhTYDsLh.jpg","url":"https://www.themoviedb.org/movie/335984","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Драма","Триллер"]},{"title":"33","rating":null,"tier":"unrated","review":"","desc":"Трое детей семьи Бодлер — Вайолет, Клаус и Солнышко — после страшного пожара остаются сиротами и оказываются на попечении графа Олафа, который всеми силами хочет захватить наследство детей. Дети всячески пытаются объяснить всем вокруг, что граф Олаф не просто плохой опекун, но и ещё пытается убить их, чтобы разбогатеть; разумеется, никто детей не слушает. И только из-за непонимания взрослых сироты попадают в разные злоключения.","poster":"https://image.tmdb.org/t/p/w500/3qtRMIm1mQS2ThSksZ9kpWAXaZ2.jpg","url":"https://www.themoviedb.org/tv/65294","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Семейный","Комедия","Детектив"]},{"title":"14+","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/uoDhzJrcgHCJdgAf0ojT9yed82A.jpg","url":"https://www.themoviedb.org/tv/65752","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"3 идиота","rating":null,"tier":"unrated","review":"","desc":"Компания друзей отправляется в путешествие в поисках своего сокурсника, бесследно пропавшего прямо в день выпускного.","poster":"https://image.tmdb.org/t/p/w500/hZB9NvNLcxdmoiAh58ZfG8vdXjf.jpg","url":"https://www.themoviedb.org/movie/346034","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Комедия","Драма"]},{"title":"Аватар 2: Путь воды","rating":null,"tier":"unrated","review":"","desc":"Джейк становится предводителем народа на’ви и берёт на себя миссию по защите новых друзей от корыстных бизнесменов с Земли. Теперь ему есть за кого бороться - с Джейком его прекрасная возлюбленная Нейтири. Когда на Пандору возвращаются до зубов вооружённые земляне, Джейк готов дать им отпор.","poster":"https://image.tmdb.org/t/p/w500/yFNn7uWudLLWDJqfj3fwh5CcUdR.jpg","url":"https://www.themoviedb.org/movie/76600","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фантастика"]},{"title":"Анна","rating":null,"tier":"unrated","review":"","desc":"Отечественные учёные создали андроида-полицейского. Идеальная во всех отношениях капитан Анна Николаевна Королькевич отправляется служить в провинциальный город, чтобы увидеть реальную жизнь и стать похожей на человека. Коллеги думают, что Анна Николаевна - дочь замминистра, и ничто не предвещает беды, пока очеловечивание не заходит слишком далеко.","poster":"https://image.tmdb.org/t/p/w500/vXf9bN3ENUv88L5d8TLRvUmUerl.jpg","url":"https://www.themoviedb.org/tv/100913","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Фантастика","Фэнтези"]},{"title":"Аннигиляция","rating":null,"tier":"unrated","review":"","desc":"Биолог возглавляет опасную и секретную экспедицию в аномальную зону, в которой законы природы не действуют.","poster":"https://image.tmdb.org/t/p/w500/7VnihqNe4XZ48TTWUjf3JYAbRQm.jpg","url":"https://www.themoviedb.org/movie/300668","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Ужасы","Драма"]},{"title":"Арктические волки","rating":null,"tier":"unrated","review":"","desc":"Они берутся за задания, которые другим не под силу. Когда международный синдикат наемников похищает известного бизнесмена, единственным шансом на его спасение становится лихая команда «Авангард», не имеющая равных в мастерстве и дерзости.","poster":"https://image.tmdb.org/t/p/w500/rrHIr2HFbr3DPIwZHJUjEVxXEUQ.jpg","url":"https://www.themoviedb.org/movie/604822","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Криминал","Триллер"]},{"title":"Артемис Фаул","rating":null,"tier":"unrated","review":"","desc":"Укрытый от посторонних глаз, глубоко под поверхностью земной коры таится целый мир, населенный гномами, эльфами, пикси, лепреконами, брауни и другими волшебными существами. Они спрятались от людей и создали свою собственную весьма развитую цивилизацию. Их тайна так и оставалась бы нераскрытой, если бы не юный Артемис Фаул, прирождённый мошенник и единственный наследник древнего рода криминальных гениев. Он сумел не только найти доказательства существования подземного мира, но и придумал дерзкий план — ограбить его обитателей.","poster":"https://image.tmdb.org/t/p/w500/ft14a6KDnMRQsLoqpHCefStLcnG.jpg","url":"https://www.themoviedb.org/movie/475430","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Фантастика","Семейный"]},{"title":"Астерикс и Обеликс: Миссия Клеопатра","rating":null,"tier":"unrated","review":"","desc":"Клеопатра считает, что египетский народ ни в чём не уступает римлянам. Чтобы доказать это, она обещает Цезарю построить величайший дворец, равного которому не видел свет, всего за 3 месяца. Строительство она поручает довольно бестолковому зодчему Нумернобису, который, трезво оценив свои силы, направляется за помощью к друиду из галльской деревни.","poster":"https://image.tmdb.org/t/p/w500/9EhNmgN37wiqYoDKjHFzdSAkLoE.jpg","url":"https://www.themoviedb.org/movie/2899","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Фэнтези","Комедия","Приключения"]},{"title":"Банши Инишерина","rating":null,"tier":"unrated","review":"","desc":"Сюжет фильма развивается в 20-е годы 20-го века, во время Гражданской войны в Ирландии. Пара друзей, живущих на небольшом островке, неожиданно ссорятся и очень долго не могут вернуть былые отношения.","poster":"https://image.tmdb.org/t/p/w500/49rEsMRYaPVcKcRSOarhtXPBxC.jpg","url":"https://www.themoviedb.org/movie/674324","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Бегущий в лабиринте","rating":null,"tier":"unrated","review":"","desc":"Главный герой - подросток Томас, который просыпается в лифте, но ничего не помнит, кроме своего имени. Он оказывается среди 60 подростков, научившихся выживать в замкнутом пространстве. Раз в 30 дней прибывает новый мальчик. Группа ребят проживает в «Приюте» уже два года. Они кормятся тем, что удается вырастить на земле, и пытаются найти выход из лабиринта, окружающего их место жительства. Когда герои уже начинают терять надежду, появляется девочка в состоянии комы, но со странной запиской. Мир героев начинает меняться.","poster":"https://image.tmdb.org/t/p/w500/fvy2LrxQzSCpUuGaB9jK5z1NeA6.jpg","url":"https://www.themoviedb.org/movie/198663","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Детектив","Фантастика","Триллер"]},{"title":"Бегущий в лабиринте: Испытание огнём","rating":null,"tier":"unrated","review":"","desc":"Лабиринт пройден, но Томасу, Терезе, Минхо и прочим глэйдерам не приходится расслабляться. Таинственное руководство ПОРОКА — секретной организации, устроившей гонки на выживание — назначает ребятам новые, смертельно опасные испытания. На сей раз их ждет переход по раскаленной пустыне и встреча с жертвами неизлечимой болезни, которые отличаются буйным нравом и непредсказуемым поведением.","poster":"https://image.tmdb.org/t/p/w500/tA3uIM8dnZqwJnFyR9A7zLE5Wd1.jpg","url":"https://www.themoviedb.org/movie/294254","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Боевик","Триллер","Приключения"]},{"title":"Безбрачная неделя","rating":null,"tier":"unrated","review":"","desc":"Главный герой получает от своей супруги разрешение на свободные отношения с другими женщинами. Похожая ситуация возникает и в семье его лучшего друга. Когда жены героев также решают воспользоваться подобным «пропуском», история принимает новый оборот.","poster":"https://image.tmdb.org/t/p/w500/rWSuOiFhXr2phiQSV7sV1djysw4.jpg","url":"https://www.themoviedb.org/movie/48988","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Безумные преподы","rating":null,"tier":"unrated","review":"","desc":"Худшие учителя Франции отправляются в Англию для выполнения сверхсекретной миссии. Вместе с «Королем Болванов» Боулардом они должны будут парашютироваться в лучшую школу страны и применить свои знаменитые методики обучения к будущему.","poster":"https://image.tmdb.org/t/p/w500/2qW5bsYI2RjduaJhUz3U6extqNb.jpg","url":"https://www.themoviedb.org/movie/325844","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Бесстыжие","rating":null,"tier":"unrated","review":"","desc":"Фрэнк Галлагер — гордый отец-одиночка шестерых умных, трудолюбивых и независимых детей, которые без него, возможно, жили бы лучше. Когда Фрэнк не проводит время в баре, тратя те немногие деньги, которые у них есть, он лежит без сознания на полу. Но дети нашли способ вырасти, несмотря на него. Возможно, они не похожи на ни одну из известных вам семей, но они не извиняются за то, что они такие, какие есть.","poster":"https://image.tmdb.org/t/p/w500/ahhEWtnEnp8TgHAVzD19JGpbIbu.jpg","url":"https://www.themoviedb.org/tv/34307","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Бог грома","rating":null,"tier":"unrated","review":"","desc":"Повелевать стихией, обращать в пепел прикосновением и заставлять всё живое трепетать от страха — удел языческих богов. Но что произойдёт, когда планета столкнётся с одним из них во плоти? Ведь этот древний Бог всего лишь человек.","poster":"https://image.tmdb.org/t/p/w500/u4kLjFlOciZNWtct6BAipGeCxNK.jpg","url":"https://www.themoviedb.org/movie/489326","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Триллер"]},{"title":"Боги египта","rating":null,"tier":"unrated","review":"","desc":"Некогда мирное и процветающее египетское царство погружается в хаос: беспощадный бог тьмы Сет убивает своего брата Осириса и узурпирует трон. Вызов ему неожиданно бросает простой смертный, находчивый молодой вор. Чтобы вернуть к жизни свою прекрасную возлюбленную, ему приходится заручиться поддержкой могущественного и мстительного бога Гора. Лишь выдержав испытание на прочность и принеся в жертву все самое дорогое, им удастся противостоять Сету и его приспешникам в мире живых и мире мертвых.","poster":"https://image.tmdb.org/t/p/w500/jvapNRg9x98url58GlW0qD8pIvR.jpg","url":"https://www.themoviedb.org/movie/205584","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези"]},{"title":"Большие глаза","rating":null,"tier":"unrated","review":"","desc":"Фильм расскажет историю художницы Маргарет Кин, прославившуюся в 50-х своими картинами, изображающими большеглазых детей и ставшими одним из первых примеров успешного распространения искусства на массовом рынке. Драма покажет пробуждение самосознания художницы на фоне феминистского движения, что, в конечном счете, приведет ее к судебной тяжбе с мужем, который пытался заявить свои права на ее работы.","poster":"https://image.tmdb.org/t/p/w500/s7FzwS9Kj0DGZz4QGSiQUp03hRL.jpg","url":"https://www.themoviedb.org/movie/87093","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Большой босс","rating":null,"tier":"unrated","review":"","desc":"В центре сюжета бизнес-леди, промышленный магнат, очутившаяся в тюрьме, погорев на теневых сделках. Отсидев положенное, женщина мечтает искупить вину и сменить статус мошенницы на всеобщую любимицу, только не все жертвы ее махинаций готовы пересмотреть свое отношение к ней.","poster":"https://image.tmdb.org/t/p/w500/72EY3LcKo0CCajqiyW7DTr7tB4s.jpg","url":"https://www.themoviedb.org/movie/323676","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Большой куш","rating":null,"tier":"unrated","review":"","desc":"«Фрэнки Четыре Пальца» должен был переправить краденый алмаз из Англии в США своему боссу Эви, но, сделав ставку на подпольный боксёрский поединок, он попал в круговорот весьма нежелательных событий. Вокруг него и его груза разворачивается сложная интрига с участием множества колоритных персонажей лондонского дна - русского гангстера, троих незадачливых грабителей, хитрого боксёра и угрюмого громилы грозного мафиози. Каждый норовит в одиночку сорвать большой куш.","poster":"https://image.tmdb.org/t/p/w500/zuVpG27FbWqEZQxrtDcw4f3Sl1I.jpg","url":"https://www.themoviedb.org/movie/107","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Комедия","Драма"]},{"title":"Борьба со льдом","rating":null,"tier":"unrated","review":"","desc":"«Борьба со льдом» рассказывает об Эйнаре Миккельсене, в 1909 году отправившемся на поиски останков полярных исследователей, погибших в Гренландии. Пытаясь пройти в труднопроходимую часть острова, Миккельсен берёт с собой только одного помощника, молодого моряка Ивера Иверсена, — и вместе они пытаются выжить и вернуться домой.","poster":"https://image.tmdb.org/t/p/w500/44PkRxS314ExWTVrKaQ1KguD78i.jpg","url":"https://www.themoviedb.org/movie/836009","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Приключения","История"]},{"title":"Братья гримм","rating":null,"tier":"unrated","review":"","desc":"Давным-давно, жили-были два брата-авантюриста Уилл и Якоб Гримм, которые впоследствии стали знаменитыми сказочниками. Но до того они путешествовали по деревушкам, занимаясь собиранием фольклора и «прогоняя нечисть» за деньги… Приезжали в деревню, убеждали жителей, что на их мельнице поселилась ведьма, а потом — за вознаграждение — успешно «изгоняли» ее. В следующем селе это был тролль под мостом и так далее.","poster":"https://image.tmdb.org/t/p/w500/wTXjGcszlkACKEmiGw1WVKpqy2c.jpg","url":"https://www.themoviedb.org/movie/4442","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Боевик","Комедия","Триллер"]},{"title":"Бросок кобры","rating":null,"tier":"unrated","review":"","desc":"Базирующееся в Египте высокотехнологичное международное элитное подразделение G.I. Joe противостоит зловещей оружейной корпорации Кобра, возглавляемой беспринципным оружейным бароном, угрожающим погрузить мир в хаос.","poster":"https://image.tmdb.org/t/p/w500/odOCtZ4zEkiVySxFbUpa64Jls0P.jpg","url":"https://www.themoviedb.org/movie/14869","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Приключения","Фантастика"]},{"title":"Будка поцелуев","rating":null,"tier":"unrated","review":"","desc":"Старшеклассница Эль — общительная, милая, но еще не испытавшая прелести поцелуев девушка. Ной — старший брат ее лучшего друга — дерзкий и ветреный, разбивший не одно девичье сердце. Решив однажды поучаствовать в «Будке поцелуев» на осеннем карнавале, Эль даже представить не могла, что подарит свой первый поцелуй Ною, и её жизнь изменится до неузнаваемости","poster":"https://image.tmdb.org/t/p/w500/xfsYVJ436o32Q6Rs83EooQjrKQW.jpg","url":"https://www.themoviedb.org/movie/454983","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Комедия","Драма"]},{"title":"В конце туннеля","rating":null,"tier":"unrated","review":"","desc":"Банда грабителей пытается сорвать большой куш, построив подземный туннель под банком. Происходящее привлекает внимание Хоакина, парализованного человека в инвалидном кресле, проживающего в соседнем доме. Но он совсем не торопится разоблачать гангстеров, так как считает, что у него появился шанс.","poster":"https://image.tmdb.org/t/p/w500/j39YtwpvcCEbCO6lIv05w9DD5lv.jpg","url":"https://www.themoviedb.org/movie/394374","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Триллер","Драма"]},{"title":"В погоне за счастьем","rating":null,"tier":"unrated","review":"","desc":"Крис Гарднер — отец одиночка. Воспитывая пятилетнего сына, Крис изо всех сил старается сделать так, чтобы ребенок рос счастливым. Работая продавцом, он не может оплатить квартиру, и их выселяют.Оказавшись на улице, но не желая сдаваться, отец устраивается специалистом в брокерскую компанию. Только и там его доходы далеки от нормальных. Но Крис поклялся себе во чтобы то ни стало вырастить сына, и никакие трудности его не остановят.","poster":"https://image.tmdb.org/t/p/w500/lL0USBLkbymo7U3PwOlbV8ymPsI.jpg","url":"https://www.themoviedb.org/movie/1402","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Вабанк","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/dsPhkOpGbaO3AJkwSENuhY0217v.jpg","url":"https://www.themoviedb.org/movie/1025872","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Васаби","rating":null,"tier":"unrated","review":"","desc":"Юбер Фиорентини — французский полицейский, исполняя последнюю волю когда-то им любимой японской девушки, вынужден отправиться в далёкую Японию, где ему приходится встретиться со старым другом и дочерью, о существовании которой он даже не подозревал. А также получить наследство в 200 млн. долларов, и познакомиться с японской якудзой, охотящейся за заманчивой суммой...","poster":"https://image.tmdb.org/t/p/w500/vN6L3aoRdCi25FdF0wpZZdwJXK6.jpg","url":"https://www.themoviedb.org/movie/2110","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Боевик","Комедия"]},{"title":"Век адалин","rating":null,"tier":"unrated","review":"","desc":"По сюжету главная героиня родилась вместе с XX веком и живёт на свете уже сто лет, но при этом не стареет. Несмотря на свою долгую жизнь, Аделайн так и не смогла найти любимого человека. Однако наконец-то она встречает мужчину, ради которого сможет снова стать смертной и состариться вместе с ним.","poster":"https://image.tmdb.org/t/p/w500/eOWf8GmxjDX5vpPWHnrbQSXmv03.jpg","url":"https://www.themoviedb.org/movie/293863","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Фэнтези","Драма"]},{"title":"Взаперти","rating":null,"tier":"unrated","review":"","desc":"Случайные знакомые Кема и Макс посреди праздничного застолья уединяются в квартире, чтобы остаться в ней навсегда. Они ищут выход, но его нет, окна и двери ведут в новые лабиринты комнат, а вокруг — лишь замкнутое пространство. Кема и Макс видят жутких призраков детей, лишь со временем понимая, что эти сущности — такие же жертвы обстоятельств, как и они. Разгадывая тайны прошлого, они пытаются помочь пленникам, чтобы спастись самим.","poster":"https://image.tmdb.org/t/p/w500/ouBQfMvTf3pv6hwdYqB2OSuH7d.jpg","url":"https://www.themoviedb.org/movie/1178074","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Драма"]},{"title":"Взрослые игры","rating":null,"tier":"unrated","review":"","desc":"Бесстыжая и бесстрашная Эрика готова на любые выходки, лишь бы почувствовать настоящую взрослую жизнь. Для этого у Эрики есть две веселые подруги, одно необычное хобби и целая Калифорния. Далекие от невинности забавы меняются, когда отчим знакомит Эрику со своим сыном. Кажется, у этого неуклюжего и ранимого парня нет с девушкой ничего общего, однако вскоре он перевернет ее жизнь, и дерзкая инди-комедия обернется для героев криминальным роуд-муви по солнечным просторам долины Сан-Фернандо.","poster":"https://image.tmdb.org/t/p/w500/s0323JO1ln6jt33iMmAm9r0U8LD.jpg","url":"https://www.themoviedb.org/movie/421471","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Взрывная блондинка","rating":null,"tier":"unrated","review":"","desc":"Агент Лоррейн Бротон, бриллиант в короне Секретной разведывательной службы Её Величества, не просто мастер шпионажа: она бомбически сексуальна, взрывоопасна и использует весь арсенал своих уникальных умений во время невыполнимых миссий. В неспокойном Берлине, куда её направляют с заданием вернуть бесценное досье, она вынуждена объединиться с агентом под прикрытием, Дэвидом Персивалем. Вместе им предстоит проложить путь через тернии смертельных шпионских игр.","poster":"https://image.tmdb.org/t/p/w500/ch9WDg6zKs1qTNR7Spz4QC63eG3.jpg","url":"https://www.themoviedb.org/movie/341013","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Драма"]},{"title":"Виктория и абдул","rating":null,"tier":"unrated","review":"","desc":"Взойдя на престол в возрасте 18-ти лет, Виктория стала королевой Великобритании, Ирландии, а позже и императрицей Индии. Среди бесчисленных подданных короны был красавец Абдул Карим. Появившись, казалось бы, из ниоткуда, он превратился в очень влиятельного человека при дворе. Ему завидовали, против него плели интриги, а их отношения с королевой обсуждали не только в Англии, но и во всем мире.","poster":"https://image.tmdb.org/t/p/w500/fMeU2lT8IiX913XsmWmnezMDbmH.jpg","url":"https://www.themoviedb.org/movie/423899","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Триллер"]},{"title":"Виноваты звезды","rating":null,"tier":"unrated","review":"","desc":"Хэйзел больна раком. Несмотря на то, что болезнь временно отступила, девушка не чувствует ни капли радости. Она ходит в группу поддержки, где однажды знакомится с Августом Уотерсом и моментально влюбляется в него. Август и Хэйзел отправляются в полное страсти и жизни путешествие, которое лишний раз покажет им, что весь смысл жизни можно найти в любом ее отрезке.","poster":"https://image.tmdb.org/t/p/w500/Avyndi4kkJqorPVPKd9fRTNMWJ3.jpg","url":"https://www.themoviedb.org/movie/222935","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Драма","Триллер"]},{"title":"Виновный","rating":null,"tier":"unrated","review":"","desc":"Оператор службы 911 Джо Бэйлер принимает звонок от женщины, оказавшейся в смертельной опасности. Пытаясь спасти звонившую, герой понимает, что на самом деле всё не то, чем кажется, и выяснить правду — единственно верный выход из ситуации.","poster":"https://image.tmdb.org/t/p/w500/szSt5wkQ7wUSmpDE0SaSeeLtPQk.jpg","url":"https://www.themoviedb.org/movie/567748","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Влюблённый ван гог","rating":null,"tier":"unrated","review":"","desc":"«Подлинная любовь вселяет отвращение к искусству». Для Лео Мадзотти, чья карьера художника не складывается, эта фраза Ван Гога — отличный повод расстаться с влюбленной в него Элизой. Десять лет спустя в лучах мировой славы он возвращается во Францию с женой-миллионершей, хозяйкой модной нью-йоркской галереи. Накануне открытия персональной выставки он встречает свою бывшую возлюбленную и… Ван Гога. Легендарный художник сошел с автопортрета, чтобы жениться на Элизе, заняться воспитанием детей и больше никогда не заниматься живописью…","poster":"https://image.tmdb.org/t/p/w500/RXwlI8cVAPwYdZMyRqtuPO57vk.jpg","url":"https://www.themoviedb.org/movie/758345","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Фэнтези"]},{"title":"Во всё тяжкое","rating":null,"tier":"unrated","review":"","desc":"Профессор колледжа решает жить на полную катушку после того, как ему ставят серьезный диагноз. Отныне все запреты сняты, а тайные желания могут наконец осуществиться!","poster":"https://image.tmdb.org/t/p/w500/q09g1QTouHIWUZLa4tyXmNokRJF.jpg","url":"https://www.themoviedb.org/movie/467956","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Воздушный бой","rating":null,"tier":"unrated","review":"","desc":"1943 год, разгар Второй мировой войны. Девушка-офицер Мод Гэррет с секретным грузом садится в американский бомбардировщик B-17 «Летающая крепость» и сразу же становится объектом насмешек. Капитан приказывает ей занять место в кабине пулемётчика под брюхом самолета, откуда девушка замечает японский истребитель и странное существо на фюзеляже. Если сексистские комментарии команды она до поры до времени решает потерпеть, то хозяйничать в небе вражеским самолетам и небесным гоблинам позволять не намерена.","poster":"https://image.tmdb.org/t/p/w500/4ig8j3M3kLBimwsYEAgEFFdhcGo.jpg","url":"https://www.themoviedb.org/movie/675327","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Боевик","Военный"]},{"title":"Воздушный маршал","rating":null,"tier":"unrated","review":"","desc":"Межконтинентальный авиарейс. Билл Маркс, воздушный маршал, который обеспечивает безопасность пассажиров, получает сообщения с угрозами от маньяка-террориста. Преступник просчитал все ходы и подставил под обвинение самого спецагента. Теперь Маркс - цель спецслужб США. Ему остается одно: вычислить и обезвредить преступника, спасти пассажиров и свою любовь, которую он обретает на краю гибели. До взрыва остаются считанные минуты...","poster":"https://image.tmdb.org/t/p/w500/l2myfEVGQAAdbycx9QKjQEe7cl8.jpg","url":"https://www.themoviedb.org/movie/225574","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Детектив"]},{"title":"Волк с уолл стрит","rating":null,"tier":"unrated","review":"","desc":"1987 год. Джордан Белфорт становится брокером в успешном инвестиционном банке. Вскоре банк закрывается после внезапного обвала индекса Доу-Джонса. По совету жены Терезы Джордан устраивается в небольшое заведение, занимающееся мелкими акциями. Его настойчивый стиль общения с клиентами и врождённая харизма быстро даёт свои плоды. Он знакомится с соседом по дому Донни, торговцем, который сразу находит общий язык с Джорданом и решает открыть с ним собственную фирму. В качестве сотрудников они нанимают нескольких друзей Белфорта, его отца Макса и называют компанию «Стрэттон Оукмонт». В свободное от работы время Джордан прожигает жизнь: лавирует от одной вечеринки к другой, вступает в сексуальные отношения с проститутками, употребляет множество наркотических препаратов, в том числе кокаин и кваалюд. Однажды наступает момент, когда быстрым обогащением Белфорта начинает интересоваться агент ФБР...","poster":"https://image.tmdb.org/t/p/w500/ihlWMaVZVXFzxU5wwZnbHJZ7Zpx.jpg","url":"https://www.themoviedb.org/movie/106646","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Комедия"]},{"title":"Время","rating":null,"tier":"unrated","review":"","desc":"Добро пожаловать в мир, где время стало единственной и самой твердой валютой, где люди генетически запрограммированы так, что в 25 лет перестают стареть. Но последующие годы стоят денег. И вот богатые становятся практически бессмертными, а бедняки ведут отчаянную борьбу за каждую минуту жизни.","poster":"https://image.tmdb.org/t/p/w500/ip4GMRyHjDkfSt3PTp6rrTYSClK.jpg","url":"https://www.themoviedb.org/movie/49530","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Боевик","Триллер"]},{"title":"Все и сразу","rating":null,"tier":"unrated","review":"","desc":"Тима и Дэн — друзья-неудачники из провинциального городка. Учеба позади, работать не тянет, девушек нет. На пути к мечте (выбиться в люди) и в надежде получить всё и сразу (без особого напряга) парни берутся выполнить задание местного бандюка и отправляются на дело, прихватив с собой автослесаря Жору, такого же полного лузера.  На кону внушительная сумма, главное — не облажаться и чётко инсценировать ограбление своего же, подставного наркокурьера. Но вот засада: роль курьера случайно достаётся честному дембелю Ване, который оказывается не в курсе схем и обещаний. И теперь в водовороте погонь, потасовок и перестрелок всем четверым нужно по-настоящему напрячься, чтобы грамотно разрулить ситуацию. И получить ВСЁ и СРАЗУ.","poster":"https://image.tmdb.org/t/p/w500/hNsmPpl3zLG36jr4EIEd5P8I4pa.jpg","url":"https://www.themoviedb.org/movie/280422","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Комедия","Детектив"]},{"title":"Все или ничего","rating":null,"tier":"unrated","review":"","desc":"Офисный планктон — опасный зверь, если его разозлить. Трое менеджеров-неудачников объединяются в почти преступную группировку в попытке свергнуть обнаглевшего начальника, который безбожно обворовывает компанию. Друзья разрабатывают экстремальный план, как выкрасть 50 миллионов у босса и восстановить справедливость. Но как это бывает у новичков — всё идёт не по плану. Настоящим хозяином мешка с деньгами оказывается совсем не тот, на кого охотились герои — и вот тут у них начинаются реальные проблемы с криминальным миром.","poster":"https://image.tmdb.org/t/p/w500/d4ugTqPrYJ6RMTz3MzcMatTrofn.jpg","url":"https://www.themoviedb.org/movie/556488","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Драма"]},{"title":"Всем парням которых я раньше любила","rating":null,"tier":"unrated","review":"","desc":"Жизнь Лары выходит из-под контроля, когда внезапно секретные письма всем парням, которых она тайно любила, попадают к адресатам.","poster":"https://image.tmdb.org/t/p/w500/tnKAILJV1hXbBlwJnTqTM2fAeyO.jpg","url":"https://www.themoviedb.org/movie/466282","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Вчера","rating":null,"tier":"unrated","review":"","desc":"Неудачливый музыкант Джек после глобального сбоя электричества просыпается в мире, где никто никогда не слышал о группе The Beatles. Джек исполняет легендарные песни четверки и в одно мгновение становится мировой суперзвездой.","poster":"https://image.tmdb.org/t/p/w500/7cgXWyf4w3z5QuBNQKKAzF6QvZM.jpg","url":"https://www.themoviedb.org/movie/515195","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Мелодрама","Музыка","Фэнтези"]},{"title":"Геракл","rating":null,"tier":"unrated","review":"","desc":"Более тысячи лет назад измученная душа скиталась по Земле, полубог, получеловек - Геракл - могучий сын царя богов Зевса, совершив все 12 подвигов, потерял семью и теперь находит утешение только в кровавых битвах. За эти годы он собирает вокруг себя шестерых таких же потерянных воинов, единственным смыслом жизни для которых стали сражения и присутствие смертельной опасности. Эти мужчины и женщина никогда не задают вопрос, где, почему или с кем они идут сражаться; только, сколько им заплатят. Зная это, фракийский царь Котис нанимает этих воинов, чтобы они обучили его солдат и сделали из них самую сильную и великую армию всех времен.","poster":"https://image.tmdb.org/t/p/w500/xhkgpLTfFCup6nVmgQ76q0NsuHO.jpg","url":"https://www.themoviedb.org/movie/184315","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Драма"]},{"title":"Гладиатор","rating":null,"tier":"unrated","review":"","desc":"Римская империя. Бесстрашного и благородного генерала Максимуса боготворят солдаты, а старый император Марк Аврелий безгранично доверяет ему и относится как к сыну. Однако опытный воин, готовый сразиться с любым противником в честном бою, оказывается бессильным перед коварными придворными интригами. Коммод, сын Марка Аврелия, убивает отца, который планировал сделать преемником не его, а Максимуса, и захватывает власть. Решив избавиться от опасного соперника, который к тому же отказывается присягнуть ему на верность, Коммод отдаёт приказ убить Максимуса и всю его семью. Чудом выжив, но не сумев спасти близких, Максимус попадает в плен к работорговцу, который продаёт его организатору гладиаторских боёв Проксимо. Так легендарный полководец становится гладиатором. Но вскоре ему представится шанс встретиться со своим смертельным врагом лицом к лицу.","poster":"https://image.tmdb.org/t/p/w500/1wjNqlfsuHNTXTpCt2ZOV2iPxaf.jpg","url":"https://www.themoviedb.org/movie/98","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Драма","Приключения"]},{"title":"Гнев человеческий","rating":null,"tier":"unrated","review":"","desc":"Грузовики лос-анджелесской инкассаторской компании Fortico Security часто подвергаются нападениям, и во время очередного ограбления погибают оба охранника. Через некоторое время в компанию устраивается крепкий немногословный британец Патрик Хилл. Он получает от босса прозвище Эйч и, впритык к необходимому минимуму пройдя тесты по фитнесу, стрельбе и вождению, отправляется на первое задание. Вскоре и его грузовик пытаются ограбить вооруженные налётчики, но Эйч в одиночку расправляется с целой бандой и становится героем. Кажется, слава и уважение коллег его совершенно не интересуют, ведь он преследует свои цели.","poster":"https://image.tmdb.org/t/p/w500/nRE9zOfzdp4uQMeDOgCvMf6izNh.jpg","url":"https://www.themoviedb.org/movie/637649","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Криминал","Драма"]},{"title":"Голая правда","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/cXxh8emuJhYIDV82vXEZ2sC6lHX.jpg","url":"https://www.themoviedb.org/tv/11894","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Голос монстра","rating":null,"tier":"unrated","review":"","desc":"Тринадцатилетний мальчик по имени Конор вынужден принять известие о скорой смерти матери. Смириться с этим, пережить все ощущения и прийти к пониманию ему помогает монстр из его снов, старое тисовое дерево, превращающееся в чудовище, когда мальчику особенно плохо.","poster":"https://image.tmdb.org/t/p/w500/by4OCQevKa7zFjDiBlB4x35pjxM.jpg","url":"https://www.themoviedb.org/movie/258230","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Семейный"]},{"title":"Гонка","rating":null,"tier":"unrated","review":"","desc":"Реалити-шоу, в котором команды из двух человек, связанные между собой разными отношениями (сестры, братья, друзья, супруги и тд) путешествуют по всему миру, параллельно выполняя забавные, интересные и порой невероятно сложные задания. Каждая команда стремится первой прибыть на «пит-стоп» (конечная точка каждого этапа), чтобы выиграть призы и избежать последнего места, которое влечет за собой исключение из гонки или в некоторых случаях серьезные проблемы в следующем этапе.","poster":"https://image.tmdb.org/t/p/w500/x1jq0atcQg6UkaZpco0kFL6QHuM.jpg","url":"https://www.themoviedb.org/tv/30957","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Реалити-шоу","Драма","Триллер"]},{"title":"Гонка со временем","rating":null,"tier":"unrated","review":"","desc":"Эми Карр во время утренней пробежки узнает о том, что ее сын оказался в эпицентре стрельбы. На что готова мать ради спасения своего ребенка? В мире практически не осталось места для надежды. Помощи ждать тоже неоткуда, ведь даже власти бессильны, когда города один за другим объявляют об изоляции. Уютное местечко под названием Лейквуд превращается в отдельный, независимый мир — государство, отрезанное от страны. Именно здесь произойдет гонка со смертью и борьба со временем. Кто окажется победителем, когда на кону жизнь ребенка?","poster":"https://image.tmdb.org/t/p/w500/2TYW0pROl0fc3f8EXJhNfvNMQfq.jpg","url":"https://www.themoviedb.org/movie/764835","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Драма","Комедия"]},{"title":"Господин никто","rating":null,"tier":"unrated","review":"","desc":"Действие картины происходит в не слишком отдалённом будущем. Главный герой внезапно просыпается в 2092 году дряхлым стариком и понимает, что он является 120-летним последним смертным на планете, доживающим свой век среди счастливых бессмертных людей.","poster":"https://image.tmdb.org/t/p/w500/6j1TfRRDuoHFc36kx3vob1NxZmp.jpg","url":"https://www.themoviedb.org/movie/31011","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Драма","Романтика"]},{"title":"Гретель и ганзель","rating":null,"tier":"unrated","review":"","desc":"Гретель и её младший брат Гензель отправляются в глухой заколдованный лес в поисках пропитания и работы, где натыкаются на уединенную избушку приветливой на первый взгляд старухи, скрывающей жуткие тайны.","poster":"https://image.tmdb.org/t/p/w500/t2BrNHjmBwtmnzt0o1oSDNXCMuV.jpg","url":"https://www.themoviedb.org/movie/542224","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Фэнтези","Детектив","Триллер"]},{"title":"Дангал","rating":null,"tier":"unrated","review":"","desc":"Когда-то Махавир Сингх Пхогат был чемпионом Индии по борьбе. По причине бедности он был вынужден бросить спорт, но поклялся воспитать сына, который станет в будущем олимпийским чемпионом. Но вот досада — у них с женой родились четыре дочки. Отец сначала отчаялся, но потом, увидев, что подросшие девчонки поколачивают одноклассников, решил всё же сделать из них спортсменок.","poster":"https://image.tmdb.org/t/p/w500/s4CGpFZVAoCLjdyHGRNBa9t0Ulr.jpg","url":"https://www.themoviedb.org/movie/360814","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Семейный","Комедия"]},{"title":"Девушка из дании","rating":null,"tier":"unrated","review":"","desc":"Действие происходит в 1920-х годах в Копенгагене. Иллюстратор и художник Герда Вегенер просит своего мужа Эйнара Вегенера попозировать в качестве женской модели. Портреты приобретают популярность и Герда продолжает писать картины со своим мужем в качестве женщины. Эйнару нравится собственная женская внешность и он начинает жить под именем Лили Эльбе. Впоследствии Эльбе становится первым человеком, прошедшим хирургическую коррекцию пола.","poster":"https://image.tmdb.org/t/p/w500/i2Vg8IOKKM7OaJgwP3t4Q26Sy9j.jpg","url":"https://www.themoviedb.org/movie/306819","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Девять жизней","rating":null,"tier":"unrated","review":"","desc":"Маша Трофимова мечтала о спокойной счастливой жизни: поступить в институт и выйти замуж за любимого Сергея. Но чтобы спасти отца от тюрьмы, Маше пришлось связать свою жизнь с чудовищем. В обмен на свободу отца, мать Маши устраивает дочери свадьбу с Игнатом, суровым хромым мужчиной гораздо старше Маши. Через несколько лет Сергей возвращается, чтобы отомстить бывшей невесте. В одночасье Маша лишается всего — мужа, сына, дома, надежды. Ее разыскивает и полиция, и бандиты. Она оставляет маленького сына родителям и пускается в бега. На что способна женщина, загнанная в угол?","poster":"https://image.tmdb.org/t/p/w500/A2d4EoiiTQi7DuckR0CnmAS9qwn.jpg","url":"https://www.themoviedb.org/tv/98208","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Джаспер джонс","rating":null,"tier":"unrated","review":"","desc":"В фильме рассказывается история Чарльза Бактина, четырнадцатилетнего мальчика, который очень любит читать. Однажды ночью к нему за помощью обращается местный изгой-мулат, Джаспер Джонс, нашедший тело своей девушки, и жизнь Чарли меняется навсегда. Втайне от взрослых он пытается найти настоящего убийцу, попутно борясь с проявлениями расизма, переживая разлад в семье и первую любовь.","poster":"https://image.tmdb.org/t/p/w500/kB0fpfm0aArdBOdokVXUxS3rxtP.jpg","url":"https://www.themoviedb.org/movie/414027","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","Триллер"]},{"title":"Джентльмены","rating":null,"tier":"unrated","review":"","desc":"Эдди Хорниман неожиданно наследует огромное поместье от своего отца и вскоре узнаёт, что вместе с ним получил и целую подпольную империю по производству наркотиков. Пытаясь разобраться с семейным наследством, он сталкивается с криминальными группировками, хитрыми бизнесменами и опасными людьми, которые не собираются просто так отдавать ему контроль над прибыльным бизнесом. Постепенно Эдди втягивается в мир британской организованной преступности, где сделки, предательство, юмор и насилие идут рука об руку, а попытка избавиться от криминального наследства оказывается гораздо сложнее, чем он предполагал.","poster":"https://image.tmdb.org/t/p/w500/bpy9uaV0oOlKnEoPzodwrSSUFXg.jpg","url":"https://www.themoviedb.org/tv/236235","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Криминал"]},{"title":"Джой","rating":null,"tier":"unrated","review":"","desc":"История, основанная на непростой жизни матери-одиночки в Лонг-Айленде, которая стала одним из самых успешных предпринимателей страны.","poster":"https://image.tmdb.org/t/p/w500/5oCuWnS1rTlPahiUrNRw19HCb2s.jpg","url":"https://www.themoviedb.org/movie/274479","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Династия","rating":null,"tier":"unrated","review":"","desc":"В центре сюжета сериала Кэррингтоны — состоятельная семья, владеющая нефтяным бизнесом и живущая в Денвере, штат Колорадо.","poster":"https://image.tmdb.org/t/p/w500/wxKEdlB4Zuq2THGqKYLnGKU37g9.jpg","url":"https://www.themoviedb.org/tv/3769","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мыльная опера","Драма","Триллер"]},{"title":"Дичь","rating":null,"tier":"unrated","review":"","desc":"В результате странного инцидента старшеклассница оказывается в теле жестокого серийного убийцы. У неё есть меньше 24 часов, чтобы всё исправить, после чего ситуацию будет уже не обратить.","poster":"https://image.tmdb.org/t/p/w500/xEGrAhg9nCdCzL3ZzsoYSKXmk9K.jpg","url":"https://www.themoviedb.org/movie/551804","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Комедия","Драма"]},{"title":"Дом","rating":null,"tier":"unrated","review":"","desc":"После смерти короля Визериса династия Таргариенов начинает бескомпромиссную борьбу за Железный трон. Предводительницей «черной» ветви становится принцесса Рейнира, а на стороне «зеленой» оказывается ее лучшая подруга и дочь десницы короля Алисента. В битве за престол соперницы заручаются поддержкой неожиданных союзников, плетут интриги — и используют разрушительную мощь драконов.","poster":"https://image.tmdb.org/t/p/w500/hXyYN6LFo7QnKUA3QBx7B3KsnJE.jpg","url":"https://www.themoviedb.org/tv/94997","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма","Боевик","Приключения"]},{"title":"Дом гуччи","rating":null,"tier":"unrated","review":"","desc":"Милан, 1978 год. Девушка из небогатой семьи Патриция Реджани на вечеринке знакомится с Маурицио Гуччи, нерешительным наследником знаменитого модного дома. Несмотря на неодобрение его отца Родольфо и отлучение от финансирования, молодые люди женятся. Но дядя Маурицио, второй владелец империи Альдо Гуччи, хочет наладить семейные отношения, и Патриция, пользуясь советами и наущениями телевизионной гадалки, решает извлечь из этой ситуации максимальную выгоду.","poster":"https://image.tmdb.org/t/p/w500/lMuc6dmVoEAoOTIJp4AnPwmEZ2T.jpg","url":"https://www.themoviedb.org/movie/644495","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Криминал","История"]},{"title":"Дом с паранормальными явлениями","rating":null,"tier":"unrated","review":"","desc":"Малкольм и Киша переезжают в дом своей мечты, но скоро понимают, что там уже проживает демон. Когда Киша становится одержимой, Малкольм обращается за помощью к священнику, экстрасенсу и команде охотников за привидениями.","poster":"https://image.tmdb.org/t/p/w500/m9jc6WRPhLGoVmF3NBm3olO23iz.jpg","url":"https://www.themoviedb.org/movie/139038","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Ужасы","Драма"]},{"title":"Дом с паранормальными явлениями 2","rating":null,"tier":"unrated","review":"","desc":"После потери своей возлюбленной Киши в автокатастрофе Малкольм решает начать новую жизнь — жениться на Меган, матери двоих детей. Вскоре начинают происходить странные вещи, и все усложняется, когда вернувшаяся к жизни Киша вселяется в дом по соседству…","poster":"https://image.tmdb.org/t/p/w500/1hWdDGZa58Ulo0uP0mw4EIf85bt.jpg","url":"https://www.themoviedb.org/movie/184345","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Ужасы","Драма"]},{"title":"Дом странных детей мисс перегрин","rating":null,"tier":"unrated","review":"","desc":"Детство Джейкоба прошло под рассказы дедушки о приюте для необычных детей. Среди его обитателей девочка, которая умела держать в руках огонь, девочка, чьи ноги не касались земли, невидимый мальчик и близнецы, умевшие общаться без слов. Когда дедушка умирает, 16-летний Джейкоб получает загадочное письмо и отправляется на остров, где вырос его дед. Там он находит детей, которых раньше видел только на фотографиях.","poster":"https://image.tmdb.org/t/p/w500/dnEoeRcpMVfcEBkGL2i4xm1CPv4.jpg","url":"https://www.themoviedb.org/movie/283366","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Драма"]},{"title":"Дорога домой","rating":null,"tier":"unrated","review":"","desc":"Хозяева двух собак, Шедоу и Шанса, и очаровательной кошечки Сэсси, уезжая на время, отдают своих питомцев на ранчо к другу. Через некоторое время животные, решив, что с их хозяевами случилась беда, отправляются домой пешком через горы и реки дикой природы.","poster":"https://image.tmdb.org/t/p/w500/oDg87O7abdZpJfv3GXFZr9SznrN.jpg","url":"https://www.themoviedb.org/movie/6878","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Драма","Семейный"]},{"title":"Достать ножи: Стеклянная луковица","rating":null,"tier":"unrated","review":"","desc":"Новое расследование сыщика Бенуа Бланка будет происходить на частном острове в Греции. Миллиардер Майлз Брон приглашает к себе разношёрстную компанию друзей. Вскоре на вечеринке происходит убийство...","poster":"https://image.tmdb.org/t/p/w500/14PudL6hCEhqwPDbxoBt2RHK5cC.jpg","url":"https://www.themoviedb.org/movie/661374","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Детектив"]},{"title":"Евровидение история огненной саги","rating":null,"tier":"unrated","review":"","desc":"В далёком 1974 году, увидев по телевизору выступление на Евровидении группы ABBA с песней «Waterloo», маленький исландский мальчик Ларс твёрдо решил, что когда-нибудь обязательно там выступит и победит. Много лет спустя Ларс уже немолод, всё ещё живёт с отцом, но свою мечту не оставил и исполняет песни собственного сочинения с подругой детства Сигрит. Хотя их группа Fire Saga выступает в местном баре, жители городка не хотят слушать самодеятельность и постоянно требуют кабацкий хит «Jaja Ding Dong». Однажды эльфы услышали просьбы Сигрит, и внезапно Fire Saga получает шанс участвовать в Евровидении.","poster":"https://image.tmdb.org/t/p/w500/9zrbgYyFvwH8sy5mv9eT25xsAzL.jpg","url":"https://www.themoviedb.org/movie/531454","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Музыка","Комедия","Драма"]},{"title":"Евротур","rating":null,"tier":"unrated","review":"","desc":"Выпускнику школы Скотту Томасу нужна помощь в изучении немецкого языка, поэтому он знакомится с жителем Германии по имени Майк и начинает с ним дружескую переписку. Причём Скотт абсолютно уверен, что Майк — это парень, и делится с ним своими переживаниями и проблемами, которые возникают у него с девушкой. Но в конце концов Скотт узнаёт, что Майк, точнее Мике — это обворожительная блондинка, которой Скотт очень понравился. И теперь он сделает всё, чтобы увидеться с Мике, даже совершит путешествие по Европе.","poster":"https://image.tmdb.org/t/p/w500/pyNDzXP4UCYz4vDb9ZKaRplumRt.jpg","url":"https://www.themoviedb.org/movie/9352","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"За бортом","rating":null,"tier":"unrated","review":"","desc":"Джоанна Стейтон — властная, заносчивая и несговорчивая жена самоуверенного владельца яхты. Когда их посудина останавливается для ремонта в небольшом городке, сварливая и взбалмошная Джоанна нанимает плотника Дина Проффитта, чтобы тот смастерил ей новый шкафчик. Но вместо платы за работу Дин получает от ворот поворот — ведь Джоанна никогда ничем не бывает довольна.","poster":"https://image.tmdb.org/t/p/w500/gtPBI3XNyee3BvVxqejvoOmxwJp.jpg","url":"https://www.themoviedb.org/movie/10780","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Залив тишины","rating":null,"tier":"unrated","review":"","desc":"Розалинда внезапно исчезает вместе с тремя детьми. Уилл ищет семью по всей Европе и находит своих родных в отдалённой деревне на севере Франции. Облегчение быстро сменяется ужасом из-за таинственной смерти маленького сына...","poster":"https://image.tmdb.org/t/p/w500/qENDjeRRtnL0xkxmvSni5YHm7oX.jpg","url":"https://www.themoviedb.org/movie/623958","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Драма","Комедия"]},{"title":"Запах женщины","rating":null,"tier":"unrated","review":"","desc":"Наступил День благодарения, и отставной полковник разведки Фрэнк Слэйд решает справить праздник, побаловав себя поездкой в Нью-Йорк. Фрэнк хочет обставить свой последний «коронный выход» по высшему разряду: изысканный отель, шикарный лимузин, дорогая выпивка и женщины потрясающей красоты.  Есть лишь две проблемы. Первая: Фрэнк слеп на оба глаза. И вторая: волнующиеся родственники полковника решают нанять за небольшую сумму провожатого в лице нуждающегося студента престижного колледжа по имени Чарли Симмз. Последнее, что было нужно в поездке полковнику Слэйду - так это «зеленый» юнец Чарли. Но случилось так, что путешествие этих двух потрясающе непохожих друг на друга людей изменило их жизни навсегда.","poster":"https://image.tmdb.org/t/p/w500/dQtZbo8LfqpwjLfDDuoK5KQdcRR.jpg","url":"https://www.themoviedb.org/movie/9475","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Засланец из космоса","rating":null,"tier":"unrated","review":"","desc":"Доктор Гарри Вандершпигель — отшельник в небольшом городке в Колорадо. Ещё Вандершпигель — пришелец, который на самом деле упал на Землю и занял тело врача. Когда же доктора убивают, пришелец вынужден отложить миссию по возвращению домой и занять место убитого. Живя в новом теле, он постепенно начинает задаваться вопросами, стоят ли люди спасения или нет.","poster":"https://image.tmdb.org/t/p/w500/iEZRhWp1QlxWnUU6uYPUTuIexvn.jpg","url":"https://www.themoviedb.org/tv/96580","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма"]},{"title":"Зачинщики","rating":null,"tier":"unrated","review":"","desc":"Рори и Кобби — неожиданные сообщники: отчаявшийся отец и бывший заключенный, объединившиеся для ограбления. Когда всё идет насмарку, они, вместе с необычным подельником, психотерапевтом Рори, пытаются уйти от полиции, замшелых бюрократов и мстительного главаря гангстеров.","poster":"https://image.tmdb.org/t/p/w500/coj1qHiVAF7CfRtO42EBGUXdJwP.jpg","url":"https://www.themoviedb.org/movie/1059064","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Комедия","Драма"]},{"title":"Здравствуй, папа, Новый год!","rating":null,"tier":"unrated","review":"","desc":"Отец двоих детей возвращается к своей бывшей жене, которая успела выйти замуж, и теперь его ждет соперничество с отчимом за внимание своих отпрысков.","poster":"https://image.tmdb.org/t/p/w500/aB7eWGAvM9zkf4r2vmBVA8Rbd1e.jpg","url":"https://www.themoviedb.org/movie/274167","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Земля будущего","rating":null,"tier":"unrated","review":"","desc":"Связанные общей судьбой, талантливая девушка-подросток с невероятной тягой к новым знаниям и бывший гений-изобретатель, переживший разочарования и крах своих иллюзий, отправляются сквозь пространство и время в полную опасностей миссию, чтобы раскрыть секреты таинственного места, которое существует в их общей памяти под названием «Земля завтрашнего дня».","poster":"https://image.tmdb.org/t/p/w500/pjJ8eIx7j6T8e5ifkL1ox7GH25W.jpg","url":"https://www.themoviedb.org/movie/158852","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Семейный","Детектив","Фантастика"]},{"title":"Зубная фея","rating":null,"tier":"unrated","review":"","desc":"Жестокого и свирепого хоккеиста Дерека Томпсона часто зовут «Зубной феей» — сами догадайтесь почему. За выбитые на ледовой арене зубы своим соперникам он денег не даёт, а придётся, ведь самые настоящие зубные феи давно точат на него зуб.","poster":"https://image.tmdb.org/t/p/w500/wiRiKbcKt2nhPJLEUsitHHX7TtE.jpg","url":"https://www.themoviedb.org/movie/23023","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Семейный","Фэнтези"]},{"title":"Идеальное свидание","rating":null,"tier":"unrated","review":"","desc":"Чтобы накопить на обучение в Йельском университете, Брукс создаёт мобильное приложение, благодаря которому любая девушка сможет арендовать его в качестве бойфренда на один вечер. По мере того, как он встречается с разными девушками, он начинает понимать чего же он на самом деле хочет от этой жизни.","poster":"https://image.tmdb.org/t/p/w500/xg9syO3yCDJAPOfLe8Mw7hIGE5O.jpg","url":"https://www.themoviedb.org/movie/543540","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Комедия","Драма"]},{"title":"Из моего окна","rating":null,"tier":"unrated","review":"","desc":"Ракель уже давно тайно влюблена в своего соседа. Но все меняется, когда он начинает отвечать ей взаимностью несмотря на протесты родителей.","poster":"https://image.tmdb.org/t/p/w500/mDlsFNi0HdlEWbm7066KQM27bDE.jpg","url":"https://www.themoviedb.org/movie/818647","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Драма","Комедия"]},{"title":"Изгоняющий дьявола: Инсомния","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/6EyEGGhkaDZLCjxRIRoeUm248G8.jpg","url":"https://www.themoviedb.org/movie/920429","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Ужасы","Триллер"]},{"title":"Иллюзия обмана","rating":null,"tier":"unrated","review":"","desc":"Команда лучших иллюзионистов мира проворачивает дерзкие ограбления прямо во время своих шоу, играя в кошки-мышки с агентами ФБР.","poster":"https://image.tmdb.org/t/p/w500/theB79zav0sACXPxMFgKI3nQIr8.jpg","url":"https://www.themoviedb.org/movie/75656","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Криминал","Драма"]},{"title":"Иллюзия обмана 2","rating":null,"tier":"unrated","review":"","desc":"«Четыре всадника», команда лучших иллюзионистов мира, снова в сборе! Их «магия» стала ещё совершеннее, а враги - опаснее. На сей раз им предстоит спасти свою репутацию и вывести на чистую воду жестокого техномагната.","poster":"https://image.tmdb.org/t/p/w500/jzm3Pmp1uaFCDo0NrA0Tn98Ddda.jpg","url":"https://www.themoviedb.org/movie/291805","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Триллер","Драма"]},{"title":"Иллюзия обмана 3","rating":null,"tier":"unrated","review":"","desc":"«4 всадника» возвращаются вместе с молодым поколением иллюзионистов, демонстрируя головокружительные трюки, магию и превращения, каких ещё не видел мир.","poster":"https://image.tmdb.org/t/p/w500/681ne20BQP8urbDD15EuS2R8UOh.jpg","url":"https://www.themoviedb.org/movie/425274","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Триллер","Драма"]},{"title":"Иностранец","rating":null,"tier":"unrated","review":"","desc":"В центре сюжета — ветеран вьетнамской войны Нгуен Нго Мин, убивавший сначала американцев, а затем вьетнамцев. Герой, отсидевший после победы в тюрьме,  оказывается в Лондоне, где открывает китайский ресторан в южной части города. В тот момент, когда он думает, что все несчастья и ужасы его семьи позади, дочь погибает в теракте, устроенном истинными IRA. Видя, что власти не слишком рьяно разыскивают террористов, Мин решает самостоятельно разыскать и уничтожить преступников.","poster":"https://image.tmdb.org/t/p/w500/el3tjVPKbZ7aKDs6nopwu8iPo4w.jpg","url":"https://www.themoviedb.org/movie/379149","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Криминал"]},{"title":"Инструкции не прилагаются","rating":null,"tier":"unrated","review":"","desc":"Валентин вёл жизнь плейбоя в Акапулько, пока бывшая любовница не преступила порог его дома с ребёнком и не вынудила его с девочкой поехать прочь из Мексики.","poster":"https://image.tmdb.org/t/p/w500/aT3qQ3LWRZAV10LWqcf1bsbTtwd.jpg","url":"https://www.themoviedb.org/movie/211954","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Искупление","rating":null,"tier":"unrated","review":"","desc":"Шайка исправившихся воров и мошенников использует свои уникальные навыки, чтобы исправлять случаи несправедливости в отношении простых граждан со стороны богачей, корпораций и коррумпированных чиновников.","poster":"https://image.tmdb.org/t/p/w500/i3Evib4bHONndY7pZ9gbznYUcGj.jpg","url":"https://www.themoviedb.org/tv/106502","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Драма"]},{"title":"История R32","rating":null,"tier":"unrated","review":"","desc":"Трогательная научно-фантастическая короткометражка украинского режиссёра Владимира Власенко (2014). История повествует об одиноком роботе устаревшей модели по имени R32, который бродит по улицам и тщетно пытается привлечь внимание равнодушных к нему людей в надежде найти своё место в мире.","poster":"https://img.youtube.com/vi/oUTjY6xjtfk/hqdefault.jpg","url":"https://www.youtube.com/watch?v=oUTjY6xjtfk","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Короткометражка","Фантастика","Гонки","CGI"]},{"title":"Кабинет редкостей гильермо дель торо","rating":null,"tier":"unrated","review":"","desc":"Причудливые кошмары разворачиваются в этой зрелищной коллекции из восьми леденящих кровь историй, подобранных Гильермо дель Торо.","poster":"https://image.tmdb.org/t/p/w500/2SDczyepihX7JdBKoIBdMhetDyf.jpg","url":"https://www.themoviedb.org/tv/83659","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","Фантастика","Фэнтези"]},{"title":"Как громом поражённый","rating":null,"tier":"unrated","review":"","desc":"16-летний Брайан — застенчивый подросток, который не может попасть в школьную баскетбольную команду. Случайная встреча с суперзвездой НБА Кевином Дюрантом и волшебный инцидент передают юноше весь талант чемпиона, пока сам Дюрант разучивается бросать мяч.","poster":"https://image.tmdb.org/t/p/w500/lR1ssqRzslQx9WtTOKnfgqbNB1y.jpg","url":"https://www.themoviedb.org/movie/119738","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Семейный","Драма"]},{"title":"Как малые дети","rating":null,"tier":"unrated","review":"","desc":"Идеальное течение жизни американского города: работа, дом, семья, дети. Идиллия? Однообразие? Скука? Интрига? Все меняется ночью: запретные развлечения — измены, жаркие сексуальные утехи, в то время как по улицам разгуливает маньяк, не вполне определившийся в своих предпочтениях…","poster":"https://image.tmdb.org/t/p/w500/A0LewtoHlOvIGi6XDKu6z6ui1Cs.jpg","url":"https://www.themoviedb.org/movie/1440","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Триллер"]},{"title":"Каникулы","rating":null,"tier":"unrated","review":"","desc":"Расти Гризвольд решает сплотить семью и устраивает грандиозное автомобильное путешествие через всю страну в самый крутой тематический парк развлечений «Walley World», но по пути семью ждут невероятно курьёзные катастрофы.","poster":"https://image.tmdb.org/t/p/w500/7K4pewvTT1yc7cbFNS6GOZYlNtW.jpg","url":"https://www.themoviedb.org/movie/296099","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Приключения","Семейный"]},{"title":"Капитан фантастик","rating":null,"tier":"unrated","review":"","desc":"Отец, живущий со своими шестью маленькими детьми в лесах Тихоокеанского Северо-Запада, приезжает на похороны жены, покончившей с собой из-за депрессии. Жизнь семьи далека от общепринятых норм: папа выживает как умеет, дети ловят и разделывают оленя, получают на общий праздник (день рождения Ноама Хомского) оружие, умеют ориентироваться по звездам и лечат раны мхом. Они не ходят в обычную школу, но в 8 лет могут рассказать о спорах, которые в XXI веке вызывает Билль о правах и о том, почему главному герою «Лолиты» хочется сочувствовать, несмотря ни на что.  Утопия рушится, когда все семеро выдвигаются на похороны матери, где встречают ее родителей, — самых обычных, простых американцев.","poster":"https://image.tmdb.org/t/p/w500/yNEgSVWwZKHAAHRaq7vtlnRjOQz.jpg","url":"https://www.themoviedb.org/movie/334533","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Китайский продавец","rating":null,"tier":"unrated","review":"","desc":"Ян Цзянь, молодой китайский IT-инженер, отправляется в Северную Африку на конкурс. За право контролировать минеральные ресурсы страны будет бороться и Майкл, французский шпион. Он нанял лучшего наемника Африки и бывшего генерала Кабба, чтобы выиграть. Ян единственный, кто может их остановить.","poster":"https://image.tmdb.org/t/p/w500/TmO5oywb87UwHBkpAulR13Y06m.jpg","url":"https://www.themoviedb.org/movie/461714","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Приключения"]},{"title":"Клаус","rating":null,"tier":"unrated","review":"","desc":"Почтальон-эгоист и нелюдимый мастер-игрушечник заводят странную дружбу, принося чистую радость в тёмный и холодный город, которому не хватает надежды.","poster":"https://image.tmdb.org/t/p/w500/iQ4WqwaeYzL9Hiljji98AkwR8Ix.jpg","url":"https://www.themoviedb.org/movie/508965","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Семейный","Комедия"]},{"title":"Клуб школа","rating":null,"tier":"unrated","review":"","desc":"Юноша Лиам всю жизнь учился дома под опекой гиперопекающей матери. Но однажды он решает завалить выпускной экзамен, чтобы пойти в обычную государственную школу и узнать настоящую жизнь подростков.","poster":"https://image.tmdb.org/t/p/w500/mdupWntFAGyyP5dfMt6hbdtDvWa.jpg","url":"https://www.themoviedb.org/movie/471515","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Мелодрама"]},{"title":"Королева проклятых","rating":null,"tier":"unrated","review":"","desc":"Легендарный вампир Лестат пробудился после долгих лет сна и решил выйти в свет. Теперь он имеет возможность перемещаться среди смертных в образе некой рок-звезды. Его опьяняющая музыка — приманка популярна во всем мире, и в конечном счете, доходит до ушей дремлющей Королевы Акаши в ее склепе во льдах Арктики.Мать всех вампиров, Акаша отдыхала несколько столетий, ожидая подходящее время для того, чтобы подняться и вновь захватить власть по всему миру. Музыка Лестата — открытие, которого она ожидала…","poster":"https://image.tmdb.org/t/p/w500/2AcJlgzxjBXYXjjF4mFlpAsHmbZ.jpg","url":"https://www.themoviedb.org/movie/11979","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Ужасы","Романтика"]},{"title":"Королевская игра","rating":null,"tier":"unrated","review":"","desc":"Вена, 1938 год. Юрист Йозеф Барток арестован гестапо. Находясь в одиночном заключении и подвергаясь психологическим пыткам, он случайно крадет книгу с шахматными партиями, которая становится его единственным спасением от безумия.","poster":"https://image.tmdb.org/t/p/w500/8ZKoCSmiyPI8f7bbMSDL4EJRo91.jpg","url":"https://www.themoviedb.org/movie/748787","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Военный","Триллер"]},{"title":"Королевы крика","rating":null,"tier":"unrated","review":"","desc":"Сюжет сериала сосредоточен вокруг университетского городка, жизнь которого потрясает серия убийств.","poster":"https://image.tmdb.org/t/p/w500/6RPtYOrSaCk51nYTdMInT78UaCh.jpg","url":"https://www.themoviedb.org/tv/62046","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Комедия","Драма"]},{"title":"Король ричард","rating":null,"tier":"unrated","review":"","desc":"Комптон, 1988 год. Отец пяти дочерей Ричард Уильямс уже давно составил подробный план на будущее своих девочек и упорно ему следует, а из восьмилетней Винус и семилетней Серены он намеревается сделать звёзд тенниса. Хотя Ричард с женой Брэнди мало что понимают в подготовке профессиональных теннисистов, они сами тренировали дочек и как могли ставили им технику. Всемирно известный тренер Пол Коэн, который работает с Питом Сампрасом и Джоном Макинроем, соглашается на бесплатные уроки, но только для Винус. Тогда Ричард записывает занятия на камеру, и Брэнди на их основе начинает тренировать Серену.","poster":"https://image.tmdb.org/t/p/w500/JHb7M3mwxWGLHHtfTu08Ys6aVz.jpg","url":"https://www.themoviedb.org/movie/614917","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Триллер"]},{"title":"Красавчик со стажем","rating":null,"tier":"unrated","review":"","desc":"Встречайте мужчину мечты! Он знает секреты обольщения и вовсю этим пользуется, чтобы жить в свое удовольствие. Возможно, опытный мачо уже немного растерял обаяние, но отказываться от роскошной жизни не входит в его планы. Применяя весь свой арсенал, он вновь готов вернуться в игру.","poster":"https://image.tmdb.org/t/p/w500/vkfFcTQMT3EX9PNAP0Tf7xuJMql.jpg","url":"https://www.themoviedb.org/movie/544345","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Красная река","rating":null,"tier":"unrated","review":"","desc":"На Запад идет большой караван. Тяжелые, медленные повозки тащат измотанные лошади и скорость этого усталого, еле-еле передвигающегося «организма» настолько мала, что это уже даже представляет опасность, так как на такой караван легче всего напасть и разграбить. И тогда самый отчаянный и пассионарный малый по имени Том Дансон решает наплевать на все, в том числе и на свою возлюбленную Фен, и податься на Юг. Туда, где настоящего ковбоя манит сказочно богатая и многообещающая Красная Река. Как только они перевалили через небольшой холм, то услышали сзади звуки выстрелов и увидели мощные клубы черного дыма.","poster":"https://image.tmdb.org/t/p/w500/90E1xVYHlDAuWofQToDm4G3Zdzr.jpg","url":"https://www.themoviedb.org/movie/3089","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Вестерн","Драма","Приключения"]},{"title":"Красотка на взводе","rating":null,"tier":"unrated","review":"","desc":"Никогда не злите Линди! Она сногсшибательная красотка, но её ярости позавидует любой вышибала. Чтобы гасить вспышки гнева, она носит на себе оригинальное приспособление — жилет из электродов, бьющих ее током за мгновение до срыва. Но когда кто-то убивает ее парня, Линди понимает, что только ей под силу раскрыть преступление. Теперь у нее есть веский повод пуститься во все тяжкие и надрать задницы всему преступному миру в поисках виновных.","poster":"https://image.tmdb.org/t/p/w500/sgl3Mlw1LHrXX7HYEHUe43nuTRS.jpg","url":"https://www.themoviedb.org/movie/617502","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Криминал"]},{"title":"Красота по американски","rating":null,"tier":"unrated","review":"","desc":"Лестер Бернэм переживает кризис среднего возраста. Его не уважают и не ценят на работе, а от счастливой семьи осталась лишь видимость. У жены Кэролайн страстный роман с коллегой по работе, а угрюмая дочь-подросток Джейн увлечена соседским парнем, побывавшим в психиатрической больнице.  Терзаемый душевными муками Лестер впадает в депрессию. Но неожиданно для себя влюбляется в одноклассницу дочери Анджелу, и эта страсть дает Лестеру мощный жизненный импульс. Он ощущает прилив сил и желаний и готов снова радоваться красоте.","poster":"https://image.tmdb.org/t/p/w500/lusI8lV9eThjA7otUGo3bRmFWk9.jpg","url":"https://www.themoviedb.org/movie/14","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Красотки в бега","rating":null,"tier":"unrated","review":"","desc":"Тусовщица Джейми и её скромная подруга Мэриан отправляются на машине в Таллахасси, но все быстро идет наперекосяк, когда по дороге они сталкиваются с группой неумелых преступников.","poster":"https://image.tmdb.org/t/p/w500/csQP4n1dY6ZPmAyaPJwzx5vREX9.jpg","url":"https://www.themoviedb.org/movie/957304","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Драма"]},{"title":"Кровный отец","rating":null,"tier":"unrated","review":"","desc":"17-летняя девушка попадает в серьёзные неприятности, и теперь за ней охотятся убийцы наркокартеля. Из близких у неё только отец — завязавший алкоголик и бывший заключённый, который даже особо не видел свою дочь и не принимал участия в её воспитании. Но родственников не выбирают, и девушке приходится обратиться к нему за помощью.","poster":"https://image.tmdb.org/t/p/w500/unJJ1FtpbeIMBvohdymWzfLjv9T.jpg","url":"https://www.themoviedb.org/movie/309886","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Драма"]},{"title":"Кровью и потом:анаболики","rating":null,"tier":"unrated","review":"","desc":"Однажды тренеру по фитнесу надоело ходить в трениках. Он решил круто изменить свою судьбу и разбогатеть. Нашел двух других незадачливых качков и предложил им план похищения своего клиента-миллионера. Но если в организме мышц больше, чем мозгов, то даже самый лучший план, подсмотренный в экшен-боевике, может не сработать…","poster":"https://image.tmdb.org/t/p/w500/yHfQWJbIrKi4hpmvNG3X8MY4TJz.jpg","url":"https://www.themoviedb.org/movie/134374","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Боевик"]},{"title":"Крупная рыба","rating":null,"tier":"unrated","review":"","desc":"В основу этой приключенческой ленты положен роман Дэниела Уоллеса «Большая рыба: роман мифических пропорций». Умирает отец, о жизни которого сын хочет узнать как можно больше, собирая истории о нем. Сын пытается воссоздать ускользающую жизнь отца в серии легенд и мифов, которые тот придумывает на основе разрозненных фактов. Взлеты и падения в жизни человека в итоге предстают в неожиданном ракурсе.","poster":"https://image.tmdb.org/t/p/w500/kAYWFyOLoQloDNwk1CH82SN4YxT.jpg","url":"https://www.themoviedb.org/movie/587","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Драма"]},{"title":"Кулаки возмездия","rating":null,"tier":"unrated","review":"","desc":"Наемник со сверхспособностями выслеживает убийцу в Бангкоке. В процессе выясняется, что его миссия — не просто отомстить, а спасти мир от давней угрозы.","poster":"https://image.tmdb.org/t/p/w500/nsQvHU2IjHjI24CgLCcmDAQ2RMr.jpg","url":"https://www.themoviedb.org/movie/890656","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Триллер"]},{"title":"Леди макбет","rating":null,"tier":"unrated","review":"","desc":"В основу фильма лег одноименный очерк Николая Лескова. Любовь и страсть красавицы Катерины Измайловой не знает границ и приводит к страшному преступлению. Впрочем, не единственному…","poster":"https://image.tmdb.org/t/p/w500/s7sBRFEE73dGKbWcsp4sTfLIPws.jpg","url":"https://www.themoviedb.org/movie/342167","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Летучий шотландец","rating":null,"tier":"unrated","review":"","desc":"Биографическая лента расскажет правдивую историю знаменитого шотландского велосипедиста, чемпиона мира Грэма Обри. Он был известен тем, что установил мировой рекорд на велосипеде собственного производства, при создании которого использовал части стиральной машины. И при всем этом у Обри были проблемы с психикой.","poster":"https://image.tmdb.org/t/p/w500/1ARffaR8ujlrxsGQrcpuPXwPaUS.jpg","url":"https://www.themoviedb.org/movie/15008","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Линия горизонта","rating":null,"tier":"unrated","review":"","desc":"Сара и Джексон собирались полететь на небольшом самолёте на свадьбу друга. За штурвалом опытный пилот, и ничто не предвещало беды, пока у того не случился сердечный приступ прямо в небе. Сара и Джексон на огромной высоте, нет никакой связи, неизвестно их точное местонахождение, и главное — они совершенно без понятия, как посадить самолёт. Плюс к тому, вокруг только океан и небо, и судя по обстановке, их вот-вот накроет бушующий шторм.","poster":"https://image.tmdb.org/t/p/w500/dg2JcLkA4vSfgunZHRpUeq2QCqA.jpg","url":"https://www.themoviedb.org/movie/602654","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Приключения","Боевик"]},{"title":"Ловушка времени","rating":null,"tier":"unrated","review":"","desc":"Группа студентов оказывается в ловушке в таинственной пещере, внутри которой они обнаруживают, что время здесь течёт иначе.","poster":"https://image.tmdb.org/t/p/w500/6000lU02F16hskDhnwKOZzDXh0M.jpg","url":"https://www.themoviedb.org/movie/455839","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Приключения","Драма"]},{"title":"Лоро","rating":null,"tier":"unrated","review":"","desc":"На закрытых вечеринках и дорогих приёмах в Риме и на Сардинии его всегда окружают самые красивые и самые опасные люди, готовые на всё, лишь бы получить доступ к живой легенде. «Лоро» («они») — это нувориши-итальянцы и их нравы, воплощение которых — тиран и весельчак, гедонист и романтик, скандальный политик и миллиардер Сильвио Берлускони.","poster":"https://image.tmdb.org/t/p/w500/zO6qGLPoLbe8AeUDp7cpYAwd9C0.jpg","url":"https://www.themoviedb.org/movie/541660","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Любовницы","rating":null,"tier":"unrated","review":"","desc":"В центре сюжета находится жизнь четырёх подруг, каждая из которой находится в сложных и опасных отношениях.","poster":"https://image.tmdb.org/t/p/w500/baJQGX2aXDtBngCwdukDaTnc1ea.jpg","url":"https://www.themoviedb.org/tv/43856","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Любовь зла","rating":null,"tier":"unrated","review":"","desc":"Харизматичный вор-домушник Максим попадает в неприятности, задолжав деньги опасным бандитам. Во время очередного ограбления он становится свидетелем отчаянного поступка, который совершает неожиданно вернувшаяся хозяйка квартиры Ева: она пытается сжечь всё, что напоминает о парне-предателе, и вдобавок покончить жизнь самоубийством. Максим решает остановить Еву и уберечь себя от еще больших проблем.","poster":"https://image.tmdb.org/t/p/w500/dteNTZMOZEbLNVkVvimnEDluFgf.jpg","url":"https://www.themoviedb.org/movie/1265305","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Любовь как бестселлер","rating":null,"tier":"unrated","review":"","desc":"Молодой и скромный английский писатель узнаёт, что его сдержанный личный опус вдруг стал феноменальным бестселлером в Мексике и привлек к нему толпы поклонниц. Всё благодаря своенравной переводчице, которая без его ведома превратила книгу в горячий эротический роман. Горе-творцам не остается ничего, кроме как отправиться в совместный тур по стране, выпустив на свободу все потаённые чувства друг к другу.","poster":"https://image.tmdb.org/t/p/w500/vYPK7NQme2khKdlX4rJc0Cpbrz3.jpg","url":"https://www.themoviedb.org/movie/892835","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Люцифер","rating":null,"tier":"unrated","review":"","desc":"«Скучно в аду? Развлекусь в Городе ангелов!» — решает Сатана и отправляется на Землю. Он открывает ночной клуб и знакомится с женщиной-детективом из убойного отдела.","poster":"https://image.tmdb.org/t/p/w500/z24OWggvuqkmB0xmtgChXbl9THw.jpg","url":"https://www.themoviedb.org/tv/63174","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Фантастика","Фэнтези"]},{"title":"Мажор 2021","rating":null,"tier":"unrated","review":"","desc":"Таких, как наш главный герой Игорь Соколовский, называют мажорами. То есть, детей высокопоставленных, богатых родителей. Наш герой имеет юридическое образование, но ни одного дня не проработал. Безответственный прожигатель жизни. В один из загулов ночью он вступился за приятеля, подрался с полицейскими, выбил табельное оружие у офицера… В итоге отец лишает героя всего и отправляет работать в отделение полиции — то самое, в котором служат ночные полицейские. Его, мажора, там не ждут. Его презирают. Но именно там он начнет становиться мужчиной, встретит свою любовь и найдет убийцу мамы.","poster":"https://image.tmdb.org/t/p/w500/kDEpaBqnD40tI7XpRDUFWn4JWcA.jpg","url":"https://www.themoviedb.org/tv/63435","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Криминал","Триллер"]},{"title":"Майор гром: чумной доктор","rating":null,"tier":"unrated","review":"","desc":"Майор полиции Игорь Гром известен всему Санкт-Петербургу пробивным характером и непримиримой позицией по отношению к преступникам всех мастей. Неимоверная сила, аналитический склад ума и неподкупность — всё это делает майора Грома идеальным полицейским. Но всё резко меняется с появлением человека в маске Чумного Доктора. Заявив, что его город «болен чумой беззакония», он принимается за «лечение», убивая людей, которые в своё время избежали наказания при помощи денег и влияния. Общество взбудоражено. Полиция бессильна. Игорь впервые сталкивается с трудностями в расследовании, от итогов которого может зависеть судьба всего города.","poster":"https://image.tmdb.org/t/p/w500/al7XQOEnLfRQtuDdUeUeW4KtBVI.jpg","url":"https://www.themoviedb.org/movie/529106","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Драма"]},{"title":"Малена","rating":null,"tier":"unrated","review":"","desc":"Малена - красавица-вдова, наваждение мужчин и предмет зависти женщин. Жены распускают о ней грязные сплетни. Мужья преследуют ее по пятам и грезят о ней. «Мне было 13, когда я увидел ее впервые. Прошло время, я любил многих женщин, и когда мы были близки, они спрашивали: буду ли я помнить их? И я говорил: да, я буду помнить вас. Но единственная, кого я никогда не забуду - та, которая никогда не спрашивала. Малена».","poster":"https://image.tmdb.org/t/p/w500/32oUtiC15RMqZNILZPdcbVSMTah.jpg","url":"https://www.themoviedb.org/movie/10867","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Мальчишник 1","rating":null,"tier":"unrated","review":"","desc":"Мальчишник в Лас-Вегасе выходит из-под контроля: жених исчезает, а трое его друзей совершенно не помнят события прошлой ночи.","poster":"https://image.tmdb.org/t/p/w500/eqfuqXcv0MlbnzihcfsTaTGMbd.jpg","url":"https://www.themoviedb.org/movie/18785","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Мальчишник 2: Из Вегаса в Бангкок","rating":null,"tier":"unrated","review":"","desc":"В продолжении культовой комедии «Мальчишник в Вегасе» четверо друзей Фил, Стю, Алан и Даг отправляются в экзотический Тайланд на свадьбу Стю. После безумного мальчишника в Лас-Вегасе, они решают не испытывать судьбу во второй раз, а потому в Бангкоке планируют очень спокойное и безопасное празднество. Но как обычно, все идет совсем не по плану… Что происходит в Вегасе, остается в Вегасе. Но то, что происходит в Бангкоке — это просто настоящее безумие!","poster":"https://image.tmdb.org/t/p/w500/zDJYcvMxqIFVXpbs4US4YF5eskU.jpg","url":"https://www.themoviedb.org/movie/45243","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Медовый месяц","rating":null,"tier":"unrated","review":"","desc":"Выпускница медицинского института Людочка «выскакивает» замуж за инженера Алексея для того, чтобы после распределения остаться в Ленинграде. Но неожиданно, Алексей дает согласие на работу в Сибири, и бедной Людочке пришлось последовать за мужем на сибирскую стройку и начать свою трудовую деятельность врачом в крохотном медпункте рабочего посёлка...","poster":"https://image.tmdb.org/t/p/w500/oVAEYAepDq2mneZZCu2osBgOcdy.jpg","url":"https://www.themoviedb.org/movie/81214","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Комедия","Драма"]},{"title":"Между небом и землёй","rating":null,"tier":"unrated","review":"","desc":"История Ачата и Тарсуна, друзей с детства, ставших цирковыми артистами и выступавшими против советской власти в Узбекистане.","poster":"https://image.tmdb.org/t/p/w500/jlZ4fGovP8b75KhiQip7qmSJsMN.jpg","url":"https://www.themoviedb.org/movie/637139","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Документальный","Драма","Триллер"]},{"title":"Мейер лански","rating":null,"tier":"unrated","review":"","desc":"Мейер Лански — легенда американской мафии, с которым считались все преступные синдикаты и сам Аль Капоне. Ему, конечно, есть, что рассказать. Тот, кто сумеет разговорить скандально известного главу «корпорации убийств», получит эксклюзив на миллион долларов. Но пойдет ли на это Мейер Лански и чьи головы полетят, если он все-таки заговорит?","poster":"https://image.tmdb.org/t/p/w500/9dLOHGabCg5Y05F6wQh2lZa23yC.jpg","url":"https://www.themoviedb.org/movie/693827","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Триллер"]},{"title":"Мёртвые не умирают","rating":null,"tier":"unrated","review":"","desc":"В тихом американском городке Центрвиль начинают происходить необъяснимые явления: солнце не заходит вовремя, часы останавливаются, а мертвецы восстают из могил и отправляются бродить по улицам в поисках кофе и интернета. Местные полицейские берутся за оружие.","poster":"https://image.tmdb.org/t/p/w500/5WdNwPQQqoS8f0mQFhq6oy3QaTN.jpg","url":"https://www.themoviedb.org/movie/535581","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Ужасы"]},{"title":"Операция «Мёртвый снег»","rating":null,"tier":"unrated","review":"","desc":"После встречи в горах с нацистами-зомби лишь Мартину удалось добраться до цивилизации, в то время как все его приятели погибли. Однако парень забыл о маленьком подарке, который он получил от своей возлюбленной Ханны, — золотой монете, которую та нашла в старом доме. Эта монета — часть клада, который подчиненные штандартенфюрера Герцога собирали для своего фюрера. Но даже после смерти немцы не намерены никому отдавать свои сокровища…","poster":"https://image.tmdb.org/t/p/w500/AujbcgNGMUqwuUHlrgtrYelIKd6.jpg","url":"https://www.themoviedb.org/movie/241842","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Боевик","Комедия"]},{"title":"Операция «Мертвый снег» 2","rating":null,"tier":"unrated","review":"","desc":"После встречи в горах с нацистами-зомби лишь Мартину удалось добраться до цивилизации, в то время как все его приятели погибли. Однако парень забыл о маленьком подарке, который он получил от своей возлюбленной Ханны, — золотой монете, которую та нашла в старом доме. Эта монета — часть клада, который подчиненные штандартенфюрера Герцога собирали для своего фюрера. Но даже после смерти немцы не намерены никому отдавать свои сокровища…","poster":"https://image.tmdb.org/t/p/w500/AujbcgNGMUqwuUHlrgtrYelIKd6.jpg","url":"https://www.themoviedb.org/movie/241842","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Боевик","Комедия"]},{"title":"Механик","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/4s9hiyQvTaMe1bK91HRCTgDTAoF.jpg","url":"https://www.themoviedb.org/tv/3469","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Боевик","Приключения","Криминал"]},{"title":"Миссия: Неадекватна","rating":null,"tier":"unrated","review":"","desc":"Главный герой фильма — безработный бывший заключенный. К нему является Бог и просит отправиться в Пакистан — найти и убить Осаму бин Ладена.","poster":"https://image.tmdb.org/t/p/w500/ofMUb1nLJ5MSjVp5iBnyXEimvrJ.jpg","url":"https://www.themoviedb.org/movie/336445","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Мой друг Зигмунд Фрейд","rating":null,"tier":"unrated","review":"","desc":"Оказавшись в Вене, молодой парень встречает свою первую и, как ему кажется, последнюю любовь. В тонкостях желаний и соблазнов ему помогает разобраться тот, кто знает об этом всё, - сам Зигмунд Фрейд.","poster":"https://image.tmdb.org/t/p/w500/puLdmpVzHQ42THnHZ3guCq37q5X.jpg","url":"https://www.themoviedb.org/movie/538061","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Триллер"]},{"title":"Мой любимый марсианин","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/kw90AgVKEPwfKLtC07hoRQFwOXk.jpg","url":"https://www.themoviedb.org/tv/3882","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Комедия","Семейный"]},{"title":"Монстр","rating":null,"tier":"unrated","review":"","desc":"Основанная на реальных событиях драма о судьбе Эйлин Уорнос (Шарлиз Терон), одной из первых признанных женщин — серийных убийц в истории Америки.","poster":"https://image.tmdb.org/t/p/w500/25Xg23kr54H8ucAtydjGpd5uqyV.jpg","url":"https://www.themoviedb.org/movie/504","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Триллер"]},{"title":"Море соблазна","rating":null,"tier":"unrated","review":"","desc":"Капитан корабля спустя годы вновь встречает свою любимую женщину, которая вышла замуж за богача, а теперь хочет избавиться от него. Чтобы осуществить это, она просит помощи у того, кто до сих пор испытывает к ней чувства.","poster":"https://image.tmdb.org/t/p/w500/oMMl18ufSO2jmti12kwzb9prjCU.jpg","url":"https://www.themoviedb.org/movie/452832","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Детектив","Драма"]},{"title":"Моя девушка монстр","rating":null,"tier":"unrated","review":"","desc":"Гигантский монстр нападает на Сеул, разрушая все на своем пути. В Нью-Йорке потерявшая работу и бойфренда Глория понимает, что каким-то образом связана с этими фантастическими событиями.","poster":"https://image.tmdb.org/t/p/w500/6x8QfyCKKjsqxsw7Zqx0sQ6Ogc7.jpg","url":"https://www.themoviedb.org/movie/339967","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фэнтези","Фантастика"]},{"title":"Моя золотая жизнь","rating":null,"tier":"unrated","review":"","desc":"История женщины Со Джи-ан, которая получает возможность войти в высшее общество и стать наследницей богатой семьи конгломерата, но неожиданные жизненные испытания и раскрытие семейных тайн переворачивают её судьбу.","poster":"https://image.tmdb.org/t/p/w500/yCABEV6w6a1hxnWt1KuogyXEid7.jpg","url":"https://www.themoviedb.org/tv/46555","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Фэнтези","Детектив"]},{"title":"На игре","rating":null,"tier":"unrated","review":"","desc":"После победы на турнире по киберспорту команде геймеров вручают диски с только что разработанной игрой. Запустив игру, каждый из них подвергается воздействию, переводящему их игровые способности в реальные. Некие \"авторитетные\" структуры путем шантажа, обмана и подкупа предлагают геймерам \"работу\". Перед геймерами стоит задача либо найти тираж и уничтожить его, либо, создав и возглавив целую армию геймеров, диктовать преступникам свою волю...","poster":"https://image.tmdb.org/t/p/w500/9RSVyIwttjIMcCOgpszmkXka5wt.jpg","url":"https://www.themoviedb.org/movie/37656","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Драма"]},{"title":"Настоящие боссы","rating":null,"tier":"unrated","review":"","desc":"Будучи лучшими подругами ещё с колледжа, Миа и Мел управляют небольшой косметической компанией, которую создали с нуля. Девушки всё делают вместе и даже живут в одном доме. Их бизнес находится на грани разорения, когда подруги получают предложение, от которого невозможно отказаться — титан отрасли Клэр Луна предлагает оплатить их долги в обмен на долю в компании. Мел видит в этом спасение, а Миа, хоть и подозревает неладное, но тоже соглашается, и теперь многолетней дружбе девушек предстоит проверка на прочность.","poster":"https://image.tmdb.org/t/p/w500/gXayNOH3MwVMj0XmP8v1usSZ3PW.jpg","url":"https://www.themoviedb.org/movie/526019","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Не звезди","rating":null,"tier":"unrated","review":"","desc":"Джером всегда врёт,  да так, что и глазом не моргнёт! Он врёт постоянно и с особым размахом: глядя прямо в глаза, он будет утверждать, что лично знаком с Мисс Мира, что он чемпион по карате и, по совместительству, астронавт. Но однажды Джером просыпается в мире, где вся его ложь становится правдой и все выдуманное начинает происходить с ним на самом деле...","poster":"https://image.tmdb.org/t/p/w500/6PkLMiRfnkMYkoKmLgE2Tq8WV3A.jpg","url":"https://www.themoviedb.org/movie/829165","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Не та девушка","rating":null,"tier":"unrated","review":"","desc":"Фильм расскажет о приключениях 29-летней Лили Вудворд, которая пытается наладить свою жизнь и карьеру, и о том, к чему эти попытки приводят.","poster":"https://image.tmdb.org/t/p/w500/faq9Xxzk75IW3Z0mUoblZ1pQ6xl.jpg","url":"https://www.themoviedb.org/tv/67770","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Не твоё тело","rating":null,"tier":"unrated","review":"","desc":"Андреа — гениальный нейрохирург, София — амбициозная телеведущая. Их десятилетний брак трещит по швам. Во время экспериментального научного теста происходит сбой, и супруги внезапно меняются телами. Чтобы спасти работу и отношения, им придётся прожить жизнь друг друга.","poster":"https://image.tmdb.org/t/p/w500/mfi9TNOn0TXNCaINH6hxF1wDn8x.jpg","url":"https://www.themoviedb.org/movie/445793","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Небольшое привидение вы знакомы с моим","rating":null,"tier":"unrated","review":"","desc":"Нелегко быть школьником. Но быть Максом Дойлом еще сложнее: его задирает тупой брат, оценки в школе ниже среднего, а девушки его попросту не замечают. Да, мы еще не все сказали: Макс способен видеть и слышать призраков. Тем временем злой волшебник Фирз готов направить свою армию живых мертвецов на человечество, и остановить его может только наш незадачливый герой. По ходу действия Макс узнает, что способен также управлять духами и призраками. Так что ему придется спасти мир, девушку и ненавистную школу.","poster":"https://image.tmdb.org/t/p/w500/eiVY4kKpbo1f7wyNubgJX5ILpxg.jpg","url":"https://www.themoviedb.org/movie/289239","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Фэнтези","Ужасы","Комедия"]},{"title":"Невероятный бёрт Уандерстоун","rating":null,"tier":"unrated","review":"","desc":"Фильм рассказывает историю двух фокусников-конкурентов в Лас-Вегасе. Берт Уандерстоун однажды во время исполнения номера лишается напарника, и всё оставшееся время пытается вернуть себе мотивацию и вернуться к любимому занятию.","poster":"https://image.tmdb.org/t/p/w500/tFXS3y6T0tK2msQkhYTwltnodd0.jpg","url":"https://www.themoviedb.org/movie/124459","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Невозможное","rating":null,"tier":"unrated","review":"","desc":"Лента о событиях, разворачивающихся на фоне цунами 2004 года.","poster":"https://image.tmdb.org/t/p/w500/gfTF3DpPwr9HEwjd4NG4SZAPAeI.jpg","url":"https://www.themoviedb.org/movie/80278","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","История"]},{"title":"Невыносимая тяжесть огромного таланта","rating":null,"tier":"unrated","review":"","desc":"Фильм расскажет о том, как Николас Кейдж, чтобы заработать несколько миллионов долларов, отправляется на вечеринку на острове Мальорке, которую в честь своего дня рождения устроил криминальный авторитет Хави. Он большой фанат Кейджа и хранит у себя восковую фигуру актёра, а когда тот приезжает, обсуждает с ним кино — от «Кабинета доктора Калигари» до «Паддингтона 2».  Однако Хави не знает, что Кейджа завербовали агенты ЦРУ, которые с помощью актёра пытаются задержать главу преступного мира.","poster":"https://image.tmdb.org/t/p/w500/8T0K2p2BC3WCV1HWxPZ7nIfodqo.jpg","url":"https://www.themoviedb.org/movie/648579","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Криминал"]},{"title":"Неидеальный мужчина","rating":null,"tier":"unrated","review":"","desc":"Свете не везет с отношениями: она вечно подстраивается под парней, унижается и терпит измены. После расставания с очередным непутевым бойфрендом девушка идет работать в компанию по продаже роботов. Те уже стали частью обычной жизни, их не отличить от людей, но не в пример своим создателям роботы чутко реагируют на характер человека, его потребности, привычки и слабости. Когда у одного из роботов обнаруживается программный сбой и его хотят вернуть производителю, Света упрашивает продать его ей, так как… влюбляется в него, приняв технический дефект за проявление личности. Более того, Света хочет связать свою жизнь с чутким, внимательным и заботливым роботом, и это приводит к самым неожиданным последствиям…","poster":"https://image.tmdb.org/t/p/w500/s8h8GfOIcqsLVFbAxuOadWM1KLy.jpg","url":"https://www.themoviedb.org/movie/576987","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фантастика","Романтика"]},{"title":"Необитаемый остров","rating":null,"tier":"unrated","review":"","desc":"Второй фильм из цикла \"Рассказы старого моряка\". На этот раз герои попадают в XVIII век к пиратам Карибского моря. Знание истории той эпохи и биологии моря помогает им спастись.","poster":"https://image.tmdb.org/t/p/w500/7ci8IblMHHlk5oUCbClZmZPvGJh.jpg","url":"https://www.themoviedb.org/movie/1366378","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Боевик"]},{"title":"Несносный дед","rating":null,"tier":"unrated","review":"","desc":"86-летний старикан по имени Ирвинг Зисман путешествует по Америке с необычным компаньоном — восьмилетним «внуком» Билли. По дороге заводной дедушка знакомит впечатлительного Билли с людьми, местами и ситуациями, которые вряд ли укладываются в рамки привычных представлений о воспитании. Парочка столкнется со стриптизерами, разъяренными участниками помпезного детского конкурса красоты и их не менее злыми мамашами, скорбящими посетителями панихиды, завсегдатаями бара для байкеров и другими ничего не подозревающими гражданами США.","poster":"https://image.tmdb.org/t/p/w500/i6N2A63bLtNbeS80zusni6mf4pm.jpg","url":"https://www.themoviedb.org/movie/208134","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Неувольняемый","rating":null,"tier":"unrated","review":"","desc":"Венсан обожает свою непыльную работу. Однако грядет массовое сокращение госслужащих. Начальница Изабель всеми силами пытается найти причину для его увольнения, а он категорически отказывается уходить по собственному желанию. В ее власти командировать его в самые сложные и удаленные места службы: от африканской глуши и амазонских джунглей до Северного полюса. Кто победит в этой схватке не на жизнь, а на повышенную пенсию?","poster":"https://image.tmdb.org/t/p/w500/nSQRdqZ4fyy3Ll5OIPMsWZhTZba.jpg","url":"https://www.themoviedb.org/movie/745608","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Неудачники","rating":null,"tier":"unrated","review":"","desc":"Эксцентричная французская комедия Жана-Пьера Жене. Базиль пережил ранение в голову случайной пулей. Лишившись работы и жилья, он знакомится с колоритной компанией чудаков со свалки и решает отомстить двум крупнейшим оружейным концернам Парижа.","poster":"https://image.tmdb.org/t/p/w500/fTOlKrr1LauQFOuwJVRBit66DN2.jpg","url":"https://www.themoviedb.org/movie/27936","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Приключения"]},{"title":"Неудержимые","rating":null,"tier":"unrated","review":"","desc":"Отряд профессиональных наёмников и отчаянных парней во главе с Барни Россом получает непростое задание - любой ценой найти и уничтожить кровавого тирана-диктатора, нагнетающего страх на мирное население и сеющего хаос в южноамериканской стране.  Отправляясь на выполнение нелёгкой миссии, закалённые огнём и водой, прошедшие не одну войну, люди Росса попадают в самое пекло. Отныне им придётся выживать: сплотиться и достигнуть цели, либо отчаяться и погибнуть. И всё же эти храбрые, поистине невозмутимые ребята готовы реализовать даже не реализуемое. Но не всё так просто, как кажется на первый взгляд...","poster":"https://image.tmdb.org/t/p/w500/kx6qXzlYwM6lYi8PvU3XhBcmPDq.jpg","url":"https://www.themoviedb.org/movie/27578","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Приключения","Боевик"]},{"title":"Никто","rating":null,"tier":"unrated","review":"","desc":"Непримечательный и незаметный семьянин Хатч живёт скучной жизнью обычного аудитора, пока однажды в его дом не вламываются грабители. И это бы сошло им с рук, если бы они не забрали браслетик его маленькой дочки. Не в силах это терпеть, Хатч отправляется на поиски наглецов, а на обратном пути ввязывается в драку с пьяными хулиганами, пристававшими к девушке в общественном транспорте. От души помахав кулаками, наш аудитор отправляет дебоширов в больницу, но оказывается, что один из пострадавших — брат влиятельного русского бандита. И он теперь жаждет мести.","poster":"https://image.tmdb.org/t/p/w500/izl5fI8GnvT9NGCacv3VjxlvViJ.jpg","url":"https://www.themoviedb.org/movie/615457","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Драма"]},{"title":"Новейший завет","rating":null,"tier":"unrated","review":"","desc":"Да, Бог существует. Но он совсем не такой, каким мы его представляли. Он живет в Брюсселе, и у него есть не только сын, но и дочь. Она сбегает из дома и отправляется в наш мир искать приключения и испытывать терпение своего отца на прочность. Надолго ли его хватит?..","poster":"https://image.tmdb.org/t/p/w500/uSe3BH1Lz7Jz8BahYDaAN2smFRq.jpg","url":"https://www.themoviedb.org/movie/330764","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Драма"]},{"title":"НОУ","rating":null,"tier":"unrated","review":"","desc":"Бонду дано задание выяснить что является источником электронных помех в компьютерах американских пусковых шахт на мысе Канаверал. По агентурным данным мозговой центр вражеских сил находится на Ямайке. Бонд незамедлительно выдвигается туда.  В процессе расследования ему придется столкнуться с могущественной структурой СПЕКТР и ее представителем Доктором Ноу, готовым пойти на все, лишь бы держать весь мир в своих металлических руках. И только Бонд и его верный Вальтер ППК могут остановить злые силы на знойном океанском побережье.","poster":"https://image.tmdb.org/t/p/w500/hEvrqTMm1DkyCMMYQkJsFHmQ8dZ.jpg","url":"https://www.themoviedb.org/movie/646","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Боевик","Триллер"]},{"title":"Няня","rating":null,"tier":"unrated","review":"","desc":"Сюжет развивается вокруг Фрэн Файн — энергичной и экстравагантной еврейки из Квинса, которую бросает и увольняет с работы ее жених Денни Империали. Работая теперь продавщицей косметики, Фрэн попадает в дом Максвелла Шеффилда — известного Бродвейского продюсера, вдовца и отца троих детей. Максвелл устраивает вечеринку для потенциальных инвесторов, и ему позарез нужна няня, что бы присмотреть за детьми. В отчаянии он берет на работу Фрэн, хотя и сомневается в своем выборе.","poster":"https://image.tmdb.org/t/p/w500/4syShXMjaPAP3mG81ekhruv94sd.jpg","url":"https://www.themoviedb.org/tv/2352","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Семейный","Драма"]},{"title":"Обратный отсчёт","rating":null,"tier":"unrated","review":"","desc":"Константин Корсаков ведёт запутанные уголовные дела. Он хладнокровен и беспощаден к самому себе. Каждый день Корсаков имеет дело с жертвами злоумышленников, которые во что бы то ни стало хотят отомстить своим обидчикам. Корсакову нужно предотвратить новые преступления и удержать пострадавших от непоправимых ошибок. В этом ему помогают коллеги: старшие лейтенанты Инга Гордеева, Макс Лобов и лейтенант Люся Алёхина.","poster":"https://image.tmdb.org/t/p/w500/x3kliPTtsfFedspqkoaaLhBSW30.jpg","url":"https://www.themoviedb.org/tv/293678","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Детектив"]},{"title":"Ограбление по-джентльменски","rating":null,"tier":"unrated","review":"","desc":"После дерзкого побега из тюрьмы самый известный вор в мире Ричард Пейс заключает сделку с «Командой изгоев», которые грабят богатых и отдают деньги бедным. Под началом бывалого вора-джентльмена новые Робин Гуды нацеливаются на крупнейшее хранилище золотых слитков в мире, владелец которого — Уорнер Шольц — отмывает деньги международных преступников, а по совместительству является давним врагом Пейса. Грабить они будут красиво, задорно и со вкусом — по-джентльменски.","poster":"https://image.tmdb.org/t/p/w500/gwsawMRP0gMcCYfWdtVsBn6EpHb.jpg","url":"https://www.themoviedb.org/movie/581644","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Драма"]},{"title":"Ограбление президента","rating":null,"tier":"unrated","review":"","desc":"Банда грабителей решает обчистить незаконные предвыборные фонды Ричарда Никсона. План, разумеется, даёт сбой, и приходится действовать по обстоятельствам.","poster":"https://image.tmdb.org/t/p/w500/gXSFzSKoceCVS2g6cljgTqa2n8y.jpg","url":"https://www.themoviedb.org/movie/433499","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Триллер"]},{"title":"Одержимая","rating":null,"tier":"unrated","review":"","desc":"Вернувшись домой из длительной командировки, Марк обнаруживает, что за время отсутствия стал для жены совсем чужим человеком. Он решает узнать всю правду. Постепенно выясняется, что дело в чём-то большем, чем обычная любовная интрижка. С каждым днем супруги все глубже погружаются в пучину безумия, перерастающего в кровавый кошмар.","poster":"https://image.tmdb.org/t/p/w500/6ztSOW2XF6GsDw59JuMgvbZMJEK.jpg","url":"https://www.themoviedb.org/movie/21484","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"Однажды в голливуде","rating":null,"tier":"unrated","review":"","desc":"1969 год, золотой век Голливуда уже закончился. Известный актёр Рик Далтон и его дублер Клифф Бут пытаются найти свое место в стремительно меняющемся мире киноиндустрии.","poster":"https://image.tmdb.org/t/p/w500/nHg4GLAPjo8rhRkzv6lLfGwuRJq.jpg","url":"https://www.themoviedb.org/movie/466272","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Одноклассники","rating":null,"tier":"unrated","review":"","desc":"5 друзей детства встречаются после 30 лет разлуки в летнем доме у озера на уик-энд в День независимости. Они приехали сюда с семьями, чтобы почтить память школьного тренера по баскетболу и отпраздновать тридцатую годовщину чемпионата, в котором они вместе выиграли.","poster":"https://image.tmdb.org/t/p/w500/n7Hx7Arnv3SmfTv3Kli9NSPalHd.jpg","url":"https://www.themoviedb.org/movie/38365","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Опасная ложь","rating":null,"tier":"unrated","review":"","desc":"Когда богатый пожилой мужчина умирает и неожиданно оставляет свое имение новой сиделки, её втягивают в паутину обмана и убийств. Если она выживет, ей придется ставить под сомнение мотивы каждого - даже людей, которых она любит.","poster":"https://image.tmdb.org/t/p/w500/5qDNZryGFPFSzwgSKdj2FrBBoC9.jpg","url":"https://www.themoviedb.org/movie/689723","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Драма","Комедия"]},{"title":"Опасные долги","rating":null,"tier":"unrated","review":"","desc":"Криминальный боевик Дэвида Эйра («Выбивая долги» / The Tax Collector, 2020). Дэвид и Крипер работают коллекторами для криминального авторитета, собирая дань с банд по всему Лос-Анджелесу. Но когда из Мексики возвращается давний соперник босса, под смертельным ударом оказывается весь их бизнес и семьи.","poster":"https://image.tmdb.org/t/p/w500/fVR1vju4FJN0Zj4k6ajk5wsmTA9.jpg","url":"https://www.themoviedb.org/movie/531499","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Криминал","Драма"]},{"title":"Особо опасна","rating":null,"tier":"unrated","review":"","desc":"Меган — спецагент международного класса. В свои шестнадцать она владеет карате, стреляет без промаха и способна обезвредить взрослого вооруженного мужчину. Но Меган мечтает о жизни простого тинейджера — с тусовками и дискотеками. И судьба предоставляет ей такую возможность, но очень скоро супердевушка понимает, что в школе бывает опаснее, чем на на самой сложной спецоперации.","poster":"https://image.tmdb.org/t/p/w500/67qGv7tvrwp5w4awuCe1HI9QPmg.jpg","url":"https://www.themoviedb.org/movie/248574","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения","Романтика"]},{"title":"От любви не  убежишь","rating":null,"tier":"unrated","review":"","desc":"Еще не оправившись после разорванной помолвки и карьерного краха, певица отправляется работать на шикарный островной курорт... где ее бывший собирается пожениться.","poster":"https://image.tmdb.org/t/p/w500/17oadzgRWfYiG5KqKaBLNIcO8jf.jpg","url":"https://www.themoviedb.org/movie/785539","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Комедия","Драма"]},{"title":"Отряд самоубийц: Миссия навылет","rating":null,"tier":"unrated","review":"","desc":"Отобрав наиболее перспективных заключенных из тюрьмы, в которой содержатся не только самые опасные преступники, но и люди со свехрспособностями, и даже не люди, правительственный агент отправляет их на самоубийственное задание в одну латиноамериканскую страну, где недавно произошел военный переворот. А чтобы те наверняка не сбежали, каждому в голову вживляется взрывное устройство.","poster":"https://image.tmdb.org/t/p/w500/asD8pGLw2uI3HzPtjuX8ls8RNsg.jpg","url":"https://www.themoviedb.org/movie/436969","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения"]},{"title":"Отцовство","rating":null,"tier":"unrated","review":"","desc":"Мэтт, чья жена умерла во время родов, оказывается один с маленькой дочкой на руках. Он не был готов стать отцом, но вынужден взять себя в руки и начать заботиться о ребёнке.","poster":"https://image.tmdb.org/t/p/w500/mb1wbPGN5X8sXRhWkaCXRhpDOFf.jpg","url":"https://www.themoviedb.org/movie/607259","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Охотник за головами","rating":null,"tier":"unrated","review":"","desc":"Бывший музыкант и охотник за головами Хаб Хэллоран погибает по вине нового ухажера своей экс-жены, но дьявол возвращает его к жизни, чтобы тот истреблял демонов. Теперь Хабу предстоит скрывать от матери свою нечеловеческую сущность, мстить бывшему сопернику и выяснить, зачем чертовщина лезет в их тихий городок.","poster":"https://image.tmdb.org/t/p/w500/hOH1JUTHNCig2wfAtLJIr4E1Ste.jpg","url":"https://www.themoviedb.org/tv/229711","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фантастика","Фэнтези","Комедия","Детектив"]},{"title":"Охотник на монстров","rating":null,"tier":"unrated","review":"","desc":"Лейтенант Артемис и её солдаты с Земли случайно попадают в параллельный мир, где обитают разнообразные монстры. Закалённые бойцы оказываются в необычной ситуации и вынуждены использовать все свои навыки, чтобы пережить встречу с фантастическими тварями. Спасти их может только загадочный Охотник, который как никто умеет убивать монстров.","poster":"https://image.tmdb.org/t/p/w500/hJbbx83Wj6JX4Mew0bVApKoqYRx.jpg","url":"https://www.themoviedb.org/movie/458576","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Приключения"]},{"title":"Очень голодные игры","rating":null,"tier":"unrated","review":"","desc":"Храбрая девушка по имени Кантмисс Эвершот вызывается добровольцем для участия в «Играх за хавчик». Однако она даже предположить не могла, чем всё это закончится и кто будет сражаться вместе с ней.","poster":"https://image.tmdb.org/t/p/w500/9nloXqqo5qQhRdZmflDtGrMx9Vn.jpg","url":"https://www.themoviedb.org/movie/225703","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Очень плохие девчонки","rating":null,"tier":"unrated","review":"","desc":"Что может омрачить развеселый и безбашенный девичник в Майами? Наверное, только нелепая смерть стриптизера. Теперь подружкам предстоит выпутаться из дурацкой истории и как-то замести следы, пока они не попали в руки к копам.","poster":"https://image.tmdb.org/t/p/w500/iDo342QwoqAkIYMTih5n7p9Cm3R.jpg","url":"https://www.themoviedb.org/movie/397422","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Комедия","Триллер"]},{"title":"Очень страшное кино 4","rating":null,"tier":"unrated","review":"","desc":"Журналистка Синди Кэмпбелл всё ещё не может оправиться после ужасных событий, произошедших с ней за последнее время. Чтобы сменить обстановку, она устраивается на работу сиделкой к пожилой женщине. Вскоре Синди знакомится с овдовевшим соседом Томом и влюбляется в него. Казалось бы, жизнь начинает налаживаться, как вдруг на Землю высаживаются инопланетяне, которые хотят уничтожить всё человечество.","poster":"https://image.tmdb.org/t/p/w500/36I3eeaMjrO6lUCmQJzA32Wkv4S.jpg","url":"https://www.themoviedb.org/movie/4257","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Очень страшное кино 5","rating":null,"tier":"unrated","review":"","desc":"Молодая супружеская пара Дэн и Джоди начинают замечать некоторые странные активности, когда они приносят своего новорожденного ребёнка Айдена домой из больницы. Но когда нарастают проблемы и хаос в работе Джоди и карьере Дэна, они понимают, что их семью преследуют гнусные демоны. Вместе с советом сертифицированных специалистов и при помощи многочисленных камер, они должны выяснить, как избавиться от этих существ, пока не стало слишком поздно.","poster":"https://image.tmdb.org/t/p/w500/yZZi7bGVOfEyWeOeCdISFPspWOb.jpg","url":"https://www.themoviedb.org/movie/4258","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Порнолоджи, или Милашка как ты","rating":null,"tier":"unrated","review":"","desc":"Когда Люси Нил застукала своего бойфренда за просмотром эротических фильмов, он назвал её «сексофобкой». В попытке доказать ему, что он не прав, Люси решила больше узнать об этом феномене. Как и любой хороший исследователь, она составила довольно дикий список дел, который отправляет её в удивительное путешествие самопознания, дружбы и новой любви.","poster":"https://image.tmdb.org/t/p/w500/bDUm7JB40dfnFS6lPlfS0IG0X5f.jpg","url":"https://www.themoviedb.org/movie/718840","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Папа-досвидос","rating":null,"tier":"unrated","review":"","desc":"Переспав с «очень плохой училкой» прямо в школе, тинейджер становится отцом «по залету», а его зрелая пассия попадает в тюрьму за совращение малолетнего. Теперь юный папа-одиночка вынужден заботиться о сыне до его совершеннолетия, а затем благополучно исчезает в неизвестном направлении. И вот, много лет спустя, оказавшись на мели, эксцентричный папаша-инфантил словно ураган врывается в жизнь сына накануне его свадьбы, и своими безумными выходками переворачивает всё вверх дном.","poster":"https://image.tmdb.org/t/p/w500/AqaRFb83lNhqWvhwkpfy8Hslk1V.jpg","url":"https://www.themoviedb.org/movie/87428","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Пара на праздник","rating":null,"tier":"unrated","review":"","desc":"Сытые по горло одиночеством по праздникам, незнакомые до этого девушка и парень соглашаются быть парой на праздники в течение всего года, но неожиданно они попутно начинают испытывать к друг другу настоящие чувства.","poster":"https://image.tmdb.org/t/p/w500/aCdJsARgdVj2URgoXlpvjibSuv7.jpg","url":"https://www.themoviedb.org/movie/615665","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Парни со стволами","rating":null,"tier":"unrated","review":"","desc":"Реальная история о приятелях-планокурах из Майами, умудрившихся выбить в Пентагоне контракт на 300 миллионов долларов на поставку оружия.","poster":"https://image.tmdb.org/t/p/w500/4B8eiy4zIliE5sGLktkmQBnOStG.jpg","url":"https://www.themoviedb.org/movie/308266","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Драма"]},{"title":"Пассажир 57","rating":null,"tier":"unrated","review":"","desc":"Через несколько недель после начала жизни в доме на колёсах молодая пара становится свидетелями страшной аварии, в которой погибает водитель. Вскоре их начинает преследовать демоническая сущность, от которой невозможно уйти — куда бы они ни отправились, она следует за ними.","poster":"https://image.tmdb.org/t/p/w500/grlCRoCv2uT7WGvpkWSKxjPPVqc.jpg","url":"https://www.themoviedb.org/movie/1368314","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Драма"]},{"title":"Пассажиры","rating":null,"tier":"unrated","review":"","desc":"В системе космического корабля, перевозящего колонистов на далёкую планету, происходит сбой. В результате главный герой выходит из гиперсна на 90 лет раньше положенного срока. Оставшись с перспективой стареть и умирать в одиночестве, он будит прекрасную девушку, которой такой расклад, само собой, придётся не по душе...","poster":"https://image.tmdb.org/t/p/w500/RY7YPqLRkgK5KiIq3kFQhCUJnB.jpg","url":"https://www.themoviedb.org/movie/274870","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Фантастика"]},{"title":"Петля времени","rating":null,"tier":"unrated","review":"","desc":"В недалеком будущем, где стали возможны путешествия во времени, некая корпорация убирает нежелательных людей, отправляя их в прошлое в пластиковых пакетах. Задача принимающей стороны — всадить жертве пулю в голову, стерев тем самым несчастного из истории. Все идет гладко до тех пор, пока главный герой не распаковывает очередной пакет, обнаруживая в нем… самого себя из будущего.","poster":"https://image.tmdb.org/t/p/w500/moFUn35rGpj99XasdywgzjgL6Uw.jpg","url":"https://www.themoviedb.org/movie/59967","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Фантастика"]},{"title":"Пианист","rating":null,"tier":"unrated","review":"","desc":"Фильм снят по автобиографии Владислава Шпильмана, одного из лучших пианистов Польши 30-х годов прошлого века. Главный герой фильма — Владек — занимается искусством до тех пор, пока территорию Польши не занимают нацисты. Жизнь всех евреев меняется: их помещают в Варшавское гетто, запрещают работать, унижают, заставляют носить отличительные повязки, а через некоторое время отправляют в концлагерь.","poster":"https://image.tmdb.org/t/p/w500/eih8OFL5Kc4nrGU821jxU5rWINx.jpg","url":"https://www.themoviedb.org/movie/423","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Военный","Триллер"]},{"title":"Пикей","rating":null,"tier":"unrated","review":"","desc":"ПиКей, инопланетянин, высаживается на Землю в городе, расположенном в пустыне Раджастан, для изучения человеческой природы и жизни на Земле. Но планета встретила его довольно грубо — у него украли пульт дистанционного управления, с помощью которого он держал связь с космическим кораблем. Теперь он должен найти пульт, а до тех пор ему придется выживать на Земле по-своему. ПиКей задает вопросы, которые никто не задавал раньше. Его детское любопытство приводит к катастрофическим последствиям. Люди, сформировавшиеся на протяжении многих поколений, вынуждены переоценивать свой мир, глядя на него невинными глазами ПиКея.","poster":"https://image.tmdb.org/t/p/w500/cvyJc3AnCdmQADv0meJfwN0yGBE.jpg","url":"https://www.themoviedb.org/movie/297222","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Фантастика"]},{"title":"Плейбой под прикрытием","rating":null,"tier":"unrated","review":"","desc":"Ники Ларсон — супердетектив и самый крутой телохранитель в мире. Его ждёт опасная миссия — найти похищенный парфюм, который делает привлекательным для противоположного пола любого, кто им пользуется…","poster":"https://image.tmdb.org/t/p/w500/25LEB8zxdz4qdEfKNDa1bxmRpXU.jpg","url":"https://www.themoviedb.org/movie/469274","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Приключения"]},{"title":"Помогите я уменьшил своих родителей","rating":null,"tier":"unrated","review":"","desc":"Новый год, новые приключения. После короткой встречи с ненавистной директрисой Хульдой Стехбарт родители Феликса уменьшаются до размера карандаша. Теперь Феликс за них в ответе — ведь мама с папой легко помещаются ему в ладонь. Со своими друзьями он разрабатывает план, как вернуть родителям прежний размер, а заодно освободить настоящего директора фрау Шмидт и помешать Хульде Стехбарт захватить в школе власть.","poster":"https://image.tmdb.org/t/p/w500/mz1JkqyqHR0RY69jxYapj1a0uK1.jpg","url":"https://www.themoviedb.org/movie/454545","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Приключения","Семейный"]},{"title":"Попробуй подкати","rating":null,"tier":"unrated","review":"","desc":"Успешный бизнесмен и эгоистичный мачо пускает в ход все свои уловки, чтобы соблазнять девушек. Но однажды он сам оказывается в крайне щекотливой ситуации.","poster":"https://image.tmdb.org/t/p/w500/iYkrVfB7twml5aNRVoICB44qkLJ.jpg","url":"https://www.themoviedb.org/movie/458534","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Портал","rating":null,"tier":"unrated","review":"","desc":"XXI век. В Великобритании начинают  происходить необъяснимые вещи: в разных уголках страны люди замечают  животных, которые по утверждению палеонтологов вымерли миллионы  лет назад. Британское правительство создает тайное научное агентство  во главе с Джеймсом Лестером. Члены этой организации выясняют, что в  природе существуют некие загадочные дыры между современным  и доисторическим мирами, которые они называют . Целью  ученых является обнаружение этих «аномалий» и нейтрализация проникающих  через них опасных для человечества существ…","poster":"https://image.tmdb.org/t/p/w500/pjRhnncEnTT8T5YsLbTb0A4msuQ.jpg","url":"https://www.themoviedb.org/tv/10268","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Боевик","Приключения","Драма"]},{"title":"Посланники","rating":null,"tier":"unrated","review":"","desc":"Cемья Соломон оставляет свою размеренную жизнь в Чикаго ради того, чтобы пожить на уединенной ферме в Северной Дакоте. Среди усыпанных подсолнухами идиллических полей, шестнадцатилетняя Джесс очень скоро понимает, каким кошмаром может обернуться уединение. Сразу после переезда, Джесс и ее трехлетний брат Бен видят зловещих призраков, которых никто кроме них не замечает.  Когда призраки начинают вести себя агрессивно, у родителей появляются сомнения в психическом здоровье Джесс. Ее небезоблачное прошлое сталкивается с прошлым тех, кто когда-то жил в этом доме — опасное соседство для раздираемого противоречиями подростка. Ей не верят те, кого она отчаянно пытается предупредить, пока еще не слишком поздно…","poster":"https://image.tmdb.org/t/p/w500/qIRspsWXxgEa6ZxPIaVNJIOWDJR.jpg","url":"https://www.themoviedb.org/movie/9966","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Триллер","Ужасы"]},{"title":"После","rating":null,"tier":"unrated","review":"","desc":"Случайная встреча перевернула их привычный мир. Она — прилежная студентка и образцовая дочь, а он — дьявольски притягательный бунтарь из богатой семьи. Живя в параллельных вселенных, они бы вряд ли даже взглянули друг на друга. Однако этому знакомству суждено разделить жизнь влюбленных на до и после…","poster":"https://image.tmdb.org/t/p/w500/7Prt3Le9H0EeRYVltAXFJqwDIig.jpg","url":"https://www.themoviedb.org/movie/537915","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Триллер"]},{"title":"Последний богатырь","rating":null,"tier":"unrated","review":"","desc":"Фильм рассказывает об обычном парне Иване, который переносится из современной Москвы в фантастическую страну Белогорье. Параллельный мир населяют персонажи русских сказок, а волшебство здесь не является чем-то необычным. Герой оказывается в самом центре борьбы светлых и тёмных сил, и именно ему, как все считают, предстоит положить конец войне.","poster":"https://image.tmdb.org/t/p/w500/kWQh4iIt3WQvWrhMoukPCshzNsh.jpg","url":"https://www.themoviedb.org/movie/471968","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"]},{"title":"Последний богатырь: Корень зла","rating":null,"tier":"unrated","review":"","desc":"В Белогорье мир и спокойствие, зло побеждено. Рядом отец Илья Муромец, возлюбленная Василиса в предсвадебных заботах, ставшие друзьями Баба Яга и Водяной и маленькие радости из современного мира, чтоб обеспечить комфортную жизнь — благо Меч-Кладенец даёт возможность регулярно прорубать дыру между мирами и бегать за припасами. Но тоска по родному миру тяготит Ивана. А ещё больше его заботит неминуемое начало Богатырских игр — съезда всех витязей Белогорья, где добры молодцы будут показывать удаль и силу. Той самой Богатырской силушки в себе Иван не чувствует, и опозориться на глазах у отца и невесты ему совсем не хочется. Однако, когда в самый разгар состязаний пробуждается древнее зло и само существование волшебного мира оказывается под угрозой, Ивану приходится объединиться и со старыми друзьями, и с новыми недругами. Им предстоит отправиться в дальнее путешествие, за пределы известного мира, чтобы обнаружить истоки зла и вернуть мир в Белогорье.","poster":"https://image.tmdb.org/t/p/w500/9ZH3XulXJPHmXuOgZMqzXCvRB6K.jpg","url":"https://www.themoviedb.org/movie/589754","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Комедия"]},{"title":"Последний дом слева","rating":null,"tier":"unrated","review":"","desc":"Родители и дочь на выходные отправляются в загородный дом. Кажется удивительным, что подросток соглашается провести время подобным образом. Но все очень просто, недалеко живет ее подруга. Девушки знакомятся с парнем, у которого есть травка. Компания приходит в отель чтобы оттянуться, но тут появляются преступники, которые начинают глумиться над девушками. Затем они перемещаются в дом родителей девушки. Ничего не подозревающие родители предоставляют кров преступникам, но узнав о гибели дочери, отец-хирург начинает жестоко мстить…","poster":"https://image.tmdb.org/t/p/w500/lB6AlFsly6vTtesO3e45cYTmAV4.jpg","url":"https://www.themoviedb.org/movie/18405","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Триллер","Ужасы","Драма"]},{"title":"Посылка","rating":null,"tier":"unrated","review":"","desc":"Артур и Норма — молодая семья, которая испытывает финансовые затруднения. Неожиданно супруги становятся счастливыми обладателями коробочки с кнопкой.Им объясняют что, если нажать на кнопку, они немедленно получат 1 млн. долларов. Одна тонкость — в этот момент где-то умрет совершенно незнакомый им человек…","poster":"https://image.tmdb.org/t/p/w500/imNydslDYWQxYn2PboNa6ojssTX.jpg","url":"https://www.themoviedb.org/movie/22825","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Фантастика","Драма"]},{"title":"Чувствуй ритм","rating":null,"tier":"unrated","review":"","desc":"Не сумев добиться успеха на Бродвее, Эйприл возвращается в свой маленький родной город и неохотно набирается, чтобы подготовить неподходящую группу молодых танцоров для большого соревнования.","poster":"https://image.tmdb.org/t/p/w500/Af2jt7m9GLFpR4V11xOsFmT8OKD.jpg","url":"https://www.themoviedb.org/movie/707886","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Музыка","Драма"]},{"title":"Привидение","rating":null,"tier":"unrated","review":"","desc":"Сэм и Молли счастливы вместе, но однажды вечером на них нападает грабитель, и Сэм погибает. Однако его дух не покидает землю: он узнаёт, что смерть не была случайной, а Молли грозит смертельная опасность. Чтобы предупредить любимую, он связывается с эксцентричным медиумом Одой Мэй Браун.","poster":"https://image.tmdb.org/t/p/w500/684PPkWfczma004WFg7cq2Yqefg.jpg","url":"https://www.themoviedb.org/movie/251","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Романтика","Триллер"]},{"title":"Придурки на экзаменах","rating":null,"tier":"unrated","review":"","desc":"Директор школы хочет ввести новую систему обучения и ужесточить правила поведения на уроках. В свою очередь «детки» дают жару и строят всяческие козни не только администрации школы, но и друг другу!  Ведь непросто заниматься воспитанием «высокосознательных» учеников, которые протягивают электричество к дверным ручкам, активно занимаются сексом на уроках химии, притаскивают на занятия домашних животных и предпочитают беременность от несовершеннолетних отцов — постижению скучных наук!","poster":"https://image.tmdb.org/t/p/w500/6lw59oTZ0nCPmjYzxwM50vo0aGE.jpg","url":"https://www.themoviedb.org/movie/60175","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Призраки бывших подружек","rating":null,"tier":"unrated","review":"","desc":"Симпатичный холостяк приезжает на свадьбу своего младшего брата, где ему начинают являться призраки бывших подружек: каким-то невероятным образом он может видеть прошлое, настоящее и будущее своих экс-пассий.","poster":"https://image.tmdb.org/t/p/w500/8SXlfPKt4mBNrLwpJ1DA81hWiMW.jpg","url":"https://www.themoviedb.org/movie/12556","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Комедия","Фэнтези"]},{"title":"Призрачная красота","rating":null,"tier":"unrated","review":"","desc":"Главный герой работает в рекламном агентстве Нью-Йорка. Не так давно в его личной жизни произошла трагедия, ввергнувшая его в тяжелейшую депрессию. Коллеги пытаются помочь и разрабатывают нетрадиционный план по возвращению друга обратно на твёрдую почву, однако план срабатывает неожиданным образом.","poster":"https://image.tmdb.org/t/p/w500/jg4jZrbGCve8qfPbZYITADwRfbU.jpg","url":"https://www.themoviedb.org/movie/345920","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Триллер"]},{"title":"Призрачный патруль","rating":null,"tier":"unrated","review":"","desc":"Детективы из загробного департамента расследуют преступления по ту сторону могилы и гоняются за не в меру ретивой нечистью. Молодой коп, после гибели от руки неизвестного злоумышленника угодивший в мир иной, в обмен на помощь при расследовании собственного убийства обязуется следующие сто лет посвятить службе в R.I.P.D. и, получив в напарники брутального стрелка эпохи вестернов, выходит на борьбу с неупокоившимся злом.","poster":"https://image.tmdb.org/t/p/w500/aPqHFuWMiY9yWfUexoIP56cJdVq.jpg","url":"https://www.themoviedb.org/movie/49524","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Боевик","Комедия"]},{"title":"Притворись моей женой","rating":null,"tier":"unrated","review":"","desc":"Главный герой Дэнни встретил Палмер, и чтобы произвести впечатление, рассказал о своей несуществующей жене и тяготах семейной жизни. Вместо ожидаемого сочувствия, Палмер хочет познакомится с его женой, и Дэнни необходимо срочно придумать, как выпутаться из столь интересного положения. К счастью, у него есть знакомая коллега Кэтрин, обаятельная и с детьми, которые и сыграют на время роль его семьи.","poster":"https://image.tmdb.org/t/p/w500/sn085yZBrbQdbYo1LDAwsQ4P6ba.jpg","url":"https://www.themoviedb.org/movie/50546","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Прогулка по солнечному свету","rating":null,"tier":"unrated","review":"","desc":"После красивого, бурного и стремительного романа Мэдди и Раф принимают решение пожениться, а свадьбу сыграть на берегу Средиземного моря в Испании. Мэдди счастлива. Она готовится к церемонии, приглашает гостей, среди которых — ее любимая сестра Тэйлор. Кто мог предположить, что между Рафом и Тэйлор была когда-то страстная любовь, которая, как оказалось, вовсе не угасла…","poster":"https://image.tmdb.org/t/p/w500/cinzBoSTTENMpUPIILrEHE7To91.jpg","url":"https://www.themoviedb.org/movie/267863","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Проклятие Аннабель","rating":null,"tier":"unrated","review":"","desc":"Джон находит идеальный подарок для своей будущей жены — это редкая старинная кукла в белом свадебном платье. Но восторг от подарка продлился не долго. Однажды ночью в их дом вторгаются члены сатанинского культа…","poster":"https://image.tmdb.org/t/p/w500/i12HsW8jXnCoy5IieQEpFLush7O.jpg","url":"https://www.themoviedb.org/movie/250546","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"Проклятие Аннабель: Зарождение зла","rating":null,"tier":"unrated","review":"","desc":"Через несколько лет после трагической гибели их маленькой дочери кукольник и его жена приглашают в свой дом монахиню и нескольких девочек из приюта, вскоре становящихся мишенью для одержимого создания кукольника — Аннабель.","poster":"https://image.tmdb.org/t/p/w500/5Omlys7hQXOKFDdueBq63roIhVE.jpg","url":"https://www.themoviedb.org/movie/396422","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"Проклятие Аннабель 3","rating":null,"tier":"unrated","review":"","desc":"Преисполнившись решимости удержать Аннабель от дальнейших разрушений и хаоса, демонологи Эд и Лоррейн Уоррены приносят одержимую куклу в запертую комнату артефактов в своем доме, поместив ее под «надежное» освященное стекло и заручившись благословением священника. Однако беспросветная ночь ужаса ждет обитателей дома, когда Аннабель пробуждает злых духов комнаты и их новой мишенью становится десятилетняя дочь Уорренов Джуди и ее друзья.","poster":"https://image.tmdb.org/t/p/w500/jLqJCkyepldyxQhp28Kr6zsKcF3.jpg","url":"https://www.themoviedb.org/movie/521029","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"Проклятие плачущей","rating":null,"tier":"unrated","review":"","desc":"Ла Йорона. Плачущая женщина. Вселяющий ужас призрак, затерянный между Раем и Адом и загнанный в ужасную ловушку судьбы, запечатанную его собственной рукой. Простое упоминание ее имени сеет страх по всему миру уже многие поколения. Еще при жизни женщина утопила своих детей в порыве яростной ревности, бросившись в бушующую реку вслед за ними, рыдая от боли и отчаяния. Теперь ее слезы вечны и несут смерть. Тот, кто слышит ее предсмертный крик в ночи, обречен. Ла Йорона крадется в тени и охотится на детей, отчаянно пытаясь восполнить утрату собственных. Проходят столетия, она становится все более ненасытной… а её методы все более ужасными.","poster":"https://image.tmdb.org/t/p/w500/4PAoKDQAKMO94HxjWsonsEPk45Y.jpg","url":"https://www.themoviedb.org/movie/480414","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"Просто друзья","rating":null,"tier":"unrated","review":"","desc":"Мью - типичный студент-заучка, у которого нет времени ни на секс, ни на отношения. Однажды его друг Бостон сводит его с Топом, но предполагаемая интрижка на одну ночь выливается в нечто куда более серьёзное.    \n        \n    История компании друзей, которые не просто друзья, а может, и не друзья вовсе.","poster":"https://image.tmdb.org/t/p/w500/xVCkYP92OSq03bCqDJb7WhsKQfd.jpg","url":"https://www.themoviedb.org/tv/217807","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Прочь","rating":null,"tier":"unrated","review":"","desc":"Знакомство с родителями подружки не предвещает молодому чернокожему фотографу из Нью-Йорка ничего хорошего, ведь семья девушки принадлежит к элитному белому обществу и живет в уединенном загородном доме. Если бы он только знал истинную причину своего приглашения, то немедленно бросился бы прочь.","poster":"https://image.tmdb.org/t/p/w500/hkchWNmGfcgow2Jivyxv83JqHCy.jpg","url":"https://www.themoviedb.org/movie/419430","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Триллер","Ужасы"]},{"title":"Пусть идёт снег","rating":null,"tier":"unrated","review":"","desc":"В канун Рождества на небольшой городок обрушивается сильный буран. Поезда останавливаются, дороги перекрыты, а группа старшеклассников оказывается отрезанной от внешнего мира. Эта снежная буря кардинально изменит их дружбу и любовные отношения.","poster":"https://image.tmdb.org/t/p/w500/1Wakzc09OYr7GWfq2Eq1peA2JdS.jpg","url":"https://www.themoviedb.org/movie/295151","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Комедия","Драма"]},{"title":"Путешествия Гулливера","rating":null,"tier":"unrated","review":"","desc":"Лемюэль Гулливер, ищущий славы и сенсационного материала, отправляется в Бермудский треугольник, одно из самых таинственных мест планеты. Оттуда шторм уносит его в неизвестном направлении к острову, населённому крошечным народом, благодаря которому Гулливер вырвется из своего тесного мирка в большой мир.","poster":"https://image.tmdb.org/t/p/w500/oj165IiIp469ysflTjE62BAIzNr.jpg","url":"https://www.themoviedb.org/movie/38745","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Комедия","Приключения","Фэнтези"]},{"title":"Пятница 13-е   2009","rating":null,"tier":"unrated","review":"","desc":"Молодые друзья Уитни, Майк, Ричи, Аманда и Уэйд заблудились в лесах около заброшенного лагеря «Хрустальное озеро». Когда их любопытство взяло верх, они решили посетить то место, где когда-то обитал убийца-психопат. Тем временем Трент приглашает друзей: Джену, Брии, Чеви, Челси, Лоуренса и Нолана в его хижину, расположенную у озера, на уикэнд, полный секса, выпивки и наркотиков.Однако их забавный уикэнд, по-видимому, скоро перерастет в кошмар после того, как одинокий путешественник Клэй начинает поиски своей пропавшей сестры Уитни, и молодые тинейджеры вскоре оказываются лицом к лицу со злом, заново рожденным, невообразимым, и усовершенствованным, его имя Джейсон Вурхиз!","poster":"https://image.tmdb.org/t/p/w500/qoP4xq8YZff6clhfSfZYGiqm8xa.jpg","url":"https://www.themoviedb.org/movie/13207","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Драма"]},{"title":"Работа без авторства","rating":null,"tier":"unrated","review":"","desc":"Молодой художник Курт Барнерт сбегает из Восточной Германии в Западную, чтобы учиться живописи и свободно работать. Но прошлое настигает его, когда в отце своей возлюбленной он узнает человека, ответственного за страшные преступления. Курт разоблачит его через свои картины, которые со временем станут манифестом целого поколения.","poster":"https://image.tmdb.org/t/p/w500/xmkmFc5GucHDEEYJ2em3VHI5rUk.jpg","url":"https://www.themoviedb.org/movie/423612","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","История"]},{"title":"Расплата","rating":null,"tier":"unrated","review":"","desc":"Фрэнсис Хоген, молодой инженер Facebook, обращается за помощью к Джеффу Хорвицу, репортеру Wall Street Journal, чтобы отправиться в опасное путешествие, которое в конечном итоге раскрывает самые охраняемые секреты социальной сети.","poster":"https://image.tmdb.org/t/p/w500/7jK6NuxVg1XuEV7UdNa6KO03IgZ.jpg","url":"https://www.themoviedb.org/movie/1281331","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Триллер"]},{"title":"Револьвер","rating":null,"tier":"unrated","review":"","desc":"Семь лет назад Джейк влип в неприятную историю. Город был помешан на нелегальных азартных играх, организованных преступным боссом Мака. Однажды накануне большой игры Мака потерял своего парня, и Джейку Грину предложили пойти на замену. Под давлением Грин согласился и выиграл за карточным столом. С этого всё и началось.","poster":"https://image.tmdb.org/t/p/w500/toMYCAqf8l9NfUWr1Zb9jhUXwDy.jpg","url":"https://www.themoviedb.org/movie/10851","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Криминал","Детектив"]},{"title":"Руби спаркс","rating":null,"tier":"unrated","review":"","desc":"Молодой, но уже успешный писатель переживает творческие и душевные муки: новый роман никак не выходит, музы все нет, да и вообще с девушками как-то не клеится. И вот, призвав на помощь остатки своей фантазии, Кэлвин придумывает себе девушку по имени Руби Спаркс — умницу, красавицу, спортсменку, короче говоря, идеал, а спустя неделю… обнаруживает этот идеал из плоти и крови на своем собственном диване. Уходить Руби явно не собирается, но вот кем она окажется — Галатеей или Белочкой?..","poster":"https://image.tmdb.org/t/p/w500/eWeW8D3SoVZLbVIvHHJnbMjB5LX.jpg","url":"https://www.themoviedb.org/movie/103332","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Фэнтези","Драма"]},{"title":"С вещами на вылет","rating":null,"tier":"unrated","review":"","desc":"Несгибаемый коп Хосе Фернандес получает задание экстрадировать в Кабул обычного человека по имени Аким, которого по ошибке приняли за террориста. Аким никогда прежде не был ни в каком Кабуле, но для Хосе это не имеет никакого значения. Задание должно быть выполнено. Однако вынужденная посадка в Мальте внезапно меняет все карты. Теперь Хосе самого принимают за араба и им обоим приходится пуститься в бега.","poster":"https://image.tmdb.org/t/p/w500/lgCfU0n4fGJYmMQB0pY97gOo6Gv.jpg","url":"https://www.themoviedb.org/movie/382518","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"С холода","rating":null,"tier":"unrated","review":"","desc":"Бывшая русская шпионка с уникальными навыками, а теперь мать-одиночка из США разрывается между заботой о дочери и охотой на коварного врага, когда ее выходит ЦРУ.","poster":"https://image.tmdb.org/t/p/w500/n1eL0iQiLx141MSVbDoY4B24Oqo.jpg","url":"https://www.themoviedb.org/tv/146173","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Боевик","Приключения"]},{"title":"Самый быстрый индиан","rating":null,"tier":"unrated","review":"","desc":"Фильм рассказывает об истории жизни знаменитого новозеландца Берта Монро, который потратил десятилетия жизни на переоснащение своего любимого мотоцикла марки «Индиан» 1920 года выпуска с максимальной скоростью в 58 миль/ч в гоночный болид для установления рекорда скорости. И официальный рекорд (200 миль/ч) в конце концов был установлен! Это случилось в 1967 году…","poster":"https://image.tmdb.org/t/p/w500/oBFzq9Fdb8GIg8Pc2oFVTvkUmDZ.jpg","url":"https://www.themoviedb.org/movie/9912","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Приключения","История"]},{"title":"Киллер по вызову","rating":null,"tier":"unrated","review":"","desc":"В первый же день после освобождения из тюрьмы взломщик сейфов Ред и его подруга становятся мишенью киллера. Сея вокруг себя хаос, киллер шутит с акцентом, что мстит за убитую собаку. Не спеша уничтожать жертву, он явно ведет свою игру, истинной целью которой может быть вовсе не Ред.","poster":"https://image.tmdb.org/t/p/w500/7KehicphH1fNwlgTNUfZpxCEc0i.jpg","url":"https://www.themoviedb.org/movie/477508","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Криминал","Триллер"]},{"title":"Сигнал бедствия","rating":null,"tier":"unrated","review":"","desc":"Уставшая от своей серой жизни Ана переносится в другую реальность, где встречает небольшую группу девушек, живущую на берегу бескрайнего моря. В этом мире вечная весна, а на фоне залитых солнцем пейзажей идёт бесконечная война. Подобно сиренам, девушки посылают сигналы бедствия, обрекая несчастных моряков на погибель. Но когда ситуация начинает выходить из-под контроля, Ана понимает, что, возможно, в этом мире ей не место, а путь назад таит в себе множество опасностей…","poster":"https://image.tmdb.org/t/p/w500/zeYB6bMTysbc1QNZejCUAfWRmtM.jpg","url":"https://www.themoviedb.org/movie/672521","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Фэнтези","Драма"]},{"title":"Сирена","rating":null,"tier":"unrated","review":"","desc":"По легенде возле Бристольской бухты когда-то жили русалки. Однажды здесь появляется таинственная зеленоглазая девушка. Кому-то встреча с ней принесет смерть, а для кого-то она приоткроет старые тайны на первый взгляд безобидного провинциального города.","poster":"https://image.tmdb.org/t/p/w500/cj9DiCsZOkkm1qQja0OkLV1LCZx.jpg","url":"https://www.themoviedb.org/tv/71886","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма"]},{"title":"Скандал","rating":null,"tier":"unrated","review":"","desc":"Специалист по связям с общественностью Оливия Поуп, ранее работавшая на президента США, создает свое антикризисное агенство, цель которого — устранять проблемы высокопоставленных клиентов до того, как они станут всеобщим достоянием. Но если Вы посвящаете 24 часа в сутки решению проблем других людей, у Вас просто не будет времени, чтобы заняться своей собственной жизнью. Поэтому несмотря на то, что Оливия и ее команда самых блестящих специалистов прекрасно справляются с решением самых деликатных ситуаций своих клиентов, их собственная жизнь полна всякого рода проблем.","poster":"https://image.tmdb.org/t/p/w500/v02XUhody91leUUT5o3OvwzjUZd.jpg","url":"https://www.themoviedb.org/tv/39269","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Слепота","rating":null,"tier":"unrated","review":"","desc":"Место действия фильма — огромный мегаполис, у которого нет названия. Именно здесь начинается странная эпидемия… эпидемия слепоты. Жители города теряют зрение один за другим и, это ставит целый мегаполис на грань жизни и смерти. Лишь одна женщина по неизвестной причине осталась видеть. Сможет ли она стать проводником для других?","poster":"https://image.tmdb.org/t/p/w500/2wV1cVpY39RlMyYpJRLHRQ3giGd.jpg","url":"https://www.themoviedb.org/movie/8338","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","Фантастика","Триллер"]},{"title":"Сикарио","rating":null,"tier":"unrated","review":"","desc":"Безлюдные пустоши, по которым проходит граница между Мексикой и США, — это территория без правил, поле битвы между мексиканскими наркокартелями и американскими спецслужбами. Агент ФБР Кейт Мэйсер, которая работает в приграничных районах, старается придерживаться собственных идеалов, хотя и начинает ощущать, что исход войны с наркотрафиком складывается не в пользу служителей закона.\r Однажды ей предоставляется шанс принять участие в работе элитного подразделения по борьбе с наркотиками, возглавляемого агентом Мэттом Грейвером. Самый загадочный участник команды — местный консультант, человек без имени, привычек, и, кажется, без прошлого. Его истинное лицо откроется только в ходе рискованной операции, во время которой Кейт будет вынуждена поступиться собственными принципами, чтобы остаться в живых.","poster":"https://image.tmdb.org/t/p/w500/8uV8nnOejsd6GSi2KfeFCM5u05F.jpg","url":"https://www.themoviedb.org/movie/273481","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Криминал","Триллер"]},{"title":"Смешанные","rating":null,"tier":"unrated","review":"","desc":"После катастрофического свидания «вслепую»  родители-одиночки Лорен и Джим согласны только в одном: они не хотят больше видеть друг друга никогда! Полагая, что их знакомство окончено, обе семьи пользуются удобным случаем и отправляются в идеальный отпуск с детьми. А оказываются в одних и тех же гостиничных апартаментах на роскошном южноафриканском курорте аж на целую неделю.","poster":"https://image.tmdb.org/t/p/w500/jyFa15o2cZQ4A0OzwppZowLnvoJ.jpg","url":"https://www.themoviedb.org/movie/232672","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Собачья жизнь","rating":null,"tier":"unrated","review":"","desc":"Собаки бывают разных пород, мастей и размеров. Они — наши самые верные и преданные друзья, а мы учим их хорошим манерам. Собаки всегда думают о нас, правда, иногда и о беконе. Все они каждый день провожают и встречают нас у порога в уверенности, что пока им есть, кого облизывать и любить, в их жизни есть смысл.","poster":"https://image.tmdb.org/t/p/w500/iTSNCcbjehovQf26YcW2uTRKBhH.jpg","url":"https://www.themoviedb.org/movie/381289","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фэнтези","Семейный","Драма"]},{"title":"Соник 2 в Кино","rating":null,"tier":"unrated","review":"","desc":"Поселившись в Грин Хилз, Соник стремится доказать, что у него есть все задатки настоящего героя. И геройское испытание не заставляет себя долго ждать: злодейский доктор Роботник вновь строит козни. На этот раз с загадочным напарником Наклзом. Вместе они разыскивают бесценный изумруд, в котором заключены силы, способные уничтожать целые цивилизации. Соник объединяется с лисёнком Тейлзом, чтобы отправиться в кругосветное путешествие и найти изумруд до того, как он попадет в плохие руки.","poster":"https://image.tmdb.org/t/p/w500/6gi3bF0Qymv6Ja4FYIInLxa4xDU.jpg","url":"https://www.themoviedb.org/movie/675353","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Семейный","Комедия"]},{"title":"Сорвиголова","rating":null,"tier":"unrated","review":"","desc":"Ослеплённый с детства (из-за несчастного случая) адвокат Мэтт Мёрдок под именем «Сорвиголова» использует остальные, невероятно усиленные, чувства и бойцовские навыки для борьбы с преступностью на улицах ночной Адской кухни.","poster":"https://image.tmdb.org/t/p/w500/c47xj2YlMKPEMbLXlLriZaRnlXu.jpg","url":"https://www.themoviedb.org/tv/61889","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Боевик","Приключения"]},{"title":"Соседка","rating":null,"tier":"unrated","review":"","desc":"Старшеклассник Мэттью живёт спокойной жизнью, хорошо учится и строит планы на будущее. Всё меняется, когда по соседству поселяется обаятельная девушка Даниэль, и между ними быстро возникает взаимная симпатия. Однако вскоре Мэттью узнаёт, что у неё непростое прошлое, которое неожиданно возвращается и ставит под угрозу их отношения. Чтобы сохранить любовь и не отказаться от своих мечтаний, ему предстоит сделать непростой выбор, столкнуться с неожиданными испытаниями и понять, что взрослая жизнь редко бывает такой простой, как кажется.","poster":"https://image.tmdb.org/t/p/w500/yIOGYx5KidcOTzs2BlvCyBQ8d4L.jpg","url":"https://www.themoviedb.org/movie/10591","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Социальная сеть","rating":null,"tier":"unrated","review":"","desc":"Октябрьский вечер 2003 года. Студента Гарварда Марка Цукерберга бросает его девушка. Раздосадованный Марк, подогретый алкоголем, решает отомстить и публикует злобный и оскорбительный пост в адрес бывшей подруги. Но этого парню показалось мало. Он решает создать сайт, позволяющий сформировать рейтинг студенток по степени привлекательности. Марк взламывает базы данных различных общежитий, скачивает фотографии и всю необходимую информацию, используя алгоритм, предложенный его другом Эдуардо. После сбора данных Марк создаёт страницу facemash.com, где студенты могут проголосовать за одну из двух девушек, которая по их мнению является более привлекательной. Так начинается история создания одной из крупнейшей социальных сетей мира, которая впоследствии получит название Facebook.","poster":"https://image.tmdb.org/t/p/w500/mS14zRPoZxR7bmJ9m9JQT72cS3v.jpg","url":"https://www.themoviedb.org/movie/37799","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Спасите колю","rating":null,"tier":"unrated","review":"","desc":"У студентки Маши Матушкиной все в жизни могло быть прекрасно, если бы не одна большая проблема: вырастивший её в одиночку отец командует военкоматом. Из-за этого ни один парень возле Маши надолго не задерживается – один за другим они уезжают проходить армейскую службу по призыву в самые дальние уголки России. И хотя Маша искренне любит своего упрямого папу, окончательное столкновение характеров неизбежно. И так получается, что случится эта эпическая битва в день юбилея уважаемого военкома…","poster":"https://image.tmdb.org/t/p/w500/kuCCKHETtUdSzojtACTRDfyI65n.jpg","url":"https://www.themoviedb.org/movie/594899","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Старикам тут не место","rating":null,"tier":"unrated","review":"","desc":"Посреди техасской пустыни Ллевелин Мосс обнаруживает место кровавой бойни, партию героина и чемодан с двумя миллионами долларов. Решив забрать деньги, он запускает цепь опасных событий, в которую оказываются втянуты безжалостный убийца Антон Чигур и местный шериф Эд Том Белл.","poster":"https://image.tmdb.org/t/p/w500/yxQJriDjr16vj38nhhVqsdsk47L.jpg","url":"https://www.themoviedb.org/movie/6977","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Триллер","Вестерн"]},{"title":"Стокер","rating":null,"tier":"unrated","review":"","desc":"Во время съемок студенческого фильма главную актрису похищает странный человек на ржавой машине. Пытаясь спасти её, друзья девушки отправляются за ним в погоню, но впереди их ждет кромешный ад.","poster":"https://image.tmdb.org/t/p/w500/yJxL52rks4nFtrSPb6Y66N4AyRE.jpg","url":"https://www.themoviedb.org/movie/759426","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Детектив","Триллер"]},{"title":"Странный Томас","rating":null,"tier":"unrated","review":"","desc":"Главный герой наделен даром (или проклятием) видеть мертвецов. Каждый их визит становится началом очередной охоты на убийцу — призраки ведут Томаса на помощь тем, кому еще рано расставаться с жизнью. О способности героя знают только самые близкие друзья и любимая девушка. С их помощью ему предстоит отвести большую беду от маленького городка в центре пустыни Мохаве.","poster":"https://image.tmdb.org/t/p/w500/utySetJkNdYrHesMb0oKGa7JnFS.jpg","url":"https://www.themoviedb.org/movie/179826","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Триллер","Драма"]},{"title":"Стрелок 2007","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/tYf5Sc83chWG2nBlo5xKdpBBwlI.jpg","url":"https://www.themoviedb.org/tv/13859","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Вестерн","Семейный"]},{"title":"Субурбикон","rating":null,"tier":"unrated","review":"","desc":"Действие фильма происходит в тихом городке Субурбикон в 1950-е. Образцовая и добропорядочная семья переживает вторжение в свой дом, что вынуждает их идти на шантаж, предательство и месть.","poster":"https://image.tmdb.org/t/p/w500/lETTNP41N6lQkjBGlE98T3datwS.jpg","url":"https://www.themoviedb.org/movie/395458","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Криминал","Драма","Детектив"]},{"title":"Судья 2014","rating":null,"tier":"unrated","review":"","desc":"В центре истории — успешный адвокат, который приезжает в родной город на похороны матери и узнаёт, что его отца, городского судью, подозревают в убийстве. Герой решает задержаться, чтобы выяснить правду, и постепенно лучше узнаёт родственников, с которыми давно вообще никак не общался.","poster":"https://image.tmdb.org/t/p/w500/ojnzwkvFpytJWKtS0OcwOKgYL4F.jpg","url":"https://www.themoviedb.org/movie/205587","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Супергёрл","rating":null,"tier":"unrated","review":"","desc":"13-летнюю Кару Зор-Эл посылают на Землю, так как её родная планета Криптон была обречена. Её родители, Зор-Эл и Алура, просят её присмотреть за маленьким кузеном, Кал-Элом(Супермен), которого уже отправили на Землю. Также ей раскрывают, что под жёлтым солнцем она приобретёт экстраординарные силы.    \n        \n    Однако капсула Кары сбилась с курса в результате взрыва планеты и попала в Фантомную зону, где девочка пробыла 24 года, не постарев ни на день, так как в фантомной зоне время не идёт. К тому времени, когда она наконец попала на Землю, Кал-Эл уже вырос и стал Суперменом. Так как кузен больше не нуждался в ней, она была взята на попечение семьёй Денверсов, которые и вырастили её как свою родную дочь. Спустя 11 лет после прибытия на Землю она вынуждена использовать свои сверх-силы, которые до сих пор скрывала, чтобы спасти свою сводную сестру, и неожиданно становится известна как Супергёрл","poster":"https://image.tmdb.org/t/p/w500/7tfFwoh5gtATf0yFloSVnlgFQdj.jpg","url":"https://www.themoviedb.org/tv/62688","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фантастика","Фэнтези","Боевик","Приключения"]},{"title":"Таинственный альберт ноббс","rating":null,"tier":"unrated","review":"","desc":"1898 год, Дублин. В небольшой гостинице Morrison’s живут самые разные люди: сбежавший от жены престарелый доктор Холлоран, французские снобы мадам и мсье Пиго, экономное семейство Мур, не чуждый гомоэротических утех виконт Яррелл и его супруга со схожими сексуальными предпочтениями… И каждому из них стремится услужить официант Альберт Ноббс.  Ему чуть больше сорока, и он успел поработать в лучших заведениях Лондона, Бристоля и Ливерпуля. Личной жизни у него практически нет. Пабам и варьете Ноббс предпочитает тихие вечера в своей каморке и бесконечное пересчитывание сбережений. Коллеги практически не обращают на него внимания, и это ему даже на руку. Ведь на самом деле Альберт — женщина, уже около тридцати лет успешно выдающая себя за представителя сильного пола…","poster":"https://image.tmdb.org/t/p/w500/rzJBbf0eMeHcv3J8KIn52tbeQsd.jpg","url":"https://www.themoviedb.org/movie/73873","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Тайлер Рейк: операция по спасению","rating":null,"tier":"unrated","review":"","desc":"И без того непростая миссия наёмника превращается в отчаянную борьбу за жизнь, когда его отправляют в Бангладеш спасти похищенного сына наркобарона.","poster":"https://image.tmdb.org/t/p/w500/zD9fW1g5gB6mirfX8Wk3FhdlzBn.jpg","url":"https://www.themoviedb.org/movie/545609","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Драма"]},{"title":"Таймер","rating":null,"tier":"unrated","review":"","desc":"Новые технологии всегда меняли жизнь человека, а с изобретением ТАйМЕРа они смогли изменить и его личную жизнь. Это высокотехнологичное устройство имплантируется в запястье и начинает отсчёт времени, когда время на нём закончится, раздастся сигнал — оглянитесь, ваш идеальный партнёр перед вами. Так говорилось в рекламе и неудивительно, что одинокая Уна Олири, которой в личной жизни всегда не везло, поспешила воспользоваться заманчивым предложением. Но и тут ей не везёт, имплантированный ТАйМЕР не работает, «пока не работает» — уверяют производители. Вскоре Уна повстречает в супермаркете симпатичного продавца Майки и у них возникнут взаимные чувства. Она будет уверена в том, что встретила того единственного, которого ждала всю свою жизнь. Но на её запястье вдруг заработает ТАйМЕР, утверждающий, что только через четыре месяца к ней должна придти настоящая любовь.","poster":"https://image.tmdb.org/t/p/w500/fSekg5p0H4wJPGGpsPRshoyBWQl.jpg","url":"https://www.themoviedb.org/movie/39545","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Драма","Комедия","Фантастика","Романтика"]},{"title":"Тайный орден","rating":null,"tier":"unrated","review":"","desc":"Чтобы отомстить за смерть своей матери, студент колледжа заручается помощью тайного ордена и оказывается втянутым в войну оборотней и тёмных магов.","poster":"https://image.tmdb.org/t/p/w500/jCUvIvsbPDFk66fDnj1Rtnmo5Ds.jpg","url":"https://www.themoviedb.org/tv/82104","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","Фантастика","Фэнтези"]},{"title":"Телеведущий: Легенда о Роне Бургунди","rating":null,"tier":"unrated","review":"","desc":"1970-е годы. Рон Бургунди — самый популярный ведущий новостей в Сан-Диего, уверенный в собственном превосходстве. Но его карьера и привычный мир оказываются под угрозой, когда в студии появляется амбициозная и талантливая журналистка Вероника Корнингстоун.","poster":"https://image.tmdb.org/t/p/w500/xxdBGj0NMdMyLPgWv0ChlhzDT1K.jpg","url":"https://www.themoviedb.org/movie/8699","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Телеведущий 2","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/9QNqeKB4XodrvEiYewOTG9WEka5.jpg","url":"https://www.themoviedb.org/movie/37536","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Телесные игры","rating":null,"tier":"unrated","review":"","desc":"Когда размолвка длиной в пять лет прерывает многолетнюю дружбу шестерых друзей, Боб, также известный как Папаша Боб, решает воссоединиться с друзьями для «Телесных игр» — безумного состязания, состоящего из абсурдных физических и психологических заданий, с шансом сорвать солидный куш — 150 000 долларов. Все прогнозы бессмысленны, все правила забыты, а шестеро приятелей, твердо намеренных победить, отчаянно сражаются и безудержно веселятся ради бешеных денег.","poster":"https://image.tmdb.org/t/p/w500/pEBmMa95LqqdkrrWtFgMll4BIpg.jpg","url":"https://www.themoviedb.org/movie/472815","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Телекинез","rating":null,"tier":"unrated","review":"","desc":"Застенчивая старшеклассница Кэрри Уайт живёт с фанатично религиозной матерью и постоянно подвергается травле в школе. Когда у неё пробуждаются разрушительные телекинетические способности, жестокая шутка одноклассников на выпускном балу оборачивается кровавым кошмаром.","poster":"https://image.tmdb.org/t/p/w500/sEe3hu1yfHjVmlJL4gPkl4DTrp8.jpg","url":"https://www.themoviedb.org/movie/7340","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Драма"]},{"title":"Телохранитель бабушки","rating":null,"tier":"unrated","review":"","desc":"Где-то в Нью-Йорке гадалка предсказала бабушке большую удачу. Никогда не поздно начать жить в свое удовольствие. Бабушка сняла все деньги со счета и отправилась в казино. Сорвать огромный куш в казино? Да легко! Нанять телохранителя? Не проблема! Черпая вдохновение из остросюжетных телесериалов, бабушка оказывается в эпицентре настоящих бандитских разборок. Теперь несладко будет всем!","poster":"https://image.tmdb.org/t/p/w500/ibBtJc538VDyvNxnjCdvdNanHCb.jpg","url":"https://www.themoviedb.org/movie/597588","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Драма"]},{"title":"Тёмное зеркало","rating":null,"tier":"unrated","review":"","desc":"18-летняя старшеклассница Мария нелюбима родителями и отвергнута сверстниками. Будучи изгоем, она доверяет все свои секреты и переживания своему отражению в зеркале, своему воображаемому злому близнецу, который поддерживает, поощряет и знает все её тайны. Однажды она меняется местами со своим двойником, который начинает воплощать самые дикие и необузданные желания.","poster":"https://image.tmdb.org/t/p/w500/eLFTwvHiVyhwjBm4wCWqNmmc8bo.jpg","url":"https://www.themoviedb.org/movie/526051","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Фэнтези"]},{"title":"Тик-так, бум!","rating":null,"tier":"unrated","review":"","desc":"1990 год. Молодой композитор Джон работает официантом в нью-йоркской забегаловке. Параллельно он пишет мюзикл «Супербия», который, как он рассчитывает, в будущем станет новым хитом Бродвея и позволит ему вырваться из нищеты. В жизни Джона всё непросто. Его девушка Сюзан устала ждать, пока бойфренд добьется успеха, а лучший друг оставил мечты и устроился на престижную работу в рекламном агентстве. Джону скоро исполнится 30 лет, и он начинает переживать, что впустую потратил все эти годы.","poster":"https://image.tmdb.org/t/p/w500/5WJVoaPGxCHK40yiZlz7KfL07hH.jpg","url":"https://www.themoviedb.org/movie/537116","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Музыка","Триллер"]},{"title":"Титаны","rating":null,"tier":"unrated","review":"","desc":"Сюжет сериала сосредоточен на группе молодых супергероев, известных как Титаны, возглавляемые Диком Грейсоном, также известным как Найтвинг.","poster":"https://image.tmdb.org/t/p/w500/1DU4MXFZkCDn9ZjsRgjk6r07qxq.jpg","url":"https://www.themoviedb.org/tv/75450","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Боевик","Приключения","Фантастика","Фэнтези"]},{"title":"Тихое место 2","rating":null,"tier":"unrated","review":"","desc":"474 дня прошло после нападения на Землю охотящихся на звук существ, семья Эбботт продолжает бороться за жизнь в полной тишине. Столкнувшись со смертельной угрозой в собственном доме, они вынуждены отправиться во внешний мир, где находят убежище и старого знакомого семьи. Поймав радиосигнал, Реган вычисляет место предполагаемой колонии выживших и решает во что бы то ни стало её разыскать.","poster":"https://image.tmdb.org/t/p/w500/9mLRf87tqKKpOjEx8M1yl1jZa1k.jpg","url":"https://www.themoviedb.org/movie/520763","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Триллер","Ужасы"]},{"title":"Тренировочный","rating":null,"tier":"unrated","review":"","desc":"Джейк Хойт устраивается на работу в отдел по борьбе с наркотиками полиции Лос-Анджелеса. Его напарником становится опытный полицейский Алонзо Харисс, который в борьбе с преступностью далеко не всегда использует законные методы. И почти сразу Джейк оказывается вовлечённым в стремительный водоворот событий.","poster":"https://image.tmdb.org/t/p/w500/6rt6zNBUHrNjh2pdoZlh3oWuYCC.jpg","url":"https://www.themoviedb.org/movie/2034","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Криминал","Драма"]},{"title":"Три билборда на границе Эббинга, мис","rating":null,"tier":"unrated","review":"","desc":"Прошло семь месяцев, а виновный в убийстве её дочери так и не найден. Тогда Милдред Хейз решает пойти на смелый шаг: она расписывает три рекламных щита на въезде в город, разместив на них провокационное послание, адресованное Биллу Уиллоуби, уважаемому начальнику полиции города. Когда в дело вмешивается его заместитель, офицер Джейсон Диксон — незрелый «маменькин сынок» со склонностью к насилию, — конфликт между Милдред и правоохранительными органами Эббинга только обостряется.","poster":"https://image.tmdb.org/t/p/w500/xnyRGjhSIbM2ZVaolkhmPVNncL2.jpg","url":"https://www.themoviedb.org/movie/359940","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Триллер"]},{"title":"Три тысячи лет желаний","rating":null,"tier":"unrated","review":"","desc":"Британская лингвистка Алетея прилетает из Лондона в Стамбул, чтобы прочитать курс лекций по нарративу. Уже в аэропорту женщина начинает видеть загадочных существ, а когда в одной из многочисленных сувенирных лавочек покупает стеклянную бутылочку и пытается её отмыть, перед ней возникает самый настоящий джинн. Алетея не торопится загадывать три желания, ей интереснее послушать его историю. Джинн начинает свой рассказ.","poster":"https://image.tmdb.org/t/p/w500/tb3967BJu5QbZgiIh715pAigywF.jpg","url":"https://www.themoviedb.org/movie/556694","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фэнтези","Романтика"]},{"title":"Убойные каникулы","rating":null,"tier":"unrated","review":"","desc":"Группа студентов колледжа отправляется за город, чтобы вовсю оторваться на выходных: попить пивка, поплавать в озере и подышать чистым лесным воздухом. Но уже в 1-ый день они сталкиваются с неотёсанными фермерами Такером и Дэйлом. Приняв этих диковатых ребят за маньяков, горожане решают дать деревенщине жёсткий отпор. Но с каждым их шагом становится только хуже.","poster":"https://image.tmdb.org/t/p/w500/oId9WDFgTJGLrXz7RAvnjSrn5PX.jpg","url":"https://www.themoviedb.org/movie/46838","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Ужасы","Драма"]},{"title":"Удача логана","rating":null,"tier":"unrated","review":"","desc":"Уволили с работы? Подготовь самое дерзкое ограбление в истории! Джимми Логан молниеносно подбирает команду «специалистов», способных на такую аферу, и надеется выйти сухим из воды. Будь как Логан!","poster":"https://image.tmdb.org/t/p/w500/wqOI7jJXRmMtn15oR4jnYxUFQJJ.jpg","url":"https://www.themoviedb.org/movie/399170","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Боевик","Драма"]},{"title":"Удивительное путешествие доктора Дулиттла","rating":null,"tier":"unrated","review":"","desc":"Семь лет назад доктор Дулиттл, прославленный врач-ветеринар, живущий в викторианской Англии, потерял свою жену. Теперь он ведёт затворнический образ жизни, скрывшись за высокими стенами своего поместья. Экзотические животные из его коллекции — его единственная компания. Но когда неизвестная болезнь становится угрозой для жизни юной королевы, доктору Дулиттлу приходится покинуть свое убежище и отправиться в невероятное путешествие к мифическому острову. В поисках лекарства для королевы он вступит в схватку с беспощадными врагами, познакомится с диковинными существами и будет вынужден проявить недюжинное мужество и смекалку.","poster":"https://image.tmdb.org/t/p/w500/AwsewPKXebJvtl4EU5Dx5uBCW6G.jpg","url":"https://www.themoviedb.org/movie/448119","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Комедия","Фэнтези","Приключения"]},{"title":"Укрытие","rating":null,"tier":"unrated","review":"","desc":"На отравленной гибнущей планете будущего тысячи людей ютятся в огромном подземном укрытии. Нарушение шерифом основного правила и серия загадочных смертей вынуждают инженера Джульетту заняться раскрытием тайн и поиском правды о бункере.","poster":"https://image.tmdb.org/t/p/w500/gRkvq6FgiGRdtCwhVIozaUqhoDL.jpg","url":"https://www.themoviedb.org/tv/125988","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма"]},{"title":"Уловки норбита","rating":null,"tier":"unrated","review":"","desc":"Жизнь Норбита с самого детства была полна испытаний и разочарований. Брошенный родителями у дверей китайского ресторанчика и воспитанный мистером Вонгом, с начальной школы он был обречен ходить в ухажерах монструозной Распутии. Не смея возразить своей защитнице, герой смиренно собирается вести ее к алтарю, как в город возвращается любовь всей жизни Норбита, прекрасная Кейт. Теперь ему предстоит как-то избавиться от деспотичной Распутии и завоевать сердце Кейт.","poster":"https://image.tmdb.org/t/p/w500/2ZdQ1ULswOERjGyjLHvnbnXB0nB.jpg","url":"https://www.themoviedb.org/movie/9757","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Управление гневом","rating":null,"tier":"unrated","review":"","desc":"До своей карьеры терапевта, Чарли был в тупике из-за отсутствия перспектив в низшей бейсбольной лиге. Проблема неумения контролировать свой гнев сбила его с пути в высшую лигу. После прохождения курса терапии по борьбе с гневом, он вывел свою команду в высшую лигу и провел один потрясающий сезон, прежде чем старые проблемы вновь не напомнили о себе. В своем финальном матче он пытался ударить себя битой по ноге, в результате чего получил травму, которая положила конец его карьере.     \n        \n         \n        \n    Но в итоге эта же травма привела его к нынешней профессии. В то время как Чарли борется со своим гневом, в его жизни процветает хаос. Всё осложняется его отношениями с собственным терапевтом и лучшим другом, бывшей женой, чьи позитивные взгляды на будущее, но при этом плохой выбор мужчин, расстраивают Чарли и их 13-летнюю дочь, имеющую психические расстройства.","poster":"https://image.tmdb.org/t/p/w500/ekItnn6W73RN9muvLTbeRW8LHlo.jpg","url":"https://www.themoviedb.org/tv/42878","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Успеть за 30 минут","rating":null,"tier":"unrated","review":"","desc":"Ник — простой разносчик пиццы, чья размеренная жизнь буквально в одно мгновенье переворачивается с ног на голову, когда в нее с хитроумным планом врываются два бандита, мечтающих сорвать большой куш. Безбашенная парочка похищает Ника с целью заставить его ограбить банк. Ник понимает, что ему никак не обойтись без помощи своего лучшего друга Чета. Вместе приятели должны обвести вокруг пальца похитителей, не попасться в руки полиции, да еще и разобраться друг с другом — ведь их отношения далеко не безоблачны. На эту практически невыполнимую миссию друзьям отведены считанные часы.","poster":"https://image.tmdb.org/t/p/w500/slMgVkQlIstqBaeCXB2NdKaDN3G.jpg","url":"https://www.themoviedb.org/movie/62206","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия"]},{"title":"Фантастические твари","rating":null,"tier":"unrated","review":"","desc":"Профессор Альбус Дамблдор узнает, что могущественный темный волшебник Геллерт Грин-де-Вальд планирует захватить власть над миром. Понимая, что не сможет остановить его в одиночку, Дамблдор просит магозоолога Ньюта Саламандера возглавить команду из выдающихся волшебников и одного отважного магла-пекаря. Им предстоят невероятно опасные приключения, встреча со старыми и укрощение новых магических существ и борьба со сторонниками Грин-де-Вальда, которых становится все больше. Но какая роль в этой миссии уготована самому Дамблдору?","poster":"https://image.tmdb.org/t/p/w500/8LIpVm3uvoGrHYrtmIzxlRt31zn.jpg","url":"https://www.themoviedb.org/movie/338953","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма"]},{"title":"Фантастические твари: Преступления Грин-де-Вальда","rating":null,"tier":"unrated","review":"","desc":"В конце первого фильма могущественный темный волшебник Геллерт Грин-де-Вальд был пойман сотрудниками МАКУСА (Магического Конгресса Управления по Северной Америке), не без помощи Ньюта Саламандера. Выполняя свое обещание, темный маг устраивает грандиозный побег и начинает собирать сторонников, большинство из которых не знают о его истинной цели: добиться превосходства волшебников над всеми немагическими существами на планете. Чтобы сорвать планы Грин-де-Вальда, Альбус Дамблдор обращается к своему бывшему студенту Ньюту Саламандеру, который соглашается помочь, не подозревая, какая опасность ему грозит. В раскалывающемся на части волшебном мире любовь и верность проверяются на прочность, а конфликт разделяет даже настоящих друзей и членов семей.","poster":"https://image.tmdb.org/t/p/w500/st03eTWNNcVTX5je7mRxjbgEDAq.jpg","url":"https://www.themoviedb.org/movie/338952","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма"]},{"title":"Фантастические твари: Тайны Дамблдора","rating":null,"tier":"unrated","review":"","desc":"Профессор Альбус Дамблдор узнает, что могущественный темный волшебник Геллерт Грин-де-Вальд планирует захватить власть над миром. Понимая, что не сможет остановить его в одиночку, Дамблдор просит магозоолога Ньюта Саламандера возглавить команду из выдающихся волшебников и одного отважного магла-пекаря. Им предстоят невероятно опасные приключения, встреча со старыми и укрощение новых магических существ и борьба со сторонниками Грин-де-Вальда, которых становится все больше. Но какая роль в этой миссии уготована самому Дамблдору?","poster":"https://image.tmdb.org/t/p/w500/8LIpVm3uvoGrHYrtmIzxlRt31zn.jpg","url":"https://www.themoviedb.org/movie/338953","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Приключения","Драма"]},{"title":"Ford против Ferrari","rating":null,"tier":"unrated","review":"","desc":"В начале 1960-х Генри Форд II принимает решение улучшить имидж компании и сменить курс на производство более модных автомобилей. После неудавшейся попытки купить практически банкрота Ferrari американцы решают бросить вызов итальянским конкурентам на трассе и выиграть престижную гонку 24 часа Ле-Мана. Чтобы создать подходящую машину, компания нанимает автоконструктора Кэррола Шэлби, а тот отказывается работать без выдающегося, но, как считается, трудного в общении гонщика Кена Майлза. Вместе они принимаются за разработку впоследствии знаменитого спорткара Ford GT40.","poster":"https://image.tmdb.org/t/p/w500/579BjDiFrK9VK8EnKZzYwtGGXCg.jpg","url":"https://www.themoviedb.org/movie/359724","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Боевик"]},{"title":"Хардкор","rating":null,"tier":"unrated","review":"","desc":"Прекрасная супружеская жизнь рядом с очаровательной Эстель - это все, что помнит главный герой после того, как просыпается в неизвестной научной лаборатории, где в чувства его приводит собственная жена. Но супруга тут же оказывается похищенной, и ничего не понимающий главный герой Генри уже вынужден преследовать монстра Акана, который украл его жену. Теперь ради достижения цели Генри готов на многое. Но позже оказывается, что не только он один является врагом для Акана. У подозрительного Джимми тоже свои планы на злодея. Теперь вместе ребятам предстоит спасти Эстель и предотвратить попытку задействовать армию киборгов в борьбе с человечеством. Им предстоит бороться с самим воплощением зла.","poster":"https://image.tmdb.org/t/p/w500/jC0PzGjVfzvyri5UcQrUwwz6otm.jpg","url":"https://www.themoviedb.org/movie/325348","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фантастика"]},{"title":"Хищники","rating":null,"tier":"unrated","review":"","desc":"Наемник Ройс невольно вынужден возглавить группу профессионалов, выполняющих загадочную миссию на неизвестной планете. За исключением опального доктора все они - хладнокровные убийцы: наемники, гангстеры, осужденные и участники отрядов смерти - людские «хищники». Но когда их начинает систематически преследовать и истреблять невообразимое чудовище, становится очевидно, что теперь они в роли своих жертв.","poster":"https://image.tmdb.org/t/p/w500/l7oNiP5Oo89TqxNtHn9yExqsgYq.jpg","url":"https://www.themoviedb.org/movie/34851","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Боевик","Триллер"]},{"title":"Хроники хищных городов","rating":null,"tier":"unrated","review":"","desc":"Прошли тысячелетия после того, как мир настиг апокалипсис. Человечество адаптировалось и теперь живет по новым правилам. Гигантские движущиеся мегаполисы рассекают пустоши и поглощают маленькие города ради ресурсов. Том Нэтсуорти из нижнего уровня великого Лондона оказывается в смертельной опасности, когда на его пути появляется скрывающаяся от закона бунтарка Эстер Шоу. Они не должны были встретиться, но им суждено изменить будущее.","poster":"https://image.tmdb.org/t/p/w500/6GOzuWuwcEmys4Vs4U699YiqXE3.jpg","url":"https://www.themoviedb.org/movie/428078","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Фантастика","Драма"]},{"title":"Худеющий","rating":null,"tier":"unrated","review":"","desc":"Адвокат Билли Хэллек, сбивший машиной цыганку, оправдывается перед судом благодаря своим связям. Но всех этих людей настигает суровая кара — страшные заклятия, превратившие жизнь каждого из них в особенный кошмар.","poster":"https://image.tmdb.org/t/p/w500/ukJGlf1jQxcbqYQAh5Br7R3n4Br.jpg","url":"https://www.themoviedb.org/movie/10280","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Ужасы","Драма"]},{"title":"Цепляясь за лёд","rating":null,"tier":"unrated","review":"","desc":"Одержимая мечтой о победе претендентка на олимпийскую медаль по фигурному катанию разрывается между любовью, семьей и своим хрупким душевным здоровьем.","poster":"https://image.tmdb.org/t/p/w500/pTasKvIq9F9m7ZeDURsod7bvGwu.jpg","url":"https://www.themoviedb.org/tv/83050","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Человек который познал бесконечность","rating":null,"tier":"unrated","review":"","desc":"Фильм рассказывает о жизни известного индийского математика-самоучки Сриниваса Рамануджана.","poster":"https://image.tmdb.org/t/p/w500/pjJR7iz0kJTEr9GJ6tvpJVlbWCL.jpg","url":"https://www.themoviedb.org/movie/353326","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Триллер"]},{"title":"Чем дальше в лес","rating":null,"tier":"unrated","review":"","desc":"Золушка мечтает попасть на бал, Пекарь, когда-то проклятый Ведьмой, и его Жена горюют о том, что у них нет ребенка, Джек хочет, чтобы его корова Беляночка наконец-то дала молоко, его Мать мечтает быть богатой, а Красной Шапочке очень нужен каравай хлеба — гостинец для Бабушки, которая живет в лесу… и, может быть, немного сластей для себя лично.  Наконец, Ведьма, живущая по соседству с Пекарем, мечтает вернуть себе молодость и красоту, которые она утратила по несчастному стечению обстоятельств. Для этого она предлагает Пекарю в обмен на снятие проклятия помочь ей и добыть необходимые составляющие для волшебного напитка: корову, белую, как молоко, плащ, красный как кровь, прядь волос, желтых, как кукуруза, и золотые туфельки…","poster":"https://image.tmdb.org/t/p/w500/s4pbFVyEIlpyPjxdbG15JeIET0S.jpg","url":"https://www.themoviedb.org/movie/224141","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фэнтези","Комедия","Драма"]},{"title":"Чёрная молния","rating":null,"tier":"unrated","review":"","desc":"Действие картины разворачивается в наши дни, где главный герой, двадцатилетний Дима Майков, получает в подарок от отца старенькую «Волгу-21» и внезапно обнаруживает, что его машина летает, как настоящий истребитель. Герой бесцельно парит над столичными пробками и беззаботно наслаждается полетами, пока однажды беда не заставляет его по-другому взглянуть на мир. Теперь ему предстоит встать на защиту тех, кем он дорожит, и сразиться со Злом в небе над новогодней Москвой.","poster":"https://image.tmdb.org/t/p/w500/aL0dpOCjNPXGzGn6uMlsunxFPd9.jpg","url":"https://www.themoviedb.org/movie/31162","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Боевик","Приключения"]},{"title":"Что скрывает вода","rating":null,"tier":"unrated","review":"","desc":"Мать-одиночка с 16-летней дочерью отправляются в загородный дом, где девушку ждёт сюрприз: мама встречается с мужчиной и собирается за него замуж. Разумеется, в потенциальном отчиме дочь видит угрозу, и, как вскоре выяснится, не зря. Незнакомец оказывается вовсе не человеком, а загадочным монстром. Или девушке всего лишь так кажется?","poster":"https://image.tmdb.org/t/p/w500/xjzREl8EWGz2Rti6hPFGJQPqgjR.jpg","url":"https://www.themoviedb.org/movie/716703","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Фантастика","Драма"]},{"title":"Чудо на гудзоне","rating":null,"tier":"unrated","review":"","desc":"Произошедшее 15 января 2009 года назовут «Чудом на Гудзоне». В тот день капитан рейса 1549 Чесли Салленбергер совершил аварийную посадку самолета A320 на холодные воды реки Гудзон в Нью-Йорке. При этом никто из находившихся на борту 155 человек не пострадал. Но, несмотря на все почести со стороны общественности и СМИ, было начато расследование, которое угрожало профессиональной репутации и многолетней карьере капитана Салли.","poster":"https://image.tmdb.org/t/p/w500/qwG7SP5KV8fSxpLkB31Ta4dCYlR.jpg","url":"https://www.themoviedb.org/movie/363676","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Триллер"]},{"title":"Шалун","rating":null,"tier":"unrated","review":"","desc":"Главный герой так мечтает стать отцом, что по ошибке принимает находящегося в бегах маленького и похожего на ребенка воришку за своего брошенного сына. Новоявленный папаша и его жена берут «малыша» к себе в дом и начинают всячески о нем заботиться. Тем временем напарник вора, ограбивший вместе с ним ювелирный магазин, пытается выманить его из новой семьи, чтобы заполучить украденный бриллиант…","poster":"https://image.tmdb.org/t/p/w500/d8DHk6Kevl4zw4ViQjys4cUsL4P.jpg","url":"https://www.themoviedb.org/movie/9072","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Драма"]},{"title":"Шальная карта","rating":null,"tier":"unrated","review":"","desc":"Главный герой — бывший военный Ник Эскаланте — работает в Лас-Вегасе охранником, мечтает накопить денег и навсегда уехать в Венецию. Но Ник соглашается помочь проститутке Холли, постоянно подвергающейся насилию со стороны сына крупного гангстера, из-за чего отъезд в Венецию затягивается.","poster":"https://image.tmdb.org/t/p/w500/4ZQPmpqigWJuwefUOpJBCLLyF6D.jpg","url":"https://www.themoviedb.org/movie/265208","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Криминал","Боевик"]},{"title":"Шары ярости","rating":null,"tier":"unrated","review":"","desc":"Рэнди Дайтона — одаренный игрок в пинг-понг, опозорившийся на мировой арене и вынужденный зарабатывать, выступая в кабаре города Рино, штат Невада. Но шанс на возвращение в мир большого спорта ему предоставляет ЦРУ. Надо лишь принять участие в подпольном турнире, который проводит у себя в поместье криминальный авторитет Фанг — известный душегуб и энтузиаст настольного тенниса.","poster":"https://image.tmdb.org/t/p/w500/rQoeLgQ3f5wJiSwpP5ujI9v18gK.jpg","url":"https://www.themoviedb.org/movie/9750","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Криминал","Драма"]},{"title":"Шепот","rating":null,"tier":"unrated","review":"","desc":"Когда у вдовца пропадает маленький сын, мужчина обращается к отцу, с которым давно не общался. Отец — бывший детектив, поймавший маньяка, который связан с делом мальчика.","poster":"https://image.tmdb.org/t/p/w500/1hnX64v6HWSnAFAjG4GPL03DxKb.jpg","url":"https://www.themoviedb.org/movie/860508","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Триллер"]},{"title":"Эйфория","rating":null,"tier":"unrated","review":"","desc":"17-летняя Ру Беннетт возвращается домой после лечения в реабилитационной клинике. Не имея ни малейшего желания завязывать с наркотиками, она немедленно берётся за старое. На вечеринке Ру обращает внимание на недавно приехавшую в их пригород ровесницу Джулс, и это знакомство становится началом большой дружбы.","poster":"https://image.tmdb.org/t/p/w500/yJz0VPfztciUt8cYulEOnk7wQhs.jpg","url":"https://www.themoviedb.org/tv/85552","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Эксперимент «Офис»","rating":null,"tier":"unrated","review":"","desc":"В чьём-то извращённом социальном эксперименте группа из 80-ти американцев заблокирована в многоэтажном корпоративном офисном здании в Боготе (Колумбия), и по внутренней телефонной связи компании неизвестный голос приказывает им участвовать в смертельной игре — «Убей, или будешь убит».","poster":"https://image.tmdb.org/t/p/w500/Af4lEwc1ETj8YN8uQoTT2Bh9Lnn.jpg","url":"https://www.themoviedb.org/movie/341006","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Триллер","Боевик"]},{"title":"Этим летом","rating":null,"tier":"unrated","review":"","desc":"Дети пытаются спасти пожилого отца, обвиняемого в убийстве. Детектив с горьким привкусом семейной драмы    \n        \n    Пожилой таксист Макарыч неожиданно становится главным подозреваемым по делу об убийстве политика Ремезова, кандидата на пост мэра их городка. У Макарыча двое взрослых детей, и каждый из них стремится доказать невиновность отца. Старший сын Влад – сотрудник местного ФСБ, его отстраняют от официального расследования, но остаться в стороне он не может. Младшая дочь Тина пытается докопаться до правды со своей стороны: она участвует в боях без правил и вращается в околокриминальных кругах. Беда в том, что дети Макарыча давно не разговаривают друг с другом, а потому не могут объединить усилия. Мало того, со временем Влад начинает подозревать, что его отец не так чист, как ему казалось. А Тина начинает подозревать Влада… И не она одна.","poster":"https://image.tmdb.org/t/p/w500/f3sAsHEAXN9OynbY6rrdVOarsaa.jpg","url":"https://www.themoviedb.org/tv/223203","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детектив","Драма","Триллер"]},{"title":"Это все он","rating":null,"tier":"unrated","review":"","desc":"Талантливая в детстве, но совершенно потерянная в свои тридцать Вася вдруг осознаёт, что катится на самое дно, а сил выбраться нет. На помошь приходит Мальвина - воображаемая подруга из детства, женщина-фрик с фиолетовыми волосами и своеобразным чувством юмора. Мальвина толкает Васю на поиски её детской любви - Стасика. Вася пройдёт большой путь и поймёт, что в её жизни пошло не так, но, главное, узнает, почему появилась Мальвина.","poster":"https://image.tmdb.org/t/p/w500/vXxyywN2BvhB1ILJXVglCFd5Sgr.jpg","url":"https://www.themoviedb.org/movie/634290","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези","Драма"]},{"title":"Эффект колибри","rating":null,"tier":"unrated","review":"","desc":"Бывший спецназовец Джоуи Джонс пытается начать новую жизнь. Он соглашается работать на азиатскую мафию. Но проникая все глубже в криминальный мир родного города, он понимает, что не может спокойно смотреть на творящееся в нем беззаконие. Когда от рук бандитов погибает его возлюбленная Изабель, Джоуи решает восстановить справедливость. Он начинает расследование, которое ведет его на самый верх преступного синдиката.","poster":"https://image.tmdb.org/t/p/w500/aip6sNrOBiuKtmUbMkxPpIvCp7H.jpg","url":"https://www.themoviedb.org/movie/136418","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Драма"]},{"title":"Отрочество","rating":null,"tier":"unrated","review":"","desc":"История охватывает двенадцать лет жизни Мейсона (от первого класса в школе до первого дня в колледже) и складывается из небольших эпизодов, показывающих взросление и отношения с родителями ребёнка, подростка, юноши.","poster":"https://image.tmdb.org/t/p/w500/yR93WtIUOv32LgqCsYgt9vhm6xr.jpg","url":"https://www.themoviedb.org/movie/85350","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Я — четвёртый","rating":null,"tier":"unrated","review":"","desc":"Обычный с виду подросток Джон Смит на самом деле — один из последних выживших обитателей далекой планеты. Джон вынужден скрываться от страшных врагов, посланных уничтожить его, ему приходится менять имена, постоянно переезжая с места на место со своим опекуном Генри. В разных городках и в разных школах Джон всегда был новичком без прошлого, но однажды он нашел место, которое смог назвать домом: в маленьком городке в Огайо Джон встретил свою любовь. Теперь ему предстоит открыть в себе уникальные способности, сразиться с древними и страшными врагами своего народа и осознать свое удивительное предназначение.","poster":"https://image.tmdb.org/t/p/w500/iCTi4zBFmqKQb0Q8D8FZ3i5hFyx.jpg","url":"https://www.themoviedb.org/movie/46529","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Триллер","Фантастика"]},{"title":"Я никогда не..","rating":null,"tier":"unrated","review":"","desc":"Девушка-подросток индийского происхождения пытается стать популярной, но это оказывается не так просто.","poster":"https://image.tmdb.org/t/p/w500/wdi3dE8YsENX0DkeNAhO93AHwRm.jpg","url":"https://www.themoviedb.org/tv/100883","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Два далеких незнакомца","rating":null,"tier":"unrated","review":"","desc":"В получившем «Оскар» короткометражном фильме герой пытается вернуться домой, но, попав во временную петлю, раз за разом погибает в стычке с полицейским.","poster":"https://image.tmdb.org/t/p/w500/awnMWuq64kfzfKtNLctjBTJKqi0.jpg","url":"https://www.themoviedb.org/movie/787428","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"128 ударов сердца в минуту","rating":null,"tier":"unrated","review":"","desc":"Действие фильма разворачивается в Голливуде. Двадцатитрехлетний диджей по имени Коул проводит дни и ночи своей жизни в беспрестанной работе над одним треком, который должен будет взорвать весь мир. Всё это меняется, когда он знакомится с более опытным, хотя и не совсем здоровым диджеем Джеймсом, который берет парня под свое крыло. Вскоре Коул влюбляется в Софи, девушку Джеймса, и ему приходится выбирать между любовью, дружбой и своим будущим.","poster":"https://image.tmdb.org/t/p/w500/jdKfkrUTl2JknNAeTOnz8We15bX.jpg","url":"https://www.themoviedb.org/movie/301351","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Музыка","Романтика","Комедия"]},{"title":"Национальная безопасность","rating":null,"tier":"unrated","review":"","desc":"Два неудачливых охранника — отчисленный из полицейской академии дерзкий Эрл Монтгомери и бывший коп Хэнк Рафферти — вынуждены объединить усилия, чтобы разоблачить крупную банду контрабандистов.","poster":"https://image.tmdb.org/t/p/w500/8nKu2PcyIWOqEgMnbqo4kADNtl8.jpg","url":"https://www.themoviedb.org/movie/11078","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Комедия","Криминал"]},{"title":"Джек Ричер","rating":null,"tier":"unrated","review":"","desc":"Снайпер убивает нескольких случайных прохожих. Его находят и арестовывают. Все улики указывают на него. На допросе вместо признания он пишет имя — Джек Ричер. Больше обвиняемый не может ничего сказать, поскольку после избиения заключёнными впадает в кому. Загадочный Джек Ричер появляется незамедлительно. Что теперь будет с убийцей?","poster":"https://image.tmdb.org/t/p/w500/qw1RGKZDasgyJIA4yUbaQxAgxD8.jpg","url":"https://www.themoviedb.org/movie/75780","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Триллер","Боевик"]},{"title":"Кошачьи миры Луиса Уэйна","rating":null,"tier":"unrated","review":"","desc":"Картины эксцентричного аристократа Луиса Уэйна обладают одной общей чертой — он пишет исключительно антропоморфных котов. Благодаря любви своей жены Эмили, Луис навсегда меняет взгляд людей на жизнь и на кошек. Но с каждой новой картиной причудливые миры Луиса начинают всё сильнее заменять ему реальность.","poster":"https://image.tmdb.org/t/p/w500/dvRNjOqm8UNtu2tzlkHBahm0gDZ.jpg","url":"https://www.themoviedb.org/movie/617762","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","История","Комедия"]},{"title":"Разлом","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/oLipsA3Q8ITLKU6SYbCVphDZdUM.jpg","url":"https://www.themoviedb.org/movie/1774906","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Грань времени","rating":null,"tier":"unrated","review":"","desc":"Двое врачей скорой помощи из Нового Орлеана сталкиваются с серией ужасных смертей, связанных с новым наркотиком со странным побочным эффектом. Пытаясь докопаться до правды, герои сами оказываются на грани то ли нервного срыва, то ли жизни и смерти.","poster":"https://image.tmdb.org/t/p/w500/lHmF2lv5q5EzNNiZ6DXVKrRDgX.jpg","url":"https://www.themoviedb.org/movie/549294","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Фантастика","Триллер"]},{"title":"Удачи, Чак!","rating":null,"tier":"unrated","review":"","desc":"Довольный жизнью молодой дантист обнаруживает удивительную вещь — любая девушка после встреч с ним буквально на следующий день находит себе идеального спутника жизни. Главного героя вполне устраивает такая ситуация — никаких, понимаешь, обязательств и шумных разрывов. Разумеется, ситуация в корне меняется, когда он находит свою половинку.","poster":"https://image.tmdb.org/t/p/w500/yvIAQ5bhTTx0k8MAsSqXgPbr6dz.jpg","url":"https://www.themoviedb.org/movie/10030","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Сахара","rating":null,"tier":"unrated","review":"","desc":"Неистребимая жажда приключений толкает Дирка Пита в одну из самых опасных областей Западной Африки. Поиск несметных сокровищ Нила сопровождается страшной тайной — засекреченный «корабль смерти» повинен в гибели людей.Питу, вместе с другом, необходимо держать ухо востро, собрав воедино смекалку, мужество и героизм, чтобы помочь доктору Еве Рохас победить таинственную болезнь, уносящую человеческие жизни в результате действия и желания себе же подобных.","poster":"https://image.tmdb.org/t/p/w500/qN9n6RlBWc17IYfyaCp5CGeMaj7.jpg","url":"https://www.themoviedb.org/movie/7364","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Комедия","Драма","Детектив"]},{"title":"Явление","rating":null,"tier":"unrated","review":"","desc":"Эллиотт Мур (Марк Уолберг), преподаватель биологии из Филадельфии, одновременно с миллионами соотечественников узнаёт странную и трагическую новость — о коллективных самоубийствах жителей Нью-Йорка. Постепенно выясняется, что под угрозу распространения явления попали практически все города и даже небольшие населённые пункты Восточного побережья США. Вместе с молодой женой Альмой (Зоуи Дэшенел), другом и коллегой Джулианом (Джон Легуизамо), а также его двенадцатилетней дочкой Джесс (Эшлин Санчес) Эллиотт решает укрыться в безлюдной местности, лихорадочно пытаясь понять, какова природа происходящего и что может их спасти?","poster":"https://image.tmdb.org/t/p/w500/7jsOVoRDGfSMehONjoaKd6mp9Lh.jpg","url":"https://www.themoviedb.org/movie/8645","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Фантастика","Драма"]},{"title":"Без обид","rating":null,"tier":"unrated","review":"","desc":"Находясь на грани потери дома своего детства, молодая ветреная девушка Мэдди обнаруживает интригующее предложение работы: богатые родители ищут кого-то, с кем бы мог «встречаться» их замкнутый 19-летний сын Перси перед отъездом в колледж. К своему удивлению, Мэдди вскоре обнаруживает, что неуклюжий Перси не так уж и безнадёжен.","poster":"https://image.tmdb.org/t/p/w500/fbHVg1r89KZ7OKuKgD9PaJSuKbB.jpg","url":"https://www.themoviedb.org/movie/884605","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Драма"]},{"title":"Капсула времени","rating":null,"tier":"unrated","review":"","desc":"В недалеком будущем политик, потерпевший поражение на выборах, уезжает в летний домик у озера. Его отдых нарушает появление его первой любви, которая только что вернулась из 20-летнего космического путешествия и не постарела ни на день.","poster":"https://image.tmdb.org/t/p/w500/c12EChMNDP11dJzoruUBIHwsYRa.jpg","url":"https://www.themoviedb.org/movie/974188","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Фантастика"]},{"title":"Джиперс Криперс","rating":null,"tier":"unrated","review":"","desc":"Если бы Дэрри и Триш знали, во что превратится их обычное путешествие домой на каникулы, то остались бы в колледже навсегда. Брат и сестра заметили его на безлюдной дороге рядом с жуткой, обветшалой церковью. Страшная фигура в длинном чёрном плаще и широкополой шляпе скидывала в подвал свертки, испачканные чем-то красным. После увиденного нужно было немедленно вдавить педаль газа взятой напрокат машины и умчаться от этого проклятого места как можно дальше. Но Дэрри и Триш допустили непоправимую, смертельную ошибку. Они решили вернуться и посмотреть: что же он прячет там, в подвале покосившейся церкви? Это безрассудное любопытство обернулось самым невообразимым кошмаром, который только можно себе представить…","poster":"https://image.tmdb.org/t/p/w500/hQcaiIcnPy6Ke0BQRFO6PblXnTd.jpg","url":"https://www.themoviedb.org/movie/8922","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Детектив","Драма"]},{"title":"Пять вечеров","rating":null,"tier":"unrated","review":"","desc":"Они познакомились двадцать лет назад и полюбили друг друга, но война разлучила их. Теперь Ильин и Тамара Васильевна встретились вновь, и любовь вспыхнула с новой силой…","poster":"https://image.tmdb.org/t/p/w500/dq3z0WRK1JpqHnsBBOcFvwRAnpD.jpg","url":"https://www.themoviedb.org/movie/47851","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Триллер"]},{"title":"Ловушка 2024","rating":null,"tier":"unrated","review":"","desc":"Элис Мартин — успешный судебный бухгалтер, которая разоблачила множество финансовых афер. Будучи партнером в крупной фирме Лос-Анджелеса, она имеет высокий уровень жизни, который разделяет со своим женихом Кираном.   В одночасье мир Элис рушится, когда Киран бросает её и сбегает с двумя миллионами долларов и ценными документами, в то время как она работает над крупным делом. Элис еще не знает, что Киран женат и вместе со своей супругой занимается обманом ничего не подозревающих женщин.","poster":"https://image.tmdb.org/t/p/w500/mBtSzZ3Q2ONN0CEAz1q02jl76Dj.jpg","url":"https://www.themoviedb.org/tv/65579","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Криминал","Комедия"]},{"title":"Обливион","rating":null,"tier":"unrated","review":"","desc":"Можно ли скучать по месту, в котором никогда не был, мечтать о девушке, которую никогда не видел? Добро пожаловать в будущее! Мы больше не можем называть Землю своим домом. Мы выиграли войну, но не смогли сохранить планету…","poster":"https://image.tmdb.org/t/p/w500/56xLv14jx6qvKWMCrF6C96Hs0cl.jpg","url":"https://www.themoviedb.org/movie/75612","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Приключения","Детектив"]},{"title":"Стажёр","rating":null,"tier":"unrated","review":"","desc":"70-летний вдовец Бен Уитакер обнаруживает, что выход на пенсию — еще не конец. Пользуясь случаем, он становится старшим стажером в интернет-магазине модной одежды под руководством Джулс Остин.","poster":"https://image.tmdb.org/t/p/w500/WT7mDImTIHzFrtZunY9EGGwMty.jpg","url":"https://www.themoviedb.org/movie/257211","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Невероятная жизнь Уолтера Митти","rating":null,"tier":"unrated","review":"","desc":"Кто сказал, что в сердце маленького человека не могут жить великие мечты? Даже скромному и незаметному служащему хочется иногда совершить пусть безумные, но геройские поступки, поверить в свою силу и мужество. Почему всех спасать должны исключительно супермены?","poster":"https://image.tmdb.org/t/p/w500/nIKlc3okrp1d0N7R7OA0r11J5rR.jpg","url":"https://www.themoviedb.org/movie/116745","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Драма","Фэнтези"]},{"title":"Путешествие Гектора в поисках счастья","rating":null,"tier":"unrated","review":"","desc":"Гектор — немного эксцентричный, но ужасно обаятельный лондонский психиатр — пребывает в состоянии кризиса, вызванного тем, что его пациенты не становятся счастливее, несмотря на все его усилия. И однажды Гектор решается самолично отправиться в путешествие по всему свету, чтобы узнать, существует ли счастье вообще и, что еще важнее, существует ли оно для него самого.","poster":"https://image.tmdb.org/t/p/w500/fTreEC6tsRbhdFH4f0umSWzujUp.jpg","url":"https://www.themoviedb.org/movie/254375","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Комедия"]},{"title":"Холодная игра","rating":null,"tier":"unrated","review":"","desc":"Играя крупный шахматный матч в Варшаве против русского чемпиона, блестящий, но позабытый бывший чемпион США, ныне алкоголик, Джош Мански оказывается втянут в мир шпионажа и конфликта между мировыми сверхдержавами. По мере эскалации Карибского кризиса шахматный матч приобретает невообразимое значение. Американцы рискуют проиграть обе партии - и в шахматы, и борьбу за мировое господство.","poster":"https://image.tmdb.org/t/p/w500/AdpSqlORYePWbKv91GJseAcMCyr.jpg","url":"https://www.themoviedb.org/movie/585759","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Королевский гамбит","rating":null,"tier":"unrated","review":"","desc":"Марио «Мистер Ти» Мартинез ведет факультатив шахмат для подростков из неблагополучных семей. От остальных учителей его отличает легкий стиль общения, эмпатия и высокий интеллект. На улицах города творится беспредел, подростки здесь постоянно попадают в неприятности, и многие берутся за самые рискованные дела, чтобы выжить. Какие тут могут быть шахматы? Но Мартинез искренне верит в своих учеников. Смогут ли ребята из гетто играть на равных с игроками национального турнира по шахматам?","poster":"https://image.tmdb.org/t/p/w500/tEFhHjzchawd5e7q0LsiAggqncT.jpg","url":"https://www.themoviedb.org/movie/665877","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Рыцари Южного бронкса","rating":null,"tier":"unrated","review":"","desc":"Они – дети из неполных семей, выросшие на улицах неблагополучного района Нью-Йорка Ричард Мэйсон – обладатель престижной работы, крепкой семьи и большого красивого дома. По воле судьбы их пути пересекаются. Неожиданно лишившись места, Мэйсон вспоминает про своe первое образование и устраивается замещающим учителем в 4-й класс школы Южного Бронкса. Поначалу эстету Ричарду и 26 его подопечным, еле умеющим читать по слогам, никак не удается установить контакт. Но, однажды учитель приносит на урок шахматную доску…","poster":"https://image.tmdb.org/t/p/w500/31tamKoAe4NayUVAxZ6PSbNBpY2.jpg","url":"https://www.themoviedb.org/movie/58104","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Шахматист","rating":null,"tier":"unrated","review":"","desc":"Это история жизни Фахима Мохаммада, чемпиона мира по шахматам среди юниоров, родившегося в Бангладеш в 2000 году и в настоящее время проживающего во Франции и выступающего за нее.","poster":"https://image.tmdb.org/t/p/w500/zg1NzqTCVnwFFBUAXN9OZtqDAD0.jpg","url":"https://www.themoviedb.org/movie/589978","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Семейный","Комедия"]},{"title":"Защита Лужина","rating":null,"tier":"unrated","review":"","desc":"По роману Владимира Набокова. Он - гениальный шахматист, его жизнь - игра. Но встреча с Наталией открывает для него новый, неизведанный и пугающе манящий мир. Шахматная доска - граница меж двух реальностей, любовь к женщине - единственное, что связывает его с внешним миром. Но здесь он чужой, а там ему нет места без нее.","poster":"https://image.tmdb.org/t/p/w500/tVV3PhTO58R0CAsvWhsUkYDzIEZ.jpg","url":"https://www.themoviedb.org/movie/52654","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Драма","Триллер"]},{"title":"Жизнь короля","rating":null,"tier":"unrated","review":"","desc":"Бывший заключенный Юджин Браун (Кьюба Гудинг мл.), отсидевший 17 лет за вооруженное ограбление, устраивается уборщиком в школу и создает шахматный клуб Big Chair Chess Club, чтобы уберечь трудных подростков от криминала.","poster":"https://image.tmdb.org/t/p/w500/n4tMTQlET0AHUMi0Chvp5z69LYy.jpg","url":"https://www.themoviedb.org/movie/201550","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Криминал","Биография"]},{"title":"Жертвуя пешкой","rating":null,"tier":"unrated","review":"","desc":"Фильм о жизни легендарного гроссмейстера Бобби Фишера. Кульминационным моментом картины станет его матч с Борисом Спасским за чемпионский титул 1972 года, который по уровню резонанса стал одним из важнейших спортивных событий тех лет.","poster":"https://image.tmdb.org/t/p/w500/qwyiCdKcvzd44Bhrc9CVhhp29MH.jpg","url":"https://www.themoviedb.org/movie/245698","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Триллер","Драма","Комедия"]},{"title":"Выбор игры","rating":null,"tier":"unrated","review":"","desc":"Джош Вайцкен, как и все американские мальчишки учится в колледже и обожает бейсбол. Но все меняется в тот день, когда он впервые в жизни оказывается за шахматной доской. Ребенок сразу выигрывает партию у своего отца. Вскоре становится очевидно, что у Джоша просто уникальные способности.  Родители юного гения, окрыленные успехами сына, нанимают ему известного шахматного преподавателя Брюса Пандолфини в надежде, что он сделает из их мальчика второго Бобби Фишера.","poster":"https://image.tmdb.org/t/p/w500/kfLlvyLE5dSotI1UTvdu9rpu16N.jpg","url":"https://www.themoviedb.org/movie/14291","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Королева из Катве","rating":null,"tier":"unrated","review":"","desc":"Фильм «Королева из Катве» основан на подлинной истории молодой девушки, выросшей на улицах сельской Уганды. Жизнь девушки в корне меняется в тот момент, когда она знакомится с игрой в шахматы. Благодаря поддержке семьи и общины она обретает уверенность и решимость на пути к своей мечте – титулу международного чемпиона по шахматам.","poster":"https://image.tmdb.org/t/p/w500/z5GvCJyMQ3emC53qkgpKLsXxpw9.jpg","url":"https://www.themoviedb.org/movie/317557","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Дерзкий","rating":null,"tier":"unrated","review":"","desc":"12-летний Майкл растет в самом эпицентре преступного мира. Однако мальчик решает вырваться из цепких лап беззакония. Для этого Майкл разрабатывает хитроумный, но смертельно опасный план.","poster":"https://image.tmdb.org/t/p/w500/uXRIIUzjDZZdWR2cUzPJ9eAqaHv.jpg","url":"https://www.themoviedb.org/movie/13815","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Триллер"]},{"title":"Мост в Терабитию","rating":11,"tier":"great","review":"Хороший фильм иточка.","desc":"Надежды ученика пятого класса Джесса Аарона стать самым быстрым бегуном в классе разбились после того, как новичок Лесли Берк одержала победу в соревнованиях. Оснований для враждебности по отношению друг к друг у Джесса и Лесли более чем достаточно, и тем не менее между ними завязывается дружба. Как тут не подружиться, если приходится быть королем и королевой в обнаруженном в лесу волшебном царстве?","poster":"https://image.tmdb.org/t/p/w500/wrjb8LodEnIDxNcENrVJfkYbrHJ.jpg","url":"https://www.themoviedb.org/movie/1265","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Семейный"]},{"title":"Хищник убийца убийц","rating":null,"tier":"unrated","review":"","desc":"Обожающие охоту инопланетные хищники прилетают на Землю, чтобы сразиться с лучшими, как они считают, воинами разных эпох — предводительницей викингов в IX веке и ниндзя начала XVII века. Также их целью становится американский авиамеханик во Второй мировой войне, вынужденно севший за штурвал самолёта.","poster":"https://image.tmdb.org/t/p/w500/822rE7ihoRBL66jyeaGBJPJYEZq.jpg","url":"https://www.themoviedb.org/movie/1376434","status":"watching","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Триллер","Приключения"]},{"title":"Паразиты 2019","rating":15,"tier":"great","review":"","desc":"Обычное корейское семейство Кимов жизнь не балует. Приходится жить в сыром грязном полуподвале, воровать интернет у соседей и перебиваться случайными подработками. Однажды друг сына семейства, уезжая на стажировку за границу, предлагает тому заменить его и поработать репетитором у старшеклассницы в богатой семье Пак. Подделав диплом о высшем образовании, парень отправляется в шикарный дизайнерский особняк и производит на хозяйку дома хорошее впечатление. Тут же ему в голову приходит необычный план по трудоустройству сестры.","poster":"https://image.tmdb.org/t/p/w500/9xL2PwIOerz8jld06J9cxwuJfoD.jpg","url":"https://www.themoviedb.org/movie/496243","status":"watched","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Триллер","Драма"]},{"title":"Окулус","rating":null,"tier":"unrated","review":"","desc":"Смерть родителей сильно повлияла на судьбу двух осиротевших детей. По прошествии времени, в двадцатилетнем возрасте, сестра все еще продолжает так считать и хочет доказать брату, что привидение, вышедшее из зеркала, стало причиной гибели близких людей и всех случившихся последующих бед…","poster":"https://image.tmdb.org/t/p/w500/7wXWjqt21GaZNbpcZMalri39v43.jpg","url":"https://www.themoviedb.org/movie/157547","status":"planned","category":"film","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Ужасы","Драма","Триллер"]},{"title":"Мстители: Эра Альтрона","rating":9,"tier":"solid","review":"","desc":"Человечество на грани уничтожения. На этот раз людям угрожает Альтрон — искусcтвенный интеллект, ранее созданый для того, чтобы защищать Землю от любых угроз. Однако, главной угрозой он посчитал человечество. Международная организация Щ. И. Т не способна справится с таким мощным врагом, и потому они вновь обращаются за помощью к Величайшим Героям Земли — Мстителям. Однако Альтрон слишком силен, и есть большая вероятность, что даже им не удастся остановить начало надвигающейся Эры Альтрона, где нет места для людей…","poster":"https://image.tmdb.org/t/p/w500/6rANrpZe3g2PPeF1m3lQUK1ovpW.jpg","url":"https://www.themoviedb.org/movie/99861","status":"watched","category":"film","subcat":"marvel","chronoOrder":13,"universeOrder":"MCU #13","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Человек-муравей","rating":10,"tier":"solid","review":"","desc":"Вооружившись удивительной способностью уменьшаться в размере, но обладать при этом большой силой, мошенник Скотт Лэнг должен стать героем и помочь своему наставнику, доктору Хэнку Пиму, сохранить в тайне существование костюма Человека-муравья от угроз нового поколения.","poster":"https://image.tmdb.org/t/p/w500/9cMJSp2LVSzmPzMWPHIHpeBfECr.jpg","url":"https://www.themoviedb.org/movie/102899","status":"watched","category":"film","subcat":"marvel","chronoOrder":14,"universeOrder":"MCU #14","genres":["Супергероика","Фантастика","Приключения","Боевик"]},{"title":"Первый мститель: Противостояние","rating":9,"tier":"solid","review":"","desc":"Мстители под руководством Капитана Америки оказываются участниками разрушительного инцидента, имеющего международный масштаб. Эти события заставляют правительство задуматься над тем, чтобы начать регулировать действия всех людей с особыми способностями, введя «Акт о регистрации супергероев», вынуждая их раскрыть свои личности и работать на правительственные службы.  Видя в этом законе нарушение гражданских прав и плевок во всё, что он верит, Стив Роджерс открыто восстаёт против нового режима, ведя за собой группу героев, поддерживающих его мнение. В свою же очередь, Тони Старк видит правильность в новом законе, и становится во главе героев, поддерживающих его. Всё это приводит к неизбежному расколу Мстителей, и гражданской войне между двумя сторонами. Сражаясь друг с другом, Старк и Роджерс не знают о том, что таинственный Барон Земо уже строит свои собственные планы, воспользовавшись расколом величайших героев Земли.","poster":"https://image.tmdb.org/t/p/w500/7TWq9G7zU0lLG7WpMK6f5EQwwf2.jpg","url":"https://www.themoviedb.org/movie/271110","status":"watched","category":"film","subcat":"marvel","chronoOrder":15,"universeOrder":"MCU #15","genres":["Супергероика","Приключения","Боевик","Фантастика"]},{"title":"Чёрная вдова","rating":10,"tier":"solid","review":"","desc":"Наташе Романофф предстоит лицом к лицу встретиться со своим прошлым. Чёрной Вдове придется вспомнить о том, что было в её жизни задолго до присоединения к команде Мстителей, и узнать об опасном заговоре, в который оказываются втянуты её старые знакомые — Елена, Алексей (известный как Красный Страж) и Мелина.","poster":"https://image.tmdb.org/t/p/w500/mbtN6V6y5kdawvAkzqN4ohi576a.jpg","url":"https://www.themoviedb.org/movie/497698","status":"watched","category":"film","subcat":"marvel","chronoOrder":16,"universeOrder":"MCU #16","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Доктор Стрэндж","rating":10,"tier":"solid","review":"","desc":"Страшная автокатастрофа поставила крест на карьере успешного нейрохирурга Доктора Стрэнджа. Отчаявшись, он отправляется в путешествие в поисках исцеления и открывает в себе невероятные способности к трансформации пространства и времени. Теперь он — связующее звено между параллельными измерениями, а его миссия — защищать жителей Земли и противодействовать Злу, какое бы обличие оно ни принимало.","poster":"https://image.tmdb.org/t/p/w500/fR4oifDjoGFAyhWyPUl3h9H1xpQ.jpg","url":"https://www.themoviedb.org/movie/284052","status":"watched","category":"film","subcat":"marvel","chronoOrder":19,"universeOrder":"MCU #19","genres":["Супергероика","Фэнтези","Приключения","Боевик"]},{"title":"Человек-паук: Возвращение домой","rating":10,"tier":"solid","review":"","desc":"Питер Паркер - обычный школьник из Нью-Йорка, который после укуса генетически изменённого паука получает сверхспособности и становится Человеком-пауком. Под маской он защищает жителей города, используя невероятную силу, ловкость и способность цепляться за стены, а также созданные им веб-шутеры для перемещения между зданиями. После встречи с Тони Старком, Питер получает новый высокотехнологичный костюм и пытается доказать, что способен стать настоящим супергероем. Однако появление опасного преступника Стервятника превращает его обычную жизнь в серьёзное испытание, где Питеру предстоит одновременно оставаться школьником и Человеком-пауком.","poster":"https://image.tmdb.org/t/p/w500/s0DiivKEQWKZzIaw5JWbrkDGVyv.jpg","url":"https://www.themoviedb.org/movie/315635","status":"watched","category":"film","subcat":"marvel","chronoOrder":18,"universeOrder":"MCU #18","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Стражи Галактики","rating":10,"tier":"solid","review":"","desc":"Отважному путешественнику Питеру Квиллу попадает в руки таинственный артефакт, принадлежащий могущественному злодею Ронану. Чтобы спасти Вселенную от гибели, Квилл объединяется с четвёркой нелюдимых изгоев: енотом Ракетой, древоподобным гуманоидом Грутом, смертельно опасной Гаморой и одержимым жаждой мести Драксом Разрушителем.","poster":"https://image.tmdb.org/t/p/w500/4uVdNj0FWCjtG1jEYASuNzE33LS.jpg","url":"https://www.themoviedb.org/movie/118340","status":"watched","category":"film","subcat":"marvel","chronoOrder":11,"universeOrder":"MCU #11","genres":["Супергероика","Боевик","Фантастика","Приключения","Комедия"]},{"title":"Стражи Галактики. Часть 2","rating":10,"tier":"solid","review":"","desc":"Все в сборе: землянин Питер Квилл, молчаливый громила Дракс, зелёнокожая наёмница Гамора, живое дерево Грут и говорящий енот. Герои не изменяют себе и с завидной регулярностью продолжают попадать в немыслимые ситуации, выпутываясь из них почти без ущерба. На этот раз им предстоит раскрыть одну из самых главных тайн во всей Галактике: кто же на самом деле отец Питера Квилла?","poster":"https://image.tmdb.org/t/p/w500/p9hLW1dQckYuNGomOgqaXFMXcmP.jpg","url":"https://www.themoviedb.org/movie/283995","status":"watched","category":"film","subcat":"marvel","chronoOrder":12,"universeOrder":"MCU #12","genres":["Супергероика","Фантастика","Приключения","Боевик"]},{"title":"Тор: Рагнарёк","rating":10,"tier":"solid","review":"","desc":"Тор возвращается в Асгард в поисках таинственного врага, охотящегося на Камни Бесконечности. Он сталкивается с богиней смерти Хелой, теряет Мьёльнир и оказывается на планете Сакаар, где вынужден сойтись в гладиаторском поединке с Халком.","poster":"https://image.tmdb.org/t/p/w500/7pzUsnFD4T8Syeqaojcb9zheR3H.jpg","url":"https://www.themoviedb.org/movie/284053","status":"watched","category":"film","subcat":"marvel","chronoOrder":20,"universeOrder":"MCU #20","genres":["Супергероика","Боевик","Приключения","Комедия","Фантастика"]},{"title":"Чёрная пантера","rating":8,"tier":"good","review":"","desc":"С первого взгляда можно решить, что Ваканда — обычная территория дикой Африки, но это не так. Здесь, в недрах пустынных земель, скрываются залежи уникального металла вибраниума. Молодой принц Т’Чалла возвращается домой, чтобы занять законный трон и надеть маску Чёрной Пантеры, защищая свой народ от надвигающейся угрозы.","poster":"https://image.tmdb.org/t/p/w500/ndpwgAANbZSMwgTcxmQ7o4SKDsd.jpg","url":"https://www.themoviedb.org/movie/284054","status":"watched","category":"film","subcat":"marvel","chronoOrder":17,"universeOrder":"MCU #17","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Капитан Марвел","rating":11,"tier":"great","review":"","desc":"После столкновения с враждующими инопланетными расами пилот военно-воздушных сил Кэрол Дэнверс обретает суперсилу и становится неуязвимой. Героине предстоит совладать со своими новыми способностями, чтобы противостоять могущественному врагу.","poster":"https://image.tmdb.org/t/p/w500/khIspz4hW7RyEJag16UKYxI9fuP.jpg","url":"https://www.themoviedb.org/movie/299537","status":"watched","category":"film","subcat":"marvel","chronoOrder":2,"universeOrder":"MCU #2","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Мстители: Война бесконечности","rating":10,"tier":"solid","review":"","desc":"Пока Мстители и их союзники продолжают защищать мир от различных опасностей, с которыми не смог бы справиться один супергерой, новая угроза возникает из космоса: Танос. Межгалактический тиран преследует цель собрать все шесть Камней Бесконечности — артефакты невероятной силы, с помощью которых можно менять реальность по своему желанию. Всё, с чем Мстители сталкивались ранее, вело к этому моменту — судьба Земли никогда ещё не была столь неопределённой.","poster":"https://image.tmdb.org/t/p/w500/c6RSGB6O0RaaHG3JGLq8lnUJSBC.jpg","url":"https://www.themoviedb.org/movie/299536","status":"watched","category":"film","subcat":"marvel","chronoOrder":22,"universeOrder":"MCU #22","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Человек-муравей и Оса","rating":10,"tier":"solid","review":"","desc":"Скотт Лэнг, известный также, как Человек-Муравей уже заслужил право оказаться в команде Мстителей, но желание быть ближе к собственной дочке удерживает его в родном Сан-Франциско — до тех пор, пока доктор Хэнк Пим, создавший когда-то изменяющий размеры своего владельца чудо-костюм, не призывает Скотта присоединиться к новой, опасной миссии. А помогать в противостоянии с коварным врагом Человеку-Муравью будет новая напарница — Оса.","poster":"https://image.tmdb.org/t/p/w500/5r85N1iOnHFoWkyC0EeOw9aEqOW.jpg","url":"https://www.themoviedb.org/movie/363088","status":"watched","category":"film","subcat":"marvel","chronoOrder":21,"universeOrder":"MCU #21","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Мстители: Финал","rating":11,"tier":"great","review":"","desc":"После разрушительных событий в «Мстители: Войны бесконечности», вселенная лежит в руинах. Оставшиеся в живых участники команды Мстителей снова объединяются в попытке восстановить баланс во вселенной.","poster":"https://image.tmdb.org/t/p/w500/dynnf8NGGfHTNMz8Vd3CzFtYjec.jpg","url":"https://www.themoviedb.org/movie/299534","status":"watched","category":"film","subcat":"marvel","chronoOrder":23,"universeOrder":"MCU #23","genres":["Супергероика","Боевик","Фантастика","Драма"]},{"title":"Человек-паук: Вдали от дома","rating":11,"tier":"great","review":"","desc":"После битвы с Таносом и возвращения всех исчезнувших после щелчка, Питер пытается вернуться к обычной жизни. Мир переживает последствия грандиозной битвы, а сам Питер тяжело переживает гибель Тони Старка, который стал для него наставником и близким человеком. Чтобы немного отвлечься от супергеройской жизни, Питер отправляется вместе с одноклассниками в школьную поездку по Европе. Однако путешествие неожиданно прерывается, когда появляется загадочный супергерой Мистерио и просит Человека-паука помочь остановить опасных существ, угрожающих миру.","poster":"https://image.tmdb.org/t/p/w500/wL1S9750WaxxvbbuUBfkbAskDd8.jpg","url":"https://www.themoviedb.org/movie/429617","status":"watched","category":"film","subcat":"marvel","chronoOrder":26,"universeOrder":"MCU #26","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Шан-Чи и легенда десяти колец","rating":10,"tier":"solid","review":"","desc":"Мастер боевых искусств Шан-Чи сбежал от своего отца, предводителя тайной организации «Десять колец», пытаясь вести обычную жизнь в Сан-Франциско. Но прошлое настигает его, вынуждая противостоять отцу и защитить магическую деревню Та Ло.","poster":"https://image.tmdb.org/t/p/w500/rXvU6SZOGyUzy9ZHJNlVMw0OeUR.jpg","url":"https://www.themoviedb.org/movie/566525","status":"watched","category":"film","subcat":"marvel","chronoOrder":24,"universeOrder":"MCU #24","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Вечные","rating":9,"tier":"solid","review":"","desc":"Много тысячелетий назад с планеты Олимпия на Землю была отправлена группа сверхлюдей, обладающих суперспособностями, — Вечные. С доисторических времён они защищали человечество от нападений ужасных чудовищ девиантов, но любое другое вмешательство в развитие цивилизации им было запрещено. Начало XXI века. Уже несколько столетий прошло с тех пор, как был уничтожен последний девиант, когда после странного землетрясения внезапно объявляется новый монстр. Теперь живущим в разных уголках планеты Вечным снова придётся сплотить силы, чтобы противостоять новой угрозе.","poster":"https://image.tmdb.org/t/p/w500/r174t1SLtGamhPx3Wwj6f6YSyAi.jpg","url":"https://www.themoviedb.org/movie/524434","status":"watched","category":"film","subcat":"marvel","chronoOrder":25,"universeOrder":"MCU #25","genres":["Супергероика","Фантастика","Боевик","Приключения"]},{"title":"Человек-паук: Нет пути домой","rating":10,"tier":"solid","review":"","desc":"После того, как Мистерио раскрыл миру личность Питера Паркера, его жизнь полностью меняется. Оказавшись в центре внимания, Питер просит Доктора Стрэнджа помочь всем забыть, что он Человек-паук, но заклинание выходит из-под контроля и открывает путь в другие вселенные. В его мир начинают проникать знакомые враги, с которыми сражались другие версии Человека-паука. Питеру предстоит объединиться с неожиданными союзниками и попытаться вернуть порядок, одновременно столкнувшись с последствиями своего решения и окончательно повзрослеть как герой.","poster":"https://image.tmdb.org/t/p/w500/qad0kyRLHG1Qccp2A0YCCUbvhiD.jpg","url":"https://www.themoviedb.org/movie/634649","status":"watched","category":"film","subcat":"marvel","chronoOrder":27,"universeOrder":"MCU #27","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Доктор Стрэндж в мультивселенной безумия","rating":10,"tier":"solid","review":"","desc":"Продолжение истории величайшего мага Земли доктора Стивена Стрэнджа. С помощью старых и новых мистических союзников Стрэндж отправляется в мультивселенную, чтобы сразиться с новым таинственным противником.","poster":"https://image.tmdb.org/t/p/w500/sfeDNbQgEgzgM81cbPnRss6Acs4.jpg","url":"https://www.themoviedb.org/movie/453395","status":"watched","category":"film","subcat":"marvel","chronoOrder":28,"universeOrder":"MCU #28","genres":["Супергероика","Фэнтези","Боевик","Приключения"]},{"title":"Тор: Любовь и гром","rating":10,"tier":"solid","review":"","desc":"Джейн Фостер берет на себя обязанности Бога-громовержца и становится обладательницей молота Мьёльнира.","poster":"https://image.tmdb.org/t/p/w500/xWA0Av3mO7uH2bqGU7QMfckY9si.jpg","url":"https://www.themoviedb.org/movie/616037","status":"watched","category":"film","subcat":"marvel","chronoOrder":29,"universeOrder":"MCU #29","genres":["Супергероика","Фэнтези","Боевик","Комедия"]},{"title":"Человек-муравей и Оса: Квантомания","rating":null,"tier":"unrated","review":"","desc":"Скотт Лэнг, Хоуп ван Дайн, Хэнк Пим и Джанет ван Дайн случайно отправляются в опасное путешествие по неизведанному Квантовому измерению, где сталкиваются с могущественным Кангом Завоевателем.","poster":"https://image.tmdb.org/t/p/w500/8BoKsen8orEAiFWCmQkwmONjuTX.jpg","url":"https://www.themoviedb.org/movie/640146","status":"planned","category":"film","subcat":"marvel","chronoOrder":31,"universeOrder":"MCU #31","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Стражи Галактики. Часть 3","rating":10,"tier":"solid","review":"","desc":"Питер Квилл никак не может смириться с потерей Гаморы и теперь вместе со Стражами Галактики вынужден отправиться на очередную миссию по защите Вселенной.","poster":"https://image.tmdb.org/t/p/w500/mz7lPfNOLOWDKoz625tFgNcSPVi.jpg","url":"https://www.themoviedb.org/movie/447365","status":"watched","category":"film","subcat":"marvel","chronoOrder":32,"universeOrder":"MCU #32","genres":["Супергероика","Фантастика","Приключения","Боевик"]},{"title":"Чудо-женщина","rating":9,"tier":"solid","review":"","desc":"В костюме, украшенном звездами, и с лассо Истины, сделанным из пояса Геи, Диана Принс прибыла в наш мир, и вскоре люди окрестили ее Чудо-Женщиной. Чудо-женщина добровольно идет служить в армию под своим настоящим именем, чтобы затем сражаться с фашистами.","poster":"https://image.tmdb.org/t/p/w500/7vHxWO6ahByDWzWufFL48MXaktT.jpg","url":"https://www.themoviedb.org/tv/4331","status":"watched","category":"film","subcat":"dc","chronoOrder":1,"universeOrder":"DC #1","genres":["Супергероика","Фантастика","Фэнтези","Боевик","Приключения","Драма"]},{"title":"Чудо-женщина: 1984","rating":10,"tier":"solid","review":"","desc":"1984 год. Диана всё ещё грустит по погибшему Стиву, борется с мелким криминалом и работает в музее Смитсоновского института. Однажды она знакомится с новой коллегой Барбарой, специалисткой широкого профиля, которой поручено изучить новые артефакты. Среди древних предметов оказывается загадочный кристалл, который исполняет желания. Так к Диане внезапно возвращается Стив, а застенчивая и неуклюжая Барбара обретает невероятную силу, сноровку и привлекательность. Но за волшебным кристаллом охотится бизнесмен Максвелл Лорд, и у него имеются очень коварные планы на этот артефакт.","poster":"https://image.tmdb.org/t/p/w500/1B2YJCYyRudISmfSWCRfc95gAtq.jpg","url":"https://www.themoviedb.org/movie/464052","status":"watched","category":"film","subcat":"dc","chronoOrder":2,"universeOrder":"DC #2","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Человек из стали","rating":10,"tier":"solid","review":"","desc":"Кларк Кент (Кал-Эл) — молодой журналист, который чувствует себя чужаком из-за своей невероятной силы. Много лет назад он был отправлен на Землю с развитой планеты Криптон, и теперь задаётся вопросом: зачем?  Воспитанный приёмными родителями Мартой и Джонатаном Кентами, Кларк знает: обладать сверхспособностями — значит принимать сложные решения. Но когда человечество более всего нуждается в стабильности, оно подвергается нападению. Сможет ли герой восстановить мир, или воспользуется своей силой для того, чтобы окончательно его разрушить?  Кларк должен стать супергероем известным как «Супермен», чтобы вселять надежду в сердца людей и защищать тех, кого он любит.","poster":"https://image.tmdb.org/t/p/w500/azlOOwkq3FS0unvTBjtQVsz6YIk.jpg","url":"https://www.themoviedb.org/movie/49521","status":"watched","category":"film","subcat":"dc","chronoOrder":3,"universeOrder":"DC #3","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Отряд самоубийц","rating":10,"tier":"solid","review":"","desc":"Правительство решает дать команде суперзлодеев шанс на искупление. Подвох в том, что их отправляют на миссию, где они, вероятнее всего, погибнут...","poster":"https://image.tmdb.org/t/p/w500/7tJjv7vPBhG2pzcTIMgGBV1mL4w.jpg","url":"https://www.themoviedb.org/movie/297761","status":"watched","category":"film","subcat":"dc","chronoOrder":5,"universeOrder":"DC #5","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Отряд самоубийц: Миссия навылет","rating":null,"tier":"unrated","review":"","desc":"Отобрав наиболее перспективных заключенных из тюрьмы, в которой содержатся не только самые опасные преступники, но и люди со свехрспособностями, и даже не люди, правительственный агент отправляет их на самоубийственное задание в одну латиноамериканскую страну, где недавно произошел военный переворот. А чтобы те наверняка не сбежали, каждому в голову вживляется взрывное устройство.","poster":"https://image.tmdb.org/t/p/w500/asD8pGLw2uI3HzPtjuX8ls8RNsg.jpg","url":"https://www.themoviedb.org/movie/436969","status":"planned","category":"film","subcat":"dc","chronoOrder":11,"universeOrder":"DC #11","genres":["Супергероика","Боевик","Комедия","Приключения"]},{"title":"Бэтмен против Супермена: На заре справедливости","rating":10,"tier":"solid","review":"","desc":"Опасаясь, что действия богоподобного супергероя так и останутся бесконтрольными, грозный и могущественный страж Готэм Сити бросает вызов самому почитаемому в наши дни спасителю Метрополиса, в то время как весь остальной мир решает, какой герой ему по-настоящему нужен. И пока Бэтмен и Супермен пребывают в состоянии войны друг с другом, возникает новая угроза, которая ставит человечество под самую большую опасность, с которой оно когда-либо сталкивалось.","poster":"https://image.tmdb.org/t/p/w500/tAQOcxxcZbpM1jEhz7hJC5nmCDi.jpg","url":"https://www.themoviedb.org/movie/209112","status":"watched","category":"film","subcat":"dc","chronoOrder":4,"universeOrder":"DC #4","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Лига справедливости","rating":10,"tier":"solid","review":"","desc":"Брюс Уэйн, вдохновленный самопожертвованием Супермена, вновь обретает веру в человечество. Он заручается поддержкой новой союзницы, Дианы Принс, чтобы сразиться с еще более могущественным врагом — Степным Волком. Бэтмен и Чудо-Женщина набирают команду супергероев: Аквамена, Киборга и Флэша.","poster":"https://image.tmdb.org/t/p/w500/e2f1GaWLkk5Sj7cZMi38mUPXYdt.jpg","url":"https://www.themoviedb.org/movie/141052","status":"watched","category":"film","subcat":"dc","chronoOrder":6,"universeOrder":"DC #6","genres":["Супергероика","Боевик","Фантастика","Приключения","Фэнтези"]},{"title":"Лига справедливости Зака Снайдера","rating":null,"tier":"unrated","review":"","desc":"Вдохновившись самопожертвованием Супермена, Брюс Уэйн вновь обретает веру в человечество. Он заручается поддержкой новой союзницы Дианы Принс, чтобы сразиться с ещё более могущественным противником. Бэтмен и Чудо-женщина набирают команду сверхлюдей для борьбы с пробудившейся угрозой.","poster":"https://image.tmdb.org/t/p/w500/tpPWUv258JrMSIdkVVV1NDp3aoT.jpg","url":"https://www.themoviedb.org/movie/791373","status":"planned","category":"film","subcat":"dc","chronoOrder":7,"universeOrder":"DC #7","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Аквамен","rating":15,"tier":"great","review":"","desc":"Действие фильма разворачивается в необъятном и захватывающем подводном мире семи морей, а сюжет знакомит зрителей с историей происхождения получеловека-полуатланта Артура Карри и ключевыми событиями его жизни — теми, что заставят его не только столкнуться с самим собой, но и выяснить, достоин ли он быть тем, кем ему суждено... царём!","poster":"https://image.tmdb.org/t/p/w500/hA5rapmD3Lwv4I981yh6Ct8zvIC.jpg","url":"https://www.themoviedb.org/movie/297802","status":"watched","category":"film","subcat":"dc","chronoOrder":8,"universeOrder":"DC #8","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Шазам!","rating":15,"tier":"great","review":"","desc":"В каждом из нас живет супергерой, нужна лишь толика магии, чтобы он проявил себя. Билли Бэтсон должен прокричать всего лишь одно слово - ШАЗАМ - чтобы из сообразительного четырнадцатилетнего мальчишки превратиться во взрослого супергероя Шазама.","poster":"https://image.tmdb.org/t/p/w500/s4byZ8CP7NLfH54FV3QF6l0JLSh.jpg","url":"https://www.themoviedb.org/movie/287947","status":"watched","category":"film","subcat":"dc","chronoOrder":9,"universeOrder":"DC #9","genres":["Супергероика","Боевик","Комедия","Фэнтези"]},{"title":"Хищные птицы: Потрясающая история Харли Квинн","rating":null,"tier":"unrated","review":"","desc":"Харли Квинн рассталась с Джокером и через некоторое время сообщила об этом всему Готэму, взорвав тот самый химзавод. Девушка больше не тоскует по несостоявшимся отношениям - ей некогда, так как она также потеряла неприкосновенность, и теперь за ней охотятся разной степени криминализованности граждане, желающие отомстить. А в это время ставший крёстным отцом Готема Роман Сайонис очень жаждет вернуть пропавший бриллиант, который стащила у его подручного малолетняя карманница.","poster":"https://image.tmdb.org/t/p/w500/11ZCJWv9OK1ubjiMSqQUtt4reWF.jpg","url":"https://www.themoviedb.org/movie/495764","status":"planned","category":"film","subcat":"dc","chronoOrder":10,"universeOrder":"DC #10","genres":["Супергероика","Боевик","Криминал"]},{"title":"Чёрный Адам","rating":11,"tier":"great","review":"","desc":"Спустя почти 5 000 лет после того, как он был наделен всемогущими силами египетских богов и так же быстро заключен в тюрьму, Черный Адам освобождается из своей земной гробницы и готов обрушить свою уникальную форму правосудия на современный мир.","poster":"https://image.tmdb.org/t/p/w500/ebtyQ43I2QSeEJiXYNFgSp4yuYT.jpg","url":"https://www.themoviedb.org/movie/436270","status":"watched","category":"film","subcat":"dc","chronoOrder":12,"universeOrder":"DC #12","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Флэш","rating":null,"tier":"unrated","review":"","desc":"Когда Барри Аллен был маленьким, больше всего на свете ему хотелось быть супергероем – тем, кто превосходит лимиты человеческого организма и использует во благо данную ему силу. Когда Барри было одиннадцать лет, он на собственном опыте узнал, что люди с необычными способностями действительно существуют: его мать была убита одним из таких людей. Повзрослев и став судмедэкспертом, Барри не отбросил мыслей о сверхлюдях и продолжал искать доказательства их существования, что не лучшим образом сказывалось на его репутации и общении с коллегами. Впрочем, однажды его усилия были вознаграждены...","poster":"https://image.tmdb.org/t/p/w500/q14oRmj0ITMBzqHUdiGwXUIvg7t.jpg","url":"https://www.themoviedb.org/tv/60735","status":"planned","category":"film","subcat":"dc","chronoOrder":13,"universeOrder":"DC #13","genres":["Супергероика","Драма","Фантастика","Фэнтези"]},{"title":"Ведьмак 1","rating":9,"tier":"solid","review":"","desc":"Геральт из Ривии, наемный охотник за чудовищами, перенесший мутации, идет навстречу своей судьбе в неспокойном мире, где люди часто оказываются куда коварнее чудовищ.","poster":"https://image.tmdb.org/t/p/w500/rY2c2LhN07CRKlAbRaDZxN2XjvK.jpg","url":"https://www.themoviedb.org/tv/71912","status":"watched","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма","Боевик","Приключения"]},{"title":"Ведьмак 2","rating":9,"tier":"solid","review":"","desc":"Геральт из Ривии, наемный охотник за чудовищами, перенесший мутации, идет навстречу своей судьбе в неспокойном мире, где люди часто оказываются куда коварнее чудовищ.","poster":"https://image.tmdb.org/t/p/w500/rY2c2LhN07CRKlAbRaDZxN2XjvK.jpg","url":"https://www.themoviedb.org/tv/71912","status":"watched","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма","Боевик","Приключения"]},{"title":"Ведьмак 3","rating":null,"tier":"unrated","review":"","desc":"Геральт из Ривии, наемный охотник за чудовищами, перенесший мутации, идет навстречу своей судьбе в неспокойном мире, где люди часто оказываются куда коварнее чудовищ.","poster":"https://image.tmdb.org/t/p/w500/rY2c2LhN07CRKlAbRaDZxN2XjvK.jpg","url":"https://www.themoviedb.org/tv/71912","status":"dropped","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма","Боевик","Приключения"]},{"title":"Тень и кость 1","rating":null,"tier":"unrated","review":"","desc":"В мире, разделенном на две части массивным барьером вечной темноты, где неестественные существа питаются человеческой плотью, молодой солдат раскрывает силу, которая может, наконец, объединить ее страну. Но, когда она борется за свою власть, против нее строят заговоры опасные силы. Бандиты, воры, убийцы и святые сейчас в состоянии войны, и для выживания потребуется больше, чем магия.","poster":"https://image.tmdb.org/t/p/w500/zMxOK6oRAPATW6vWzvkVfqcq98x.jpg","url":"https://www.themoviedb.org/tv/85720","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фантастика","Фэнтези"]},{"title":"Тень и кость 2","rating":null,"tier":"unrated","review":"","desc":"В мире, разделенном на две части массивным барьером вечной темноты, где неестественные существа питаются человеческой плотью, молодой солдат раскрывает силу, которая может, наконец, объединить ее страну. Но, когда она борется за свою власть, против нее строят заговоры опасные силы. Бандиты, воры, убийцы и святые сейчас в состоянии войны, и для выживания потребуется больше, чем магия.","poster":"https://image.tmdb.org/t/p/w500/zMxOK6oRAPATW6vWzvkVfqcq98x.jpg","url":"https://www.themoviedb.org/tv/85720","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фантастика","Фэнтези"]},{"title":"Конец этого ёбаного мира","rating":9,"tier":"solid","review":"","desc":"Джеймсу семнадцать и он уверен, что он - психопат. Алисе тоже семнадцать, она - капризная новенькая девчонка в школе. Они с пол-оборота заводят подростковый роман, и Алиса уговаривает Джеймса начать поиски её отца. Джеймсу от Алисы тоже кое-что нужно.","poster":"https://image.tmdb.org/t/p/w500/mXlGqhVyrKieJli2eQq4jOg7WFz.jpg","url":"https://www.themoviedb.org/tv/74577","status":"watched","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Криминал"]},{"title":"Конец этого ёбаного мира 2","rating":9,"tier":"solid","review":"","desc":"Джеймсу семнадцать и он уверен, что он - психопат. Алисе тоже семнадцать, она - капризная новенькая девчонка в школе. Они с пол-оборота заводят подростковый роман, и Алиса уговаривает Джеймса начать поиски её отца. Джеймсу от Алисы тоже кое-что нужно.","poster":"https://image.tmdb.org/t/p/w500/mXlGqhVyrKieJli2eQq4jOg7WFz.jpg","url":"https://www.themoviedb.org/tv/74577","status":"watched","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Криминал"]},{"title":"Игра кальмара 1","rating":9,"tier":"solid","review":"","desc":"Из-за нужды в деньгах сотни игроков принимают странное приглашение поучаствовать в детских соревнованиях. Их ждет заманчивый приз, но ставки смертельно высоки.","poster":"https://image.tmdb.org/t/p/w500/6zHKgCKht3vwrtSXFvSUntSRsJh.jpg","url":"https://www.themoviedb.org/tv/93405","status":"watched","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Детектив","Драма"]},{"title":"В поисках Аляски","rating":null,"tier":"unrated","review":"","desc":"Главный герой, шестнадцатилетний Майлз Холтер, интересуется предсмертными высказываниями известных людей. Следуя последним словам Франсуа Рабле, он оставляет свою скучную жизнь с родителями и оправляется учиться в новую школу Калвер Крик в поисках «Великого «Возможно»». Здесь он находит первых друзей и влюбляется в девочку по имени Аляска Янг, которая переворачивает его жизнь, а потом исчезает из неё. Ужасная трагедия заставляет Майлза серьезно задуматься над вопросами жизни и смерти.","poster":"https://image.tmdb.org/t/p/w500/nV1ZTHsILOETTARczD4ns5YySa0.jpg","url":"https://www.themoviedb.org/tv/88640","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Школа разбитых сердец","rating":null,"tier":"unrated","review":"","desc":"Панорама жизни старшеклассников школы Хартли из мульти-расового района Сиднея: наркотики, любовь, религия, бездомность - запретных тем нет.","poster":"https://image.tmdb.org/t/p/w500/6O6bKf7u4xJshV21hP1d9Bn7l0h.jpg","url":"https://www.themoviedb.org/tv/12998","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Люпен","rating":null,"tier":"unrated","review":"","desc":"Ассан Диоп ещё в детстве прочитал книгу о приключениях грабителя Арсена Люпена и теперь собирается обчистить Лувр. Он сделает это красиво - во время аукциона, где выставляется дорогое колье. Но дело не только в деньгах: это месть богатому семейству, из-за которого 25 лет назад отца Диопа незаслуженно осудили за преступление.","poster":"https://image.tmdb.org/t/p/w500/64Eu2KUZOFhhSmkdb3oUw124tYQ.jpg","url":"https://www.themoviedb.org/tv/96677","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Криминал","Драма","Детектив"]},{"title":"Аватар Короля (дорама)","rating":null,"tier":"unrated","review":"","desc":"В популярной онлайн-игре «Слава» Е Сю — легендарный топ-игрок, известный как «Бог битв». Из-за конфликта с руководством команды его вынуждают уйти в отставку. Он устраивается администратором в интернет-кафе, а с открытием десятого сервера возвращается в игру с самодельным оружием, начав путь обратно к вершине.","poster":"https://image.tmdb.org/t/p/w500/i8q25VBh7ID9rbi5zz4pCO8Djqm.jpg","url":"https://www.themoviedb.org/tv/91470","status":"dropped","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Боевик","Приключения"]},{"title":"Дэш и  Лили","rating":null,"tier":"unrated","review":"","desc":"В Рождество противоположности притягиваются. Циник Дэш и оптимистка Лили обмениваются посланиями в красном блокноте, который они оставляют друг другу по всему Нью-Йорку.","poster":"https://image.tmdb.org/t/p/w500/olMgJjGeQHhLZaco8S7BpjCCeym.jpg","url":"https://www.themoviedb.org/tv/111625","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Пловец (дорама)","rating":null,"tier":"unrated","review":"","desc":"История о двух пловцах: Бай Янь Цзэ, спортивном гении из обычной семьи, и и его лучшем друге, принце плавания Лань Тяне. Конечно, не обойдется без любовного треугольника, в центре которого окажется Сон Ча Ча, богатая девушка с серьезными семейными проблемами. Она встречается с Лань Тянем, но без видимой причины он ее бросает. Через какое-то время дружба двух главных героев перерастает в постоянную борьбу. Они сражаются во всем: от любви до карьеры. Оба спортсмена проходят интенсивные тренировки для участия в национальном отборе пловцов. Перед началом финального состязания отец Лань Тяна угрожает Янь Цзэ и требует, чтобы он снялся с заплыва. Во имя справедливости и ради достижения честного спортивного результата принц плавания помогает своему другу отстоять свою репутацию. Пройдя череду неожиданных поворотов судьбы, главные герои смогут воспитать в себе ответственность и упорство характера, создать яркий внутренний мир, свойственный представителям выдающейся молодежи","poster":"https://image.tmdb.org/t/p/w500/kdiRXgYKfZtK0CjS8EN9V2KDgUa.jpg","url":"https://www.themoviedb.org/tv/82951","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Драма","Триллер"]},{"title":"Хорошая работа (дорама)","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://image.tmdb.org/t/p/w500/lRPGeHIT5MlWD3AZzNdbR9LHNnc.jpg","url":"https://www.themoviedb.org/movie/1721700","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Комедия"]},{"title":"Месть от третьего лица","rating":null,"tier":"unrated","review":"","desc":"Ок Чан Ми – 19-летняя ученица старшей школы. Раньше она была стрелком в школьной команде. Однажды брат-близнец Ок Чан Ми умирает. В попытках выяснить, что произошло, она начинает общаться в Чжи Су Хоном, который занимается тем, что мстит за учеников, над которыми издеваются в школе.","poster":"https://image.tmdb.org/t/p/w500/2uI87oGnS6sUORMVVZltZYAlrZh.jpg","url":"https://www.themoviedb.org/tv/208336","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Детектив","Триллер"]},{"title":"Детство Шелдона","rating":null,"tier":"unrated","review":"","desc":"История о непростом детстве вундеркинда Шелдона Купера. Родители юного гения не разделяют увлечения сына наукой: его мать очень религиозна, а отец, бывший футбольный тренер, предпочитает проводить вечера в компании пива и телевизора. Со сверстниками тоже не ладится, ведь Шелдона куда больше детских игрушек интересует, где можно взять обогащённый уран для научных экспериментов.","poster":"https://image.tmdb.org/t/p/w500/9bZR5H7LrEo4i9gYoKvUhvcfr1y.jpg","url":"https://www.themoviedb.org/tv/71728","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Семейный","Драма"]},{"title":"Бандит, ставший старшеклассником (дорама)","rating":null,"tier":"unrated","review":"","desc":"47-летний гангстер Ким Дык Пал — второе лицо в банде. У него нет образования из-за бедности родителей, но он всегда мечтал поступить в университет. Он даже учится, чтобы воплотить свою мечту, но учеба дается ему тяжело. Однажды Ким Дык Пал замечает молодого человека Сон Ли Хона, который собрался покончить с собой. В этот момент каким-то образом Ким Дык Палу удалось вселиться в тело юноши и спасти его. Также он узнал, что над Ли Хоном издеваются в школе, и именно поэтому он решил свести счеты с жизнью. Будучи в теле старшеклассника, Ким Дык Пал решает разобраться в обидчиками и отправляется в школу. Там он сближается с Чхве Се Гёном, образцовым учеником, жизнь которого кажется идеальным, но никто не знает, что он подвергается домашнему насилию со стороны отца.","poster":"https://image.tmdb.org/t/p/w500/yzZ2WwfjDqPZPSco2WoCj1pGqLS.jpg","url":"https://www.themoviedb.org/tv/224030","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Фантастика","Фэнтези","Драма"]},{"title":"Секретный уровень","rating":null,"tier":"unrated","review":"","desc":"Анимационный сериал, состоящий из оригинальных коротких историй, действие которых разворачивается в мирах любимых видеоигр.","poster":"https://image.tmdb.org/t/p/w500/rymRp36Kkl76CpQZr9m12ziIbI5.jpg","url":"https://www.themoviedb.org/tv/261579","status":"planned","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Фантастика","Фэнтези","Боевик","Приключения"]},{"title":"Игра кальмара 2","rating":10,"tier":"solid","review":"","desc":"Из-за нужды в деньгах сотни игроков принимают странное приглашение поучаствовать в детских соревнованиях. Их ждет заманчивый приз, но ставки смертельно высоки.","poster":"https://image.tmdb.org/t/p/w500/6zHKgCKht3vwrtSXFvSUntSRsJh.jpg","url":"https://www.themoviedb.org/tv/93405","status":"watched","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Детектив","Драма"]},{"title":"Игра кальмара 3","rating":null,"tier":"unrated","review":"","desc":"Из-за нужды в деньгах сотни игроков принимают странное приглашение поучаствовать в детских соревнованиях. Их ждет заманчивый приз, но ставки смертельно высоки.","poster":"https://image.tmdb.org/t/p/w500/6zHKgCKht3vwrtSXFvSUntSRsJh.jpg","url":"https://www.themoviedb.org/tv/93405","status":"watching","category":"series","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Детектив","Драма"]},{"title":"Леди баг и супер кот 4","rating":12,"tier":"great","review":"","desc":"Леди Баг и Супер-Кот столкнутся с новым врагом — таинственным, тревожным, неуловимым и все же близким к ним. Очень близким, но они об этом не догадываются. К тому же, Маринетт и Эдриан никогда не были так близки друг к другу, но это не обязательно делает их повседневную жизнь ложем из роз, поскольку они хранят тайны друг от друга. Самая большая тайна в том, что они все еще не знают, что они Леди Баг и Супер-Кот. В новом и образцовом зеленом Париже, в самом сердце новой и революционной школы, наши герои переживут учебный год, полный эмоций и откровений.","poster":"https://image.tmdb.org/t/p/w500/pJKWBSVPebRcyLe3pM5awvMioy8.jpg","url":"https://www.themoviedb.org/tv/65334","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Мультфильм","Детский","Семейный"]},{"title":"Леди баг и супер кот 5","rating":10,"tier":"solid","review":"","desc":"Леди Баг и Супер-Кот столкнутся с новым врагом — таинственным, тревожным, неуловимым и все же близким к ним. Очень близким, но они об этом не догадываются. К тому же, Маринетт и Эдриан никогда не были так близки друг к другу, но это не обязательно делает их повседневную жизнь ложем из роз, поскольку они хранят тайны друг от друга. Самая большая тайна в том, что они все еще не знают, что они Леди Баг и Супер-Кот. В новом и образцовом зеленом Париже, в самом сердце новой и революционной школы, наши герои переживут учебный год, полный эмоций и откровений.","poster":"https://image.tmdb.org/t/p/w500/pJKWBSVPebRcyLe3pM5awvMioy8.jpg","url":"https://www.themoviedb.org/tv/65334","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Мультфильм","Детский","Семейный"]},{"title":"Удача","rating":10,"tier":"solid","review":"","desc":"Сэм Гринфилд – самая невезучая девочка в мире! Внезапно оказавшись в невиданной Стране Удачи, она объединяется с населяющими ее волшебными существами, чтобы вернуть свое везение.","poster":"https://image.tmdb.org/t/p/w500/1tNajPL9FmFbM0msgFF1DMVdpcs.jpg","url":"https://www.themoviedb.org/movie/585511","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Комедия","Фэнтези","Семейный"]},{"title":"Кот в сапогах","rating":10,"tier":"solid","review":"","desc":"Кот в сапогах объединяется с умным Шалтай-Болтаем и сообразительной Кисой Мягколапкой, чтобы украсть знаменитую Гусыню, несущую золотые яйца.","poster":"https://image.tmdb.org/t/p/w500/4iuuvaCYNswlhG5f73JqX976a9d.jpg","url":"https://www.themoviedb.org/movie/417859","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Комедия","Семейный","Фэнтези"]},{"title":"Кот в сапогах: Три Чертёнка","rating":10,"tier":"solid","review":"","desc":"Кот в сапогах соглашается помочь принцессе вернуть украденный рубин «Сердце огня» из лап коварного вора по кличке Шептун. Его проводниками и помощниками становятся трое озорных котят, которых называют Три Чертёнка.","poster":"https://image.tmdb.org/t/p/w500/ptvbHUWpU8Nh6vrmSvjx4ESDgfC.jpg","url":"https://www.themoviedb.org/movie/83201","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Мультфильм","Комедия","Семейный"]},{"title":"Кот в сапогах 2: Последнее желание","rating":15,"tier":"great","review":"","desc":"Спустя десять лет после событий первого фильма Кот в сапогах обнаруживает, что потратил восемь из девяти своих жизней. Теперь он отправляется в эпическое путешествие в поисках мифического Последнего Желания, чтобы восстановить свои жизни, скрываясь от смертельно опасного Волка-наёмника.","poster":"https://image.tmdb.org/t/p/w500/z2gOE3Z4mNLAcw0dQ1BlGoWLrH7.jpg","url":"https://www.themoviedb.org/movie/315162","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Фэнтези","Комедия","Семейный"]},{"title":"Человек паук: через вселенные","rating":10,"tier":"solid","review":"","desc":"Майлз Моралес - обычный подросток из Бруклина, который после укуса радиоактивного паука получает сверхспособности: он становится сильнее, быстрее, может цепляться за стены и чувствовать опасность. Пытаясь разобраться с новыми силами, Майлз сталкивается с настоящим Человеком-пауком, Питером Паркером. После трагической гибели Питера, Майлз решает продолжить его дело, но вскоре узнаёт, что существует не один Человек-паук. Из-за эксперимента с коллайдером в его мир начинают проникать герои-пауки из параллельных вселенных, и Майлзу вместе с ними предстоит остановить угрозу, способную разрушить границы между мирами.","poster":"https://image.tmdb.org/t/p/w500/oCAi3NdfXNYLd8PROu5ycUhVety.jpg","url":"https://www.themoviedb.org/movie/324857","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Семейный"]},{"title":"Зверополис","rating":10,"tier":"solid","review":"","desc":"Добро пожаловать в Зверополис - современный город, населённый самыми разными животными, от огромных слонов до крошечных мышек. В город приезжает новый офицер полиции, крольчиха Джуди Хоппс, которая с 1-ых дней работы понимает, как сложно быть маленькой и пушистой среди больших и сильных полицейских. Судьба сводит её с хитроватым, но обаятельным лисом Ником Уайлдом. Вместе они берутся за расследование загадочного дела о пропавших животных, которое оказывается гораздо масштабнее и опаснее, чем казалось сначала.","poster":"https://image.tmdb.org/t/p/w500/5qcww3ZqlpCqPrUessuFkdwsDL2.jpg","url":"https://www.themoviedb.org/movie/269149","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Семейный","Комедия"]},{"title":"Зверопой","rating":100,"tier":"masterpiece","review":"","desc":"Неважно кто ты: грабитель банков или домохозяйка - все рвутся к славе. Овца, горилла, бык или даже свинья - каждое животное мечтает стать звездой. Всё как у людей.","poster":"https://image.tmdb.org/t/p/w500/vlXBtiqwNrcheDh4TB5kHTRnlUY.jpg","url":"https://www.themoviedb.org/movie/335797","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Комедия","Семейный","Музыка"]},{"title":"Зверопой 2","rating":100,"tier":"masterpiece","review":"","desc":"Тяжело быть продюсером, когда ты коала и у тебя лапки. Ещё сложнее, когда твоя верная помощница древнее печатной машинки. И совсем весело, когда твоя труппа — это танцующий без остановки пухляш, колючая девочка-панк, застенчивая школьница, верзила-гангстер и многодетная мама, чьи дети — поросята в прямом смысле слова. Рецепт успеха прост — рвануть в мировую столицу развлечений, завербовать легендарного рок-музыканта и взорвать сцену новым шоу.","poster":"https://image.tmdb.org/t/p/w500/cYWc9bCi2gprrXnIMa4MqXUTpNu.jpg","url":"https://www.themoviedb.org/movie/438695","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Комедия","Семейный","Музыка"]},{"title":"Плохие парни","rating":15,"tier":"great","review":"","desc":"Мир еще не видел столь искусных авантюристов: ловкий карманник Мистер Волк, опытный взломщик сейфов Мистер Змей, хладнокровный мастер маскировки Мистер Акула, вспыльчивый и мускулистый Мистер Пиранья, а также остроумная хакер высшего класса Мисс Тарантула. Однако даже самые умные преступники иногда допускают ошибки. Чтобы спастись от неминуемый тюрьмы, главарь банды Мистер Волк вынужден идти на крайние меры: «Плохие парни» должны измениться в лучшую сторону. Или сделать вид? Но когда новый злодей угрожает городу, сможет ли Мистер Волк убедить остальных действительно стать… хорошими ребятами?","poster":"https://image.tmdb.org/t/p/w500/5pAo3fhARrsu3UhoxyWADLukPwz.jpg","url":"https://www.themoviedb.org/movie/629542","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Мультфильм","Комедия","Криминал","Семейный"]},{"title":"Суперпитомцы","rating":null,"tier":"unrated","review":"","desc":"Пес Крипто — лучший друг Супермена, обладающий такими же внеземными способностями, как и его хозяин. Вместе они отважно борются с преступностью в Метрополисе. Но когда Супермена и других членов Лиги справедливости похищают неизвестные злодеи, Крипто приходится подготовить новых помощников, а именно разношерстную компанию животных из приюта, которые неожиданно обрели суперсилу. Сможет ли пушистая Лига суперпитомцев спасти Супермена, а заодно и весь мир?","poster":"https://image.tmdb.org/t/p/w500/75jSDcQtHrcVoSflDolT7PC5v82.jpg","url":"https://www.themoviedb.org/movie/539681","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Семейный","Комедия","Приключения","Мультфильм","Фантастика","Боевик"]},{"title":"Чип и Дейл спешат на помощь","rating":null,"tier":"unrated","review":"","desc":"Главные герои мультсериала — бурундуки Чип и Дейл, которые вместе с их друзьями Рокфором, Гайкой и Вжиком образуют «Команду спасателей» и защищают родной город от преступности. Как только где-то запахло опасностью, наши маленькие герои тут же прибегут, они уже спешат на помощь всем, кому она понадобится.","poster":"https://image.tmdb.org/t/p/w500/cVa6j0tiZ4y68Rm5RnDIvxEXzSR.jpg","url":"https://www.themoviedb.org/tv/1615","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Комедия","Детский","Семейный","Боевик","Приключения"]},{"title":"Энтергалактик","rating":null,"tier":"unrated","review":"","desc":"Джараби - молодой парень, который обожает музыку. Он хочет стать популярным музыкантом, поэтому отправляется в Нью-Йорк, где у него явно будет больше шансов. Совсем недавно он расстался с девушкой и теперь решил всего себя посвятить осуществлению мечты. Но у судьбы свои планы. Герой знакомится с очаровательной соседкой Мэдоу, которая увлекается фотографией и хочет построить успешную карьеру. С первого взгляда она очаровывает его, и Джараби оказывается в сложном положении. Что ему выбрать: новые отношения или достижение цели. К тому же, ситуацию усугубляет неожиданное появление бывшей...","poster":"https://image.tmdb.org/t/p/w500/e2NZcmjoqYqzRm7cgsjAiaYIJ9n.jpg","url":"https://www.themoviedb.org/movie/1027014","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Романтика","Музыка","Комедия","Семейный"]},{"title":"Я краснею","rating":9,"tier":"solid","review":"","desc":"Торонто, 2002 год. Активная и неунывающая 13-летняя Мэйлинь всеми силами пытается быть первой во всём, чтобы угодить строгой гиперопекающей матери. Семья девочки живёт при храме и поклоняется Богине-прародительнице. Одним прекрасным утром Мэйлинь просыпается и вместо привычного отражения в зеркале видит красную панду — теперь, когда она волнуется, злится или испытывает другие сильные эмоции, превращается в большого зверя.","poster":"https://image.tmdb.org/t/p/w500/ft3eKr1ah85out6t6nAsZ1EAdUM.jpg","url":"https://www.themoviedb.org/movie/508947","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Семейный","Комедия","Фэнтези"]},{"title":"Мавка. Лесная песня","rating":null,"tier":"unrated","review":"","desc":"Древний волшебный Лес никогда не пускал людей в свои таинственные глубины. Люди из соседнего села и сами держались от него подальше - думали, что Лес опасен, потому что в нём обитают загадочные лесные существа. И вдруг произошло чудо. Мавка - одна из тех самых лесных созданий, душа Леса и его будущая царица, - и Лукаш, простой деревенский кузнец, полюбили друг друга больше всего на свете. Но их миры пошли войной друг на друга. А всё из-за появления в селе коварной фабрикантши Килины, которая построила рядом с лесом фабрику, задумав уничтожить Лес. Смогут ли Мавка и Лукаш остановить войну между людьми и Лесом? Помешают ли они Килине покорить природу? Спасут ли собственную любовь?","poster":"https://image.tmdb.org/t/p/w500/mjVNDAYjHW93FWTR8BJAffTszeK.jpg","url":"https://www.themoviedb.org/movie/459003","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Семейный","Фэнтези"]},{"title":"Базз Лайтер","rating":null,"tier":"unrated","review":"","desc":"«Базз Лайтер» расскажет не о персонаже, известном поклонникам основной серии мультфильмов, а о вымышленном космонавте, на основе которого и начали выпускать те самые игрушки.","poster":"https://image.tmdb.org/t/p/w500/DQU4vUTMoAlUGJIC5hNfHPVELz.jpg","url":"https://www.themoviedb.org/movie/718789","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Фантастика","Семейный","Приключения"]},{"title":"Том и Джерри","rating":9,"tier":"solid","review":"","desc":"«Том и Джерри в детстве» несколько подобна классическому «Том и Джерри». Котёнок Том постоянно пытается поймать мышонка Джерри, часто терпя неудачу.","poster":"https://image.tmdb.org/t/p/w500/pApniCXhegDnhxQda7RcpG8gFP0.jpg","url":"https://www.themoviedb.org/tv/4274","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Детский","Мультфильм","Комедия","Семейный"]},{"title":"Пламенное сердце","rating":10,"tier":"solid","review":"","desc":"С самого детства у Джорджии Нолан была только одна мечта: стать пожарным, как ее папа! К сожалению, законы того времени не оставляли шанса этой мечте осуществиться. Но когда в городе стали один за другим пропадать пожарные, а таинственные пожары — сжигать дотла городские театры, Джорджиа поняла: вот она, ее возможность! Переодевшись в «Джо», неуклюжего парня с усиками, она присоединяется к команде пожарных-добровольцев, которым поручено остановить загадочного поджигателя. Джорджии придется здорово постараться, чтобы ее не раскрыли, особенно учитывая, что возглавляет рискованное расследование ее отец.","poster":"https://image.tmdb.org/t/p/w500/m6NNHAa7WvO1PJOwrlSTR25ENPZ.jpg","url":"https://www.themoviedb.org/movie/778810","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Семейный","Комедия"]},{"title":"Дорога домой","rating":9,"tier":"solid","review":"","desc":"Самые опасные животные Австралии устали быть запертыми в террариуме под взглядами любопытных посетителей. Они совершают побег, чтобы вернуться на природу и жить свободно. Бунт возглавляет ядовитая змея Мэдди, ее первый помощник — ящерица Зои, «шипастый дьявол», в компанию также входят волосатый паук Фрэнк и скорпион Найджел. В последний момент к ним присоединяется и коала Красавчик, хотя с ним друзья не в ладах и брать его с собой никто не собирался. Так начинается жуткое и веселое путешествие по Австралии.","poster":"https://image.tmdb.org/t/p/w500/cVVdiyxGTMaCwfSA704H62lw1AS.jpg","url":"https://www.themoviedb.org/movie/770254","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Комедия","Семейный"]},{"title":"Большой красный пес Клиффорд","rating":null,"tier":"unrated","review":"","desc":"Когда школьница Эмили получает в подарок от спасателя животных очаровательного щенка с красной шерстью, она и представить не может, что на утро обнаружит в своей маленькой нью-йоркской квартирке… огромного 3-метрового пса! Мама в командировке, поэтому самые захватывающие и необыкновенные приключения ждут Эмили и ее веселого и порывистого дядю Кейси. Клиффорд научит их — а заодно и весь мир — любить по-крупному.","poster":"https://image.tmdb.org/t/p/w500/dd2T7vtnkHoCaiQKJcbyN88wYdP.jpg","url":"https://www.themoviedb.org/movie/585245","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Семейный","Приключения","Комедия","Фэнтези"]},{"title":"Огонек-огниво","rating":null,"tier":"unrated","review":"","desc":"История начинается с доброго, но бедного Гончара, который однажды находит Огниво — магический артефакт, делающий его владельца богатым, но взамен насылающий смертельное проклятье. Спасти Гончара может только самоотверженность главной героини — девушка по имени Огонёк. Она, не раздумывая, бросается на выручку друга, помогая ему понять, что любовь и честный труд важнее денег и власти.","poster":"https://image.tmdb.org/t/p/w500/lrVRMjSgGTmEKPq5qSf98XPwOjT.jpg","url":"https://www.themoviedb.org/movie/670046","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Семейный","Комедия"]},{"title":"Безумный Бог","rating":null,"tier":"unrated","review":"","desc":"Воин спускается в странный мир, напоминающий постапокалиптический, и начинает путешествие по лабиринту кошмаров, где обитают немыслимые чудовища, а безумные ученые проводят ужасающие эксперименты.","poster":"https://image.tmdb.org/t/p/w500/3jMnto1YBhDiadvteULPMUOnrd9.jpg","url":"https://www.themoviedb.org/movie/846867","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Фэнтези","Ужасы","Фантастика","Семейный"]},{"title":"Душа","rating":10,"tier":"solid","review":"","desc":"Уже немолодой школьный учитель музыки Джо Гарднер всю жизнь мечтал выступать на сцене в составе джазового ансамбля. Однажды он успешно проходит прослушивание у известной клубной певицы и, возвращаясь домой вне себя от счастья, падает в люк и умирает. Теперь у Джо одна дорога — в Великое После, но он сбегает с идущего в вечность эскалатора и случайно попадает в Великое До. Тут новенькие души обретают себя, и у будущих людей зарождаются увлечения, мечты и интересы. Джо становится наставником упрямой души 22, которая уже много веков не может найти свою искру и отправиться на Землю.","poster":"https://image.tmdb.org/t/p/w500/jZkksyMZdTYw7fIVKyA95nFEPnt.jpg","url":"https://www.themoviedb.org/movie/508442","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Семейный","Драма","Музыка","Фэнтези"]},{"title":"Снова мы","rating":8,"tier":"good","review":"","desc":"История одной ночи. Пара средних лет Арт и Дот через танец возвращает себе вкус жизни.","poster":"https://image.tmdb.org/t/p/w500/8u98OFrqc5AfOtgMOuXowbzVCmN.jpg","url":"https://www.themoviedb.org/movie/779047","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Драма","Семейный","Романтика"]},{"title":"Вперёд","rating":11,"tier":"great","review":"","desc":"Когда-то давно в сказочном мире царила магия, но после открытия электричества маги стали не нужны, и развитие пошло по техногенному пути. Братья-эльфы Иэн и Барли Лайтфуты отправляются в захватывающий квест на поиски древней магии, чтобы провести хотя бы один день со своим отцом.","poster":"https://image.tmdb.org/t/p/w500/6Pvojxr83EZNisODJbXmLfmOya8.jpg","url":"https://www.themoviedb.org/movie/508439","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Приключения","Комедия","Семейный","Фэнтези"]},{"title":"Ши-Ра и непобедимые принцессы 1","rating":10,"tier":"solid","review":"","desc":"Перезагрузка сериала 80-х. Волшебный меч превращает девочку-сироту в воительницу Ши-Ру, которой суждено возглавить восстание против сил зла.","poster":"https://image.tmdb.org/t/p/w500/xEQmAeD2IxUoEyOErnDT3O0fmBn.jpg","url":"https://www.themoviedb.org/tv/79732","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Фэнтези","Семейный"]},{"title":"Ши-Ра и непобедимые принцессы 2","rating":10,"tier":"solid","review":"","desc":"Перезагрузка сериала 80-х. Волшебный меч превращает девочку-сироту в воительницу Ши-Ру, которой суждено возглавить восстание против сил зла.","poster":"https://image.tmdb.org/t/p/w500/xEQmAeD2IxUoEyOErnDT3O0fmBn.jpg","url":"https://www.themoviedb.org/tv/79732","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Фэнтези","Семейный"]},{"title":"Ши-Ра и непобедимые принцессы 3","rating":10,"tier":"solid","review":"","desc":"Перезагрузка сериала 80-х. Волшебный меч превращает девочку-сироту в воительницу Ши-Ру, которой суждено возглавить восстание против сил зла.","poster":"https://image.tmdb.org/t/p/w500/xEQmAeD2IxUoEyOErnDT3O0fmBn.jpg","url":"https://www.themoviedb.org/tv/79732","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Фэнтези","Семейный"]},{"title":"Ши-Ра и непобедимые принцессы 4","rating":null,"tier":"unrated","review":"","desc":"Перезагрузка сериала 80-х. Волшебный меч превращает девочку-сироту в воительницу Ши-Ру, которой суждено возглавить восстание против сил зла.","poster":"https://image.tmdb.org/t/p/w500/xEQmAeD2IxUoEyOErnDT3O0fmBn.jpg","url":"https://www.themoviedb.org/tv/79732","status":"watching","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Фэнтези","Семейный"]},{"title":"Ши-Ра и непобедимые принцессы 5","rating":null,"tier":"unrated","review":"","desc":"Перезагрузка сериала 80-х. Волшебный меч превращает девочку-сироту в воительницу Ши-Ру, которой суждено возглавить восстание против сил зла.","poster":"https://image.tmdb.org/t/p/w500/xEQmAeD2IxUoEyOErnDT3O0fmBn.jpg","url":"https://www.themoviedb.org/tv/79732","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Фэнтези","Семейный"]},{"title":"Война единорогов","rating":5,"tier":"mediocre","review":"","desc":"Много лет между мишками и единорогами идёт жестокая война, хотя никто уже и не помнит, почему. Молодой рядовой Блюэт жаждет крови единорогов, потому что согласно пророчеству она дарует вечную красоту. Вместе с мишками своего полка он отправляется из тренировочного лагеря прямо в гущу кровопролитной бойни.","poster":"https://image.tmdb.org/t/p/w500/cGCFmyYK0n6mK1lfRTSj86Y89xK.jpg","url":"https://www.themoviedb.org/movie/587092","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Мультфильм","Фэнтези","Ужасы","Военный","Семейный"]},{"title":"Аркейн","rating":15,"tier":"great","review":"","desc":"История разворачивается в утопическом краю Пилтовере и жестоком подземном мире Зауне и рассказывает о становлении двух сестёр — Вай и Джинкс, и о той силе, что разведёт их по разные стороны баррикад.","poster":"https://image.tmdb.org/t/p/w500/wg1lHGauCXlYw0m2qWWW5TGEmkT.jpg","url":"https://www.themoviedb.org/tv/94605","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Фэнтези","Семейный"]},{"title":"Аркейн 2","rating":15,"tier":"great","review":"","desc":"В условиях глубоких разногласий между городами-близнецами, Пилтовером и Зауном, две сестры оказываются по разные стороны баррикад в войне технологий и убеждений.","poster":"https://image.tmdb.org/t/p/w500/kVioUjk1SXGWblJNaKsIJcBqUcY.jpg","url":"https://www.themoviedb.org/tv/94605","status":"watched","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Боевик","Приключения","Фантастика","Фэнтези","Семейный"]},{"title":"Книга жизни","rating":null,"tier":"unrated","review":"","desc":"В мультфильме описывается романтическая история любви на фоне празднования Дня мертвых в Мексике.","poster":"https://image.tmdb.org/t/p/w500/zcqB9UEuoQ1nD2NAHwD38IDne4i.jpg","url":"https://www.themoviedb.org/movie/228326","status":"planned","category":"cartoon","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Мультфильм","Семейный","Фэнтези"]},{"title":"Моя геройская академия","rating":100,"tier":"masterpiece","review":"","desc":"В один прекрасный день один маленький четырёхлетний мальчик кое-что понял: мир несправедлив. У 80% населения есть особая способность, известная как причуда, которая позволяет осуществить мечту детства и стать супергероем. К сожалению, у Идзуку Мидории нет такой силы, и всю жизнь он страдал от такой несправедливости. Вот только от своей мечты стать супергероем он не отказался. Готовый на невозможное, парень возлагает большие надежды на элитную геройскую академию.        \n        Но всё меняется, когда парень встречается со своим кумиром Всемогущим . Узнав, что его мечта может сбыться, Идзуку проходит специальную подготовку. Удивительно, но после этого он получает силу Всемогущего , и благодаря этому поступает в элитную академию. Так начинается его путешествие к званию лучшего героя всей планеты.","poster":"https://shikimori.io/system/mangas/original/75989.jpg?1712724240","url":"https://shikimori.one/mangas/75989-boku-no-hero-academia","status":"watched","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Школа","Супергероика","Сёнэн","Манга"]},{"title":"Клинок рассекающий демонов","rating":10,"tier":"solid","review":"","desc":"Семья Тандзиро Камадо дружно живёт на отдалённой горе. Пускай им приходится туго, ведь глава семейства умер, оставив на руках матери кучу детишек от мала до велика, но они потихоньку справляются. Как старший из детей, Тандзиро, которому приходится заменить отца, по мере сил зарабатывает, продавая уголь в ближайшей деревне. Вот и в этот раз он спустился с горы, но, задержавшись допоздна, остался ночевать в деревне.        \n        Вернувшись на следующий день домой, Тандзиро обнаруживает, что вся его семья зверски убита, и слабые признаки жизни подаёт лишь старшая из сестёр — Нэдзуко. Схватив сестру в охапку, Тандзиро хочет отнести её к врачу, однако по дороге его останавливает опасный незнакомец с мечом, который собирается немедля добить Нэдзуко. Не понимая, что происходит, Тандзиро бросается на защиту сестры — и начинается его долгий жестокий путь по её спасению...","poster":"https://shikimori.io/system/mangas/original/96792.jpg?1712759160","url":"https://shikimori.one/mangas/z96792-kimetsu-no-yaiba","status":"watched","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Манга","Драма","Повседневность"]},{"title":"Девушка на час","rating":null,"tier":"unrated","review":"","desc":"Кадзуя Киносита — обычный студент университета, которого девушка только что бросила ради другого парня. Чувствуя себя ниже плинтуса, он решает воспользоваться приложением «Diamond», наняв Тидзуру Мидзухару , «девушку на час», чтобы почувствовать себя лучше. По первому впечатлению она идеальная девушка, но правда ли она такая, какой кажется? И как будут развиваться их не совсем обычные отношения?","poster":"https://shikimori.io/system/mangas/original/108407.jpg?1712756731","url":"https://shikimori.one/mangas/108407-kanojo-okarishimasu","status":"watching","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнэн","Комедия","Романтика","Школа","Манга"]},{"title":"Гениальный мечник академии","rating":null,"tier":"unrated","review":"","desc":"","poster":"https://shikimori.io/system/mangas/original/162700.jpg?1718588813","url":"https://shikimori.one/mangas/162700-the-academy-s-genius-swordsman","status":"watching","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Манга"]},{"title":"Кайдзю 8","rating":null,"tier":"unrated","review":"","desc":"Японию регулярно атакуют кайдзю — смертоносные гигантские чудовища. Чтобы сдерживать их натиск, были созданы элитные Силы обороны. 32-летний Кафка Хибино, некогда мечтавший вступить в ряды защитников, работает в клининговой службе по утилизации тел монстров. Однако после встречи с молодым напарником Рэно Итикавой он вновь решает исполнить детскую мечту. Неожиданно в тело Кафки проникает миниатюрный летающий паразит, превращая его в могучего человека-кайдзю.","poster":"https://shikimori.io/system/mangas/original/127907.jpg","url":"https://shikimori.one/mangas/127907-kaijuu-8-gou","status":"watching","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фантастика","Сёнэн","Манга"]},{"title":"Всего наилучшего, стерва","rating":null,"tier":"unrated","review":"","desc":"Сунао Акиёси до сих пор видит в кошмарах свою бывшую девушку. Воспоминания о дне, когда она призналась ему в измене с тремя парнями, не покидают его по сей день. Травма была настолько сильной, что Сунао уже хотел навсегда отказаться от любви, как встреча с Нацуми Когахарой, его университетским товарищем по клубу, вновь заставила поверить в счастливое будущее.   \n   Окрылённый новой любовью, ни с того ни с сего Сунао вновь пересекается с Лемон Нисикавой, своей отвратительной бывшей. И это только начало его личного ада. Ведь на следующее утро он просыпается в её теле!","poster":"https://shikimori.io/system/mangas/original/163630.jpg?1718588090","url":"https://shikimori.one/mangas/163630-kuso-onna-ni-sachi-are","status":"planned","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Сёнэн","Манга"]},{"title":"Прощай эри","rating":10,"tier":"solid","review":"Прикольная, понял что мышление человека формираетться на основе фильмов, манг, аниме и короче всего что они смотрят, полностью увидел своего друга в ГГ который и порекомендовал мне эту мангу","desc":"Мать Юты смертельно больна. Она попросила запечатлеть её последние дни на только что подаренный сыну телефон. Из отснятого материала Юта смонтировал фильм, который показал на школьном фестивале. Его старания не приняли, и парень пришёл на крышу больницы, чтобы покончить с собой, но там встретил Эри, которая заявила, что фильм ей понравился и она хочет увидеть ещё одну работу Юты.","poster":"https://shikimori.io/system/mangas/original/145863.jpg?1708875468","url":"https://shikimori.one/mangas/145863-sayonara-eri","status":"watched","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Сёнэн","Манга"]},{"title":"Факультет зачистки подземелья","rating":null,"tier":"unrated","review":"","desc":"Двадцать первый век. На планету Земля проникли части иного мира и изменили её до неузнаваемости. Настала эпоха существования Подземелий, кишащих монстрами, Охотников, которые эти подземелья зачищают, а также лучшего элитного заведения, занимающегося воспитанием и подготовкой этих охотников — «Старшей школы героев». Отец Ю Ча Рёна некогда был лучшим охотником Азии, но в настоящем его репутация испорчена, он болен и забыт. Ради лечения отца сын занимается контрабандой, незаконно зачищая подземелья. Однажды он встретил девушку, которая попросила его помочь ей поступить в знаменитую школу. Это история о юноше, который вынужден скрывать своё происхождение и отказаться от мечты, но который решил рискнуть и воспользоваться представившейся возможностью, чтобы отыскать себя в мире подземелий.","poster":"https://shikimori.io/system/mangas/original/152825.jpg?1712891717","url":"https://shikimori.one/mangas/152825-yongsa-high-dungeon-raiders","status":"planned","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Фэнтези","Школа","Манга"]},{"title":"Очаровательный цветок расцветает с достоинством","rating":null,"tier":"unrated","review":"","desc":"Так случилось, что муниципальная школа для мальчиков «Тидори», где собрались все беспризорники района, и частная школа для девочек «Кикэ», считающаяся крайне престижным учебным заведением, расположены рядом. Разумеется, ученики двух школ постоянно сталкиваются друг с другом, и дня не проходит без конфликтов между двумя во всём противоположными сторонами.   \n      \n   Однажды ученик «Тидори» Ринтаро Цумуги, который в свободное время помогает родителям в семейном кафе, познакомился с Каоруко Вакури, которая является завсегдатаем их заведения. К своему удивлению, Ринтаро обнаружил, что Каоруко совсем его не боится, несмотря на то, что внешне он типичный хулиган. Однако едва зародившуюся дружбу грозит испортить тот факт, что Каоруко — ученица враждебной «Кикэ».   \n   Это история двух людей, которые так близко и в то же время так далеко друг от друга.","poster":"https://shikimori.io/system/mangas/original/144267.jpg?1712757061","url":"https://shikimori.one/mangas/144267-kaoru-hana-wa-rin-to-saku","status":"planned","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Школа","Драма","Манга"]},{"title":"Первая любовь Акиры Момосэ на грани краха","rating":null,"tier":"unrated","review":"","desc":"Жизнь старшеклассника Хадзимэ Кугаямы, мальчишки из небольшого городка, круто меняется, когда в школу возвращается его бывшая одноклассница и когда-то недосягаемая мечта — Акира Момосэ. Он планировал просто наблюдать за ней издалека и наслаждаться воспоминаниями о своей юности, но неожиданно Акира делает первый шаг навстречу. И вот тут начинается нечто гораздо большее, чем он мог себе представить. Следите за их историей и согревайте свои сердца вместе с ними.","poster":"https://uploads.mangadex.org/covers/f5c25341-d6ff-4585-8548-3a48fc7654d9/26bd1cd9-bb1b-42d8-aa92-f916122c606c.jpg","url":"https://shikimori.one/mangas/173243-momose-akira-no-hatsukoi-hatanchuu","status":"planned","category":"manga","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Манга","Драма","Повседневность"]},{"title":"Первый мститель","rating":null,"tier":"unrated","review":"","desc":"Стив Роджерс добровольно соглашается принять участие в эксперименте, который превратит его в суперсолдата, известного как Капитан Америка. Роджерс вступает в вооружённые силы США вместе с Баки Барнсом и Пегги Картер, чтобы бороться с враждебной организацией ГИДРА, которой управляет безжалостный Красный Череп.","poster":"https://image.tmdb.org/t/p/w500/slr5pTsDIJS9oCfBEBTCYNiq6xs.jpg","url":"https://www.themoviedb.org/movie/1771","status":"planned","category":"film","subcat":"marvel","chronoOrder":1,"universeOrder":"MCU #1","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Железный человек","rating":null,"tier":"unrated","review":"","desc":"Миллиардер изобретатель Тони Старк попадает в плен к Афганским террористам, которые пытаются заставить его создать оружие массового поражения. В тайне от своих захватчиков Старк конструирует высокотехнологичную киберброню, которая помогает ему сбежать. Однако по возвращению в США он узнаёт, что в совете директоров его фирмы плетётся заговор, чреватый страшными последствиями. Используя своё последнее изобретение, Старк пытается решить проблемы своей компании радикально…","poster":"https://image.tmdb.org/t/p/w500/wAKZudQn0HEXqLvaGN6BEripHbv.jpg","url":"https://www.themoviedb.org/movie/1726","status":"planned","category":"film","subcat":"marvel","chronoOrder":3,"universeOrder":"MCU #3","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Железный человек 2","rating":null,"tier":"unrated","review":"","desc":"Прошло полгода с тех пор, как мир узнал, что миллиардер-изобретатель Тони Старк является обладателем уникальной кибер-брони Железного человека. Общественность требует, чтобы Старк передал технологию брони правительству США, но Тони не хочет разглашать её секреты, потому что боится, что она попадёт не в те руки. Между тем, Иван Ванко — сын русского учёного когда-то работавшего на фирму Старка, но потом уволенного и лишенного всего, намерен отомстить Тони за беды своей семьи. Для чего сооружает своё высокотехнологичное оружие.","poster":"https://image.tmdb.org/t/p/w500/rT3JszXFT2C3iYJtXSSL4R0DkU7.jpg","url":"https://www.themoviedb.org/movie/10138","status":"planned","category":"film","subcat":"marvel","chronoOrder":4,"universeOrder":"MCU #4","genres":["Супергероика","Приключения","Боевик","Фантастика"]},{"title":"Тор","rating":null,"tier":"unrated","review":"","desc":"Эпическое приключение происходит как на нашей планете Земля, так и в вымышленном королевстве богов Асгарде. В центре истории — Могучий Тор, сильный, но высокомерный воин, чьи безрассудные поступки возрождают древнюю войну в Асгарде. Тора отправляют в ссылку на Землю, лишают сил и заставляют жить среди обычных людей в качестве наказания. Тор узнает, сколько требуется сил, чтобы стать настоящим героем, когда самый опасный злодей его мира направляет темные силы поглотить Землю.","poster":"https://image.tmdb.org/t/p/w500/9VnGpd2rXHikIwznL9I5r9i8TQJ.jpg","url":"https://www.themoviedb.org/movie/10195","status":"planned","category":"film","subcat":"marvel","chronoOrder":6,"universeOrder":"MCU #6","genres":["Супергероика","Приключения","Фэнтези","Боевик"]},{"title":"Мстители","rating":null,"tier":"unrated","review":"","desc":"Локи, сводный брат Тора, возвращается на Землю, чтобы поработить человечество. Ник Фьюри, глава организации Щ.И.Т., объединяет величайших героев Земли: Железного человека, Капитана Америку, Тора, Халка, Черную вдову и Соколиного глаза.","poster":"https://image.tmdb.org/t/p/w500/9BBTo63ANSmhC4e6r62OJFuK2GL.jpg","url":"https://www.themoviedb.org/movie/24428","status":"planned","category":"film","subcat":"marvel","chronoOrder":7,"universeOrder":"MCU #7","genres":["Супергероика","Фантастика","Боевик","Приключения"]},{"title":"Железный человек 3","rating":null,"tier":"unrated","review":"","desc":"Когда мир Старка рушится на его глазах по вине неизвестных противников, Тони жаждет найти виновных и свести с ними счеты. Оказавшись в безвыходной ситуации, Старк может рассчитывать только на себя и свою изобретательность, чтобы защитить тех, кто ему дорог. Это становится настоящим испытанием для героя, которому придется не только сражаться с коварным врагом, но и разобраться в себе, чтобы найти ответ на вопрос, который давно его тревожит: что важнее — человек или костюм?","poster":"https://image.tmdb.org/t/p/w500/4AZco6uSdog5NbvJ6ILqnCveV8I.jpg","url":"https://www.themoviedb.org/movie/68721","status":"planned","category":"film","subcat":"marvel","chronoOrder":8,"universeOrder":"MCU #8","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Тор 2: Царство тьмы","rating":null,"tier":"unrated","review":"","desc":"Могучему Тору предстоит вновь сразиться за восстановление порядка в галактике, встретившись лицом к лицу с древней инопланетной расой, ведомой злодеем Малекитом, который жаждет установить в девяти мирах власть тьмы. Столкнувшись с врагом, более могущественным, чем сам Один и всё воинство Асгарда, Тор должен собрать силы для решающей битвы. Его ждёт опасное путешествие и долгожданная встреча со своей земной возлюбленной Джейн Фостер. Сможет ли Тор рискнуть самым дорогим, чтобы не дать тьме воцариться на просторах вселенной?","poster":"https://image.tmdb.org/t/p/w500/rmII9fsUpfRmuNBhzHtarBOtHnQ.jpg","url":"https://www.themoviedb.org/movie/76338","status":"planned","category":"film","subcat":"marvel","chronoOrder":9,"universeOrder":"MCU #9","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Первый мститель: Другая война","rating":null,"tier":"unrated","review":"","desc":"После беспрецедентных событий, впервые собравших вместе команду Мстителей, Стив Роджерс, известный также как Капитан Америка, оседает в Вашингтоне и пытается приспособиться к жизни в современном мире. Но покой этому герою только снится - пытаясь помочь коллеге из агентства Щ. И. Т, Стив оказывается в центре событий, грозящих катастрофой мирового масштаба. Для того, чтобы разоблачить злодейский заговор, Капитан Америка объединяется с Черной вдовой. К ним также присоединяется новый соратник, известный как Сокол, однако никто из них даже не подозревает, на что способен новый враг.","poster":"https://image.tmdb.org/t/p/w500/oOmp3YMBnJMa0yDHCbhTcWG4iTm.jpg","url":"https://www.themoviedb.org/movie/100402","status":"planned","category":"film","subcat":"marvel","chronoOrder":10,"universeOrder":"MCU #10","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Чёрная пантера: Ваканда навеки","rating":null,"tier":"unrated","review":"","desc":"После смерти короля Т`Чаллы королева Рамонда, Шури, М`Баку, Окойе и Накия сражаются, чтобы защитить Ваканду от мировых держав.","poster":"https://image.tmdb.org/t/p/w500/wSphEs4KKbewWC01NBtmCJnlZ7y.jpg","url":"https://www.themoviedb.org/movie/505642","status":"planned","category":"film","subcat":"marvel","chronoOrder":30,"universeOrder":"MCU #30","genres":["Супергероика","Боевик","Приключения","Фантастика"]},{"title":"Капитан Марвел 2","rating":null,"tier":"unrated","review":"","desc":"Расследуя возникновение аномалии точки перехода, Кэрол Дэнверс и Моника Рамбо независимо друг от друга одновременно касаются её и тем самым спутывают свои силы с Камалой Хан. Теперь девушки меняются местами, когда кто-нибудь из них использует сверхспособности. А в это время предводительница кри с помощью одного из Квантовых наручей (точно такого же, какой достался Камале по наследству) пытается спасти свою планету от гибели, воруя ресурсы у других планет. Чтобы не допустить хаос, Кэрол, Монике и восторженной от грядущего приключения Камале предстоит научиться работать в команде.","poster":"https://image.tmdb.org/t/p/w500/hngFNCqMUxJ6nXykFxLtHblCVP8.jpg","url":"https://www.themoviedb.org/movie/609681","status":"planned","category":"film","subcat":"marvel","chronoOrder":33,"universeOrder":"MCU #33","genres":["Супергероика","Фантастика","Приключения","Боевик"]},{"title":"Дэдпул и Росомаха","rating":15,"tier":"great","review":"","desc":"Уэйд Уилсон попадает в организацию \"Управление временными изменениями\", что вынуждает его вернуться к своему альтер-эго Дэдпулу и изменить историю с помощью Росомахи.","poster":"https://image.tmdb.org/t/p/w500/4Li3gy8Ga6q0bAz2odg7ZFoRqLy.jpg","url":"https://www.themoviedb.org/movie/533535","status":"watched","category":"film","subcat":"marvel","chronoOrder":34,"universeOrder":"MCU #34","genres":["Супергероика","Боевик","Комедия","Фантастика"]},{"title":"Капитан Америка: Дивный новый мир","rating":null,"tier":"unrated","review":"","desc":"Новый президент США Таддеус Росс решает назначить Капитана Америку на официальную должность. Но в прошлом между ними были разногласия, и Сэм сомневается, что это хорошая идея. Этим же вечером на президента совершается покушение. Уилсон уверен, что предатель скрывается среди ближайшего окружения Росса.","poster":"https://image.tmdb.org/t/p/w500/bljRQO5fTGen0qRV7KuPRXIdRGx.jpg","url":"https://www.themoviedb.org/movie/822119","status":"planned","category":"film","subcat":"marvel","chronoOrder":35,"universeOrder":"MCU #35 (2025)","genres":["Супергероика","Боевик","Триллер","Фантастика"]},{"title":"Громовержцы*","rating":null,"tier":"unrated","review":"","desc":"После тяжёлых испытаний группа людей с непростым прошлым оказывается втянута в опасную миссию по поручению правительства. Каждый из них привык действовать в одиночку и преследует собственные цели, поэтому доверие становится самым сложным испытанием. Выполняя задание, они постепенно раскрывают масштабный заговор, который угрожает гораздо большему, чем они ожидали. Чтобы выжить и остановить новую угрозу, бывшим врагам и антигероям придётся стать настоящей командой.","poster":"https://image.tmdb.org/t/p/w500/aTmfXAF8tkFXU9udPPtfooX4GJr.jpg","url":"https://www.themoviedb.org/movie/986056","status":"planned","category":"film","subcat":"marvel","chronoOrder":36,"universeOrder":"MCU #36 (2025)","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Фантастическая четвёрка: Первые шаги","rating":null,"tier":"unrated","review":"","desc":"Рид Ричардс, Бен Гримм, Сью Сторм и её брат Джонни должны защитить Землю от космического бога Галактуса и его приспешника — Серебряного Сёрфера. И если план Галактуса поглотить всю планету и всех её жителей кажется недостаточно ужасающим, ситуация внезапно становится личной.","poster":"https://image.tmdb.org/t/p/w500/mFZ01wUqG8ROR9Y9xLreanLqis4.jpg","url":"https://www.themoviedb.org/movie/617126","status":"planned","category":"film","subcat":"marvel","chronoOrder":37,"universeOrder":"MCU #37 (2025)","genres":["Супергероика","Фантастика","Приключения","Боевик"]},{"title":"Блэйд","rating":null,"tier":"unrated","review":"","desc":"Перезапуск истории знаменитого охотника на вампиров Эрика Брукса в исполнении Махершалы Али. Дневной бродяга, обладающий силой вампиров, защищает мир людей от древней темной угрозы.","poster":"https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg","url":"https://www.themoviedb.org/movie/582883","status":"planned","category":"film","subcat":"marvel","chronoOrder":38,"universeOrder":"MCU #38 (2025)","genres":["Супергероика","Комедия","Ужасы"]},{"title":"Мстители: Судный день","rating":null,"tier":"unrated","review":"","desc":"Мстители, Люди Икс, Фантастическая четвёрка, вакандцы и Новые Мстители объединяются, чтобы противостоять Доктору Думу.","poster":"https://image.tmdb.org/t/p/w500/itU2A8Yco43cAuDfVcYBXlpJzH.jpg","url":"https://www.themoviedb.org/movie/1003596","status":"planned","category":"film","subcat":"marvel","chronoOrder":39,"universeOrder":"MCU #39 (2026)","genres":["Супергероика","Фантастика","Боевик","Приключения"]},{"title":"Человек-паук 4","rating":20,"tier":"exceeded","review":"","desc":"Одинокий и повзрослевший Питер Паркер полностью посвящает себя борьбе с преступностью в Нью-Йорке, поскольку 4 года назад после заклинания Доктора Стрэнджа мир и все близкие забыли его. Но с ростом угроз и нагрузки на Человека-паука, его способности претерпевают странные изменения, способные поставить под угрозу его существование. Тем временем в городе случается новая цепочка преступлений, которая приводит к появлению одного из самых опасных противников в жизни Питера.","poster":"https://image.tmdb.org/t/p/w500/gNBiOPEbEPGPTfTIyGDvNQ50m0V.jpg","url":"https://www.themoviedb.org/movie/969681","status":"watched","category":"film","subcat":"marvel","chronoOrder":40,"universeOrder":"MCU #40","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Мстители: Секретные войны","rating":null,"tier":"unrated","review":"","desc":"История о грандиозной войне героев из разных вселенных, собранных в одном мире после краха мультивселенной. Союзники и враги вынуждены сражаться бок о бок, потому что на кону стоит существование всех реальностей.","poster":"https://image.tmdb.org/t/p/w500/f0YBuh4hyiAheXhh4JnJWoKi9g5.jpg","url":"https://www.themoviedb.org/movie/1003598","status":"planned","category":"film","subcat":"marvel","chronoOrder":41,"universeOrder":"MCU #41 (2027)","genres":["Супергероика","Фантастика","Боевик","Приключения"]},{"title":"Шазам! Ярость богов","rating":null,"tier":"unrated","review":"","desc":"17-летний Билли Бэтсон, получивший дар превращаться в супергероя лет сорока, охраняет покой жителей Филадельфии вместе со своими приёмными братьями и сестрами, с которыми он поделился суперспособностями. В силу юности и недостатка дисциплины не всё у них получается идеально, и пресса называет команду супергероев \"Филадельфийскими фиаско\". Тем временем две женщины, представляющиеся дочерьми титана Атланта, крадут из греческого музея сломанный пополам волшебный жезл и направляются в Филадельфию, чтобы отобрать у супергероев магические силы.","poster":"https://image.tmdb.org/t/p/w500/t2Wy2p0lLg6BjOk10pYhrIiYWrL.jpg","url":"https://www.themoviedb.org/movie/594767","status":"planned","category":"film","subcat":"dc","chronoOrder":14,"universeOrder":"DC #14","genres":["Супергероика","Комедия","Боевик","Фэнтези"]},{"title":"Синий Жук","rating":null,"tier":"unrated","review":"","desc":"Недавний выпускник колледжа Джейми Рейес возвращается домой, полный надежд на свое будущее, только для того, чтобы обнаружить, что дом не совсем такой, каким он его оставил. Пока он пытается найти свое предназначение в этом мире, вмешивается судьба, когда Джейми неожиданно оказывается обладателем древней реликвии инопланетной биотехнологии: скарабея.","poster":"https://image.tmdb.org/t/p/w500/aHT0qcPPJGnF5ZhrRAdpfmEnl5Z.jpg","url":"https://www.themoviedb.org/movie/565770","status":"planned","category":"film","subcat":"dc","chronoOrder":15,"universeOrder":"DC #15","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Аквамен и потерянное царство","rating":15,"tier":"great","review":"","desc":"Пока Аквамен пытается совмещать отцовство и работу царём подводного мира, Дэвид Хайд вынашивает план мести. Его исследовательская экспедиция обнаруживает трезубец проклятого и запертого во льдах повелителя потерянного царства — так Дэвид попадает под влияние его злых чар. Чтобы справиться с этой угрозой, Аквамену придётся помочь сбежать из тюрьмы младшему брату, которого он сам туда и посадил.","poster":"https://image.tmdb.org/t/p/w500/vJoMnbQjLo1e7yOtFPW1LyPL6qR.jpg","url":"https://www.themoviedb.org/movie/572802","status":"watched","category":"film","subcat":"dc","chronoOrder":16,"universeOrder":"DC #16","genres":["Супергероика","Боевик","Приключения","Фэнтези"]},{"title":"Джокер","rating":null,"tier":"unrated","review":"","desc":"Готэм, начало 1980-х годов. Комик Артур Флек живет с больной матерью и мечтает дарить людям смех. Но человеческая жестокость, несправедливость и отверженность толкают его на путь безумия и превращают в символ анархии — Джокера.","poster":"https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg","url":"https://www.themoviedb.org/movie/475557","status":"planned","category":"film","subcat":"dc","chronoOrder":17,"universeOrder":"DC Elseworlds","genres":["Криминал","Триллер","Драма","Психология"]},{"title":"Бэтмен","rating":null,"tier":"unrated","review":"","desc":"После двух лет поисков правосудия на улицах Готэма для своих сограждан Бэтмен становится олицетворением беспощадного возмездия. Когда в городе происходит серия жестоких нападений на представителей элиты, загадочные улики приводят Брюса Уэйна в самые темные закоулки преступного мира, где он встречает Женщину-Кошку, Пингвина, Кармайна Фальконе и Загадочника. Теперь под прицелом оказывается сам Бэтмен, которому предстоит отличить друга от врага и восстановить справедливость во имя Готэма.","poster":"https://image.tmdb.org/t/p/w500/3EXgl14Wmr5NcbYnBy1kavGHnvh.jpg","url":"https://www.themoviedb.org/movie/414906","status":"planned","category":"film","subcat":"dc","chronoOrder":18,"universeOrder":"DC Elseworlds","genres":["Супергероика","Криминал","Детектив","Драма","Боевик"]},{"title":"Джокер: Безумие на двоих","rating":null,"tier":"unrated","review":"","desc":"Неудачливый комик Артур Флек, находящийся на принудительном лечении в государственной больнице Аркхэм, встречает любовь всей своей жизни, Харли Квинн.","poster":"https://image.tmdb.org/t/p/w500/sqHQhhjsfZ0UAu67RiIaUkabZZD.jpg","url":"https://www.themoviedb.org/movie/889737","status":"planned","category":"film","subcat":"dc","chronoOrder":19,"universeOrder":"DC Elseworlds (2024)","genres":["Криминал","Триллер","Драма","Мюзикл"]},{"title":"Бэтмен: Часть 2","rating":null,"tier":"unrated","review":"","desc":"Продолжение мрачной детективной истории Брюса Уэйна от режиссёра Мэтта Ривза. Тёмный рыцарь Готэма сталкивается с новыми угрозами и криминальными авторитетами затопленного города, погружаясь ещё глубже в тайны прошлого Готэма.","poster":"https://image.tmdb.org/t/p/w500/r5fl4aMsmTjgc8DdDqQaM84roWp.jpg","url":"https://www.themoviedb.org/movie/806704","status":"planned","category":"film","subcat":"dc","chronoOrder":20,"universeOrder":"DC Elseworlds (2026)","genres":["Супергероика","Криминал","Детектив","Драма"]},{"title":"Супермен","rating":null,"tier":"unrated","review":"","desc":"Новый фильм киновселенной DCU Джеймса Ганна. Кларк Кент (Дэвид Коренсвет) пытается сбалансировать свое криптонское наследие и человеческое воспитание, оставаясь маяком надежды и справедливости в современном циничном мире.","poster":"https://image.tmdb.org/t/p/w500/ombsmhYUqR4qqOLmwsm4bNd4tx8.jpg","url":"https://www.themoviedb.org/movie/1064213","status":"planned","category":"film","subcat":"dc","chronoOrder":21,"universeOrder":"DCU #1 (2025)","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Супергёрл: Женщина завтрашнего дня","rating":null,"tier":"unrated","review":"","desc":"Кара Зор-Эл путешествует по галактике со своим псом Крипто. На неё нападает пират и разбойник, который угоняет её корабль и ранит Крипто. Объединив силы с новой подругой и союзницей Рути, семью которой ранее убил пират, Кара отправляется мстить.","poster":"https://image.tmdb.org/t/p/w500/gcAZ5f6Y40koGYcfPUqb2tmnVd.jpg","url":"https://www.themoviedb.org/movie/1081003","status":"planned","category":"film","subcat":"dc","chronoOrder":22,"universeOrder":"DCU #2 (2026)","genres":["Супергероика","Боевик","Фантастика","Приключения"]},{"title":"Отважный и смелый","rating":null,"tier":"unrated","review":"","desc":"Первый фильм о Бэтмене в новой киновселенной DC Джеймса Ганна. История взаимоотношений Брюса Уэйна и его биологического сына Дэмиена Уэйна — юного, тренированного Лигой убийц Робина, о существовании которого Тёмный Рыцарь даже не подозревал.","poster":"https://image.tmdb.org/t/p/w500/6Fv0nNQIPnJ4uk5kTsMzKlAaqf2.jpg","url":"https://www.themoviedb.org/movie/191227","status":"planned","category":"film","subcat":"dc","chronoOrder":23,"universeOrder":"DCU #3 (2026)","genres":["Супергероика","Боевик","Криминал","Приключения"]},{"title":"Авторитеты","rating":null,"tier":"unrated","review":"","desc":"Команда антигероев с экстремальными методами берёт правосудие в свои руки. В отличие от классических супергероев, участники организации The Authority верят, что мир безнадёжно сломан, и готовы исправлять его любыми, даже самыми радикальными способами.","poster":"https://image.tmdb.org/t/p/w500/w3oLSqrKi4XQxH7BWYw53GrqptF.jpg","url":"https://www.themoviedb.org/movie/893977","status":"planned","category":"film","subcat":"dc","chronoOrder":24,"universeOrder":"DCU #4 (2026)","genres":["Супергероика","Боевик","Фантастика","Антигерои"]},{"title":"Болотная тварь","rating":null,"tier":"unrated","review":"","desc":"Фильм повествует историю о том, как группа ученых объединяет усилия, для создания специального состава, заставляет растения, расти с огромной скоростью и таким способом избавить мир от голода, поблем связанных с вырубкой лесов и многого другого. Однако они и не подозревают, что есть люди, которые планируют использовать эту формулу в своих корыстных целях. В результате несчастного случая доктор Алек Холланд превращается в монстра - получеловека-полурастение. Но, даже не смотря на это, он продолжает любить свою возлюбленную. И теперь должен защитить её от козней своего бывшего коллеги доктора Антона Аркэйна и не дать ему использовать формулу во зло.","poster":"https://image.tmdb.org/t/p/w500/poYSGyFVp2zEPMjNQzlARyvvvgy.jpg","url":"https://www.themoviedb.org/movie/17918","status":"planned","category":"film","subcat":"dc","chronoOrder":25,"universeOrder":"DCU #5 (2026)","genres":["Супергероика","Ужасы","Фантастика","Драма"]},{"title":"Магическая битва","rating":10,"tier":"solid","review":"","desc":"Действие аниме происходит в мире, где люди оказались вовсе не последним звеном в пищевой цепи, и любой ничего не подозревающий обыватель при должной доле невезения может оказаться съеденным демонами, которые воплощают собой негативные человеческие эмоции. Таких созданий называют проклятиями. Пускай люди в большинстве своём не догадываются о существовании проклятий, те имеют уже давнюю историю, одним из эпизодов которой являются деяния легендарного демона Сукуны Рёмэна, которого с большим трудом удалось одолеть. Его тело было поделено на двадцать частей, которые оказались разбросаны по миру. Если найдётся некто, кто поглотит все фрагменты его плоти, то он обретёт мощь, способную уничтожить современную цивилизацию.\nВот такая сложилась ситуация в мире, где в полном неведении о нависшей над человечеством угрозе проживает старшеклассник Юдзи Итадори. У Юдзи совершенно иные заботы: он каждый день навещает дедушку в больнице и отбрыкивается от спортивных кружков, которые мечтают заполучить его из-за выдающейся физической силы и выносливости. Юдзи предпочёл вступить в клуб оккультных наук, с которого и начались все неприятности, когда в руки членов клуба попал таинственный предмет, на который наложено проклятье. Не долго думая, школьники разбили запечатывающее заклинание и выпустили на свет ужасные силы.","poster":"https://shikimori.io/system/animes/original/40748.jpg?1711956606","url":"https://shikimori.one/animes/40748-jujutsu-kaisen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Фэнтези","Школа","Сёнен"],"episodes":24,"kind":"tv","franchise":"jujutsu_kaisen"},{"title":"Восхождение героя щита","rating":10,"tier":"solid","review":"","desc":"Наофуми Иватани вместе с тремя другими людьми был призван в параллельный мир, чтобы стать его героем. При переносе каждый из них получил специальную экипировку, которая соответствует типу героя. Наофуми достался легендарный щит, и парень решил отправиться в путешествие по сказочному миру. \nНо уже в самом начале пути у него возникли проблемы.\nНе обладающий выдающейся харизмой, парень к тому же оказался совсем не готов к геройским деяниям, поэтому сразу получил прозвище слабейшего из призванных. \nБрошенного другими героями, Наофуми в результате ограбили и подставили. А затем начали остерегаться все кому не лень: и крестьяне, и даже король. Сильные мира сего обратились во врагов, и неудачливый герой потерял веру в людей. Но кое-что всё-таки изменилось — он преисполнился гневом и желанием отомстить.","poster":"https://shikimori.io/system/animes/original/35790.jpg?1711976737","url":"https://shikimori.one/animes/z35790-tate-no-yuusha-no-nariagari","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Драма","Фэнтези"],"episodes":25,"kind":"tv","franchise":"shield_hero"},{"title":"Эта фарфоровая кукла влюбилась","rating":10,"tier":"solid","review":"","desc":"Застенчивый старшеклассник по имени Вакана с детства грезит о том, чтобы стать мастером изготовления традиционных японских кукол. И неспроста, ведь дедушка парня добрую половину жизни отдал этому ремеслу. К сожалению, как бы Вакана ни старался, а освоить главное — создание кукольных голов — ему никак не удаётся. Зато в пошиве миниатюрной одежды он, кажется, уже весьма преуспел... и не думал не гадал, что именно это поможет ему сблизиться с одноклассницей — красавицей Марин Китагавой.\nВсегда весёлая, общительная и такая недосягаемая, девушка, как оказалось, имеет не менее странное, чем у Ваканы, увлечение — эроге-игры и косплей персонажей из них. Едва узнав, что парень умеет обращаться со швейной машинкой, красотка тут же вгрызается в него мёртвой хваткой и, прилагая всё своё очарование, просит сшить для неё костюм.\nА вот в одних ли умениях дело или, быть может, тут замешано что-то ещё, будущему мастеру-кукольнику только предстоит узнать, попутно открыв для себя простую истину: вовсе не важно, чем ты увлечён, главное — что это тебе по душе!","poster":"https://shikimori.io/system/animes/original/48736.jpg?1708765101","url":"https://shikimori.one/animes/48736-sono-bisque-doll-wa-koi-wo-suru","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Романтика","Школа","Сэйнэн"],"episodes":12,"kind":"tv","franchise":"sono_bisque_doll"},{"title":"Реинкарнация безработного: История о приключениях в другом мире","rating":10,"tier":"solid","review":"","desc":"Бывает в жизни невезение. Только тридцатичетырёхлетний безработный отаку-бездельник доходит до точки и решает, что пора взяться за ум и изменить свою в общем-то никчёмную жизнь, как его насмерть сбивает грузовик. Однако на этом история его жизни не заканчивается, ведь он приходит в себя в теле ребёнка, причём в совершенно ином мире, где в ходу магия да и рыцарские бои на мечах вполне в порядке вещей. Отныне нашего героя зовут Рудеус Грейрат, и он начнёт-таки жизнь с чистого листа, но теперь уже в новом полном опасностей и чудес мире.","poster":"https://shikimori.io/system/animes/original/39535.jpg?1711965119","url":"https://shikimori.one/animes/39535-mushoku-tensei-isekai-ittara-honki-dasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Фэнтези","Этти"],"episodes":11,"kind":"tv","franchise":"mushoku_tensei"},{"title":"Реинкарнация безработного: История о приключениях в другом мире. Часть 2","rating":10,"tier":"solid","review":"","desc":"Эта история расскажет об отаку-неудачнике, который погиб под колёсами автомобиля, а после пришёл в себя в теле новорождённого. Как оказалось, он переродился в другом мире, и теперь его зовут Рудеус Грейрат. Чтобы выжить и не повторять прошлых ошибок, Рудеус решил прилежно учиться магии и искусству владения мечом. Хотя внешний мир всё ещё пугал бывшего затворника, Рудеус нашёл в себе силы и завёл первого друга. А спустя время и сам, покинув стены родного дома, взялся за обучение несносной девчонки по имени Эрис Бореас Грейрат. Всё, казалось бы, шло как нельзя лучше, но его вместе с Эрис внезапно перебросило на другой континент. \n\nТеперь молодому магу предстоит дорога домой в компании своей ученицы Эрис и сильнейшего суперда по имени Руйджерд Супердия. Возвращение будет полным приключений, опасностей и новых знакомств, но для того, чтобы отыскать близких и выяснить, что произошло с его родным домом, Рудеус ни за что не свернёт с намеченного пути!","poster":"https://shikimori.io/system/animes/original/45576.jpg?1711965124","url":"https://shikimori.one/animes/45576-mushoku-tensei-isekai-ittara-honki-dasu-part-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Драма","Фэнтези","Этти"],"episodes":12,"kind":"tv","franchise":"mushoku_tensei"},{"title":"Аватар короля","rating":10,"tier":"solid","review":"","desc":"В многопользовательской онлайн-игре «Слава» Е Сю считался легендарным игроком уровня «профи». Однако по многочисленным причинам Сю вышвырнули из команды. После ухода с профессиональной сцены парень устраивается менеджером в интернет-кафе. Когда «Слава» открывает свой десятый сервер, Сю снова погружается в игру. С десятилетним опытом, воспоминаниями о прошлом и самодельным оружием, его возвращение обещает быть запоминающимся. Кто знает, может так и начинается путь Короля.","poster":"https://shikimori.io/system/animes/original/33926.jpg?1711969864","url":"https://shikimori.one/animes/33926-quanzhi-gaoshou","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":"Экшен","episodes":12,"kind":"ona","franchise":"quanzhi_gaoshou"},{"title":"Аватар короля 2","rating":10,"tier":"solid","review":"","desc":"Близится ежегодный чемпионат многопользовательской игры «Слава», в котором Е Сю тоже планирует принять участие. Несмотря на то, что Е Сю отдал игре десять лет и настолько хорош, что получил прозвище Бог, перспективы его не такие уж радужные. Если он хочет участвовать, ему нужно собрать сильную команду, найти спонсора, пробиться через отборочные игры — и это только самые основные трудности. Стоит приблизиться к решению хотя бы одной проблемы, как возникает куча других поменьше.\n\nДействительно ли Е Сю настроен настолько серьёзен, чтобы рискнуть всем и попытаться пробиться на вершину «Славы» ещё один раз?! И на чьей стороне будет ветряная богиня игры и удачи?","poster":"https://shikimori.io/system/animes/original/37932.jpg?1711969844","url":"https://shikimori.one/animes/37932-quanzhi-gaoshou-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":"Экшен","episodes":12,"kind":"ona","franchise":"quanzhi_gaoshou"},{"title":"Добро пожаловать в класс превосходства 2","rating":10,"tier":"solid","review":"","desc":"Экзамен на необитаемом острове подошёл к концу, и ученики получили возможность отдохнуть на круизном лайнере. Однако объявление о начале нового и необычного экзамена, в котором ученики всех четырёх классов первого года будут перемешаны и распределены по группам, положило конец тихим и мирным денькам. И в то время как другие классы начинают активно действовать, класс 1-D, которому не хватает сплочённости, оказывается в затруднительном положении.\nСмогут ли студенты, колеблющиеся между доверием и подозрениями, увидеть правду и пройти экзамен с наилучшим исходом для своего класса?","poster":"https://shikimori.io/system/animes/original/51096.jpg?1713754581","url":"https://shikimori.one/animes/51096-youkoso-jitsuryoku-shijou-shugi-no-kyoushitsu-e-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Триллер","Психологическое","Школа"],"episodes":13,"kind":"tv","franchise":"classroom_of_the_elite"},{"title":"О моём перерождении в слизь","rating":10,"tier":"solid","review":"","desc":"Знакомьтесь! Сатору Миками , 37-летний рядовой служащий крупной финансовой компании, ныне мечтающий лишь об одном — о девушке. Однако встреча с приятелем на улице обернулась для Сатору трагедией, перечеркнув все планы: грабитель с ножом бросился на товарища, а Сатору принял на себя удар...\nНо жизнь для Миками на этом не закончилась. Мужчина переродился в другом мире. Перед смертью он подумал о том, как плохо человеку от потери крови, а после перерождения получил... тело слизня, в котором эта жидкая красная субстанция попросту отсутствует. Но что может сделать в огромном незнакомом мире, пускай и разумная, но слизь?","poster":"https://shikimori.io/system/animes/original/37430.jpg?1711977107","url":"https://shikimori.one/animes/z37430-tensei-shitara-slime-datta-ken","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Комедия","Фэнтези","Сёнен"],"episodes":24,"kind":"tv","franchise":"tensei_shitara_slime"},{"title":"О моём перерождении в слизь 2","rating":10,"tier":"solid","review":"","desc":"После перерождения Сатору в новом, совершенно незнакомом мире в качестве слизи можно было подумать, что ему не повезло стать таким, на первый взгляд, беспомощным существом. Но несмотря на это, он быстро стал главой построенного им города и обзавелся преданными соратниками, взяв себе новое имя — Римуру.\nОднако ему стоит задуматься о защите своих подданных, ведь чем больше разрастается город, тем больше внимания он привлекает, и вскоре даже самые могущественные силы этого мира заинтересуются этой уникальной слизью.","poster":"https://shikimori.io/system/animes/original/39551.jpg?1711977070","url":"https://shikimori.one/animes/39551-tensei-shitara-slime-datta-ken-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Комедия","Фэнтези","Сёнен"],"episodes":12,"kind":"tv","franchise":"tensei_shitara_slime"},{"title":"О моём перерождении в слизь 2. Часть 2","rating":10,"tier":"solid","review":"","desc":"Справившись с обрушившейся на страну трагедией, Римуру Темпест, получивший ещё большую силу, готовится заявить миру о принятии нового титула. В связи с этим начинается собрание с представителями других государств, где обсуждаются дальнейшие шаги и будущие союзы. Тем временем Клейман продолжает плести интриги, стремясь достичь собственных целей. Заручившись поддержкой союзников, он созывает собрание Князей Тьмы, на котором намерен изложить собственную версию недавних событий и направить ход происходящего в свою пользу.","poster":"https://shikimori.io/system/animes/original/41487.jpg?1711977051","url":"https://shikimori.one/animes/41487-tensei-shitara-slime-datta-ken-2nd-season-part-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Комедия","Фэнтези","Сёнен"],"episodes":12,"kind":"tv","franchise":"tensei_shitara_slime"},{"title":"Этот замечательный мир!","rating":10,"tier":"solid","review":"","desc":"Так уж получилось, что жизнь Казумы Сато , хикикомори, увлечённого видеоиграми, оборвалась в результате дорожно-транспортного происшествия. Такая вот суровая плата за хороший поступок, за спасение человека. Однако, очнувшись, парень вдруг понял, что жив-здоров, а перед собой увидел симпатичную девушку, Акву , представившуюся богиней. Вопреки ожиданиям, богиня не произнесла, мол: «Ну-ка, парень, сгруппируйся, сейчас тебя на небеса отправим!» Напротив, девушка едва ли не сразу стала объяснять, что ищет героя, способного победить какого-то-там злобного Владыку демонов и тем самым спасти какой-то-там другой мир. И уж больно этот «какой-то-там» мир был похож на видеоигру. Что, безусловно, подкупало.\n«Значит, гляди, — продолжала Аква. — Если согласишься, можешь взять с собой одну любую вещь или способность. Хочешь, меч из хвоста неведомого чудовища, а хочешь — силу горного великана. Ну так что выбираешь?» Долго Казума думать не стал. «Выбираю тебя!» — сообразил он, чем тут же выбил навязчивую богиню из колеи. Так начинаются приключения странного хикикомори и незадачливой богини по чужому и неприветливому миру, где Казума попытается начать новую мирную жизнь, на время позабыв, что зло здесь никогда не дремлет.","poster":"https://shikimori.io/system/animes/original/30831.jpg?1711959601","url":"https://shikimori.one/animes/x30831-kono-subarashii-sekai-ni-shukufuku-wo","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Пародия"],"episodes":10,"kind":"tv","franchise":"konosuba"},{"title":"Этот замечательный мир! 2","rating":10,"tier":"solid","review":"","desc":"] Казума  всё ещё в фэнтезийном RPG-мире. И три бесполезные девушки — бывшая богиня Аква , волшебница Мэгумин  и мазохистка Даркнесс  — по-прежнему крутятся возле него, время от времени создавая неловкие и комичные ситуации. Казалось бы, эти ребята неисправимы — куда им до борьбы со вселенским злом? Возможно, по одиночке они и не справятся с этой задачей, зато вместе... Эм... \nВпрочем, не стоит делать преждевременные выводы, ведь, как известно, удача благоволит дуракам. Где там этот Владыка демонов? Забился в свой крохотный уголок и уже намочил трусишки от страха перед беспросветной тупостью главных героев? Ещё бы! Бойтесь! Трепещите! Орды монстров и мирные жители — все от мала до велика утонут в сиянии доблестных героев, существующих в этом замечательном мире с одной целью: причинять добро и наносить справедливость!","poster":"https://shikimori.io/system/animes/original/32937.jpg?1711959560","url":"https://shikimori.one/animes/y32937-kono-subarashii-sekai-ni-shukufuku-wo-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Пародия"],"episodes":10,"kind":"tv","franchise":"konosuba"},{"title":"Непризнанный школой владыка демонов!","rating":10,"tier":"solid","review":"","desc":"Всесильный Владыка демонов, обладающий силой уничтожать людей, богов и стихии, за годы бесконечных войн устал от битв и возжаждал умиротворения и покоя. Поэтому, недолго думая, он решает махнуть рукой на существующий мир и возродиться сразу в будущем. Проходит каких-то две тысячи лет, и Владыка перерождается в мире, который, к его изумлению, полон спокойствия и давно позабыл о временах сражений. Вроде бы всё складывается так, как Аносу и хотелось, вот только из-за отсутствия практики сами магические силы ослабли, причем ослабли настолько, что даже не в состоянии признать в юноше истинного Владыку демонов! И когда Анос пытается поступить в Академию для кандидатов в Князи Тьмы, его объявляют негодным!","poster":"https://shikimori.io/system/animes/original/40496.jpg?1711962874","url":"https://shikimori.one/animes/40496-maou-gakuin-no-futekigousha-shijou-saikyou-no-maou-no-shiso-tensei-shite-shison-tachi-no-gakkou-e-kayou","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Фэнтези","Школа"],"episodes":13,"kind":"tv","franchise":"maou_gakuin"},{"title":"Семья шпиона","rating":10,"tier":"solid","review":"","desc":"Кто приходит на ум, когда речь заходит о тайных агентах? Конечно же, невероятный Джеймс Бонд, который постоянно подвергает жизнь опасности, выполняя секретные миссии. О таком харизматичном и смелом мужчине мечтают многие дамы, так что Агент 007 купается в лучах женского внимания.\nГерой этой истории, Лойд Форджер, является «Джеймсом Бондом» своего времени. Погони, шпионаж, перестрелки, тайные миссии — всё это является неотъемлемой частью его жизни. Закончив одно задание, он тут же принимается за другое — усталость ему неведома. Однако на этот раз миссия оказывается немного необычной: он должен сохранить мир между двумя странами, а для этого ему предстоит обзавестись фиктивной семьёй. Роль «роковой красотки из Бондианы», и по совместительству жены Лойда, достаётся Йор Форджер — профессиональной наёмной убийце с кодовым именем Тернистая Принцесса. Для полноты картины осталось обзавестись ещё и ребёнком, и эспер Аня Форджер только рада заполучить себе крутых новых родителей. \n\nТеперь новой семье предстоит не только выполнить секретное задание, не раскрыв себя, но и понять, что семья — это гораздо больше, чем просто кровные родственники.","poster":"https://shikimori.io/system/animes/original/50265.jpg?1716777040","url":"https://shikimori.one/animes/50265-spy-x-family","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнен","Экшен","Комедия"],"episodes":12,"kind":"tv","franchise":"spy_x_family"},{"title":"Убивая слизней 300 лет, неожиданно взяла максимальный уровень","rating":10,"tier":"solid","review":"","desc":"До боли знакомый каждому любителю историй о перемещениях в иные миры сюжет расскажет об офисной служащей по имени Адзуса Аидзава. Одним прекрасным днём она умирает от переутомления. Однако ей даруют шанс начать новую жизнь в альтернативном мире. Теперь Адзуса живёт в теле семнадцатилетней девушки, став бессмертной ведьмой, и ведёт спокойную жизнь в небольшом домике в горах. Единственным доходом для неё является уничтожение низкоуровневых слизней, обитающих поблизости. И так проходит 300 лет...","poster":"https://shikimori.io/system/animes/original/40586.jpg?1711974494","url":"https://shikimori.one/animes/40586-slime-taoshite-300-nen-shiranai-uchi-ni-level-max-ni-nattemashita","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":"slime_300"},{"title":"Арифурэта: Сильнейший ремесленник в мире","rating":10,"tier":"solid","review":"","desc":"Жизнь семнадцатилетнего Хадзимэ  переворачивается с ног на голову в тот самый момент, когда он со своими одноклассниками попадает в иной мир.\nОднако до боли знакомый любому отаку сюжет, где героя наделяют непревзойдёнными способностями, зачастую попирающими все мыслимые и немыслимые законы мироздания, даёт трещину ровно тогда, когда всех призванных юношей и девушек наделяют божественными дарами и классами.\nВпрочем, ничем не выделяющемуся школьнику, который до недавних пор прослыл изгоем среди своих сверстников, и в этот раз не светит билет в счастливое будущее, так как ему достались самые невзрачные и в плане наращивания боевого потенциала довольно посредственные силы. Сможет ли теперь он пережить все уготованные ему невзгоды и обрести славу великого героя?","poster":"https://shikimori.io/system/animes/original/36882.jpg?1711942149","url":"https://shikimori.one/animes/36882-arifureta-shokugyou-de-sekai-saikyou","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Фэнтези","Гарем"],"episodes":13,"kind":"tv","franchise":"arifureta"},{"title":"Башня Бога","rating":10,"tier":"solid","review":"","desc":"Башня бога — место, в котором сбываются мечты и разбиваются сердца, только сильный духом сможет добраться до самого верха. Именно этого всю жизнь хотела Рахиль, и Двадцать пятый Баам отправился за ней, потому как эта девушка была для него единственным лучиком света в этом мрачном и недружелюбном мире. При входе в башню больше не будет пути назад — только наверх, к новым испытаниям. Многое здесь ждёт главных героев: радость и волнения, победы и поражения, боль и утрата. Смогут ли они добраться до вершины?","poster":"https://shikimori.io/system/animes/original/40221.jpg?1711957297","url":"https://shikimori.one/animes/40221-kami-no-tou","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Драма","Фэнтези","Детектив"],"episodes":13,"kind":"tv","franchise":"tower_of_god"},{"title":"Мастера Меча Онлайн: Альтернативная «Призрачная пуля»","rating":10,"tier":"solid","review":"","desc":"Карэн  всегда чувствовала себя лишней в реальном мире... Как будто она не принадлежит ему. Из-за своего высокого роста (целых 183 см!) девушке было очень трудно завести подруг среди ровесниц. Но всё изменилось, когда Карэн познакомилась с небезызвестной VRMMORPG — «Gun Gale Online». В мире «GGO» Карэн может сыграть за персонажа своей мечты — невысокую девочку, одетую во всё розовое. Но сможет ли Карэн найти друзей в этой экшен-игре?","poster":"https://shikimori.io/system/animes/original/36475.jpg?1711975864","url":"https://shikimori.one/animes/z36475-sword-art-online-alternative-gun-gale-online","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Военное"],"episodes":12,"kind":"tv","franchise":"sao_alternative"},{"title":"Судьба/Начало","rating":10,"tier":"solid","review":"","desc":"Действие аниме-сериала разворачивается за десять лет до событий, показанных в «Судьба/Ночь схватки».\nВойна за Святой Грааль — борьба между семью магами за обладание силой, что «сотворит чудо»: исполнит любое желание владельца. Поединки проходят посредством призыва героических духов. Сражение трижды не было окончено, и эта история описывает события Четвертой войны. \nОбъединив свою волю к победе, маги выдвинулись в зону боя — город Фуюки. Но среди них был тот, кто шел по жизни в одиночку и не мог найти для себя смысл в этих битвах. Имя ему — Кирэй Котоминэ . Не в силах понять и принять такое предрешение судьбы, он чувствовал себя опустошенным и продолжал поиски.\nВ то же время члены одной из семей-основателей, Айнцберн, после трех неудачных попыток завладеть Граалем полны решимости заполучить его любой ценой, а потому выбирают в свои ряды Кирицугу Эмию  — всем ненавистного мага с репутацией умелого, но корыстного и безжалостного наемника-мерзавца. Эмия, некогда желавший стать героем, который может всех спасти, давно уже отказался от своего идеала, осознав, что спасение одного всегда происходит за счет жизни другого. Тогда он решил, что ради человечества станет «огнем и мечом» этого мира, уничтожая всех и вся, что будут ему угрожать. Ему приходится разрываться между любовью к жене и дочери и данным им обещанием заполучить Грааль.\nСтолкновение неизбежно...","poster":"https://shikimori.io/system/animes/original/10087.jpg?1711949285","url":"https://shikimori.one/animes/z10087-fate-zero","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Фэнтези","Сверхъестественное"],"episodes":13,"kind":"tv","franchise":"fate_zero"},{"title":"Девушка на час","rating":10,"tier":"solid","review":"","desc":"Кадзуя Киносита — обычный студент университета, который ведёт скромный образ жизни и уже месяц встречается с девушкой… Но счастье длится недолго, и подруга сообщает парню, что бросает его ради другого. Чувствуя себя ниже плинтуса, Кадзуя, чтобы взбодриться, решает воспользоваться приложением, с помощью которого нанимает Тидзуру Итиносэ в качестве «девушки на час». Встретившись на «свидании», Киносита видит в ней красавицу без изъянов. Однако первое впечатление бывает ошибочным...","poster":"https://shikimori.io/system/animes/original/40839.jpg?1711957520","url":"https://shikimori.one/animes/40839-kanojo-okarishimasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Гарем","Сёнен"],"episodes":12,"kind":"tv","franchise":"kanojo_okarishimasu"},{"title":"Девушка на час 3","rating":10,"tier":"solid","review":"","desc":"Узнав о том, почему Тидзуру Итиносэ непременно хочет стать актрисой, Кадзуя Киносита предложил ей безумную идею: он решил собрать деньги и самостоятельно снять фильм с Тидзуру в главной роли! Правда, только желания исполнить мечту недостаточно, ведь ещё нужно найти режиссёра, съёмочную группу и спонсоров, готовых заплатить за этот проект. \nПолучится ли у Кадзуи свершить задуманное? Может, в чём-то ему сможет помочь стримерша Мини Яэмори, заселившаяся в соседнюю квартиру?","poster":"https://shikimori.io/system/animes/original/53050.jpg?1710730946","url":"https://shikimori.one/animes/53050-kanojo-okarishimasu-3rd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Романтика","Гарем","Сёнен"],"episodes":12,"kind":"tv","franchise":"kanojo_okarishimasu"},{"title":"Мифический Дух: Хроники","rating":10,"tier":"solid","review":"","desc":"Попав в аварию, Харуто Амакава очнулся не в больнице, а в другом мире, в теле бедного мальчика из трущоб по имени Рио. Пытаясь разобраться в ситуации, новоиспечённый Рио осознал, что унаследовал от мальчика не только магические способности, но и его желание отомстить убийцам матери. \nСконфуженный произошедшим, Рио волей случая спас принцессу Флору из рук похитителей и в качестве награды получил право обучаться в королевской академии. Так начались приключения обычного японского студента, который счастлив открыть новую главу в своей жизни.","poster":"https://shikimori.io/system/animes/original/44203.jpg?1711972300","url":"https://shikimori.one/animes/44203-seirei-gensouki","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Фэнтези","Романтика","Гарем"],"episodes":12,"kind":"tv","franchise":"seirei_gensouki"},{"title":"Не люблю боль, поэтому собираюсь вложить всё в защиту","rating":10,"tier":"solid","review":"","desc":"Получив приглашение от своей подруги Рисы Сироминэ, Каэдэ Хондзё погружается в VRMMO-игру New World Online в роли персонажа Мейпл. Не имея ни малейшего представления о том, как играть в эту игру, она расходует все свои очки навыков на защиту. В результате её движения становятся медленными, Каэдэ не может использовать магию и даже подвергается нападению кроликов. Однако, благодаря такому распределению своих очков она получает навык под названием «Абсолютная защита», а также контр-навык, который убивает одним ударом. Так Каэдэ, играя в стиле «мобильной крепости», отправляется навстречу приключениям.","poster":"https://shikimori.io/system/animes/original/38790.jpg?1711955366","url":"https://shikimori.one/animes/38790-itai-no-wa-iya-nanode-bougyoryoku-ni-kyokufuri-shitai-to-omoimasu","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Приключения","Комедия","Фэнтези"],"episodes":12,"kind":"tv","franchise":"bofuri"},{"title":"Вольный стиль!","rating":10,"tier":"solid","review":"","desc":"Харука Нанасэ, Рин Мацуока, Макото Тачибана и Нагиса Хазуки в прошлом были ведущими членами команды начальной школы по плаванию. Перед самым выпуском ребята вместе завоевали кубок, но после этого их пути разошлись.\nПрошли годы. Теперь Харука беззаботно проводит свои школьные дни, забыв о том, что когда-то привёл свою команду к победе. Но однажды к нему наведывается Рин и вызывает старого товарища на состязание. Тренированный Мацуока легко одерживает победу, что сильно бьёт по самолюбию Харуки. Чтобы взять реванш, он создаёт клуб плавания старшей школы Иватоби, вновь собирая под своим руководством Макото и Нагису. А вскоре к ним примыкает и новичок Рэй Рюгазаки.","poster":"https://shikimori.io/system/animes/original/18507.jpg?1711949565","url":"https://shikimori.one/animes/18507-free","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Спорт","Школа"],"episodes":12,"kind":"tv","franchise":"free"},{"title":"Не издевайся, Нагаторо","rating":10,"tier":"solid","review":"","desc":"Жил-поживал один неприметный старшеклассник — горя не знал, рисовал рисульки разнообразные, в основном про рыцарей, которые прекрасных дам из беды выручают и героизмом, значит, поражают в самое сердце. Естественно, сам таковым ни разу не являлся, а лишь фантазии свои на бумагу переносил. Замкнутый, ранимый, мечтательный Сэмпай...\nНо манга мангой, а в реальной жизни всё иначе. Нагаторо , недавно переведённая в ту же школу, архетипичный образ девы в беде не разделяет. Воплощение зла, огнедышащее чудовище, скрывающееся под личиной миленькой девчушки, — вот кто она! И стоило только Сэмпаю с ней познакомиться, как жизнь его превратилась в ад. Ну что, скажите на милость, эта чертовка в нём нашла?\nИ хотя Нагаторо изо дня в день продолжает терроризировать свою жертву, жертва-то, кажется, начинает привыкать. Но, главное, она понимает, что даже у «чудовища» есть свои слабости. И кто знает, возможно, эта история расскажет о том, как неловкий рыцарь подружился со своим смертельным врагом...","poster":"https://shikimori.io/system/animes/original/42361.jpg?1711954792","url":"https://shikimori.one/animes/42361-ijiranaide-nagatoro-san","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Комедия","Школа"],"episodes":12,"kind":"tv","franchise":"nagatoro"},{"title":"Повседневная жизнь бессмертного короля","rating":10,"tier":"solid","review":"","desc":"С самого рождения Ван Лин  обладает сверхчеловеческими способностями, рядом с которыми меркнет даже могущество сильнейших магов всего мира. Ван Лин не может контролировать свою невероятную силу, поэтому родители накладывают на него печать, которая подавляет его мощь. \nВ возрасте шестнадцати лет Ван Лин собирается поступать в школу магов, где хочет выглядеть, как обычный школьник, но почему-то всё идёт не по плану.","poster":"https://shikimori.io/system/animes/original/41094.jpg?1711980809","url":"https://shikimori.one/animes/41094-xian-wang-de-richang-shenghuo","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Школа"],"episodes":15,"kind":"ona","franchise":"xian_wang"},{"title":"Моя геройская академия","rating":10,"tier":"solid","review":"","desc":"] Идзуку Мидория  рано осознал, что люди не рождаются равными. А пришло это понимание, когда его начали дразнить одноклассники, одарённые особой силой. Несмотря на то, что большинство людей в этом мире рождаются с необычными способностями, Идзуку оказался среди тех немногих, кто напрочь их лишён. Однако это не стало помехой для мальчика в стремлении стать таким же легендарным героем, как Всемогущий . Для осуществления мечты Идзуку не без помощи своего кумира поступает в самую престижную академию героев — Юэй. Но это, очевидно, лишь начало его удивительных приключений.","poster":"https://shikimori.io/system/animes/original/31964.jpg?1711944324","url":"https://shikimori.one/animes/31964-boku-no-hero-academia","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Школа","Супер сила","Сёнен"],"episodes":13,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"Моя геройская академия 2","rating":10,"tier":"solid","review":"","desc":"В академии героев Юэй даже беспрецедентное жестокое нападение злодеев не может отменить главное событие года: школьный спортивный фестиваль. Известный во всей Японии и даже за её пределами, приковывающий взгляды тысяч зрителей, этот фестиваль — уникальная возможность для подрастающего поколения героев продемонстрировать свои способности как всем слоям общества, так и потенциальным работодателям.\nОднако путь к славе никогда не бывает прост, особенно для юного Идзуку Мидории , чья причуда хоть и даёт великую силу, но в то же время серьёзно ранит своего носителя. Тем не менее времени на передышку у парня нет: на фестивале ему предстоит столкнуться в бою со своими талантливыми одноклассниками, среди которых один амбициознее другого, да и ребята из других классов горят желанием доказать, что не лыком шиты. Идзуку придётся использовать все свои умения, природную смекалку и даже подручные средства, чтобы побороться за победу и вслед за наставлением своего учителя заявить всему миру: «Я здесь!»","poster":"https://shikimori.io/system/animes/original/33486.jpg?1711944315","url":"https://shikimori.one/animes/33486-boku-no-hero-academia-2nd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Школа","Супер сила","Сёнен"],"episodes":25,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"Моя геройская академия 3","rating":10,"tier":"solid","review":"","desc":"За полгода, проведённые в геройской академии Юэй, ученики класса 1-А научились многому. За это время с ними произошла уйма событий — различные тренировки, практика, контрольные и, конечно же, многочисленные битвы со злодеями. Однако после сдачи экзаменов класс было решено отправить в летний тренировочный лагерь, где опытные учителя будут давить на учеников, дабы они справились со всеми своими трудностями и вышли на новый уровень владения причудами. Пройдёт ли эта школьная поездка тихо и мирно или обернётся очередным побоищем?","poster":"https://shikimori.io/system/animes/original/36456.jpg?1711944298","url":"https://shikimori.one/animes/36456-boku-no-hero-academia-3rd-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Школа","Супер сила","Сёнен"],"episodes":25,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"Моя геройская академия 4","rating":10,"tier":"solid","review":"","desc":"Новый сезон сериала продолжит рассказ о приключениях учеников геройской академии Юэй. Многие из них уже поступили на стажировку и стали участниками множества событий, таких как битвы со злодеями, патрулирование территории и прочие повседневные дела героев, с которыми им снова придётся столкнуться в будущем.\n] Идзуку Мидорию  этот долг также не обошёл стороной. Во время обычного патрулирования он сталкивается с загадочным злодеем по имени Кай Тисаки и напуганной девочкой Эри, которую тот представляет своей дочерью. Не в силах предпринять что-либо другое, мальчик решает спасти Эри из лап злодея.\nВ это же время среди обычных героев всё больше распространяются слухи о загадочном наркотике, увеличивающем силу причуд у одних и полностью забирающем возможность использовать сверхспособности у других. Но и в преступном мире неспокойно — торговая сеть препарата все расширяется, и неизвестно, что может случиться спустя время.\nСправятся ли наши герои с поставленной перед ними задачей: раскрыть тайну причуд и спасти отчаявшуюся девочку?","poster":"https://shikimori.io/system/animes/original/38408.jpg?1711944351","url":"https://shikimori.one/animes/38408-boku-no-hero-academia-4th-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Школа","Супер сила","Сёнен"],"episodes":25,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"Моя геройская академия 5","rating":10,"tier":"solid","review":"","desc":"Юный Идзуку Мидория продолжает обучение, чтобы исполнить свою мечту — стать величайшим героем. И вот уже первый год обучения в академии «Юэй» потихоньку подходит к концу. Идзуку стал сильнее, однако с его причудой «Один за всех» начинает происходить что-то странное, чего не понимает даже Всемогущий, предыдущий обладатель этой силы. Однако это не единственная проблема Идзуку, ведь враги не дремлют, и, похоже, лидер «Альянса злодеев» Томура Сигараки снова готовит ужасный план.\nБудущему герою предстоит не только разобраться в себе и своей причуде, чтобы стать ещё сильнее, но и быть готовым кинуться в бой в любой момент. А друзья, как всегда, поддержат его.","poster":"https://shikimori.io/system/animes/original/41587.jpg?1711944310","url":"https://shikimori.one/animes/41587-boku-no-hero-academia-5th-season","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Школа","Супер сила","Сёнен"],"episodes":25,"kind":"tv","franchise":"boku_no_hero_academia"},{"title":"Повседневная жизнь бессмертного короля 2","rating":10,"tier":"solid","review":"","desc":"Это продолжение истории о сильнейшем заклинателе всего мира Ван Лине. Вокруг главного героя всегда что-то происходит: то демоны нападают из-за каждого угла, то у друзей возникают какие-то проблемы. Сможет ли Ван Лин справиться со всеми трудностями и случайно не разрушить вселенную из-за своей необъятной силы?","poster":"https://shikimori.io/system/animes/original/44069.jpg?1711980829","url":"https://shikimori.one/animes/44069-xian-wang-de-richang-shenghuo-2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Приключения","Комедия","Фэнтези","Школа"],"episodes":12,"kind":"ona","franchise":"xian_wang"},{"title":"DOTA: Кровь дракона","rating":10,"tier":"solid","review":"","desc":"Прославленный драконий рыцарь Дэвион посвятил жизнь борьбе с бедами мира. После встречи с могущественным древним эльдвурмом и благородной принцессой Мираной, у которой есть своя тайная миссия, Дэвион оказывается втянут в события гораздо более масштабные, чем он мог себе представить.","poster":"https://image.tmdb.org/t/p/w500/bOHq3p1vA7q0tU7m1wB2eU3n9yv.jpg","url":"https://www.themoviedb.org/tv/118956","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Фантастика"],"episodes":8,"kind":"ona","franchise":"dota_dragons_blood"},{"title":"DOTA: Кровь дракона 2","rating":10,"tier":"solid","review":"","desc":"Второй сезон анимационного сериала от Valve и Studio Mir. Дэвион пытается обуздать силу Слайрака, пока Инвокер плетёт паутину мести против богини Селемине, а хрупкий мир балансирует на грани тотальной войны.","poster":"https://image.tmdb.org/t/p/w500/y6P3bXbF3vF5rC0s6F4p9V3F7qT.jpg","url":"https://www.themoviedb.org/tv/118956/season/2","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Боевик","Приключения","Фэнтези","Фантастика"],"episodes":8,"kind":"ona","franchise":"dota_dragons_blood"},{"title":"Хоримия","rating":10,"tier":"solid","review":"","desc":"На первый взгляд может показаться, что Хори — обыкновенная девушка-подросток, но внешность бывает обманчива. В то время, как родители трудятся на работе, героине остаются все хлопоты по дому, а также забота о младшем брате. Из-за постоянной занятости у неё просто не остаётся времени на то, чтобы насладиться прелестями подростковой жизни. Вскоре она знакомится с Миямурой, который также не показывает в школе настоящего себя. Он кажется недружелюбным тихоней, но за пределами стен школы оказывается абсолютно другим человеком. Так, у этой парочки находится много общего, и постепенно они начинают сближаться.","poster":"https://shikimori.io/system/animes/original/42897.jpg?1711954107","url":"https://shikimori.one/animes/42897-horimiya","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнен","Романтика","Школа"],"episodes":13,"kind":"tv","franchise":"horimiya"},{"title":"Этот глупый свин не понимает мечту девочки-зайки","rating":10,"tier":"solid","review":"","desc":"Ничем не примечательный школьник Сакута Адзусагава проводит всё своё свободное время в библиотеке. Однажды он встречает девушку в костюме кролика, которая старше его на год. Она представляется как Маи Сакурадзима — прославленная актриса и первая красавица школы. Девушка рассказывает, что все вокруг перестали «видеть» её, поэтому она оделась так вызывающе. По мнению Маи, всё это из-за загадочного «подросткового синдрома». Адзусагава, недолго думая, решает помочь Сакурадзиме в решении этой странной проблемы. Однако кто мог знать, чем это обернётся...","poster":"https://shikimori.io/system/animes/original/37450.jpg?1711972346","url":"https://shikimori.one/animes/z37450-seishun-buta-yarou-wa-bunny-girl-senpai-no-yume-wo-minai","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Романтика","Сверхъестественное","Школа"],"episodes":13,"kind":"tv","franchise":"seishun_buta_yarou"},{"title":"Месть Масамунэ!","rating":10,"tier":"solid","review":"","desc":"Будучи ребёнком, Масамунэ Макабэ сильно пострадал от богатой и красивой девушки по имени Аки Адагаки. Она издевалась над ним и называла «поросёнком» из-за его внешности, отягощённой лишним весом. В один момент Масамунэ признался девушке в любви, но получил в ответ лишь насмешки и отказ. Главный герой решил ей страшно отомстить: начал упорно работать над своей внешностью, взялся за учёбу и личностное развитие.\nИ вот спустя несколько лет наш обновлённый герой переводится в школу, где учится Аки, с единственной целью: заставить девушку пройти через те же страдания и унижения, через которые прошёл сам.","poster":"https://shikimori.io/system/animes/original/33487.jpg?1711962963","url":"https://shikimori.one/animes/z33487-masamune-kun-no-revenge","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Сёнен","Комедия","Романтика","Гарем","Школа"],"episodes":12,"kind":"tv","franchise":"masamune_kun"},{"title":"Вайолет Эвергарден","rating":10,"tier":"solid","review":"","desc":"Вайолет Эвергарден, молодая девушка, чья жизнь — не что иное, как война, послушно служит под командованием майора Гилберта Бугенвиллеи  из армии Ляйденшафтлиха.\nПосле серьёзных увечий, оставивших её без рук и разделивших с Гилбертом, она покинула поле боя и была взята под опеку бывшим командующим армии Клаудией Ходжинсом , который после окончания войны основал почтовую службу «C-H» в крупном портовом городе Ляйден. Эта компания осуществляет регулярные почтовые пересылки и предоставляет услуги «автозапоминающих кукол» — талантливых девушек, в чьи обязанности входит написание писем и корректировка текста для большей части неграмотного населения города.\nВ конечном итоге, тронутая работой автозапоминающих кукол, Вайолет решает присоединиться к команде, чтобы узнать судьбу майора Гилберта и смысл последних слов, сказанных им: «Я люблю тебя».","poster":"https://shikimori.io/system/animes/original/33352.jpg?1711979744","url":"https://shikimori.one/animes/33352-violet-evergarden","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Драма","Фэнтези"],"episodes":13,"kind":"tv","franchise":"violet_evergarden"},{"title":"Клинок, рассекающий демонов: Квартал красных фонарей","rating":10,"tier":"solid","review":"","desc":"Продолжение приключений Тандзиро и его неизменных спутников: сестры-демона Нэдзуко, вечно ноющего Дзэнъицу и сорвиголовы Иносукэ. На этот раз «столп звука»  берёт их с собой на задание в Квартал красных фонарей, где в последнее время стали пропадать люди. Причиной этого скорее всего служат демоны. Так кто же стоит за всеми исчезновениями, и смогут ли наши герои с ним справиться?","poster":"https://shikimori.io/system/animes/original/47778.jpg?1708747320","url":"https://shikimori.one/animes/47778-kimetsu-no-yaiba-yuukaku-hen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Фэнтези","Исторический","Сёнен"],"episodes":11,"kind":"tv","franchise":"kimetsu_no_yaiba"},{"title":"Клинок, рассекающий демонов: Деревня кузнецов","rating":15,"tier":"solid","review":"","desc":"Хотя Тандзиро Камадо удалось выжить в битве в квартале Красных Фонарей, но вот его катана изрядно пострадала и нуждается в замене. Поэтому Тандзиро в компании своей младшей сестры Нэдзуко отправляется в деревню кузнецов, чтобы ему выковали новую катану. По стечению обстоятельств в деревне оказываются «столп любви» Мицури Канродзи и «столп тумана» Муитиро Токито, также пришедшие за оружием.\nНесмотря на то, что деревня кузнецов надёжно скрыта где-то в горах, спокойствие её жителей нарушает появление демонов. Охотникам на демонов предстоит ожесточённое сражение с членами «Двенадцати демонических лун», но смогут ли они выжить и стать сильнее, чем прежде?","poster":"https://shikimori.io/system/animes/original/51019.jpg?1710735335","url":"https://shikimori.one/animes/51019-kimetsu-no-yaiba-katanakaji-no-sato-hen","status":"watched","category":"anime","subcat":"","chronoOrder":null,"universeOrder":"","genres":["Экшен","Фэнтези","Исторический","Сёнен"],"episodes":11,"kind":"tv","franchise":"kimetsu_no_yaiba"}]};